window.VIGNOLO_VINS = [{"id":"za-constantia","nom":"Constantia (Vin de Constance)","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"Constantia","couleur":"doux","famille":"blanc_doux","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Sauvignon blanc sec et frais, sous l'influence directe de l'océan."}],"cepages":["Muscat de Frontignan"],"style":"Abricot confit, orange amère, miel et thé ; liquoreux de raisins passerillés, acidité qui garde la bouche nette.","temp":"8 à 10 °C","garde":"10 à 30 ans","prix":4,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","agrumes","caramel"],"eviter":["viande_rouge","piquant","vinaigre"],"classique":"Vin de Constance et tarte aux abricots","note":"Le Vin de Constance fut le vin doux le plus célèbre du XVIIIe siècle, bu par Napoléon à Sainte-Hélène et cité par Jane Austen. Disparu avec le phylloxéra, il est recréé par Klein Constantia depuis 1986 à partir de Muscat passerillé sur pied. Servir frais, au dessert ou sur un foie gras.","lat":-34.03,"lon":18.42,"importance":4,"niveau":"incontournable"},{"id":"za-stellenbosch-cabernet-sauvignon","nom":"Stellenbosch Cabernet Sauvignon","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"Stellenbosch","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Assemblages bordelais (Cabernet, Merlot, Cabernet franc), plus fondus que le Cabernet pur."}],"cepages":["Cabernet Sauvignon","Merlot","Cabernet franc"],"style":"Cassis, cèdre, eucalyptus et une pointe de poivron ; tanins fermes, bois présent, finale longue et droite.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":3,"accords":["viande_rouge","agneau","grille","roti","sauce_vin_rouge","fromage_dure"],"eviter":["poisson_maigre","huitre","piquant"],"classique":"Cabernet de Stellenbosch et côte de bœuf grillée au braai","note":"Entre False Bay et les montagnes de granit du Simonsberg, Stellenbosch est le cœur historique du vignoble sud-africain (1679). Son Cabernet signe le cassis et le cèdre, avec une touche d'eucalyptus et des tanins fermes. À ouvrir sur une viande rouge grillée, après cinq ans de cave.","lat":-33.93,"lon":18.86,"importance":4,"niveau":"incontournable"},{"id":"za-stellenbosch-pinotage","nom":"Stellenbosch Pinotage","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"Stellenbosch","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"rose","famille":"rose","note":"Rosés de Pinotage, fruités et simples, courants au Cap."}],"cepages":["Pinotage"],"style":"Prune, mûre, fumé et banane cuite sur les versions jeunes ; tanins ronds, bouche charnue et épicée.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","grille","fume","gibier","epice_douce","charcuterie"],"eviter":["poisson_cru","huitre","fromage_frais"],"classique":"Pinotage et boerewors grillée au braai","note":"Le Pinotage est né en 1925 à Stellenbosch, du croisement du Pinot noir et du Cinsault par Abraham Perold. Reconnaissable à ses notes fumées et de fruits noirs cuits, il accompagne les grillades et la cuisine au feu de bois. Les versions « coffee » (boisé torréfié) sont plus commerciales.","lat":-33.93,"lon":18.86,"importance":4,"niveau":"classique"},{"id":"za-franschhoek","nom":"Franschhoek","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"Franschhoek","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Cabernet Sauvignon et Syrah structurés, sur les pentes de la vallée."},{"couleur":"bulles","famille":"bulles","note":"Berceau de la route du Cap Classique, effervescents de méthode traditionnelle."}],"cepages":["Sémillon","Chardonnay","Chenin blanc","Cabernet Sauvignon","Syrah"],"style":"Blancs de Sémillon de vieilles vignes : cire, citron confit, fenouil ; bouche grasse et tendue à la fois.","temp":"10 à 12 °C","garde":"3 à 10 ans","prix":3,"accords":["poisson_gras","volaille","creme","champignon","fromage_dure","asperge"],"eviter":["viande_rouge","chocolat"],"classique":"Sémillon de Franschhoek et truite fumée du Cap","note":"Vallée fondée par des huguenots français en 1688, d'où son nom (« le coin des Français »). Ses vieilles vignes de Sémillon, parfois centenaires, donnent des blancs cireux et tendus ; les rouges de Cabernet et la route du Cap Classique complètent une offre très tournée vers la table.","lat":-33.91,"lon":19.12,"importance":3,"niveau":"classique"},{"id":"za-hemel-en-aarde","nom":"Hemel-en-Aarde (Walker Bay)","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"Walker Bay","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay tendu et minéral, bourguignon dans l'esprit."}],"cepages":["Pinot noir","Chardonnay"],"style":"Cerise, framboise, terre humide et un trait fumé ; tanins soyeux, acidité fraîche portée par l'océan Austral.","temp":"14 à 16 °C","garde":"4 à 10 ans","prix":3,"accords":["volaille","canard","champignon","poisson_gras","fromage_molle","fume"],"eviter":["piquant","fromage_bleu"],"classique":"Pinot noir d'Hemel-en-Aarde et canard rôti aux cèpes","note":"La vallée « Ciel et Terre » monte depuis Hermanus, sur Walker Bay, où l'air frais de l'Atlantique sud tempère les étés. Hamilton Russell y a planté Pinot noir et Chardonnay dès 1975 sur des argiles schisteuses. Pinot fin et fumé, Chardonnay tendu : le duo bourguignon du Cap.","lat":-34.38,"lon":19.22,"importance":3,"niveau":"classique"},{"id":"za-methode-cap-classique","nom":"Méthode Cap Classique","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"rose","famille":"rose","note":"Cap Classique rosé, de Pinot noir ou de Pinotage."}],"cepages":["Chardonnay","Pinot noir","Chenin blanc","Pinot meunier"],"style":"Bulles fines, pomme verte, brioche et agrumes ; style plus mûr et solaire que le champagne, sans lourdeur.","temp":"6 à 8 °C","garde":"2 à 6 ans","prix":2,"accords":["huitre","crustace","poisson_cru","frit","volaille","fromage_dure"],"eviter":["viande_rouge","chocolat","piquant"],"classique":"Cap Classique brut et beignets de calamar de False Bay","note":"Le terme « Cap Classique » désigne depuis 1992 les effervescents sud-africains élaborés selon la méthode traditionnelle, seconde fermentation en bouteille, avec au moins 12 mois sur lies depuis 2021. Simonsig en a sorti le premier en 1971. Apéritif et fruits de mer, à prix sage.","lat":-33.91,"lon":19.12,"importance":3,"niveau":"classique"},{"id":"za-paarl","nom":"Paarl","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"Paarl","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chenin blanc et Viognier amples, de climat chaud."},{"couleur":"doux","famille":"vdn","note":"Vins mutés de tradition, type Cape Tawny, hérités de la coopérative KWV."}],"cepages":["Shiraz","Cabernet Sauvignon","Pinotage","Chenin blanc"],"style":"Shiraz mûr : mûre, poivre noir, réglisse et chocolat ; bouche chaude et généreuse, tanins enrobés.","temp":"16 à 18 °C","garde":"4 à 10 ans","prix":2,"accords":["viande_rouge","agneau","grille","mijote","epice_douce","fromage_dure"],"eviter":["huitre","poisson_maigre","vapeur"],"classique":"Shiraz de Paarl et gigot d'agneau rôti","note":"Paarl doit son nom au dôme de granit qui brille comme une perle après la pluie. Plus chaude que Stellenbosch, siège historique de la coopérative KWV, elle produit des Shiraz solaires, des Chenin amples et des vins mutés. Rouge de table généreux, à servir sur l'agneau rôti.","lat":-33.73,"lon":18.96,"importance":3,"niveau":"classique"},{"id":"za-swartland-chenin-blanc","nom":"Swartland Chenin blanc","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"Swartland","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chenin blanc"],"style":"Coing, pomme au four, miel d'acacia et pierre chaude ; bouche texturée, souvent vinifiée en vieux fûts.","temp":"10 à 12 °C","garde":"3 à 10 ans","prix":3,"accords":["volaille","porc","poisson_gras","creme","champignon","fromage_dure"],"eviter":["viande_rouge","chocolat"],"classique":"Chenin de vieilles vignes du Swartland et poulet rôti au beurre","note":"Région de blé et de buissons au nord du Cap, le Swartland a été relancé vers 2000 par des vignerons comme Eben Sadie, qui travaillent de vieux Chenin non irrigués. Ces blancs texturés, élevés sans bois neuf, portent le coing et la pierre chaude. À servir à peine frais, sur une volaille.","lat":-33.46,"lon":18.73,"importance":3,"niveau":"classique"},{"id":"za-swartland-syrah","nom":"Swartland Syrah","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"Swartland","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rouge","famille":"rouge_solaire","note":"Assemblages rhodaniens Syrah, Grenache, Cinsault, plus chaleureux et épicés."}],"cepages":["Syrah","Grenache","Cinsault","Mourvèdre"],"style":"Poivre blanc, olive noire, mûre fraîche et fleurs ; grappes entières, tanins fins, bouche plus fraîche que le climat.","temp":"15 à 17 °C","garde":"4 à 12 ans","prix":3,"accords":["agneau","viande_rouge","grille","gibier","herbes","mediterraneen"],"eviter":["poisson_cru","fromage_frais"],"classique":"Syrah du Swartland et épaule d'agneau aux herbes","note":"Sur les granits du Paardeberg et les schistes de Riebeek-Kasteel, la Syrah du Swartland se vinifie en grappes entières, avec peu d'extraction et de bois neuf. Le résultat évoque le Rhône nord : poivre, olive, fruit frais. Les assemblages avec Grenache et Cinsault y sont fréquents.","lat":-33.46,"lon":18.73,"importance":3,"niveau":"classique"},{"id":"za-cape-agulhas","nom":"Cape Agulhas (Elim)","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"Cape Agulhas","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Syrah poivrée de climat frais, légère pour le Cap."}],"cepages":["Sauvignon blanc","Sémillon","Syrah"],"style":"Sauvignon marin et vif : citron vert, bourgeon de cassis, herbe coupée, iode ; attaque nerveuse, finale saline.","temp":"8 à 10 °C","garde":"2 à 5 ans","prix":2,"accords":["huitre","coquillage","poisson_maigre","crustace","fromage_chevre","asperge"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Sauvignon d'Elim et poisson blanc grillé au citron","note":"Autour du village d'Elim, à quelques kilomètres de la pointe sud de l'Afrique où se rencontrent les deux océans, les vignes sont battues par le vent et le sel. Le Sauvignon blanc y gagne une tension marine et des notes d'iode. Zone récente (années 1990), petite et confidentielle.","lat":-34.6,"lon":19.75,"importance":2,"niveau":"decouverte"},{"id":"za-durbanville","nom":"Durbanville","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"Durbanville","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Merlot et assemblages bordelais souples."}],"cepages":["Sauvignon blanc","Merlot","Cabernet Sauvignon"],"style":"Sauvignon frais : buis, figue verte, citron et bourgeon de cassis ; bouche droite, finale saline.","temp":"8 à 10 °C","garde":"2 à 5 ans","prix":2,"accords":["huitre","poisson_maigre","coquillage","fromage_chevre","asperge","legumes"],"eviter":["viande_rouge","chocolat","sauce_vin_rouge"],"classique":"Sauvignon de Durbanville et snoek fumé du Cap","note":"Collines de blé et de vignes aux portes nord du Cap, refroidies par les brouillards de Table Bay. Durbanville est connue pour ses Sauvignon blanc tendus ; les Merlot, plus souples, suivent. Petite zone sans tourisme viticole lourd, prix accessibles pour un blanc de fruits de mer.","lat":-33.83,"lon":18.65,"importance":2,"niveau":"decouverte"},{"id":"za-elgin","nom":"Elgin","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"Elgin","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Pinot noir frais et épicé, l'un des plus fins du pays."},{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay tendu, de climat frais."}],"cepages":["Sauvignon blanc","Chardonnay","Pinot noir","Riesling"],"style":"Sauvignon vert et tendu : groseille à maquereau, buis, fenouil, citron vert ; bouche nerveuse et saline.","temp":"8 à 10 °C","garde":"2 à 5 ans","prix":2,"accords":["huitre","poisson_maigre","coquillage","fromage_chevre","asperge","herbes"],"eviter":["viande_rouge","chocolat","sauce_vin_rouge"],"classique":"Sauvignon d'Elgin et huîtres de Saldanha","note":"Plateau de vergers de pommes à 300 m d'altitude, derrière le col de Sir Lowry, Elgin est l'une des zones les plus fraîches d'Afrique du Sud : brouillards matinaux et vendanges tardives. Ses Sauvignon tendus, ses Chardonnay et ses Pinot noir conviennent à ceux qui cherchent la fraîcheur.","lat":-34.18,"lon":19.03,"importance":2,"niveau":"decouverte"},{"id":"za-robertson","nom":"Robertson","pays":"Afrique du Sud","region":"Cap-Occidental","sousRegion":"Robertson (vallée de la Breede)","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"bulles","famille":"bulles","note":"Sols calcaires propices au Cap Classique (Graham Beck y a bâti sa réputation)."},{"couleur":"rouge","famille":"rouge_souple","note":"Shiraz et Cabernet gourmands, à prix doux."}],"cepages":["Chardonnay","Sauvignon blanc","Shiraz","Cabernet Sauvignon"],"style":"Chardonnay sur calcaire : pomme mûre, citron, noisette, beurre léger ; bouche ample mais droite.","temp":"10 à 12 °C","garde":"3 à 8 ans","prix":2,"accords":["volaille","poisson_gras","creme","crustace","fromage_dure","champignon"],"eviter":["viande_rouge","piquant"],"classique":"Chardonnay de Robertson et langoustines au beurre","note":"La vallée de la Breede, à l'intérieur des terres, est chaude et sèche, mais ses sols calcaires, rares au Cap, conviennent au Chardonnay. Robertson se partage entre élevage de chevaux et vignobles ; Graham Beck y a bâti sa réputation de Cap Classique. Blancs amples et effervescents, prix doux.","lat":-33.8,"lon":19.88,"importance":2,"niveau":"decouverte"},{"id":"dz-medea","nom":"Médéa","pays":"Algérie","region":"Atlas tellien","sousRegion":"Médéa","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Cinsault","Carignan","Grenache","Cabernet Sauvignon"],"style":"Fruits rouges mûrs, réglisse, poussière de route et épices ; rouge corsé mais souple, à boire jeune.","temp":"15 à 17 °C","garde":"2 à 5 ans","prix":1,"accords":["agneau","mijote","grille","epice_douce","mediterraneen","legumes"],"eviter":["huitre","poisson_maigre","fromage_frais"],"classique":"Rouge de Médéa et couscous d'agneau aux légumes","note":"À 900 m d'altitude dans l'Atlas tellien, au sud d'Alger, Médéa est l'un des sept crus classés algériens de l'époque coloniale, quand l'Algérie était le premier exportateur de vin au monde. Le vignoble s'est beaucoup réduit, mais les rouges de Cinsault et Carignan restent corsés et francs.","lat":36.26,"lon":2.75,"importance":1,"niveau":"decouverte"},{"id":"de-ahr-spatburgunder","nom":"Ahr Spätburgunder","pays":"Allemagne","region":"Ahr","sousRegion":"","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Pinot noir","Frühburgunder"],"style":"Cerise noire, fumée, ardoise, poivre ; élégant, tanins soyeux, acidité fraîche, boisé fin.","temp":"14 à 16 °C","garde":"5 à 15 ans","prix":3,"accords":["gibier","canard","champignon","agneau","roti","fromage_lave"],"eviter":["huitre","piquant","chocolat"],"classique":"Spätburgunder de l'Ahr et gibier à plume aux champignons","note":"Vallée étroite et sombre au sud de Bonn, l'une des plus septentrionales d'Europe, où les pentes d'ardoise accumulent la chaleur. Le Pinot noir y donne un rouge fin et fumé qui rivalise avec la Bourgogne. La crue de juillet 2021 a dévasté les chais. À servir sur un gibier à plume ou un canard.","lat":50.54,"lon":7.09,"importance":2,"niveau":"decouverte"},{"id":"de-baden-spatburgunder","nom":"Baden Spätburgunder","pays":"Allemagne","region":"Baden","sousRegion":"Kaiserstuhl","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Grauburgunder et Weissburgunder, Pinots gris et blancs secs et ronds"}],"cepages":["Pinot noir"],"style":"Cerise, framboise, sous-bois, épices douces ; souple, tanins fins, chair mûre, élevage en fût discret.","temp":"14 à 16 °C","garde":"4 à 12 ans","prix":2,"accords":["volaille","canard","champignon","porc","fromage_molle","roti"],"eviter":["huitre","piquant","chocolat"],"classique":"Spätburgunder du Kaiserstuhl et canard rôti aux cerises","note":"Le Bade longe le Rhin face à l'Alsace ; le Kaiserstuhl, ancien volcan, en est le cœur le plus chaud. Le Spätburgunder (Pinot noir) y mûrit mieux que partout ailleurs en Allemagne, sur loess et tuf. Rouge souple et mûr, à servir à peine frais sur une volaille, un canard ou des champignons.","lat":48.04,"lon":7.65,"importance":3,"niveau":"classique"},{"id":"de-franken-silvaner","nom":"Franken Silvaner","pays":"Allemagne","region":"Franken","sousRegion":"Würzburg","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Silvaner"],"style":"Pomme, poire, herbe coupée, terre humide ; sec, droit, peu aromatique, texture ronde, finale minérale.","temp":"9 à 11 °C","garde":"2 à 8 ans","prix":2,"accords":["asperge","legumes","poisson_maigre","volaille","oeuf","fromage_frais"],"eviter":["viande_rouge","fruits_exotiques","chocolat"],"classique":"Silvaner de Franconie et asperges blanches au beurre","note":"Franconie, autour de Würzburg sur le Main : le Silvaner y est planté depuis 1659 et vendu dans le Bocksbeutel, la bouteille ronde et plate. Sols calcaires de Muschelkalk et climat continental donnent un blanc sec, sobre, qui ne masque pas les légumes. C'est le vin des asperges par excellence.","lat":49.79,"lon":9.94,"importance":3,"niveau":"classique"},{"id":"de-mosel-riesling-kabinett","nom":"Mosel Riesling Kabinett","pays":"Allemagne","region":"Mosel","sousRegion":"Moyenne Moselle","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Kabinett fruchtig : sucre résiduel net, 8 % d'alcool, toujours porté par l'acidité"}],"cepages":["Riesling"],"style":"Pomme verte, citron vert, pêche blanche, pierre à fusil ; léger (8 à 10 %), acidité vive, sucre discret.","temp":"8 à 10 °C","garde":"3 à 10 ans","prix":2,"accords":["asiatique","piquant","poisson_maigre","porc","sucre_sale","vapeur"],"eviter":["viande_rouge","sauce_vin_rouge","fromage_bleu"],"classique":"Riesling Kabinett de Moselle et cuisine thaïe au piment","note":"Kabinett est le premier échelon des vins de vendange mûre (Prädikat) : raisins cueillis tôt sur les ardoises grises de Bernkastel ou Piesport. On le reconnaît à son alcool très bas et à son jeu sucre-acidité. À servir frais sur une cuisine épicée ou un poisson vapeur.","lat":49.92,"lon":7.07,"importance":5,"niveau":"incontournable"},{"id":"de-eiswein","nom":"Eiswein","pays":"Allemagne","region":"Mosel","sousRegion":"","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Riesling"],"style":"Pêche, ananas, citron confit, miel clair ; très doux, cristallin, acidité électrique, sans goût de botrytis.","temp":"6 à 8 °C","garde":"10 à 30 ans","prix":4,"accords":["fruits_jaunes","fruits_exotiques","patisserie","foie_gras","fromage_bleu","glace"],"eviter":["chocolat","viande_rouge","vinaigre"],"classique":"Eiswein et tarte aux fruits jaunes","note":"Vin de glace : les raisins restent sur pied jusqu'à une nuit de gel à moins 7 °C au moins, puis sont pressés gelés ; l'eau reste en glace, le jus concentré s'écoule. Né en Allemagne, rare avec le réchauffement, il garde un fruit pur sans pourriture noble. Dessert à lui seul, à servir très frais.","lat":49.95,"lon":7.01,"importance":4,"niveau":"incontournable"},{"id":"de-mosel-riesling-spatlese","nom":"Mosel Riesling Spätlese","pays":"Allemagne","region":"Mosel","sousRegion":"Moyenne Moselle","couleur":"doux","famille":"blanc_doux","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Spätlese trocken : vendange tardive vinifiée sèche, plus corsée et minérale"}],"cepages":["Riesling"],"style":"Abricot, pêche mûre, miel léger, ardoise ; demi-doux, 8 à 9 %, acidité tranchante qui efface le sucre.","temp":"8 à 10 °C","garde":"5 à 20 ans","prix":2,"accords":["foie_gras","piquant","asiatique","fromage_bleu","fruits_jaunes","sucre_sale"],"eviter":["viande_rouge","grille","chocolat"],"classique":"Spätlese de Moselle et foie gras poêlé aux fruits","note":"Spätlese signifie vendange tardive : raisins cueillis au moins une semaine après la récolte normale, plus riches en sucre. Sur les coteaux d'ardoise de Wehlen ou Graach, le vin reste léger et aérien grâce à l'acidité. À servir frais, en entrée ou au fromage, il vieillit vingt ans sans peine.","lat":49.94,"lon":7.06,"importance":4,"niveau":"incontournable"},{"id":"de-riesling-auslese","nom":"Riesling Auslese","pays":"Allemagne","region":"Mosel","sousRegion":"","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Riesling"],"style":"Pêche confite, mangue, miel, touche de botrytis ; doux, dense mais léger en alcool, finale longue et acidulée.","temp":"8 à 10 °C","garde":"10 à 30 ans","prix":3,"accords":["foie_gras","fromage_bleu","fruits_jaunes","fruits_exotiques","patisserie","epice_douce"],"eviter":["viande_rouge","chocolat","vinaigre"],"classique":"Riesling Auslese et tarte aux abricots","note":"Auslese veut dire sélection : grappes triées à la main, surmûries et souvent touchées par la pourriture noble. Produit en Moselle, en Rheingau ou en Nahe, c'est un vin doux à 7 ou 8 % d'alcool. On le sert frais, à petite dose, sur un dessert aux fruits ou un bleu, ou seul en fin de repas.","lat":49.99,"lon":7.05,"importance":4,"niveau":"incontournable"},{"id":"de-nahe","nom":"Nahe","pays":"Allemagne","region":"Nahe","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Riesling","Müller-Thurgau"],"style":"Pamplemousse, pêche, cassis frais, pierre ; sec ou peu sucré, vif, précis, entre Moselle et Rheingau.","temp":"8 à 10 °C","garde":"4 à 12 ans","prix":2,"accords":["poisson_maigre","crustace","volaille","asiatique","legumes","fromage_chevre"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Riesling de la Nahe et crevettes sautées à l'ail","note":"Petite vallée affluente du Rhin, à l'ouest de Bad Kreuznach, remarquable par la diversité de ses sols : porphyre volcanique, grès rouge, ardoise. Le Riesling y combine la finesse mosellane et la chair rhénane, avec une touche de cassis. À servir frais sur crustacés ou cuisine légèrement épicée.","lat":49.85,"lon":7.87,"importance":3,"niveau":"classique"},{"id":"de-pfalz-riesling","nom":"Pfalz Riesling","pays":"Allemagne","region":"Pfalz","sousRegion":"Mittelhaardt","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Spätburgunder et Dornfelder, rouges mûrs d'une région chaude"}],"cepages":["Riesling"],"style":"Pêche jaune, pamplemousse, fenouil, fumée ; sec, mûr, corsé (13 %), rond mais tendu, finale épicée.","temp":"10 à 12 °C","garde":"4 à 12 ans","prix":2,"accords":["porc","volaille","poisson_gras","roti","asiatique","fromage_dure"],"eviter":["viande_rouge","chocolat","fromage_bleu"],"classique":"Riesling du Palatinat et Saumagen, la panse de porc farcie","note":"Le Palatinat prolonge l'Alsace vers le nord, abrité par la forêt du Haardt : climat sec et chaud, amandiers et figuiers. Forst et Deidesheim donnent les Rieslings secs les plus charnus d'Allemagne, souvent sur basalte. À servir sur une cochonnaille rôtie ou un plat asiatique parfumé.","lat":49.41,"lon":8.19,"importance":3,"niveau":"classique"},{"id":"de-beerenauslese-trockenbeerenauslese","nom":"Beerenauslese et Trockenbeerenauslese","pays":"Allemagne","region":"Rheingau","sousRegion":"Johannisberg","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Riesling"],"style":"Abricot sec, miel, safran, orange confite ; liquoreux, concentré, 6 à 8 % d'alcool, acidité qui porte tout.","temp":"8 à 10 °C","garde":"20 à 50 ans","prix":4,"accords":["foie_gras","fromage_bleu","patisserie","fruits_jaunes","caramel","noix"],"eviter":["viande_rouge","chocolat","vinaigre"],"classique":"Trockenbeerenauslese et roquefort","note":"Beerenauslese : baies triées une à une, atteintes de pourriture noble. Trockenbeerenauslese : baies flétries, presque des raisins secs, quelques centilitres par cep. Schloss Johannisberg a découvert la vendange tardive en 1775. Vins très rares, vendus en demi-bouteille, à servir à petites doses.","lat":49.99,"lon":7.98,"importance":4,"niveau":"incontournable"},{"id":"de-rheingau-riesling","nom":"Rheingau Riesling","pays":"Allemagne","region":"Rheingau","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Spätburgunder d'Assmannshausen, Pinot noir historique du Rhin"}],"cepages":["Riesling"],"style":"Pomme mûre, pêche, agrumes, note de pétrole en vieillissant ; sec, mûr, acidité nette, plus charnu que la Moselle.","temp":"9 à 11 °C","garde":"4 à 12 ans","prix":2,"accords":["poisson_maigre","volaille","porc","asperge","beurre_citron","fromage_dure"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Riesling du Rheingau et asperges blanches sauce hollandaise","note":"Coteaux exposés plein sud sur la rive droite du Rhin, entre Wiesbaden et Rüdesheim, où les moines d'Eberbach ont fixé le Riesling dès le Moyen Âge. Le vin est plus mûr et plus droit qu'en Moselle, le plus souvent sec aujourd'hui. À servir sur les asperges au printemps ou un poisson de rivière.","lat":50.02,"lon":8.06,"importance":4,"niveau":"incontournable"},{"id":"de-riesling-grosses-gewachs","nom":"Riesling trocken Grosses Gewächs","pays":"Allemagne","region":"Rheingau","sousRegion":"Rüdesheim","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Riesling"],"style":"Citron confit, pêche, fumée, pierre mouillée ; sec, corsé (12,5 à 13,5 %), tendu, longue finale saline.","temp":"10 à 12 °C","garde":"5 à 15 ans","prix":3,"accords":["poisson_gras","crustace","volaille","creme","champignon","asperge"],"eviter":["viande_rouge","fromage_bleu","chocolat"],"classique":"Grosses Gewächs et sandre au beurre blanc","note":"Grosses Gewächs (grand cru) est le sommet de la hiérarchie des domaines VDP : un vin sec issu d'une parcelle classée, à rendement limité, mis en vente le 1er septembre suivant. Il se reconnaît à sa densité et à sa finale saline. À servir sur un poisson noble ou une volaille à la crème.","lat":49.98,"lon":7.92,"importance":3,"niveau":"classique"},{"id":"de-sekt","nom":"Sekt","pays":"Allemagne","region":"Rheingau","sousRegion":"","couleur":"bulles","famille":"bulles","variantes":[],"cepages":["Riesling","Pinot noir","Chardonnay","Weissburgunder"],"style":"Pomme verte, agrumes, fleurs, pain frais ; sec (brut), bulle vive, acidité nette, plus fruité que le champagne.","temp":"6 à 8 °C","garde":"1 à 5 ans","prix":2,"accords":["huitre","crustace","poisson_cru","frit","volaille","charcuterie"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Riesling Sekt brut et harengs marinés","note":"L'Allemagne est le premier marché mondial des effervescents. Le Sekt de base est fait en cuve close ; le Winzersekt, celui des vignerons, est élevé sur lattes comme un champagne, souvent à partir de Riesling. Les maisons historiques sont dans le Rheingau. À servir très frais à l'apéritif.","lat":50.03,"lon":8.12,"importance":3,"niveau":"classique"},{"id":"de-rheinhessen","nom":"Rheinhessen","pays":"Allemagne","region":"Rheinhessen","sousRegion":"Nierstein","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Dornfelder et Spätburgunder, rouges fruités en progression"}],"cepages":["Riesling","Silvaner","Müller-Thurgau"],"style":"Pomme, poire, fleurs blanches, herbes ; sec, souple, fruité, acidité modérée, buvable jeune.","temp":"8 à 10 °C","garde":"1 à 5 ans","prix":1,"accords":["legumes","poisson_maigre","volaille","charcuterie","fromage_frais","asperge"],"eviter":["viande_rouge","gibier","chocolat"],"classique":"Riesling de Nierstein et truite au bleu","note":"Plus grande région viticole d'Allemagne, entre Mayence et Worms, longtemps synonyme de Liebfraumilch avant la relève d'une génération de jeunes vignerons. Les pentes rouges de Nierstein (Roter Hang) donnent les Rieslings les plus fins. Vin de tous les jours, frais, à servir sur légumes ou poisson.","lat":49.87,"lon":8.34,"importance":3,"niveau":"classique"},{"id":"de-saale-unstrut","nom":"Saale-Unstrut","pays":"Allemagne","region":"Saale-Unstrut","sousRegion":"Freyburg","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Müller-Thurgau","Weissburgunder","Silvaner","Riesling"],"style":"Pomme verte, fleurs, herbes, craie ; sec, léger, acidité franche, peu d'alcool, finale courte et nette.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":2,"accords":["poisson_maigre","legumes","asperge","fromage_frais","oeuf","vapeur"],"eviter":["viande_rouge","gibier","chocolat"],"classique":"Weissburgunder de Saale-Unstrut et asperges de Beelitz","note":"Vignoble le plus au nord d'Allemagne, en ex-RDA, sur des terrasses calcaires en bord de rivière près de Naumburg. Les murs de pierre et les coteaux raides compensent le climat continental ; les vins sont presque tous secs, légers et francs. À boire jeunes et frais sur une cuisine simple et végétale.","lat":51.21,"lon":11.77,"importance":1,"niveau":"decouverte"},{"id":"de-wurttemberg","nom":"Württemberg (Trollinger, Lemberger)","pays":"Allemagne","region":"Württemberg","sousRegion":"Heilbronn","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Lemberger (Blaufränkisch) : plus coloré, épicé, tanins francs"}],"cepages":["Trollinger","Lemberger","Schwarzriesling"],"style":"Fraise, groseille, amande ; très léger, peu tannique, parfois une pointe de sucre, à boire frais.","temp":"13 à 15 °C","garde":"1 à 4 ans","prix":1,"accords":["charcuterie","porc","volaille","mijote","fromage_molle","legumes"],"eviter":["gibier","piquant","chocolat"],"classique":"Trollinger et Maultaschen, les raviolis souabes","note":"Autour de Stuttgart et Heilbronn, sur le Neckar : avec l'Ahr, l'une des deux régions d'Allemagne majoritairement en rouge, bue sur place. Le Trollinger (Schiava du Tyrol) donne un rouge pâle de soif ; le Lemberger, plus sérieux, en est la face noble. À servir frais sur la charcuterie.","lat":49.14,"lon":9.22,"importance":2,"niveau":"decouverte"},{"id":"en-bacchus","nom":"Bacchus anglais","pays":"Angleterre","region":"Sud et Est de l'Angleterre","sousRegion":"Kent, Norfolk, Essex","couleur":"blanc","famille":"blanc_aromatique","variantes":[],"cepages":["Bacchus"],"style":"Blanc sec et aromatique : sureau, groseille à maquereau, pamplemousse, ortie ; acidité vive, alcool bas (11 à 12 %).","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":2,"accords":["asperge","legumes","fromage_chevre","poisson_maigre","herbes","asiatique"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Bacchus anglais et asperges du Kent au beurre","note":"Le Bacchus est un croisement allemand (Silvaner × Riesling × Müller-Thurgau) qui mûrit tôt, d'où son succès dans le climat frais anglais : c'est le cépage blanc tranquille le plus planté du pays. Ses notes de sureau et de groseille à maquereau rappellent un Sauvignon. À boire jeune, sur asperges.","lat":51.15,"lon":0.87,"importance":2,"niveau":"decouverte"},{"id":"en-sussex-kent-mousseux","nom":"Vin mousseux anglais (Sussex, Kent)","pays":"Angleterre","region":"Sud-Est de l'Angleterre","sousRegion":"Sussex, Kent","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"bulles","famille":"bulles","note":"Blanc de blancs (Chardonnay seul) : le style le plus tendu, pomme verte et craie."},{"couleur":"bulles","famille":"bulles","note":"Rosé de Pinot noir : fraise, groseille, même acidité vive."}],"cepages":["Chardonnay","Pinot noir","Pinot meunier"],"style":"Effervescent méthode traditionnelle, très vif : pomme verte, citron, brioche, craie ; bulle fine, acidité tranchante.","temp":"7 à 9 °C","garde":"3 à 10 ans","prix":3,"accords":["huitre","crustace","poisson_cru","frit","fromage_dure","beurre_citron"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Mousseux du Sussex et fish and chips","note":"Les South Downs du Sussex et les collines du Kent reposent sur la même craie que la Champagne, 300 km plus au nord. Depuis les années 1990, les cépages champenois y donnent des mousseux de méthode traditionnelle, plus acides et citronnés que les champagnes ; « Sussex » est protégé depuis 2022.","lat":50.87,"lon":0.01,"importance":3,"niveau":"classique"},{"id":"ar-mendoza-malbec","nom":"Mendoza Malbec","pays":"Argentine","region":"Mendoza","sousRegion":"","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de malbec, fruité et rond"}],"cepages":["Malbec","Cabernet Sauvignon","Bonarda"],"style":"Prune, mûre, violette et cacao, bouche charnue et veloutée, tanins mûrs, chaleur maîtrisée.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","grille","roti","charcuterie","fromage_dure"],"eviter":["poisson_maigre","huitre"],"classique":"Malbec de Mendoza et asado de bœuf","note":"Venu de Cahors au XIXe siècle, le malbec a trouvé à Mendoza, au pied des Andes, un désert irrigué par la fonte des neiges : soleil, altitude et nuits froides. Premier cépage du pays (un peu plus du cinquième du vignoble), il se reconnaît à son fruit noir velouté, fait pour la viande grillée.","lat":-32.89,"lon":-68.85,"importance":5,"niveau":"incontournable"},{"id":"ar-lujan-de-cuyo","nom":"Luján de Cuyo","pays":"Argentine","region":"Mendoza","sousRegion":"Luján de Cuyo","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Malbec","Cabernet Sauvignon","Cabernet Franc"],"style":"Malbec de vieilles vignes, cerise noire, violette, graphite, tanins fins et denses, élevage fondu.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["viande_rouge","agneau","roti","sauce_vin_rouge","fromage_dure"],"eviter":["poisson_cru","coquillage"],"classique":"Luján de Cuyo et bife de chorizo saignant","note":"Première appellation d'origine d'Argentine (1993), Luján de Cuyo est la « première zone » historique de Mendoza, entre 900 et 1 100 m. Ses vieilles vignes de malbec sur sols caillouteux donnent des rouges plus profonds et structurés que le malbec courant, à carafer.","lat":-33.03,"lon":-68.88,"importance":4,"niveau":"classique"},{"id":"ar-valle-de-uco","nom":"Valle de Uco","pays":"Argentine","region":"Mendoza","sousRegion":"Valle de Uco","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay d'altitude de Gualtallary, tendu et minéral"}],"cepages":["Malbec","Cabernet Franc","Chardonnay","Pinot Noir"],"style":"Malbec d'altitude, fruit rouge frais, herbes, craie, tanins fins et poudreux, acidité élevée, long.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":3,"accords":["viande_rouge","agneau","gibier","roti","herbes"],"eviter":["poisson_maigre","huitre"],"classique":"Malbec de la Valle de Uco et agneau rôti aux herbes","note":"Au sud-ouest de Mendoza, l'Uco monte de 900 à 1 500 m : sols calcaires et nuits froides y donnent les malbecs les plus frais et tendus d'Argentine. Gualtallary, Altamira, Los Chacayes sont ses lieux-dits phares, pour des rouges de garde et des chardonnays précis.","lat":-33.58,"lon":-69.05,"importance":4,"niveau":"classique"},{"id":"ar-patagonie","nom":"Patagonie argentine","pays":"Argentine","region":"Patagonie","sousRegion":"Neuquén et Río Negro","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Malbec frais et poivré de climat froid"},{"couleur":"bulles","famille":"bulles","note":"Effervescents de pinot noir et chardonnay, tendus"}],"cepages":["Pinot Noir","Malbec","Merlot","Chardonnay"],"style":"Pinot noir fin, cerise, framboise, note terreuse, tanins soyeux, acidité nette et finale fraîche.","temp":"14 à 16 °C","garde":"3 à 8 ans","prix":2,"accords":["agneau","volaille","canard","champignon","fume"],"eviter":["piquant","fromage_bleu"],"classique":"Pinot noir de Patagonie et agneau patagon à la broche","note":"Autour des rivières Neuquén et Negro, à 39° de latitude sud, la Patagonie viticole est basse, venteuse et froide : vieilles vignes de Río Negro (années 1910), plantations récentes de San Patricio del Chañar. Ses pinots noirs fins et ses malbecs tendus accompagnent l'agneau à la broche.","lat":-38.63,"lon":-68.3,"importance":3,"niveau":"classique"},{"id":"ar-cafayate-torrontes","nom":"Cafayate Torrontés","pays":"Argentine","region":"Salta","sousRegion":"Vallées Calchaquíes","couleur":"blanc","famille":"blanc_aromatique","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Malbec et tannat d'altitude, denses et épicés"}],"cepages":["Torrontés Riojano","Malbec","Tannat"],"style":"Nez de rose, jasmin, muscat et litchi, bouche sèche et vive, finale légèrement amère et poivrée.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":2,"accords":["asiatique","curry","epice_douce","fromage_chevre","crustace"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Torrontés de Cafayate et empanadas salteñas au piment doux","note":"Croisement local de muscat d'Alexandrie et de criolla chica, le torrontés est le cépage blanc emblématique de l'Argentine. À Cafayate, entre 1 700 et 3 000 m, son nez de rose et de muscat garde une bouche sèche : idéal sur cuisines épicées et plats asiatiques.","lat":-26.07,"lon":-65.98,"importance":3,"niveau":"classique"},{"id":"ar-san-juan-bonarda","nom":"San Juan Bonarda","pays":"Argentine","region":"San Juan","sousRegion":"","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Bonarda","Syrah","Malbec"],"style":"Fruit rouge et noir juteux, cerise, réglisse, tanins doux, acidité modérée, rouge gourmand et simple.","temp":"15 à 17 °C","garde":"1 à 4 ans","prix":1,"accords":["charcuterie","porc","volaille","tomate","grille"],"eviter":["poisson_cru","huitre"],"classique":"Bonarda de San Juan et pizza à l'argentine","note":"Deuxième région viticole d'Argentine, au nord de Mendoza, San Juan est chaude et sèche ; ses vallées de Tulum et Pedernal donnent des rouges solaires. La bonarda, en fait le douce noir savoyard, y est le second cépage du pays : un rouge souple et abordable, pour la cuisine de tous les jours.","lat":-31.54,"lon":-68.53,"importance":2,"niveau":"decouverte"},{"id":"am-areni","nom":"Areni","pays":"Arménie","region":"Vayots Dzor","sousRegion":"Areni","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Areni réserve, élevé en fût de chêne du Caucase : plus dense, notes de cuir et de prune cuite."}],"cepages":["Areni noir"],"style":"Rouge fin et frais : cerise, grenade, framboise, poivre, herbes de montagne ; tanins fins, acidité vive.","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":2,"accords":["agneau","grille","charcuterie","legumes","herbes","fromage_dure"],"eviter":["huitre","poisson_cru","patisserie"],"classique":"Areni noir et khorovats (brochettes d'agneau) au feu de bois","note":"Dans la grotte d'Areni-1, en Vayots Dzor, on a trouvé en 2011 le plus ancien pressoir connu, vieux de 6 100 ans. L'Areni noir pousse ici entre 1 000 et 1 600 m, sur sols volcaniques et calcaires : rouge aux tanins fins, proche du Pinot noir par sa fraîcheur. Vin de grillades d'agneau et de légumes.","lat":39.72,"lon":45.18,"importance":2,"niveau":"decouverte"},{"id":"au-barossa-valley-shiraz","nom":"Barossa Valley Shiraz","pays":"Australie","region":"Australie-Méridionale","sousRegion":"Barossa Valley","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"rouge","famille":"rouge_solaire","note":"Assemblages GSM (grenache, shiraz, mourvèdre) de vieilles vignes, plus épicés et moins boisés."},{"couleur":"doux","famille":"vdn","note":"Vins mutés de style porto (tawny) issus de la tradition des fortifiés de la vallée."}],"cepages":["Shiraz","Grenache","Mourvèdre"],"style":"Mûre, prune confite, chocolat et eucalyptus ; corps massif, tanins veloutés, alcool présent, bois vanillé.","temp":"16 à 18 °C","garde":"5 à 20 ans","prix":3,"accords":["viande_rouge","grille","roti","agneau","sauce_vin_rouge","fromage_dure"],"eviter":["huitre","poisson_maigre","poisson_cru"],"classique":"Barossa Shiraz et côte de bœuf au barbecue","note":"Vallée colonisée par des luthériens silésiens dans les années 1840 : certaines vignes de shiraz, jamais touchées par le phylloxéra, ont plus de 150 ans. Le style est opulent, solaire, souvent boisé. À ouvrir sur une viande rouge grillée ou un agneau rôti, en hiver.","lat":-34.53,"lon":138.95,"importance":5,"niveau":"incontournable"},{"id":"au-coonawarra-cabernet","nom":"Coonawarra Cabernet Sauvignon","pays":"Australie","region":"Australie-Méridionale","sousRegion":"Coonawarra","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Shiraz plus fraîche et poivrée qu'en Barossa, historiquement le premier cépage de l'appellation."}],"cepages":["Cabernet Sauvignon","Shiraz","Merlot"],"style":"Cassis, menthe, eucalyptus, cèdre ; tanins fins mais fermes, acidité fraîche, bois discret.","temp":"16 à 18 °C","garde":"5 à 20 ans","prix":3,"accords":["viande_rouge","agneau","roti","gibier","sauce_vin_rouge","fromage_dure"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Coonawarra Cabernet et carré d'agneau à la menthe","note":"Bande de terra rossa (argile rouge sur calcaire) de 15 km sur 2, à 400 km au sud-est d'Adélaïde, dans un climat frais tempéré par l'océan Austral. Le cabernet y gagne sa signature de cassis et de menthol et vieillit vingt ans. À servir sur l'agneau, le gibier ou un fromage affiné.","lat":-37.29,"lon":140.83,"importance":4,"niveau":"incontournable"},{"id":"au-adelaide-hills","nom":"Adelaide Hills","pays":"Australie","region":"Australie-Méridionale","sousRegion":"Adelaide Hills","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay de climat frais, tendu et discrètement boisé, l'un des meilleurs d'Australie."},{"couleur":"rouge","famille":"rouge_leger","note":"Pinot noir léger et croquant, ainsi que des rouges de soif (gamay, grüner veltliner en blanc)."},{"couleur":"bulles","famille":"bulles","note":"Effervescents de méthode traditionnelle à base de chardonnay et pinot noir."}],"cepages":["Sauvignon Blanc","Chardonnay","Pinot Noir"],"style":"Groseille à maquereau, fruit de la passion, herbe coupée ; sec, vif, bouche fraîche et nette.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":2,"accords":["fromage_chevre","asperge","legumes","poisson_maigre","herbes","crustace"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Sauvignon blanc des Adelaide Hills et salade de chèvre chaud","note":"À vingt minutes d'Adélaïde, les collines du mont Lofty culminent à plus de 600 m : brouillards, nuits fraîches et vendanges tardives. Région de climat frais où le sauvignon blanc rivalise avec celui de Marlborough, et berceau du mouvement nature australien (Basket Range). Apéritif et verdure.","lat":-34.98,"lon":138.8,"importance":3,"niveau":"classique"},{"id":"au-clare-valley-riesling","nom":"Clare Valley Riesling","pays":"Australie","region":"Australie-Méridionale","sousRegion":"Clare Valley","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Shiraz et cabernet sauvignon charnus, parfois assemblés avec du malbec."}],"cepages":["Riesling"],"style":"Citron vert, pomme verte, craie ; très sec, acidité vive et droite, bouche cristalline et longue.","temp":"8 à 10 °C","garde":"3 à 15 ans","prix":2,"accords":["huitre","coquillage","poisson_cru","asiatique","piquant","fromage_frais"],"eviter":["viande_rouge","mijote"],"classique":"Clare Riesling et huîtres natives","note":"À 130 km au nord d'Adélaïde, des nuits fraîches en altitude sauvent l'acidité du riesling malgré le soleil. La vallée a adopté le bouchon à vis dès 2000 pour protéger ses blancs. Sec et tranchant jeune, il se patine en miel et toast après dix ans. Parfait sur les huîtres.","lat":-33.83,"lon":138.61,"importance":3,"niveau":"classique"},{"id":"au-eden-valley-riesling","nom":"Eden Valley Riesling","pays":"Australie","region":"Australie-Méridionale","sousRegion":"Eden Valley","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Shiraz de haute altitude (Henschke Hill of Grace), plus frais et poivré que celui de la Barossa voisine."}],"cepages":["Riesling"],"style":"Citron vert, fleur de citronnier, pierre mouillée ; sec, acidité tendue, finale saline.","temp":"8 à 10 °C","garde":"3 à 15 ans","prix":2,"accords":["crustace","poisson_maigre","asiatique","vapeur","beurre_citron","fromage_chevre"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Eden Valley Riesling et crevettes grillées au citron vert","note":"Collines à 400 à 600 m d'altitude dominant la Barossa, plus fraîches et plus ventées. Le riesling y est sec, floral et citronné, avec des notes de pétrole qui apparaissent après cinq ans de bouteille. Idéal à l'apéritif ou sur des fruits de mer, jeune ou patiné.","lat":-34.65,"lon":139.1,"importance":3,"niveau":"classique"},{"id":"au-mclaren-vale","nom":"McLaren Vale","pays":"Australie","region":"Australie-Méridionale","sousRegion":"McLaren Vale","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Grenache de vieilles vignes, plus clair et fruité, ainsi que des cépages méditerranéens (fiano, nero d'Avola) en progression."}],"cepages":["Shiraz","Grenache","Cabernet Sauvignon"],"style":"Mûre, chocolat noir, épices douces et un trait de sel marin ; rond, généreux, tanins doux.","temp":"16 à 18 °C","garde":"4 à 15 ans","prix":2,"accords":["viande_rouge","grille","agneau","mijote","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_maigre"],"classique":"McLaren Vale Shiraz et épaule d'agneau confite","note":"Au sud d'Adélaïde, entre collines et golfe Saint-Vincent, la brise de mer tempère un climat méditerranéen. La shiraz y est plus suave et plus chocolatée qu'en Barossa, le grenache y donne de beaux vins de soif. Région pionnière du bio en Australie. Pour les plats mijotés.","lat":-35.22,"lon":138.54,"importance":3,"niveau":"classique"},{"id":"au-langhorne-creek","nom":"Langhorne Creek","pays":"Australie","region":"Australie-Méridionale","sousRegion":"Langhorne Creek","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rouge","famille":"rouge_solaire","note":"Shiraz ronde et épicée, souvent assemblée au cabernet dans les grandes marques."}],"cepages":["Cabernet Sauvignon","Shiraz","Malbec"],"style":"Cassis mûr, prune, menthe douce et chocolat au lait ; tanins soyeux, bouche ronde et facile.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","grille","roti","charcuterie","mijote","fromage_dure"],"eviter":["huitre","poisson_maigre"],"classique":"Langhorne Creek Cabernet et hamburger maison","note":"Plaine alluviale de la rivière Bremer, près du lac Alexandrina, rafraîchie chaque après-midi par les vents du lac. Historiquement, les vignes étaient inondées volontairement chaque hiver. Ses cabernets souples alimentent de grandes marques australiennes. Vin de barbecue sans prétention.","lat":-35.3,"lon":139.04,"importance":2,"niveau":"decouverte"},{"id":"au-margaret-river","nom":"Margaret River","pays":"Australie","region":"Australie-Occidentale","sousRegion":"Margaret River","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay de grande classe (Leeuwin Art Series), pêche, noisette et bois fin."},{"couleur":"blanc","famille":"blanc_vif","note":"Assemblage sémillon et sauvignon blanc, vif et herbacé, dans l'esprit du Bordeaux blanc."}],"cepages":["Cabernet Sauvignon","Merlot","Chardonnay","Sémillon"],"style":"Cassis, feuille de cassis, cèdre, graphite ; tanins fins et mûrs, équilibre frais, bois bien fondu.","temp":"16 à 18 °C","garde":"5 à 20 ans","prix":3,"accords":["viande_rouge","agneau","roti","gibier","sauce_vin_rouge","fromage_dure"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Margaret River Cabernet et filet de bœuf sauce au vin","note":"Pointe sud-ouest de l'Australie, entre deux océans, plantée en 1967 après qu'un agronome y eut vu l'analogue climatique de Bordeaux. Le cabernet y est droit, cassis et cèdre, sans excès de puissance ; le chardonnay rivalise avec les grands. Sur une viande rôtie, après cinq ans.","lat":-33.95,"lon":115.07,"importance":4,"niveau":"incontournable"},{"id":"au-great-southern","nom":"Great Southern (Frankland River)","pays":"Australie","region":"Australie-Occidentale","sousRegion":"Great Southern","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Shiraz poivrée et florale de Frankland River, et cabernet sauvignon de Mount Barker, tous deux frais et structurés."}],"cepages":["Riesling","Shiraz","Cabernet Sauvignon"],"style":"Citron vert, fleurs blanches, talc ; sec, acidité vive, bouche fine et droite, finale minérale.","temp":"8 à 10 °C","garde":"3 à 12 ans","prix":2,"accords":["poisson_maigre","crustace","asiatique","vapeur","beurre_citron","fromage_chevre"],"eviter":["viande_rouge","mijote"],"classique":"Riesling de Great Southern et truite au beurre citronné","note":"Vaste région de l'extrême sud-ouest, à 350 km de Perth, découpée en cinq sous-zones (Frankland River, Mount Barker, Porongurup, Denmark, Albany). Climat continental tempéré par l'océan Austral : rieslings secs et précis, shiraz poivrée. Peu connue en Europe, bon rapport qualité-prix.","lat":-34.37,"lon":117.08,"importance":2,"niveau":"decouverte"},{"id":"au-hunter-valley-semillon","nom":"Hunter Valley Semillon","pays":"Australie","region":"Nouvelle-Galles du Sud","sousRegion":"Hunter Valley","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Shiraz de climat chaud et humide, moyennement corsée, terreuse et poivrée, longue à vieillir."},{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay beurré et boisé, style historique de la vallée (Tyrrell's Vat 47)."}],"cepages":["Sémillon"],"style":"Jeune : citron, herbe, 10 à 11 % d'alcool, sec et tranchant. Âgé : toast, miel, cire, sans bois.","temp":"8 à 10 °C","garde":"5 à 20 ans","prix":2,"accords":["huitre","coquillage","poisson_cru","crustace","vapeur","asiatique"],"eviter":["viande_rouge","sauce_vin_rouge","fromage_bleu"],"classique":"Hunter Semillon de dix ans et huîtres de Sydney Rock","note":"À deux heures au nord de Sydney, la plus ancienne région viticole d'Australie (années 1820), chaude et humide, vendange tôt. Le sémillon y est récolté peu mûr, léger en alcool, vinifié sans bois : austère jeune, il devient toasté et miellé après dix ans. Un cas unique au monde.","lat":-32.78,"lon":151.3,"importance":3,"niveau":"classique"},{"id":"au-canberra-district","nom":"Canberra District","pays":"Australie","region":"Nouvelle-Galles du Sud","sousRegion":"Canberra District","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Riesling sec et tendu, citron vert et fleurs, le deuxième cépage phare de la région."}],"cepages":["Shiraz","Viognier","Riesling"],"style":"Framboise, violette, poivre blanc et abricot (le viognier) ; corps moyen, tanins fins, bouche parfumée.","temp":"15 à 17 °C","garde":"4 à 15 ans","prix":3,"accords":["agneau","canard","gibier","roti","champignon","fromage_dure"],"eviter":["huitre","poisson_cru"],"classique":"Shiraz-Viognier de Canberra et canard rôti aux épices","note":"Vignobles à 500 à 800 m d'altitude autour de Murrumbateman, au nord de la capitale, dans un climat continental froid l'hiver. Clonakilla y a lancé en 1992 un assemblage shiraz-viognier à la mode de Côte-Rôtie, devenu un style australien à part entière. Rouge parfumé pour le canard.","lat":-34.97,"lon":149.03,"importance":2,"niveau":"decouverte"},{"id":"au-tasmanie","nom":"Tasmanie","pays":"Australie","region":"Tasmanie","sousRegion":"Tamar Valley","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Pinot noir de climat frais, cerise acidulée et sous-bois, le plus bourguignon d'Australie."},{"couleur":"blanc","famille":"blanc_vif","note":"Riesling et sauvignon blanc tendus, et chardonnay citronné, très frais."}],"cepages":["Chardonnay","Pinot Noir","Pinot Meunier"],"style":"Pomme verte, agrumes, brioche fine ; bulles serrées, acidité élevée, finale longue et saline.","temp":"6 à 8 °C","garde":"3 à 10 ans","prix":3,"accords":["huitre","crustace","poisson_cru","frit","fromage_frais","poisson_gras"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Effervescent de Tasmanie et huîtres de Bruny Island","note":"Île au sud du continent, à la latitude des vents d'ouest : la région la plus fraîche d'Australie. La vallée de la Tamar (Launceston) et la Coal River (Hobart) donnent des bases d'effervescents très acides, mûries longtemps sur lattes (Arras, Jansz). Apéritif et fruits de mer.","lat":-41.44,"lon":147.14,"importance":3,"niveau":"classique"},{"id":"au-yarra-valley","nom":"Yarra Valley","pays":"Australie","region":"Victoria","sousRegion":"Yarra Valley","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay tendu, citronné et finement boisé, de référence en Australie."},{"couleur":"bulles","famille":"bulles","note":"Effervescents de méthode traditionnelle (Domaine Chandon y est installé depuis 1986)."},{"couleur":"rouge","famille":"rouge_puissant","note":"Cabernet sauvignon de climat frais, cassis et cèdre, sur les sites les plus chauds."}],"cepages":["Pinot Noir","Chardonnay","Cabernet Sauvignon","Shiraz"],"style":"Cerise rouge, framboise, sous-bois et épices ; corps léger à moyen, tanins fins, acidité fraîche.","temp":"14 à 16 °C","garde":"3 à 10 ans","prix":3,"accords":["volaille","canard","champignon","poisson_gras","porc","fromage_molle"],"eviter":["piquant","fromage_bleu"],"classique":"Pinot noir de la Yarra et magret de canard aux cerises","note":"Première région viticole du Victoria (1838), à une heure de Melbourne, replantée dans les années 1970 avec un climat frais en tête. Pinot noir et chardonnay y sont les cépages phares, les effervescents suivent. Rouge de table élégant, à servir frais sur une volaille ou un canard.","lat":-37.65,"lon":145.52,"importance":4,"niveau":"incontournable"},{"id":"au-mornington-peninsula","nom":"Mornington Peninsula","pays":"Australie","region":"Victoria","sousRegion":"Mornington Peninsula","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay précis et salin, et pinot gris en style sec plus charnu."}],"cepages":["Pinot Noir","Chardonnay","Pinot Gris"],"style":"Fraise, cerise, pivoine et épices fines ; bouche soyeuse, fraîche, tanins délicats, finale saline.","temp":"14 à 16 °C","garde":"3 à 10 ans","prix":3,"accords":["volaille","canard","champignon","poisson_gras","truffe","fromage_molle"],"eviter":["piquant","viande_rouge"],"classique":"Pinot noir de Mornington et saumon rôti aux champignons","note":"Péninsule au sud de Melbourne, cernée par la baie de Port Phillip et le détroit de Bass : climat maritime frais, vents constants. Petits domaines familiaux dédiés au pinot noir et au chardonnay depuis les années 1970. Rouges fins et aériens, à servir frais sur une volaille ou un poisson.","lat":-38.38,"lon":145.03,"importance":3,"niveau":"classique"},{"id":"au-rutherglen-muscat","nom":"Rutherglen Muscat","pays":"Australie","region":"Victoria","sousRegion":"Rutherglen","couleur":"doux","famille":"vdn","variantes":[{"couleur":"doux","famille":"vdn","note":"Topaque (ex-Tokay), même méthode sur muscadelle : notes de thé, de malt et de caramel, plus sec."},{"couleur":"rouge","famille":"rouge_puissant","note":"Durif (petite sirah) et shiraz massifs, à l'ancienne."}],"cepages":["Muscat à petits grains rouges"],"style":"Raisin de Corinthe, caramel, toffee, café et rancio ; sirupeux, très sucré, acidité qui porte.","temp":"12 à 14 °C","garde":"10 à 50 ans","prix":3,"accords":["chocolat","caramel","patisserie","noix","fromage_bleu","glace"],"eviter":["huitre","poisson_maigre","acide"],"classique":"Rutherglen Muscat et pudding de Noël","note":"Au nord-est du Victoria, sur la rivière Murray, des maisons familiales (Morris, Chambers, Campbells) mutent depuis 1850 un muscat rouge vendangé surmûri, puis l'élèvent en solera sous les toits chauds. Quatre niveaux officiels (Rutherglen, Classic, Grand, Rare). Dessert au chocolat.","lat":-36.05,"lon":146.46,"importance":3,"niveau":"classique"},{"id":"au-beechworth","nom":"Beechworth","pays":"Australie","region":"Victoria","sousRegion":"Beechworth","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Shiraz de granit, poivrée et dense, et quelques nebbiolo et sangiovese d'inspiration italienne."}],"cepages":["Chardonnay","Shiraz","Nebbiolo"],"style":"Pêche blanche, noisette grillée, pierre à fusil et beurre frais ; ample mais tendu, bois fin, longue finale.","temp":"11 à 13 °C","garde":"4 à 12 ans","prix":4,"accords":["volaille","creme","crustace","poisson_gras","champignon","truffe"],"eviter":["piquant","vinaigre"],"classique":"Chardonnay de Beechworth et poularde à la crème","note":"Ancienne ville de la ruée vers l'or, au nord-est du Victoria, à 400 à 800 m d'altitude sur granit et argiles. Une poignée de petits domaines (Giaconda, Sorrenberg, Castagna) y font des chardonnays de style bourguignon parmi les plus recherchés d'Australie. Sur une volaille à la crème.","lat":-36.36,"lon":146.69,"importance":2,"niveau":"decouverte"},{"id":"au-grampians-shiraz","nom":"Grampians Shiraz","pays":"Australie","region":"Victoria","sousRegion":"Grampians","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"bulles","famille":"bulles","note":"Shiraz effervescent rouge (sparkling Shiraz), spécialité historique de Great Western, aujourd'hui curiosité de fête."}],"cepages":["Shiraz","Riesling"],"style":"Cerise noire, poivre noir, menthe et épices ; corps moyen à plein, tanins fins, acidité fraîche.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":3,"accords":["viande_rouge","grille","gibier","agneau","charcuterie","fromage_dure"],"eviter":["huitre","poisson_maigre"],"classique":"Grampians Shiraz et kangourou grillé au poivre","note":"À l'ouest du Victoria, au pied des monts Grampians, Great Western produit du vin depuis la ruée vers l'or des années 1860 ; les caves de Seppelt y sont creusées dans le granit. Climat frais : la shiraz y est poivrée et élancée, loin de l'opulence de la Barossa. Pour une viande grillée.","lat":-37.28,"lon":142.93,"importance":2,"niveau":"decouverte"},{"id":"au-heathcote-shiraz","nom":"Heathcote Shiraz","pays":"Australie","region":"Victoria","sousRegion":"Heathcote","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Shiraz"],"style":"Mûre, violette, poivre noir et graphite ; dense, tanins mûrs et serrés, moins confituré qu'en Barossa.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":3,"accords":["viande_rouge","grille","gibier","agneau","mijote","fromage_dure"],"eviter":["huitre","poisson_maigre","poisson_cru"],"classique":"Heathcote Shiraz et gigot d'agneau au romarin","note":"Au centre du Victoria, une bande de sols cambriens rouges de 500 millions d'années, riches en fer et très profonds, qui gardent l'eau sans irrigation. La shiraz y est noire, structurée et poivrée, avec une fraîcheur que n'a pas la Barossa. Pour l'agneau et le gibier.","lat":-36.92,"lon":144.71,"importance":2,"niveau":"decouverte"},{"id":"at-wachau-gruner-veltliner-smaragd","nom":"Wachau Grüner Veltliner Smaragd","pays":"Autriche","region":"Basse-Autriche","sousRegion":"Wachau","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Steinfeder et Federspiel : les deux niveaux plus légers, secs et vifs"}],"cepages":["Grüner Veltliner"],"style":"Poivre blanc, pomme, lentille, agrumes ; sec, corsé (13 à 14 %), texture dense, finale longue et épicée.","temp":"10 à 12 °C","garde":"5 à 15 ans","prix":3,"accords":["asperge","artichaut","volaille","poisson_gras","frit","asiatique"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Grüner Veltliner Smaragd et Wiener Schnitzel","note":"La Wachau est une gorge du Danube entre Melk et Krems, aux terrasses de gneiss tenues par des murs de pierre sèche. Smaragd (émeraude, du lézard qui s'y chauffe) désigne le niveau le plus mûr, au-dessus de 12,5 %. Reconnaissable à son poivre blanc, il tient face à l'artichaut et à l'asperge.","lat":48.4,"lon":15.47,"importance":4,"niveau":"incontournable"},{"id":"at-wachau-riesling","nom":"Wachau Riesling","pays":"Autriche","region":"Basse-Autriche","sousRegion":"Wachau","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Riesling"],"style":"Pêche, abricot, citron, pierre chaude ; sec, droit, mûr (12,5 à 13,5 %), acidité fine, sans sucre résiduel.","temp":"9 à 11 °C","garde":"5 à 20 ans","prix":3,"accords":["poisson_maigre","crustace","volaille","beurre_citron","asiatique","fromage_dure"],"eviter":["viande_rouge","chocolat","fromage_bleu"],"classique":"Riesling de la Wachau et truite du Danube au beurre","note":"Sur les hauts de terrasses de gneiss et d'amphibolite (Loibenberg, Kellerberg, Singerriedel), le Riesling autrichien est toujours sec, plus mûr et plus corsé que son cousin allemand, sans jamais la note pétrolée jeune. Grand vin de poisson d'eau douce, il vieillit vingt ans.","lat":48.39,"lon":15.52,"importance":4,"niveau":"incontournable"},{"id":"at-kamptal","nom":"Kamptal","pays":"Autriche","region":"Basse-Autriche","sousRegion":"Kamptal","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Zweigelt et Pinot noir, rouges frais en petite quantité"}],"cepages":["Grüner Veltliner","Riesling"],"style":"Pamplemousse, pêche, poivre, fumée ; sec, tendu, minéral, les Rieslings du Heiligenstein sont fins et longs.","temp":"9 à 11 °C","garde":"4 à 15 ans","prix":2,"accords":["poisson_maigre","crustace","asperge","volaille","asiatique","fromage_chevre"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Riesling du Heiligenstein et sandre poêlé","note":"Vallée du Kamp autour de Langenlois, la plus grande commune viticole d'Autriche. Le Heiligenstein, colline de grès du Permien vieille de 270 millions d'années, donne des Rieslings secs de grande garde ; le loess alentour nourrit le Grüner Veltliner. À servir frais sur un poisson ou des asperges.","lat":48.47,"lon":15.68,"importance":3,"niveau":"classique"},{"id":"at-kremstal","nom":"Kremstal","pays":"Autriche","region":"Basse-Autriche","sousRegion":"Kremstal","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Grüner Veltliner","Riesling"],"style":"Pomme, poivre blanc, agrumes, pierre ; sec, vif, un peu plus souple et fruité que la Wachau voisine.","temp":"9 à 11 °C","garde":"3 à 10 ans","prix":2,"accords":["legumes","poisson_maigre","volaille","frit","asperge","fromage_frais"],"eviter":["viande_rouge","gibier","chocolat"],"classique":"Grüner Veltliner du Kremstal et poulet pané","note":"Autour de la ville de Krems, à la sortie de la Wachau : terrasses de roche primaire en amont, loess épais en aval vers Rohrendorf. Appellation DAC (contrôlée) réservée au Grüner Veltliner et au Riesling. Vins secs, nets, moins chers que la Wachau, parfaits sur une cuisine viennoise frite ou panée.","lat":48.41,"lon":15.61,"importance":3,"niveau":"classique"},{"id":"at-weinviertel-gruner-veltliner","nom":"Weinviertel Grüner Veltliner","pays":"Autriche","region":"Basse-Autriche","sousRegion":"Weinviertel","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Grüner Veltliner"],"style":"Poivre blanc marqué (Pfefferl), pomme verte, agrumes, herbe ; sec, léger, vif, désaltérant.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":1,"accords":["legumes","poisson_maigre","charcuterie","frit","asperge","fromage_frais"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Weinviertel DAC et saucisse viennoise au raifort","note":"Le « quartier du vin », vaste plateau au nord-est de Vienne jusqu'à la frontière tchèque, première appellation DAC d'Autriche en 2003. Le Grüner Veltliner y est à son plus poivré et à son plus simple : vin de Heuriger, les guinguettes de vignerons. À boire jeune, frais, sur les casse-croûte.","lat":48.67,"lon":16.63,"importance":3,"niveau":"classique"},{"id":"at-wagram","nom":"Wagram","pays":"Autriche","region":"Basse-Autriche","sousRegion":"Wagram","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Grüner Veltliner","Roter Veltliner","Riesling"],"style":"Pomme jaune, poivre, miel d'acacia, amande ; sec, rond, charnu sur loess, acidité modérée.","temp":"9 à 11 °C","garde":"3 à 10 ans","prix":2,"accords":["volaille","porc","legumes","champignon","creme","fromage_dure"],"eviter":["viande_rouge","gibier","chocolat"],"classique":"Grüner Veltliner du Wagram et rôti de porc au cumin","note":"Longue terrasse de loess au nord du Danube, entre Kamptal et Vienne, autour de Fels et Feuersbrunn. Le loess, poussière éolienne profonde, donne des Grüner Veltliner ronds et nourris ; le Roter Veltliner, cépage ancien à peau rose, est la spécialité locale. À servir sur un rôti de porc.","lat":48.44,"lon":15.81,"importance":2,"niveau":"decouverte"},{"id":"at-thermenregion","nom":"Thermenregion (Zierfandler, Rotgipfler)","pays":"Autriche","region":"Basse-Autriche","sousRegion":"Gumpoldskirchen","couleur":"blanc","famille":"blanc_aromatique","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"St. Laurent et Pinot noir de Tattendorf, rouges fins du sud de la région"}],"cepages":["Zierfandler","Rotgipfler"],"style":"Coing, pêche, miel, épices ; sec ou presque, corsé, rond, aromatique, acidité modérée.","temp":"10 à 12 °C","garde":"3 à 10 ans","prix":2,"accords":["volaille","porc","epice_douce","asiatique","fromage_lave","creme"],"eviter":["huitre","viande_rouge","chocolat"],"classique":"Zierfandler de Gumpoldskirchen et poulet à la crème au paprika","note":"Au sud de Vienne, le long des stations thermales de Baden, Gumpoldskirchen cultive deux cépages qu'on ne trouve presque nulle part ailleurs : Zierfandler et Rotgipfler, souvent assemblés. Blancs ronds et parfumés, proches d'un Pinot gris sec. À servir sur une volaille en sauce ou un plat épicé.","lat":48.04,"lon":16.28,"importance":1,"niveau":"decouverte"},{"id":"at-burgenland-blaufrankisch","nom":"Burgenland Blaufränkisch","pays":"Autriche","region":"Burgenland","sousRegion":"Mittelburgenland","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Blaufränkisch"],"style":"Cerise noire, mûre, poivre, graphite ; corsé, tanins fermes, acidité vive, finale fraîche et épicée.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["gibier","agneau","viande_rouge","mijote","grille","fromage_dure"],"eviter":["huitre","poisson_maigre","chocolat"],"classique":"Blaufränkisch et goulasch de bœuf au paprika","note":"Le Mittelburgenland, près de la frontière hongroise, s'appelle « Blaufränkischland » : sols d'argile lourde et climat pannonien chaud. Le cépage (Kékfrankos en Hongrie, Lemberger en Allemagne) donne le grand rouge d'Autriche, structuré et frais. À servir sur un goulasch, un gibier ou un agneau.","lat":47.6,"lon":16.63,"importance":3,"niveau":"classique"},{"id":"at-burgenland-zweigelt","nom":"Burgenland Zweigelt","pays":"Autriche","region":"Burgenland","sousRegion":"Neusiedlersee","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Zweigelt"],"style":"Cerise griotte, violette, poivre doux ; souple, charnu, tanins ronds, acidité modérée, facile à boire.","temp":"14 à 16 °C","garde":"2 à 8 ans","prix":1,"accords":["charcuterie","porc","volaille","mijote","grille","fromage_molle"],"eviter":["huitre","poisson_maigre","chocolat"],"classique":"Zweigelt et Schnitzel de porc ou côtelette grillée","note":"Cépage créé en 1922 par Fritz Zweigelt, croisement de Blaufränkisch et St. Laurent : le rouge le plus planté d'Autriche. Autour du lac de Neusiedl, lac plat et chaud, il donne un rouge gourmand à la cerise, vendu DAC sous le nom Neusiedlersee. À servir légèrement frais sur une viande simple.","lat":47.9,"lon":16.91,"importance":3,"niveau":"classique"},{"id":"at-ruster-ausbruch","nom":"Ruster Ausbruch","pays":"Autriche","region":"Burgenland","sousRegion":"Rust","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Furmint","Welschriesling","Weissburgunder","Chardonnay"],"style":"Abricot confit, miel, coing, zeste d'orange ; liquoreux, rôti (botrytis), acidité tendue, longue finale.","temp":"8 à 10 °C","garde":"10 à 30 ans","prix":3,"accords":["foie_gras","fromage_bleu","patisserie","fruits_jaunes","caramel","noix"],"eviter":["viande_rouge","chocolat","vinaigre"],"classique":"Ruster Ausbruch et foie gras ou gâteau aux noix","note":"La ville libre de Rust, sur la rive ouest du lac de Neusiedl, fait depuis le XVIIe siècle un liquoreux à partir de baies botrytisées, les brumes du lac favorisant la pourriture noble. Ausbruch (« tri ») est une mention protégée, DAC depuis 2020, proche du Tokaji. À servir frais, en fin de repas.","lat":47.8,"lon":16.67,"importance":2,"niveau":"decouverte"},{"id":"at-steiermark-sauvignon-blanc","nom":"Styrie Sauvignon blanc","pays":"Autriche","region":"Styrie","sousRegion":"Südsteiermark","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Gelber Muskateller et Morillon (Chardonnay), les deux autres blancs styriens"}],"cepages":["Sauvignon blanc"],"style":"Cassis frais, sureau, pamplemousse, poivron ; sec, vif, mûr, plus charnu et moins herbacé que la Loire.","temp":"8 à 10 °C","garde":"2 à 8 ans","prix":2,"accords":["fromage_chevre","asperge","poisson_maigre","crustace","herbes","legumes"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Sauvignon blanc de Styrie et salade à l'huile de pépins de courge","note":"Collines raides et vertes du sud de la Styrie, à la frontière slovène, autour de Gamlitz et Leutschach : climat frais et humide, sols de calcaire et de schiste. Le Sauvignon blanc y est planté depuis l'archiduc Jean (1822) et y atteint une maturité rare. À servir frais sur la cuisine verte locale.","lat":46.72,"lon":15.55,"importance":3,"niveau":"classique"},{"id":"at-schilcher","nom":"Schilcher","pays":"Autriche","region":"Styrie","sousRegion":"Weststeiermark","couleur":"rose","famille":"rose","variantes":[{"couleur":"bulles","famille":"bulles","note":"Schilcher Sekt, rosé effervescent très vif"}],"cepages":["Blauer Wildbacher"],"style":"Fraise des bois, groseille, rhubarbe ; rosé très pâle, sec, acidité mordante, léger, nerveux.","temp":"8 à 10 °C","garde":"1 à 2 ans","prix":2,"accords":["charcuterie","frit","legumes","fromage_frais","acide","vinaigre"],"eviter":["viande_rouge","chocolat","sucre_sale"],"classique":"Schilcher et Brettljause, la planche de charcuterie styrienne","note":"Rosé de la Styrie occidentale, autour de Stainz et Deutschlandsberg, issu du seul Blauer Wildbacher, cépage local. Son nom vient de « schillern », chatoyer, pour sa couleur œil-de-perdrix. Très acide, presque mordant, il se boit jeune et glacé sur une planche de charcuterie ou une friture.","lat":46.9,"lon":15.26,"importance":2,"niveau":"decouverte"},{"id":"at-wien-gemischter-satz","nom":"Vienne Gemischter Satz","pays":"Autriche","region":"Vienne","sousRegion":"Nussberg","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Grüner Veltliner","Riesling","Weissburgunder","Traminer"],"style":"Fleurs, pomme, agrumes, épices légères ; sec, frais, complexe sans bois, plusieurs cépages en un seul verre.","temp":"8 à 10 °C","garde":"1 à 5 ans","prix":2,"accords":["charcuterie","legumes","poisson_maigre","volaille","fromage_frais","oeuf"],"eviter":["viande_rouge","gibier","chocolat"],"classique":"Gemischter Satz et planche de Heuriger (fromages, charcuterie)","note":"Vienne est la seule capitale avec un vignoble sérieux dans ses limites, sur les collines de Nussberg et Bisamberg. Le Gemischter Satz est un « ensemble mélangé » : au moins trois cépages plantés dans la même parcelle, vendangés et vinifiés ensemble, DAC depuis 2013. Vin de guinguette, servi frais.","lat":48.26,"lon":16.35,"importance":2,"niveau":"decouverte"},{"id":"bo-tarija","nom":"Tarija","pays":"Bolivie","region":"Tarija","sousRegion":"Valle Central de Tarija","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Moscatel de Alejandría sec, floral, base du singani"}],"cepages":["Tannat","Cabernet Sauvignon","Syrah","Moscatel de Alejandría"],"style":"Tannat d'altitude, mûre, cassis, violette, tanins marqués mais frais, acidité vive, alcool contenu.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","agneau","grille","mijote","fromage_dure"],"eviter":["poisson_maigre","coquillage"],"classique":"Tannat de Tarija et pique macho (bœuf, saucisse, pommes de terre)","note":"Entre 1 800 et 2 400 m, la vallée de Tarija concentre l'essentiel du vignoble bolivien, l'un des plus hauts du monde. Le tannat y gagne en fraîcheur et en acidité grâce aux nuits froides ; le moscatel sert surtout au singani, l'eau-de-vie nationale. Rouges à servir sur viandes grillées.","lat":-21.53,"lon":-64.73,"importance":1,"niveau":"decouverte"},{"id":"br-serra-gaucha-espumante","nom":"Serra Gaúcha effervescent","pays":"Brésil","region":"Rio Grande do Sul","sousRegion":"Serra Gaúcha","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Moscatel espumante, doux, floral et léger en alcool"}],"cepages":["Chardonnay","Pinot Noir","Riesling Italico","Moscato"],"style":"Bulles fines et fraîches, pomme verte, agrumes, brioche légère, bouche vive et peu dosée.","temp":"6 à 8 °C","garde":"1 à 4 ans","prix":2,"accords":["frit","crustace","poisson_cru","fromage_frais","volaille"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Espumante de la Serra Gaúcha et beignets de crevettes","note":"Colonisée par des Italiens de Vénétie à partir de 1875, la Serra Gaúcha, humide et en altitude, est le vignoble principal du Brésil. Les effervescents, surtout de méthode traditionnelle à Garibaldi, en sont la réussite la plus régulière : frais et peu dosés, parfaits à l'apéritif ou sur une friture.","lat":-29.26,"lon":-51.53,"importance":2,"niveau":"decouverte"},{"id":"br-vale-dos-vinhedos","nom":"Vale dos Vinhedos","pays":"Brésil","region":"Rio Grande do Sul","sousRegion":"Serra Gaúcha","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"bulles","famille":"bulles","note":"Effervescents de méthode traditionnelle, chardonnay et pinot noir"},{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay boisé, rond et mûr"}],"cepages":["Merlot","Cabernet Sauvignon","Chardonnay","Tannat"],"style":"Merlot souple, prune, cerise noire, note herbacée et boisée, tanins ronds, acidité moyenne.","temp":"16 à 17 °C","garde":"3 à 8 ans","prix":2,"accords":["viande_rouge","porc","volaille","mijote","fromage_molle"],"eviter":["poisson_cru","huitre"],"classique":"Merlot du Vale dos Vinhedos et churrasco de picanha","note":"Premier vignoble brésilien reconnu en appellation d'origine (2012), le Vale dos Vinhedos s'étend entre Bento Gonçalves et Garibaldi, sur des collines à 600 m. Le merlot y est le rouge obligatoire des assemblages : souple et frais, il convient aux viandes rôties et au churrasco.","lat":-29.19,"lon":-51.56,"importance":2,"niveau":"decouverte"},{"id":"bg-melnik","nom":"Melnik","pays":"Bulgarie","region":"Vallée de la Struma","sousRegion":"Melnik","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Shiroka Melnishka Loza élevée longuement en fût : tabac, cuir, cerise confite, garde de 10 ans."}],"cepages":["Shiroka Melnishka Loza","Melnik 55","Cabernet Sauvignon"],"style":"Rouge souple et épicé : cerise mûre, tabac, cuir, herbes sèches ; tanins fins, chaleur méditerranéenne.","temp":"15 à 17 °C","garde":"3 à 10 ans","prix":1,"accords":["grille","agneau","porc","charcuterie","mijote","fromage_dure"],"eviter":["huitre","poisson_cru","patisserie"],"classique":"Melnik et kebapche (brochettes de viande hachée) grillés","note":"Melnik, la plus petite ville de Bulgarie, est blottie dans des pyramides de sable au sud-ouest du pays, sous un climat déjà méditerranéen. Le cépage local, Shiroka Melnishka Loza (« vigne de Melnik à larges feuilles »), donne un rouge de tabac et de cerise. À boire sur les grillades balkaniques.","lat":41.52,"lon":23.4,"importance":2,"niveau":"decouverte"},{"id":"ca-okanagan-valley","nom":"Okanagan Valley","pays":"Canada","region":"Colombie-Britannique","sousRegion":"Okanagan Valley","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Pinot gris et riesling, fruit net et fraîcheur ; cépage blanc le plus planté de la vallée."},{"couleur":"doux","famille":"blanc_doux","note":"Icewines de riesling et de vidal, plus rares qu'au Niagara."}],"cepages":["Merlot","Pinot gris","Syrah","Chardonnay"],"style":"Cerise noire, cassis, cacao et note herbacée ; fruité et net, acidité vive, tanins souples.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":3,"accords":["viande_rouge","volaille","porc","grille","roti","fromage_dure"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Merlot de l'Okanagan et saumon sockeye grillé","note":"Vallée de Colombie-Britannique de 250 km le long d'un lac, semi-désertique au sud (Osoyoos), fraîche au nord (Kelowna) ; été court, journées très longues. Merlot, syrah et pinot noir en rouge, pinot gris et riesling en blanc. Vins francs, peu exportés, à goûter sur un saumon ou une viande grillée.","lat":49.49,"lon":-119.59,"importance":3,"niveau":"classique"},{"id":"ca-tidal-bay","nom":"Tidal Bay (Nouvelle-Écosse)","pays":"Canada","region":"Nouvelle-Écosse","sousRegion":"Vallée de l'Annapolis","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"bulles","famille":"bulles","note":"Effervescents de méthode traditionnelle très tendus (Benjamin Bridge)."}],"cepages":["L'Acadie blanc","Seyval blanc","Vidal","Geisenheim"],"style":"Pomme verte, agrumes, fleurs blanches et note saline ; sec, léger (11 % environ), acidité très vive.","temp":"7 à 9 °C","garde":"1 à 3 ans","prix":2,"accords":["huitre","coquillage","crustace","poisson_maigre","vapeur","fromage_frais"],"eviter":["viande_rouge","sauce_vin_rouge","mijote"],"classique":"Tidal Bay et huîtres de la baie de Malpeque","note":"Première appellation de Nouvelle-Écosse (2012) : blanc d'assemblage sec et léger, produit sous un cahier des charges strict, validé par un jury. Climat maritime frais, baie de Fundy, cépages hybrides (L'Acadie blanc). Vin vif et salin, fait pour les huîtres et fruits de mer atlantiques.","lat":45.09,"lon":-64.37,"importance":1,"niveau":"decouverte"},{"id":"ca-niagara-peninsula","nom":"Niagara Peninsula","pays":"Canada","region":"Ontario","sousRegion":"Niagara Peninsula","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Pinot noir et gamay, cerise et fraîcheur ; cabernet franc plus structuré."},{"couleur":"bulles","famille":"bulles","note":"Effervescents de méthode traditionnelle en plein essor."}],"cepages":["Riesling","Chardonnay","Pinot noir","Cabernet franc"],"style":"Citron, pomme verte, pierre mouillée pour le riesling ; blancs tendus, acidité vive, alcool modéré.","temp":"8 à 10 °C","garde":"3 à 10 ans","prix":2,"accords":["poisson_maigre","crustace","huitre","volaille","asiatique","fromage_chevre"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Riesling du Niagara et perche des Grands Lacs","note":"Entre lac Ontario et escarpement du Niagara, le lac tempère les hivers et retarde les gelées d'automne. Première région viticole du Canada, réputée pour ses rieslings et chardonnays de climat frais, pinots noirs et cabernets francs. À servir frais sur un poisson de lac ou des fruits de mer.","lat":43.17,"lon":-79.3,"importance":3,"niveau":"classique"},{"id":"ca-prince-edward-county","nom":"Prince Edward County","pays":"Canada","region":"Ontario","sousRegion":"Prince Edward County","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Chardonnay tendu sur calcaire, de style chablisien."},{"couleur":"bulles","famille":"bulles","note":"Effervescents de méthode traditionnelle, chardonnay et pinot noir."}],"cepages":["Pinot noir","Chardonnay"],"style":"Cerise rouge, groseille, note terreuse et minérale ; léger, acidité vive, tanins fins.","temp":"13 à 15 °C","garde":"3 à 8 ans","prix":3,"accords":["volaille","poisson_gras","champignon","canard","fromage_molle","legumes"],"eviter":["viande_rouge","piquant","fromage_bleu"],"classique":"Pinot noir du County et truite du lac Ontario","note":"Presqu'île du lac Ontario, à l'est de Toronto, sur un calcaire proche de celui de Chablis. Hivers si rudes que les vignes sont enterrées chaque automne. Jeune région (2007), où pinot noir et chardonnay donnent des vins légers, minéraux. À servir frais sur un poisson de lac ou une volaille.","lat":43.95,"lon":-77.35,"importance":1,"niveau":"decouverte"},{"id":"ca-icewine","nom":"Icewine canadien","pays":"Canada","region":"Ontario et Colombie-Britannique","sousRegion":"Niagara Peninsula","couleur":"doux","famille":"blanc_doux","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Icewine rouge de cabernet franc : fraise et rhubarbe confites, acidité vive."}],"cepages":["Vidal","Riesling","Cabernet franc"],"style":"Abricot, mangue, miel et litchi, très sucré mais tendu par une acidité vive ; texture huileuse, finale longue.","temp":"6 à 8 °C","garde":"5 à 15 ans","prix":4,"accords":["foie_gras","fromage_bleu","fruits_exotiques","patisserie","fruits_jaunes","caramel"],"eviter":["viande_rouge","piquant","chocolat"],"classique":"Icewine de Vidal et foie gras poêlé","note":"Vendangé à la main à moins 8 °C au plus, souvent de nuit, sur raisins gelés sur pied : l'eau reste en glace, seul le jus concentré s'écoule. Le Canada, surtout le Niagara, en est le premier producteur mondial. En demi-bouteille, servi très frais, sur un foie gras ou un dessert aux fruits.","lat":43.2,"lon":-79.2,"importance":4,"niveau":"incontournable"},{"id":"cl-aconcagua","nom":"Aconcagua","pays":"Chili","region":"Aconcagua","sousRegion":"Vallée de l'Aconcagua","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Aconcagua Costa : sauvignon et chardonnay tendus près de l'océan"}],"cepages":["Cabernet Sauvignon","Syrah","Carménère","Sauvignon Blanc"],"style":"Cassis, cèdre, poivre noir et réglisse, bouche dense, tanins puissants et mûrs, élevage marqué.","temp":"17 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["viande_rouge","agneau","gibier","roti","fromage_dure"],"eviter":["poisson_maigre","coquillage"],"classique":"Rouge d'Aconcagua et gigot d'agneau rôti","note":"Vallée chaude et sèche au pied du plus haut sommet des Amériques, l'Aconcagua est la maison d'Errázuriz depuis 1870. Les grands assemblages cabernet-syrah y sont taillés pour la garde ; la partie côtière, plus fraîche, donne depuis 2005 des blancs tendus.","lat":-32.78,"lon":-70.85,"importance":3,"niveau":"classique"},{"id":"cl-casablanca-valley","nom":"Casablanca","pays":"Chili","region":"Aconcagua","sousRegion":"Vallée de Casablanca","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Pinot noir frais et fruité, cerise et sous-bois"},{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay tendu, légèrement boisé"}],"cepages":["Sauvignon Blanc","Chardonnay","Pinot Noir"],"style":"Sauvignon vif, citron vert, herbe coupée, piment vert, bouche saline et droite.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":2,"accords":["poisson_maigre","crustace","fromage_chevre","asperge","herbes"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Sauvignon de Casablanca et ceviche de poisson blanc","note":"Première vallée côtière plantée au Chili dans les années 1980, Casablanca profite des brouillards du Pacifique qui retardent la maturité. Son sauvignon blanc se reconnaît à ses notes herbacées et sa salinité : à servir frais sur un ceviche ou des crustacés.","lat":-33.32,"lon":-71.41,"importance":3,"niveau":"classique"},{"id":"cl-leyda","nom":"Leyda","pays":"Chili","region":"Aconcagua","sousRegion":"Vallée de San Antonio","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Pinot noir et syrah de climat froid, poivre et fruits rouges"}],"cepages":["Sauvignon Blanc","Pinot Noir","Chardonnay","Syrah"],"style":"Sauvignon tranchant, pamplemousse, feuille de tomate, iode, acidité élevée et finale saline.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":2,"accords":["huitre","coquillage","poisson_cru","poisson_maigre","acide"],"eviter":["viande_rouge","fromage_bleu"],"classique":"Sauvignon de Leyda et huîtres au citron vert","note":"À une dizaine de kilomètres du Pacifique, Leyda est l'une des zones les plus froides du vignoble chilien, plantée seulement depuis 1998. Ses sauvignons iodés et ses pinots noirs tendus conviennent aux coquillages et poissons crus, servis bien frais.","lat":-33.59,"lon":-71.46,"importance":3,"niveau":"classique"},{"id":"cl-elqui","nom":"Elqui","pays":"Chili","region":"Coquimbo","sousRegion":"Vallée de l'Elqui","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Pedro Ximénez et sauvignon secs, vifs et citronnés"}],"cepages":["Syrah","Carménère","Pedro Ximénez","Sauvignon Blanc"],"style":"Syrah poivrée et fraîche, mûre, violette, olive noire, tanins fins, acidité tonique d'altitude.","temp":"15 à 17 °C","garde":"4 à 10 ans","prix":2,"accords":["viande_rouge","agneau","grille","epice_douce","mediterraneen"],"eviter":["poisson_maigre","fromage_frais"],"classique":"Syrah de l'Elqui et brochettes d'agneau aux épices","note":"Vallée étroite et désertique du nord du Chili, l'Elqui est surtout connue pour le pisco et ses ciels purs d'observatoires. Les vignes de syrah, plantées jusqu'à 2 000 m d'altitude, donnent des rouges poivrés et frais, à servir légèrement rafraîchis sur des grillades épicées.","lat":-30.03,"lon":-70.71,"importance":2,"niveau":"decouverte"},{"id":"cl-limari","nom":"Limarí","pays":"Chili","region":"Coquimbo","sousRegion":"Vallée du Limarí","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Syrah poivrée et fraîche sur sols calcaires"}],"cepages":["Chardonnay","Syrah","Sauvignon Blanc"],"style":"Chardonnay tendu et crayeux, citron, pierre à fusil, bois fondu, finale saline persistante.","temp":"10 à 12 °C","garde":"3 à 8 ans","prix":2,"accords":["poisson_gras","crustace","volaille","creme","champignon"],"eviter":["piquant","sauce_vin_rouge"],"classique":"Chardonnay du Limarí et saumon à la crème","note":"Aux marges du désert d'Atacama, le Limarí combine sols calcaires rares au Chili et brume matinale venue de l'océan. Son chardonnay, proche d'un Chablis boisé, se reconnaît à sa tension crayeuse : il accompagne poissons gras et volailles en sauce.","lat":-30.6,"lon":-71.2,"importance":2,"niveau":"decouverte"},{"id":"cl-itata","nom":"Itata","pays":"Chili","region":"Sud","sousRegion":"Vallée de l'Itata","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Moscatel de Alejandría sec, floral et vieilles vignes"}],"cepages":["País","Cinsault","Moscatel de Alejandría"],"style":"Rouge léger et digeste, fraise écrasée, poivre, tanins fins un peu rustiques, acidité vive.","temp":"13 à 15 °C","garde":"1 à 5 ans","prix":2,"accords":["charcuterie","volaille","legumes","grille","fromage_frais"],"eviter":["gibier","sauce_vin_rouge"],"classique":"País de l'Itata et empanadas de viande au four","note":"Berceau du vignoble chilien au XVIe siècle, l'Itata conserve des vieilles vignes en gobelet, non irriguées, de país et de cinsault sur granit. Longtemps vendus en vrac, ces rouges légers et peu extraits sont redevenus une référence des vins nature : à servir frais.","lat":-36.52,"lon":-72.45,"importance":3,"niveau":"classique"},{"id":"cl-bio-bio","nom":"Bío-Bío","pays":"Chili","region":"Sud","sousRegion":"Vallée du Bío-Bío","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Riesling et gewurztraminer de climat frais, secs et floraux"}],"cepages":["Pinot Noir","Riesling","Gewurztraminer","Chardonnay"],"style":"Pinot noir pâle et frais, cerise, framboise, note de sous-bois, tanins soyeux, acidité marquée.","temp":"13 à 15 °C","garde":"2 à 6 ans","prix":2,"accords":["volaille","canard","champignon","poisson_gras","fromage_molle"],"eviter":["piquant","viande_rouge"],"classique":"Pinot noir du Bío-Bío et canard aux champignons","note":"À 500 km au sud de Santiago, le Bío-Bío est pluvieux et venteux, avec de vrais hivers : un climat proche de la Bourgogne ou de l'Alsace. Le pinot noir y donne des rouges légers et acidulés, les cépages germaniques des blancs secs, à découvrir sur volailles et champignons.","lat":-37.55,"lon":-72.45,"importance":2,"niveau":"decouverte"},{"id":"cl-colchagua-carmenere","nom":"Colchagua Carménère","pays":"Chili","region":"Vallée Centrale","sousRegion":"Vallée de Colchagua","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Carménère","Cabernet Sauvignon","Syrah"],"style":"Mûre, poivron rouge grillé, moka et paprika, bouche veloutée, tanins ronds, peu d'acidité.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["viande_rouge","porc","mijote","epice_douce","charcuterie"],"eviter":["poisson_cru","coquillage"],"classique":"Carménère de Colchagua et porc braisé aux épices douces","note":"Cépage bordelais disparu après le phylloxéra, le carménère a été réidentifié au Chili en 1994 parmi les merlots. Colchagua, chaude et ensoleillée, le mûrit pleinement : rond, épicé, peu tannique, il accompagne viandes mijotées et plats relevés en douceur.","lat":-34.64,"lon":-71.36,"importance":4,"niveau":"incontournable"},{"id":"cl-maipo-cabernet-sauvignon","nom":"Maipo Cabernet Sauvignon","pays":"Chili","region":"Vallée Centrale","sousRegion":"Vallée du Maipo","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Carménère","Cabernet Franc"],"style":"Cassis, menthol et eucalyptus, tanins serrés mais mûrs, bois discret, finale longue et fraîche.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["viande_rouge","agneau","grille","roti","fromage_dure"],"eviter":["poisson_maigre","huitre"],"classique":"Cabernet du Maipo et entrecôte grillée au feu de bois","note":"Aux portes de Santiago, les galets du Maipo et la fraîcheur des Andes signent le cabernet de référence du Chili. Reconnaissable à sa note mentholée et à ses tanins fins, il s'ouvre après carafage et brille sur les viandes rouges grillées.","lat":-33.62,"lon":-70.6,"importance":4,"niveau":"incontournable"},{"id":"cl-cachapoal","nom":"Cachapoal","pays":"Chili","region":"Vallée Centrale","sousRegion":"Vallée du Cachapoal (Rapel)","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Carménère","Cabernet Sauvignon","Syrah","Merlot"],"style":"Fruits noirs mûrs, poivron grillé, chocolat et tabac, bouche ronde et charnue, tanins enrobés.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","porc","mijote","charcuterie","fromage_dure"],"eviter":["poisson_cru","huitre"],"classique":"Carménère de Cachapoal et côte de porc au four","note":"Moitié nord de la vallée du Rapel, le Cachapoal est plus discret que sa voisine Colchagua mais partage ses sols d'alluvions. Peumo, sur les rives du fleuve, est tenu pour l'un des meilleurs lieux au monde pour le carménère : rouges ronds, charnus, faciles sur viandes mijotées.","lat":-34.33,"lon":-71.0,"importance":2,"niveau":"decouverte"},{"id":"cl-maule-carignan","nom":"Maule Carignan","pays":"Chili","region":"Vallée Centrale","sousRegion":"Vallée du Maule","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Carignan","País","Cabernet Sauvignon"],"style":"Mûre sauvage, violette, graphite et poivre, acidité haute, tanins francs et serrés, finale longue.","temp":"16 à 18 °C","garde":"5 à 12 ans","prix":2,"accords":["viande_rouge","agneau","gibier","mijote","fromage_dure"],"eviter":["poisson_maigre","huitre"],"classique":"Carignan du Maule et agneau braisé aux herbes","note":"Planté après le séisme de 1939 pour renforcer le país, le carignan du Maule pousse en sec sur des vignes de plus de cinquante ans. Le collectif VIGNO (2010) impose vieilles vignes et sec : on reconnaît ces rouges à leur acidité et leur côté sauvage, parfaits sur l'agneau.","lat":-35.97,"lon":-72.32,"importance":2,"niveau":"decouverte"},{"id":"cn-ningxia","nom":"Ningxia (Helan Shan)","pays":"Chine","region":"Ningxia","sousRegion":"Piémont est des monts Helan","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot","Marselan","Cabernet Gernischt"],"style":"Cassis, prune, épices douces, boisé vanillé ; corps plein, tanins mûrs et polis, finale chaleureuse.","temp":"16 à 18 °C","garde":"4 à 12 ans","prix":3,"accords":["viande_rouge","agneau","roti","grille","sauce_vin_rouge","fromage_dure"],"eviter":["huitre","poisson_cru","vapeur"],"classique":"Cabernet de Ningxia et agneau grillé au cumin","note":"Sur le piémont est des monts Helan, en bordure du désert de Gobi, le Ningxia est la région phare du vin chinois : 1 100 m d'altitude, sols caillouteux, vignes enterrées chaque hiver contre le gel. Helan Qing Xue a surpris Londres en 2011 ; le Marselan y devient une signature.","lat":38.49,"lon":106.23,"importance":3,"niveau":"classique"},{"id":"cy-commandaria","nom":"Commandaria","pays":"Chypre","region":"Limassol","sousRegion":"Villages de la Commandaria (Troodos)","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Mavro","Xynisteri"],"style":"Doux ambré, oxydatif : raisin sec, figue, caramel, miel, noix, épices ; sucre dense, acidité fine.","temp":"12 à 14 °C","garde":"10 à 50 ans","prix":2,"accords":["fromage_bleu","noix","patisserie","caramel","chocolat","foie_gras"],"eviter":["huitre","poisson_maigre","acide"],"classique":"Commandaria et halloumi grillé ou pâtisserie aux amandes","note":"Produite dans quatorze villages des pentes sud du Troodos, la Commandaria est la plus ancienne appellation encore en activité : son nom vient de la commanderie des Hospitaliers (XIIe siècle). Mavro et Xynisteri sèchent au soleil, puis le vin, souvent muté, vieillit au moins deux ans.","lat":34.82,"lon":33.05,"importance":3,"niveau":"classique"},{"id":"hr-dingac","nom":"Dingač","pays":"Croatie","region":"Dalmatie","sousRegion":"Presqu'île de Pelješac","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Plavac Mali"],"style":"Rouge puissant et solaire : figue, cerise noire confite, garrigue, cacao ; tanins fermes, alcool élevé.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":3,"accords":["agneau","grille","viande_rouge","gibier","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_cru","fruits_exotiques"],"classique":"Dingač et agneau sous la cloche (peka) de Pelješac","note":"Dingač est un versant très raide de la presqu'île de Pelješac, exposé plein sud au-dessus de l'Adriatique et cultivé à la main. Le Plavac Mali, descendant du Zinfandel, y concentre figue et cerise noire à 14 ou 15 degrés. Premier cru protégé de Croatie (1961), vin d'agneau et de grillades.","lat":42.95,"lon":17.37,"importance":3,"niveau":"classique"},{"id":"hr-korcula-posip","nom":"Korčula Pošip","pays":"Croatie","region":"Dalmatie","sousRegion":"Île de Korčula","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Pošip"],"style":"Blanc sec et charnu : abricot, figue fraîche, amande, herbes séchées ; corps ample, alcool généreux, finale saline.","temp":"10 à 12 °C","garde":"2 à 6 ans","prix":2,"accords":["poisson_gras","crustace","grille","mediterraneen","fromage_dure","legumes"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Pošip de Korčula et poisson grillé à l'huile d'olive","note":"Le Pošip est natif de l'île de Korčula, en Dalmatie du Sud, où il pousse dans les champs de Čara et Smokvica entourés de murets. Blanc plus riche que ceux du nord, abricot et amande, mais avec le sel de la mer. Le vin de la table dalmate : poisson grillé, poulpe, fromage de brebis de Pag.","lat":42.93,"lon":16.9,"importance":2,"niveau":"decouverte"},{"id":"hr-istra-malvazija","nom":"Istrie Malvazija","pays":"Croatie","region":"Istrie","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Malvazija macérée ou élevée en acacia : plus ambrée, notes d'abricot sec et d'amande."},{"couleur":"rouge","famille":"rouge_souple","note":"Teran : rouge acide et rustique sur terre rouge, mûre, fer, à boire sur charcuteries."}],"cepages":["Malvazija istarska"],"style":"Blanc sec, frais et floral : acacia, pomme, poire, amande fraîche, pointe saline ; acidité moyenne, finale nette.","temp":"9 à 11 °C","garde":"1 à 4 ans","prix":2,"accords":["coquillage","poisson_maigre","crustace","truffe","legumes","mediterraneen"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Malvazija d'Istrie et fuži à la truffe de Motovun","note":"La Malvazija istarska est le cépage blanc de la péninsule d'Istrie, sur terres rouges et calcaire blanc. Sans parenté avec les autres malvoisies, elle donne un blanc frais, floral et un peu salé. Vin de coquillages et de pâtes à la truffe blanche des forêts de Motovun, à boire jeune.","lat":45.34,"lon":13.83,"importance":2,"niveau":"decouverte"},{"id":"es-jerez-fino-manzanilla","nom":"Jerez fino et manzanilla (Xérès)","pays":"Espagne","region":"Andalousie","sousRegion":"Marco de Jerez","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Palomino fino"],"style":"Amande, pomme verte, levure, iode ; sec, très pâle, 15 %, élevé sous un voile de levures (flor). Manzanilla pasada et fino en rama : plus vieux ou non filtrés, plus intenses, amande et sel.","temp":"6 à 8 °C","garde":"1 à 2 ans","prix":2,"accords":["huitre","coquillage","crustace","frit","charcuterie","noix"],"eviter":["chocolat","sucre_sale","patisserie"],"classique":"Manzanilla de Sanlúcar et beignets de crevettes (tortillitas de camarones)","note":"Triangle Jerez, Sanlúcar, El Puerto, sols blancs d'albariza : le Palomino est muté à 15 % puis vieilli sous un voile de levures (flor) en solera. La manzanilla, élevée face à la mer à Sanlúcar, est la plus saline. Toujours sec, servi très froid, c'est le vin des fritures et du jambon ibérique.","lat":36.69,"lon":-6.14,"importance":5,"niveau":"incontournable"},{"id":"es-jerez-amontillado-oloroso","nom":"Jerez amontillado et oloroso (Xérès)","pays":"Espagne","region":"Andalousie","sousRegion":"Marco de Jerez","couleur":"doux","famille":"vdn","variantes":[{"couleur":"doux","famille":"vdn","note":"Palo cortado : entre amontillado et oloroso, rare, fin et puissant"},{"couleur":"doux","famille":"vdn","note":"Cream et medium : olorosos édulcorés au Pedro Ximénez, doux, pour le dessert ou le bleu"}],"cepages":["Palomino fino"],"style":"Noisette, noix, bois ciré, tabac ; secs, ambrés à acajou, 17 à 20 %, longueur rancio.","temp":"12 à 14 °C","garde":"10 à 30 ans","prix":3,"accords":["champignon","fromage_dure","gibier","mijote","noix","abats"],"eviter":["huitre","poisson_cru","glace"],"classique":"Oloroso sec et queue de bœuf mijotée (rabo de toro)","note":"Même Palomino que le fino, mais en élevage oxydatif : l'amontillado a d'abord vieilli sous voile avant de le perdre, l'oloroso est muté à 17 % et vieillit au contact de l'air. Secs et profonds, à servir frais mais non glacés, avec un consommé, des champignons ou un fromage de brebis vieux.","lat":36.69,"lon":-6.14,"importance":4,"niveau":"classique"},{"id":"es-pedro-ximenez","nom":"Pedro Ximénez","pays":"Espagne","region":"Andalousie","sousRegion":"Jerez et Montilla-Moriles","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Pedro Ximénez"],"style":"Raisin sec, figue, café, mélasse ; sirupeux, presque noir, 400 g de sucre par litre et une pointe d'acidité.","temp":"10 à 12 °C","garde":"20 à 50 ans","prix":2,"accords":["chocolat","glace","fromage_bleu","patisserie","caramel","noix"],"eviter":["huitre","poisson_maigre","acide"],"classique":"Pedro Ximénez versé sur une glace à la vanille","note":"Raisins Pedro Ximénez séchés au soleil sur des nattes (asoleo) jusqu'à devenir presque secs, puis mutés et vieillis en solera, à Jerez ou surtout à Montilla-Moriles, qui fournit l'essentiel du raisin. Parmi les vins les plus sucrés du monde, à servir par petits verres sur un dessert au chocolat.","lat":37.59,"lon":-4.64,"importance":3,"niveau":"classique"},{"id":"es-malaga","nom":"Málaga","pays":"Espagne","region":"Andalousie","sousRegion":"Axarquía et Montes de Málaga","couleur":"doux","famille":"vdn","variantes":[{"couleur":"rouge","famille":"rouge_solaire","note":"Sierras de Málaga (Ronda) : rouges secs de Syrah, Cabernet ou Petit Verdot, chaleureux"}],"cepages":["Moscatel de Alejandría","Pedro Ximénez"],"style":"Raisin sec, orange confite, miel, caramel ; doux et ambrés, mutés ou issus de raisins passerillés au soleil.","temp":"10 à 12 °C","garde":"10 à 40 ans","prix":2,"accords":["patisserie","fruits_jaunes","fromage_bleu","noix","caramel","foie_gras"],"eviter":["huitre","poisson_cru","acide"],"classique":"Málaga dulce et tarte aux amandes","note":"Collines de l'Axarquía et des Montes de Málaga, vignes de Moscatel en forte pente sur schiste : vin doux célèbre au XIXe siècle, tombé dans l'oubli, relancé par des domaines comme Telmo Rodríguez (Molino Real). Les Sierras de Málaga (Ronda) produisent aussi des rouges secs. À servir en fin de repas.","lat":36.72,"lon":-4.42,"importance":2,"niveau":"decouverte"},{"id":"es-montilla-moriles","nom":"Montilla-Moriles","pays":"Espagne","region":"Andalousie","sousRegion":"Montilla-Moriles","couleur":"doux","famille":"vdn","variantes":[{"couleur":"doux","famille":"vdn","note":"Amontillado et oloroso de Montilla : noix, caramel, bois, vieillis en solera"}],"cepages":["Pedro Ximénez"],"style":"Fino non muté, amande et pomme, sous voile de flor ; amontillado et oloroso de PX, noix et caramel.","temp":"8 à 12 °C","garde":"1 à 20 ans","prix":2,"accords":["frit","charcuterie","coquillage","noix","fromage_dure","champignon"],"eviter":["chocolat","glace","sucre_sale"],"classique":"Fino de Montilla et salmorejo cordouan","note":"Au sud de Cordoue, à l'intérieur des terres : mêmes styles que le Xérès (fino, amontillado, oloroso, PX) mais à base de Pedro Ximénez, qui atteint naturellement 15 % sans mutage. Vins moins connus et moins chers que ceux de Jerez, à découvrir avec un salmorejo ou une friture andalouse.","lat":37.59,"lon":-4.64,"importance":2,"niveau":"decouverte"},{"id":"es-calatayud","nom":"Calatayud","pays":"Espagne","region":"Aragon","sousRegion":"Calatayud","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Garnacha","Tempranillo","Syrah"],"style":"Framboise mûre, épices, texture soyeuse et chaleur ; Garnacha d'altitude, plus fraîche qu'il n'y paraît.","temp":"16 à 17 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","grille","mijote","charcuterie","fromage_dure","epice_douce"],"eviter":["huitre","poisson_cru","asperge"],"classique":"Garnacha vieilles vignes de Calatayud et agneau grillé","note":"Aragon occidental, vignes entre 600 et 1 000 m sur ardoise et calcaire : des Garnachas plantées avant 1950, longtemps vendues en vrac, donnent des rouges épicés, charnus et étonnamment frais. Un plaisir immédiat sur une grillade d'agneau ou un fromage de brebis affiné.","lat":41.35,"lon":-1.64,"importance":2,"niveau":"decouverte"},{"id":"es-campo-de-borja","nom":"Campo de Borja","pays":"Espagne","region":"Aragon","sousRegion":"Campo de Borja","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Garnacha","Tempranillo","Syrah"],"style":"Fraise écrasée, poivre blanc, bouche ronde et généreuse, tanins doux.","temp":"16 à 17 °C","garde":"3 à 8 ans","prix":1,"accords":["charcuterie","grille","mijote","viande_rouge","mediterraneen","porc"],"eviter":["huitre","poisson_cru","glace"],"classique":"Garnacha de Borja et ragoût de porc aux poivrons","note":"Au pied du Moncayo, entre Saragosse et Tudela : l'appellation se présente comme « l'empire de la Garnacha », avec des vignes de plus de 50 ans sur argile et galets. Rouges gourmands, souvent très bon marché, qui s'accordent avec les ragoûts et les charcuteries. Servir légèrement rafraîchi l'été.","lat":41.83,"lon":-1.53,"importance":2,"niveau":"decouverte"},{"id":"es-carinena","nom":"Cariñena","pays":"Espagne","region":"Aragon","sousRegion":"Cariñena","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Garnacha","Cariñena","Tempranillo","Syrah"],"style":"Fruits noirs confits, garrigue, poivre, alcool généreux ; rond et chaleureux.","temp":"16 à 17 °C","garde":"3 à 8 ans","prix":1,"accords":["mijote","grille","charcuterie","viande_rouge","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_maigre","asperge"],"classique":"Cariñena et migas (pain frit au chorizo) d'Aragon","note":"Vallée de l'Èbre au sud de Saragosse, vent du cierzo et sols caillouteux : berceau du cépage carignan, qui porte le nom de la ville, même si la Garnacha domine aujourd'hui l'encépagement. Rouges solaires, souvent à moins de 10 €, taillés pour un plat mijoté ou une grillade.","lat":41.34,"lon":-1.22,"importance":2,"niveau":"decouverte"},{"id":"es-somontano","nom":"Somontano","pays":"Espagne","region":"Aragon","sousRegion":"Somontano","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Gewurztraminer et Chardonnay de Somontano : litchi, rose, pêche, secs et parfumés"}],"cepages":["Cabernet Sauvignon","Merlot","Tempranillo","Moristel"],"style":"Cassis, poivron, boisé net, tanins ronds ; un style international, propre et fruité.","temp":"16 à 17 °C","garde":"3 à 8 ans","prix":2,"accords":["viande_rouge","porc","grille","roti","fromage_dure","charcuterie"],"eviter":["huitre","poisson_cru","glace"],"classique":"Somontano et ternasco (agneau de lait) d'Aragon rôti","note":"Piémont des Pyrénées aragonaises, autour de Barbastro : appellation jeune (1984), construite par de grands domaines (Viñas del Vero, Enate) autour de cépages internationaux. Rouges nets et modernes, blancs de Gewurztraminer et de Chardonnay : une valeur sûre pour une viande rôtie.","lat":42.04,"lon":0.13,"importance":2,"niveau":"decouverte"},{"id":"es-ribera-del-duero","nom":"Ribera del Duero","pays":"Espagne","region":"Castille-et-León","sousRegion":"Ribera del Duero","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Tempranillo (Tinto fino)","Cabernet Sauvignon","Merlot"],"style":"Fruits noirs, cacao, tanins denses et mûrs ; puissant et pourtant frais grâce à l'altitude et aux nuits froides.","temp":"17 à 18 °C","garde":"5 à 20 ans","prix":3,"accords":["viande_rouge","grille","agneau","gibier","fromage_dure","mijote"],"eviter":["poisson_maigre","huitre","asperge"],"classique":"Ribera del Duero et agneau de lait rôti au four à bois (lechazo)","note":"Haut plateau à 800 m le long du Duero, entre Burgos et Valladolid : nuits froides et étés brûlants donnent un Tempranillo plus sombre et plus tannique que le Rioja. Vega Sicilia a fait la réputation de l'aire dès la fin du XIXe siècle. À carafer, pour une viande rouge grillée ou un gigot.","lat":41.67,"lon":-3.69,"importance":5,"niveau":"incontournable"},{"id":"es-rueda","nom":"Rueda","pays":"Espagne","region":"Castille-et-León","sousRegion":"Rueda","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Verdejo","Sauvignon blanc","Viura"],"style":"Fenouil, pamplemousse, herbe coupée, finale légèrement amère ; sec, vif, désaltérant.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":1,"accords":["poisson_maigre","coquillage","legumes","asperge","fromage_chevre","frit"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Rueda Verdejo et asperges blanches de Tudela","note":"Plateau caillouteux au sud de Valladolid, à 700 m : la Verdejo, cépage local, a été relancée dans les années 1970 par Marqués de Riscal. Son amertume de fenouil la rend reconnaissable à l'aveugle. Blanc d'apéritif et de poisson grillé, à boire dans les deux ans qui suivent la récolte.","lat":41.41,"lon":-4.96,"importance":4,"niveau":"classique"},{"id":"es-bierzo","nom":"Bierzo","pays":"Espagne","region":"Castille-et-León","sousRegion":"Bierzo","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Godello du Bierzo : poire, amande, texture ample et minérale"}],"cepages":["Mencía","Godello"],"style":"Fruits rouges croquants, violette, note de graphite, tanins fins et fraîcheur de montagne.","temp":"15 à 16 °C","garde":"3 à 10 ans","prix":2,"accords":["volaille","porc","charcuterie","champignon","grille","legumes"],"eviter":["huitre","chocolat","piquant"],"classique":"Bierzo Mencía et botillo (charcuterie fumée du Bierzo)","note":"Cuvette entre Galice et Castille, sur le chemin de Compostelle : vieilles vignes de Mencía en coteaux d'ardoise, relancées par Álvaro Palacios et Ricardo Pérez dans les années 2000. Un rouge à mi-chemin entre pinot noir et cabernet franc, à servir frais sur une volaille ou une charcuterie.","lat":42.6,"lon":-6.73,"importance":3,"niveau":"classique"},{"id":"es-toro","nom":"Toro","pays":"Espagne","region":"Castille-et-León","sousRegion":"Toro","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Tinta de Toro (Tempranillo)","Garnacha"],"style":"Mûre, réglisse, alcool généreux, tanins massifs ; un rouge solaire et charpenté qui demande un carafage.","temp":"17 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["viande_rouge","grille","gibier","mijote","fromage_dure","charcuterie"],"eviter":["poisson_maigre","coquillage","cru"],"classique":"Toro et côte de bœuf au feu de bois","note":"Autour de la ville de Toro, province de Zamora : sols de sable et de galets, vieilles vignes franches de pied, climat continental sec. La Tinta de Toro donne des rouges très colorés à 14 ou 15 % d'alcool. Pour une pièce de bœuf ou un ragoût, après une bonne heure de carafe.","lat":41.52,"lon":-5.39,"importance":3,"niveau":"classique"},{"id":"es-cigales","nom":"Cigales","pays":"Espagne","region":"Castille-et-León","sousRegion":"Cigales","couleur":"rose","famille":"rose","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Rouges de Tempranillo, de plus en plus soignés, dans l'ombre de la Ribera voisine"}],"cepages":["Tempranillo","Garnacha","Albillo","Verdejo"],"style":"Fraise, cerise, pointe d'amande ; un rosé « clarete » coloré et vineux, fait pour la table.","temp":"10 à 12 °C","garde":"1 à 3 ans","prix":1,"accords":["charcuterie","grille","legumes","porc","volaille","mediterraneen"],"eviter":["huitre","chocolat","truffe"],"classique":"Clarete de Cigales et chorizo grillé","note":"Au nord de Valladolid, entre Ribera del Duero et Rueda : Cigales est la terre historique du « clarete », rosé obtenu par fermentation commune de raisins rouges et blancs, dans des caves creusées sous les villages. Rosés de repas, plus vineux qu'un rosé de Provence ; les rouges progressent.","lat":41.76,"lon":-4.7,"importance":1,"niveau":"decouverte"},{"id":"es-la-mancha","nom":"La Mancha","pays":"Espagne","region":"Castille-La Manche","sousRegion":"La Mancha","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Airén, cépage blanc le plus planté d'Espagne : neutre, frais, léger, à boire jeune"}],"cepages":["Tempranillo (Cencibel)","Airén","Cabernet Sauvignon","Syrah"],"style":"Fruits rouges simples, touche de vanille, tanins doux ; blancs d'Airén neutres et frais.","temp":"15 à 17 °C","garde":"1 à 4 ans","prix":1,"accords":["charcuterie","fromage_dure","grille","porc","mijote","oeuf"],"eviter":["huitre","poisson_cru","truffe"],"classique":"La Mancha Tempranillo et manchego affiné","note":"Le plus grand vignoble du monde d'un seul tenant, sur le plateau de Don Quichotte entre Tolède et Albacete : Airén blanc pour le brandy et le vrac, Cencibel (Tempranillo) pour des rouges simples et honnêtes à moins de 8 €. À boire jeune, avec un manchego ou une assiette de charcuterie.","lat":39.39,"lon":-3.21,"importance":3,"niveau":"classique"},{"id":"es-mentrida","nom":"Méntrida (Garnacha de Gredos)","pays":"Espagne","region":"Castille-La Manche","sousRegion":"Méntrida","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Garnacha","Tempranillo","Syrah"],"style":"Fraise, pivoine, pierre de granit, tanins fins, 13 à 14 % ; une Garnacha de montagne fraîche et aérienne.","temp":"15 à 16 °C","garde":"3 à 10 ans","prix":2,"accords":["volaille","porc","champignon","charcuterie","grille","legumes"],"eviter":["huitre","chocolat","piquant"],"classique":"Garnacha de Gredos et cochon de lait rôti (cochinillo)","note":"Au nord de Tolède, sur les contreforts granitiques de la sierra de Gredos : vieilles Garnachas à 700 ou 900 m, redécouvertes dans les années 2000 par Daniel Landi et Fernando García. Rouges pâles, floraux et frais, à l'opposé du cliché du rouge espagnol lourd. Servir légèrement rafraîchi.","lat":40.24,"lon":-4.2,"importance":2,"niveau":"decouverte"},{"id":"es-valdepenas","nom":"Valdepeñas","pays":"Espagne","region":"Castille-La Manche","sousRegion":"Valdepeñas","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Tempranillo (Cencibel)","Airén"],"style":"Fraise cuite, vanille, bois américain, tanins fondus ; crianza et gran reserva à petit prix.","temp":"15 à 17 °C","garde":"2 à 8 ans","prix":1,"accords":["charcuterie","porc","fromage_dure","roti","mijote","grille"],"eviter":["huitre","poisson_cru","glace"],"classique":"Valdepeñas reserva et pisto manchego (ratatouille à l'œuf)","note":"Enclave au sud de La Mancha, autour de la ville de Valdepeñas, longtemps le fournisseur de rouge des tavernes de Madrid. L'appellation élève ses Cencibel en fût de chêne américain à la manière du Rioja, pour une fraction du prix. Vins de bistrot, à servir avec les plats de la cuisine castillane.","lat":38.76,"lon":-3.38,"importance":2,"niveau":"decouverte"},{"id":"es-manchuela","nom":"Manchuela","pays":"Espagne","region":"Castille-La Manche","sousRegion":"Manchuela","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Bobal","Tempranillo","Syrah","Macabeo"],"style":"Mûre, graphite, acidité vive, tanins francs ; un Bobal d'altitude, droit et digeste.","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":2,"accords":["charcuterie","porc","mijote","grille","champignon","legumes"],"eviter":["huitre","poisson_cru","glace"],"classique":"Bobal de Manchuela et ajoarriero (morue émiettée à l'ail et à la pomme de terre)","note":"Entre Cuenca et Albacete, à l'est de La Mancha, vignes de 700 à 1 000 m sur calcaire : la Manchuela partage le Bobal avec Utiel-Requena, mais l'altitude donne des rouges plus frais, relancés par le domaine Finca Sandoval. Appellation discrète, à prix doux, pour la charcuterie et les mijotés.","lat":39.42,"lon":-1.75,"importance":1,"niveau":"decouverte"},{"id":"es-cava","nom":"Cava","pays":"Espagne","region":"Catalogne","sousRegion":"Penedès","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"bulles","famille":"bulles","note":"Cava rosado de Garnacha, Trepat ou Pinot noir : fraise, bulle fine, sec"}],"cepages":["Macabeo","Xarel·lo","Parellada","Chardonnay"],"style":"Pomme verte, pain grillé, amande, bulles fines ; sec, net, plus terrien que le champagne.","temp":"6 à 8 °C","garde":"1 à 5 ans","prix":2,"accords":["frit","coquillage","crustace","charcuterie","volaille","fromage_frais"],"eviter":["viande_rouge","chocolat","sauce_vin_rouge"],"classique":"Cava brut et tapas frites (croquetas, calamars)","note":"Effervescent de méthode traditionnelle, né à Sant Sadurní d'Anoia en 1872 : seconde fermentation en bouteille, 9 mois minimum sur lies, 30 mois pour un Gran Reserva. Trois cépages catalans et un prix souvent inférieur à 15 €. L'apéritif des tapas, et un bon partenaire des fritures.","lat":41.43,"lon":1.79,"importance":5,"niveau":"incontournable"},{"id":"es-priorat","nom":"Priorat","pays":"Espagne","region":"Catalogne","sousRegion":"Priorat","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Garnacha","Cariñena","Cabernet Sauvignon","Syrah"],"style":"Mûre, cerise noire, graphite et minéral de schiste, tanins serrés, concentration et longueur.","temp":"17 à 18 °C","garde":"8 à 25 ans","prix":3,"accords":["viande_rouge","gibier","agneau","mijote","roti","fromage_dure"],"eviter":["poisson_maigre","huitre","cru"],"classique":"Priorat et épaule d'agneau confite au romarin","note":"Montagnes au nord-ouest de Tarragone, sols de schiste (llicorella), vignes en terrasses : vignoble des moines chartreux, ressuscité en 1989 par René Barbier, Álvaro Palacios et leurs amis. Rouges de Garnacha et Cariñena denses et minéraux, parmi les plus chers d'Espagne. À carafer longtemps.","lat":41.19,"lon":0.77,"importance":4,"niveau":"incontournable"},{"id":"es-penedes","nom":"Penedès","pays":"Espagne","region":"Catalogne","sousRegion":"Penedès","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Rouges de Cabernet, Merlot ou Tempranillo, lancés par Torres : nets, fruités, boisé discret"}],"cepages":["Xarel·lo","Macabeo","Parellada","Cabernet Sauvignon"],"style":"Pomme, fenouil, amande, bouche sèche et saline ; Xarel·lo tendu, parfois élevé sur lies.","temp":"9 à 11 °C","garde":"2 à 6 ans","prix":2,"accords":["poisson_maigre","coquillage","legumes","volaille","frit","fromage_frais"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Xarel·lo du Penedès et poisson à la planxa","note":"Entre Barcelone et Tarragone, de la mer aux collines : patrie du Cava, mais aussi de blancs tranquilles de Xarel·lo, secs et salins, et de rouges de Cabernet lancés par Torres dans les années 1970. Le Xarel·lo accompagne poissons grillés et légumes de la cuisine catalane.","lat":41.35,"lon":1.7,"importance":3,"niveau":"classique"},{"id":"es-corpinnat","nom":"Corpinnat","pays":"Espagne","region":"Catalogne","sousRegion":"Penedès","couleur":"bulles","famille":"bulles","variantes":[],"cepages":["Xarel·lo","Macabeo","Parellada","Chardonnay"],"style":"Brioche, pomme mûre, noisette, bulles crémeuses et longueur ; 18 mois minimum sur lies, souvent bien plus.","temp":"8 à 10 °C","garde":"3 à 10 ans","prix":3,"accords":["crustace","poisson_gras","volaille","champignon","fromage_dure","creme"],"eviter":["viande_rouge","chocolat","piquant"],"classique":"Corpinnat et langoustines grillées","note":"Marque collective déposée en 2017 par des maisons qui ont quitté l’appellation Cava en 2019 (Gramona, Recaredo, Llopart, Torelló...) : raisins bio du Penedès, vendange manuelle, vinification au domaine, 18 mois minimum sur lies. Des bulles de gastronomie, à servir moins froides qu’un Cava de base.","lat":41.4,"lon":1.75,"importance":2,"niveau":"decouverte"},{"id":"es-costers-del-segre","nom":"Costers del Segre","pays":"Espagne","region":"Catalogne","sousRegion":"Costers del Segre","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay de Raimat, rond, pêche et beurre, parfois élevé en fût"}],"cepages":["Cabernet Sauvignon","Tempranillo","Merlot","Chardonnay"],"style":"Cassis, prune, boisé fin, tanins ronds ; rouges modernes de cépages internationaux.","temp":"16 à 17 °C","garde":"3 à 8 ans","prix":2,"accords":["viande_rouge","porc","volaille","roti","grille","fromage_dure"],"eviter":["huitre","poisson_cru","glace"],"classique":"Costers del Segre et canard aux poires (ànec amb peres)","note":"Plaine sèche de Lleida en Catalogne intérieure, irriguée depuis le domaine de Raimat créé par la famille Raventós (Codorníu) en 1914 : climat continental, cépages internationaux, cave moderniste. Rouges ronds et blancs de Chardonnay, à prix sages, pour une volaille ou un rôti.","lat":41.66,"lon":0.55,"importance":2,"niveau":"decouverte"},{"id":"es-emporda","nom":"Empordà","pays":"Espagne","region":"Catalogne","sousRegion":"Empordà","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"rose","famille":"rose","note":"Rosés de Garnacha et Cariñena, charnus, pour la cuisine de mer"},{"couleur":"doux","famille":"vdn","note":"Garnatxa de l'Empordà : Garnacha mutée et vieillie, rancio, noix et fruits secs"}],"cepages":["Garnacha","Cariñena","Syrah","Garnacha blanca"],"style":"Fruits rouges confits, garrigue, iode, tanins charnus ; un cousin du Roussillon voisin, tramontane comprise.","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":2,"accords":["mediterraneen","grille","mijote","charcuterie","poisson_gras","fromage_dure"],"eviter":["huitre","cru","glace"],"classique":"Empordà et suquet de peix (ragoût de poisson catalan)","note":"Extrême nord-est de la Catalogne, de Figueres au cap de Creus, miroir du Roussillon : Garnacha et Cariñena battues par la tramontane, sur schiste. Rouges solaires, rosés, et la Garnatxa de l'Empordà, vin doux muté et rancio. À boire avec la cuisine « mar i muntanya », mer et montagne.","lat":42.37,"lon":2.92,"importance":2,"niveau":"decouverte"},{"id":"es-montsant","nom":"Montsant","pays":"Espagne","region":"Catalogne","sousRegion":"Montsant","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Garnacha","Cariñena","Syrah","Tempranillo"],"style":"Fruits rouges mûrs, garrigue, épices, chair ronde ; le Priorat en version plus souple et abordable.","temp":"16 à 17 °C","garde":"3 à 10 ans","prix":2,"accords":["mijote","grille","charcuterie","viande_rouge","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_cru","glace"],"classique":"Montsant et calçots grillés avec sauce romesco","note":"Anneau de vignes qui entoure le Priorat, sur calcaire et granit plutôt que sur schiste : mêmes cépages, parfois mêmes vignerons, pour une fraction du prix. Rouges de Garnacha mûrs et épicés, à boire dans les cinq ans sur une grillade catalane ou un plat mijoté.","lat":41.14,"lon":0.82,"importance":2,"niveau":"decouverte"},{"id":"es-terra-alta","nom":"Terra Alta","pays":"Espagne","region":"Catalogne","sousRegion":"Terra Alta","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_solaire","note":"Rouges de Garnacha et Cariñena, solaires, épicés, à carafer"}],"cepages":["Garnacha blanca","Garnacha","Cariñena","Macabeo"],"style":"Poire mûre, anis, miel léger, bouche grasse et chaude, finale amère ; un blanc de corps.","temp":"10 à 12 °C","garde":"2 à 6 ans","prix":2,"accords":["poisson_gras","volaille","creme","champignon","fromage_dure","mediterraneen"],"eviter":["huitre","poisson_cru","glace"],"classique":"Garnacha blanca de Terra Alta et riz aux fruits de mer","note":"Hautes terres à l'ouest de Tarragone, autour de Gandesa, théâtre de la bataille de l'Èbre en 1938 : environ un tiers de la Garnacha blanche mondiale pousse ici. Blancs amples et chaleureux, rouges solaires de Garnacha. Le blanc accompagne riz, poissons gras et plats à la crème.","lat":41.05,"lon":0.44,"importance":2,"niveau":"decouverte"},{"id":"es-vinos-de-madrid","nom":"Vinos de Madrid","pays":"Espagne","region":"Communauté de Madrid","sousRegion":"Vinos de Madrid","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Albillo Real de San Martín : blanc gras, pomme mûre, amande, et Malvar d'Arganda plus simple"}],"cepages":["Garnacha","Tempranillo","Albillo Real","Malvar"],"style":"Fruits rouges, herbes sèches, granit et fraîcheur ; Garnacha à San Martín, Tempranillo à Arganda.","temp":"15 à 17 °C","garde":"3 à 10 ans","prix":2,"accords":["roti","porc","charcuterie","abats","mijote","champignon"],"eviter":["huitre","poisson_cru","glace"],"classique":"Vinos de Madrid et cocido madrileño (pot-au-feu aux pois chiches)","note":"Trois sous-zones autour de la capitale : Arganda à l'est (Tempranillo, Malvar), Navalcarnero au sud, San Martín de Valdeiglesias à l'ouest, sur granit, où la Garnacha de Gredos donne les cuvées les plus recherchées (Comando G, Marañones). Le vin des tavernes madrilènes et du cocido.","lat":40.29,"lon":-4.01,"importance":2,"niveau":"decouverte"},{"id":"es-alicante","nom":"Alicante","pays":"Espagne","region":"Communauté valencienne","sousRegion":"Alicante","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"doux","famille":"vdn","note":"Fondillón : Monastrell surmûri sur pied, non muté, 16 % naturels, 10 ans minimum en solera ; noix, raisin sec, orange confite"},{"couleur":"doux","famille":"blanc_doux","note":"Moscatel de la Marina Alta, doux, floral, servi frais"}],"cepages":["Monastrell","Garnacha Tintorera","Moscatel de Alejandría"],"style":"Fruits noirs, cuir, épices, chaleur ; le Fondillón, lui, est rancio : noix, raisin sec, orange confite, presque sec.","temp":"16 à 17 °C","garde":"3 à 10 ans","prix":2,"accords":["mijote","viande_rouge","grille","charcuterie","fromage_dure","noix"],"eviter":["huitre","poisson_cru","glace"],"classique":"Fondillón d'Alicante et fromage de brebis affiné aux noix","note":"Arrière-pays d'Alicante, du Vinalopó à la Marina : le Fondillón, Monastrell surmûri sur pied, non muté, vieilli au moins dix ans en solera, était cité par Shakespeare et servi à Louis XIV. Aujourd'hui, rouges de Monastrell charnus et blancs doux de Moscatel. Le Fondillón se sert en fin de repas.","lat":38.35,"lon":-0.48,"importance":2,"niveau":"decouverte"},{"id":"es-utiel-requena","nom":"Utiel-Requena","pays":"Espagne","region":"Communauté valencienne","sousRegion":"Utiel-Requena","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosado de Bobal, coloré et fruité, la production historique de l'aire"},{"couleur":"bulles","famille":"bulles","note":"Cava produit à Requena, l'une des rares zones de Cava hors Catalogne"}],"cepages":["Bobal","Tempranillo","Garnacha"],"style":"Mûre, violette, acidité fraîche, tanins rustiques assagis ; le Bobal, cépage autochtone, en vedette.","temp":"15 à 17 °C","garde":"2 à 8 ans","prix":1,"accords":["charcuterie","porc","mijote","grille","legumes","fromage_dure"],"eviter":["huitre","poisson_cru","glace"],"classique":"Bobal d'Utiel-Requena et embutidos de Requena (chorizo, morcilla)","note":"Plateau à 700 m à l'ouest de Valence : patrie du Bobal, cépage à grosses grappes longtemps réservé au vrac et aux rosés, repris par de jeunes vignerons pour des rouges frais et francs. Des vins souvent à moins de 10 €, taillés pour la charcuterie et les plats de tous les jours.","lat":39.49,"lon":-1.1,"importance":2,"niveau":"decouverte"},{"id":"es-valencia","nom":"Valencia","pays":"Espagne","region":"Communauté valencienne","sousRegion":"Valencia","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"doux","famille":"vdn","note":"Moscatel de Valencia (mistela) : moût de muscat muté à l'alcool, doux, floral, servi frais à l'apéritif"},{"couleur":"blanc","famille":"blanc_aromatique","note":"Moscatel sec et Merseguera : blancs parfumés et légers"}],"cepages":["Monastrell","Tempranillo","Bobal","Moscatel de Alejandría"],"style":"Fruits rouges, épices, tanins souples ; rouges de table simples, et un muscat muté doux et floral.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["mediterraneen","volaille","porc","legumes","grille","charcuterie"],"eviter":["huitre","chocolat","piquant"],"classique":"Rouge de Valencia et paella valenciana (poulet, lapin, haricots)","note":"Arrière-pays de la ville de Valence, de l'Alto Turia au Clariano : rouges de table simples et fruités, et la mistela, un Moscatel muté à l'alcool, doux et floral, que les Valenciens boivent frais à l'apéritif ou avec une pâtisserie. Le rouge est le compagnon naturel de la paella.","lat":39.47,"lon":-0.38,"importance":2,"niveau":"decouverte"},{"id":"es-ribera-del-guadiana","nom":"Ribera del Guadiana","pays":"Espagne","region":"Estrémadure","sousRegion":"Tierra de Barros","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Cayetana blanca et Pardina : blancs légers et neutres, à boire frais"}],"cepages":["Tempranillo","Garnacha","Cabernet Sauvignon","Cayetana blanca"],"style":"Fruits rouges mûrs, épices, bouche ronde et chaleureuse ; des rouges faciles, et des blancs légers de Cayetana.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["charcuterie","porc","grille","mijote","fromage_dure","roti"],"eviter":["huitre","poisson_cru","glace"],"classique":"Rouge d'Estrémadure et jambon ibérique de bellota","note":"Plaines d'Estrémadure autour d'Almendralejo, la « Tierra de Barros » : appellation récente (1999), au pays du porc ibérique et des pâturages à chênes (dehesa). Rouges de Tempranillo faciles et bon marché, qui vont de pair avec les charcuteries ibériques, la torta del Casar et les ragoûts locaux.","lat":38.68,"lon":-6.41,"importance":1,"niveau":"decouverte"},{"id":"es-rias-baixas","nom":"Rías Baixas","pays":"Espagne","region":"Galice","sousRegion":"Rías Baixas","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Albariño","Treixadura","Loureira"],"style":"Pêche blanche, citron, iode et salinité ; sec, tendu, avec une pointe de gras.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":2,"accords":["huitre","coquillage","crustace","poisson_maigre","poisson_cru","vapeur"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Albariño et coquillages des rías galiciennes","note":"Galice atlantique, autour des rías de Pontevedra : vignes en pergola sur piliers de granit, pluie et brouillard. L'Albariño, cépage à peau épaisse, y garde une acidité vive et un goût salin. C'est le blanc espagnol des fruits de mer : huîtres, palourdes, poulpe, à boire jeune et frais.","lat":42.51,"lon":-8.81,"importance":4,"niveau":"incontournable"},{"id":"es-valdeorras","nom":"Valdeorras Godello","pays":"Espagne","region":"Galice","sousRegion":"Valdeorras","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Mencía de Valdeorras : fruits rouges, fraîcheur, tanins fins"}],"cepages":["Godello","Mencía"],"style":"Poire, anis, amande, bouche ample et minérale, finale saline ; un blanc de gastronomie.","temp":"10 à 12 °C","garde":"2 à 8 ans","prix":2,"accords":["poisson_gras","poisson_maigre","volaille","creme","champignon","fromage_dure"],"eviter":["viande_rouge","chocolat","piquant"],"classique":"Godello de Valdeorras et merlu à la galicienne","note":"Vallée du Sil à l'est de la Galice, sols d'ardoise et de granit : la Godello, presque disparue dans les années 1970, a été replantée ici et donne des blancs secs à la fois minéraux et charnus, parfois élevés en fût. Un blanc de table pour un poisson en sauce ou une volaille à la crème.","lat":42.42,"lon":-6.98,"importance":3,"niveau":"classique"},{"id":"es-ribeira-sacra","nom":"Ribeira Sacra","pays":"Espagne","region":"Galice","sousRegion":"Ribeira Sacra","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Godello et Albariño des terrasses : blancs tendus, floraux, minéraux"}],"cepages":["Mencía","Brancellao","Merenzao","Godello"],"style":"Cerise, poivre, touche fumée, corps léger et acidité vive ; un rouge atlantique de montagne.","temp":"14 à 16 °C","garde":"2 à 8 ans","prix":2,"accords":["volaille","porc","poisson_gras","charcuterie","champignon","grille"],"eviter":["viande_rouge","sucre_sale","chocolat"],"classique":"Ribeira Sacra et poulpe à la galicienne (pulpo a feira)","note":"Terrasses vertigineuses taillées par les moines au-dessus du Sil et du Miño, en Galice intérieure : on parle de vendange « héroïque ». La Mencía y donne des rouges légers et poivrés, proches d'un gamay de cru. Servir frais, avec un poulpe, une charcuterie ou un poisson gras.","lat":42.52,"lon":-7.51,"importance":2,"niveau":"decouverte"},{"id":"es-ribeiro","nom":"Ribeiro","pays":"Espagne","region":"Galice","sousRegion":"Ribeiro","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Rouges de Caíño, Brancellao et Sousón : légers, acidulés, poivrés"}],"cepages":["Treixadura","Godello","Albariño","Loureira"],"style":"Pomme, poire, fleurs blanches, légèreté et fraîcheur ; un blanc d'assemblage délicat.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":2,"accords":["poisson_maigre","coquillage","vapeur","legumes","fromage_frais","oeuf"],"eviter":["viande_rouge","mijote","chocolat"],"classique":"Ribeiro et empanada galicienne au thon","note":"Vallées du Miño et de l'Avia autour de Ribadavia, la plus ancienne appellation de Galice, exportée dès le Moyen Âge vers l'Angleterre. Assemblages de Treixadura et de Godello, servis autrefois dans des bols de faïence blanche (cuncas). Blanc léger de tapas et de poissons, à boire jeune.","lat":42.29,"lon":-8.14,"importance":2,"niveau":"decouverte"},{"id":"es-binissalem","nom":"Binissalem (Majorque)","pays":"Espagne","region":"Îles Baléares","sousRegion":"Majorque","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Prensal blanc (Moll) : blanc léger, pomme et fleurs, pour les poissons de l'île"}],"cepages":["Manto Negro","Callet","Cabernet Sauvignon","Prensal blanc"],"style":"Fruits rouges, herbes méditerranéennes, tanins légers et douceur de fruit ; des rouges insulaires faciles.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":2,"accords":["porc","charcuterie","mediterraneen","grille","legumes","volaille"],"eviter":["huitre","poisson_cru","chocolat"],"classique":"Binissalem et sobrassada (saucisse de porc au paprika) sur pain grillé","note":"Plaine centrale de Majorque, autour de Binissalem, première appellation des Baléares (1991) : cépages insulaires Manto Negro et Callet, souvent renforcés de Cabernet, pour des rouges souples et épicés à boire jeunes, et des blancs de Prensal. Le vin de la sobrassada et des plats majorquins.","lat":39.69,"lon":2.84,"importance":1,"niveau":"decouverte"},{"id":"es-lanzarote","nom":"Lanzarote (Canaries)","pays":"Espagne","region":"Îles Canaries","sousRegion":"Lanzarote","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Malvasía dulce, vendange tardive ou passerillée : miel, abricot, le vin historique de l'île"},{"couleur":"rouge","famille":"rouge_leger","note":"Listán negro : rouge léger, fumé, poivré, à servir frais"}],"cepages":["Malvasía volcánica","Listán blanco","Listán negro"],"style":"Fleurs blanches, pomme, pierre à fusil et sel ; sec, tendu, marqué par la cendre volcanique.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":2,"accords":["poisson_maigre","poisson_gras","coquillage","crustace","frit","legumes"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Malvasía de Lanzarote et papas arrugadas au mojo verde","note":"Île volcanique des Canaries : à La Geria, chaque cep pousse dans un entonnoir creusé dans la cendre (picón), abrité du vent par un muret de lave. La Malvasía volcánica, jamais touchée par le phylloxéra, donne des blancs secs salins et fumés, et des doux historiques. Pour les poissons de l'île.","lat":28.98,"lon":-13.68,"importance":2,"niveau":"decouverte"},{"id":"es-rioja","nom":"Rioja","pays":"Espagne","region":"La Rioja","sousRegion":"Rioja","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Rioja blanco de Viura, parfois élevé en fût : ample, cire, noisette, pomme mûre"},{"couleur":"rose","famille":"rose","note":"Rosado de Garnacha, franc et fruité, pour les tapas"}],"cepages":["Tempranillo","Garnacha","Graciano","Mazuelo"],"style":"Fruits rouges mûrs, vanille et coco du fût de chêne américain, tanins fondus, bouche souple et chaleureuse.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["agneau","roti","charcuterie","fromage_dure","champignon","grille"],"eviter":["huitre","poisson_cru","asiatique"],"classique":"Rioja reserva et côtelettes d'agneau grillées aux sarments","note":"Vallée de l'Èbre au pied de la sierra de Cantabria : Tempranillo élevé en fût de chêne américain, héritage des négociants bordelais venus au XIXe siècle. Crianza (2 ans d'élevage dont 1 en fût) pour tous les jours, reserva (3 ans) et gran reserva (5 ans) pour un gigot ou une pièce de bœuf.","lat":42.47,"lon":-2.45,"importance":5,"niveau":"incontournable"},{"id":"es-jumilla","nom":"Jumilla","pays":"Espagne","region":"Murcie","sousRegion":"Jumilla","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"doux","famille":"vdn","note":"Monastrell dulce, rouge doux muté ou surmûri : figue, cacao, pour le chocolat"}],"cepages":["Monastrell","Syrah","Tempranillo"],"style":"Fruits noirs confiturés, réglisse, chocolat, tanins charnus et alcool chaud ; le Mourvèdre au soleil.","temp":"16 à 17 °C","garde":"3 à 10 ans","prix":1,"accords":["viande_rouge","mijote","grille","gibier","charcuterie","epice_douce"],"eviter":["huitre","poisson_maigre","asperge"],"classique":"Jumilla Monastrell et chevreau rôti","note":"Hauts plateaux arides entre Murcie et Albacete, vieilles vignes de Monastrell franches de pied, épargnées par le phylloxéra jusqu'en 1989. Rouges opulents, souvent à 15 % d'alcool, au rapport prix-plaisir imbattable. À réserver aux viandes rôties, aux plats mijotés et aux fromages affinés.","lat":38.48,"lon":-1.32,"importance":3,"niveau":"classique"},{"id":"es-yecla","nom":"Yecla","pays":"Espagne","region":"Murcie","sousRegion":"Yecla","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Monastrell","Syrah","Cabernet Sauvignon"],"style":"Cerise noire, figue, thym, bouche chaude et pleine, tanins mûrs.","temp":"16 à 17 °C","garde":"3 à 8 ans","prix":1,"accords":["grille","mijote","viande_rouge","charcuterie","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_cru","glace"],"classique":"Yecla et gazpacho manchego (galette et gibier mijotés)","note":"Petite appellation d'une seule commune, au nord de Murcie, voisine de Jumilla : même Monastrell, mêmes sols calcaires et même sécheresse, avec quelques grands domaines (Castaño) qui exportent presque tout. Rouges solaires et bon marché, pour les grillades et les ragoûts de gibier.","lat":38.61,"lon":-1.11,"importance":1,"niveau":"decouverte"},{"id":"es-navarra","nom":"Navarra","pays":"Espagne","region":"Navarre","sousRegion":"Navarra","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosado de Garnacha par saignée, coloré, franc et fruité, la spécialité historique"}],"cepages":["Tempranillo","Garnacha","Cabernet Sauvignon","Merlot"],"style":"Fruits rouges, épices douces, tanins souples ; des rouges faciles et des rosés de Garnacha francs.","temp":"15 à 17 °C","garde":"2 à 8 ans","prix":1,"accords":["charcuterie","porc","volaille","legumes","grille","mediterraneen"],"eviter":["huitre","poisson_cru","chocolat"],"classique":"Rosado de Navarre et légumes de la Ribera (asperges, poivrons, artichauts)","note":"Au sud de Pampelune, de la montagne à la vallée de l'Èbre : la Navarre fut longtemps la terre des rosés de Garnacha de saignée, avant de planter Tempranillo et cépages bordelais dans les années 1980. Vins de bon rapport qualité-prix, souples, pour la charcuterie et les légumes de la Ribera.","lat":42.48,"lon":-1.65,"importance":3,"niveau":"classique"},{"id":"es-txakoli","nom":"Txakoli","pays":"Espagne","region":"Pays basque","sousRegion":"Getariako Txakolina","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rose","famille":"rose","note":"Txakoli rosé de Hondarrabi Beltza, pâle, acidulé, perlant"}],"cepages":["Hondarrabi Zuri","Hondarrabi Beltza"],"style":"Citron vert, pomme verte, perlant léger, 11 % d'alcool ; sec, acidulé, salin.","temp":"6 à 8 °C","garde":"1 à 2 ans","prix":2,"accords":["poisson_maigre","coquillage","poisson_gras","frit","grille","huitre"],"eviter":["viande_rouge","mijote","chocolat"],"classique":"Txakoli versé de haut et anchois de Getaria","note":"Côte basque espagnole, entre Getaria et Zarautz : vignes face à l'Atlantique, climat humide. Le Txakoli est un blanc léger, légèrement perlant, que l'on verse de haut pour l'aérer. Vin d'apéritif et de pintxos, parfait sur un poisson grillé ou des anchois marinés, à boire dans l'année.","lat":43.3,"lon":-2.2,"importance":3,"niveau":"classique"},{"id":"us-central-coast","nom":"Central Coast","pays":"États-Unis","region":"Central Coast","sousRegion":"","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Pinot noir de Monterey et de Santa Barbara, fruité et souple, bon marché."}],"cepages":["Chardonnay","Pinot noir","Sauvignon blanc"],"style":"Pomme, pêche, pointe d'ananas, beurre et vanille modérés ; blanc rond et facile, acidité correcte.","temp":"10 à 12 °C","garde":"1 à 4 ans","prix":2,"accords":["volaille","poisson_gras","crustace","creme","legumes","fromage_molle"],"eviter":["piquant","vinaigre","chocolat"],"classique":"Chardonnay Central Coast et poulet rôti","note":"Grande aire qui court de la baie de San Francisco à Santa Barbara, 400 km de côte. La mention Central Coast sur l'étiquette signale un assemblage de plusieurs comtés, surtout Monterey et San Luis Obispo. Chardonnays et pinots noirs accessibles, au fruit mûr et au prix doux, pour tous les jours.","lat":35.95,"lon":-120.9,"importance":3,"niveau":"classique"},{"id":"us-paso-robles","nom":"Paso Robles","pays":"États-Unis","region":"Central Coast","sousRegion":"Paso Robles","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Assemblages rhodaniens de roussanne, marsanne et viognier, riches et parfumés."}],"cepages":["Cabernet Sauvignon","Syrah","Zinfandel","Grenache"],"style":"Fruit noir confit, prune, cacao, épices chaudes ; corps opulent, alcool généreux, tanins mûrs.","temp":"16 à 18 °C","garde":"4 à 12 ans","prix":3,"accords":["grille","viande_rouge","agneau","mijote","epice_douce","fromage_dure"],"eviter":["huitre","poisson_maigre","vapeur"],"classique":"Rouge de Paso Robles et côtelettes d'agneau grillées","note":"Entre San Francisco et Los Angeles, dans les terres : journées chaudes, nuits fraîches par le col de Templeton, passage de l'air marin. Cabernet, zinfandel et surtout assemblages rhodaniens (syrah, grenache, mourvèdre) donnent des rouges solaires et épicés. Pour les grillades et viandes épicées.","lat":35.63,"lon":-120.69,"importance":3,"niveau":"classique"},{"id":"us-santa-cruz-mountains","nom":"Santa Cruz Mountains","pays":"États-Unis","region":"Central Coast","sousRegion":"Santa Cruz Mountains","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Pinot noir frais et épicé des versants tournés vers l'océan."},{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay tendu et long, dans la lignée de Mount Eden."}],"cepages":["Cabernet Sauvignon","Pinot noir","Chardonnay"],"style":"Cassis, cèdre, graphite et eucalyptus ; structure droite, tanins fermes, finale longue, style plus européen que Napa.","temp":"16 à 18 °C","garde":"10 à 25 ans","prix":4,"accords":["viande_rouge","agneau","roti","gibier","fromage_dure","truffe"],"eviter":["poisson_cru","huitre","asiatique"],"classique":"Monte Bello de Ridge et gigot d'agneau rôti","note":"Montagnes au sud de San Francisco, vignes d'altitude sur calcaire et schistes, au-dessus du brouillard. Le Monte Bello de Ridge Vineyards, cabernet planté vers 800 m, figurait au Jugement de Paris de 1976. Rouges droits, moins solaires que Napa. À garder, pour viandes rôties.","lat":37.15,"lon":-122.05,"importance":3,"niveau":"classique"},{"id":"us-sta-rita-hills","nom":"Sta. Rita Hills","pays":"États-Unis","region":"Central Coast","sousRegion":"Santa Barbara, Sta. Rita Hills","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay vif, citron et pierre à fusil, élevage mesuré."}],"cepages":["Pinot noir","Chardonnay"],"style":"Cerise noire, framboise, herbes sèches et épices ; chair dense, acidité tranchante, tanins fins.","temp":"14 à 16 °C","garde":"4 à 12 ans","prix":3,"accords":["canard","champignon","volaille","poisson_gras","gibier","fromage_molle"],"eviter":["piquant","huitre","chocolat"],"classique":"Pinot noir de Sta. Rita Hills et canard aux champignons","note":"Entre Lompoc et Buellton, des vallées orientées est-ouest aspirent l'air froid du Pacifique vers l'intérieur, cas rare en Californie. Le pinot noir y mûrit tout en gardant une acidité bourguignonne ; le film Sideways (2004) a lancé sa renommée. À servir frais, sur un canard ou des champignons.","lat":34.63,"lon":-120.3,"importance":3,"niveau":"classique"},{"id":"us-santa-lucia-highlands","nom":"Santa Lucia Highlands","pays":"États-Unis","region":"Central Coast","sousRegion":"Monterey, Santa Lucia Highlands","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay mûr et long, fruits jaunes et noisette."}],"cepages":["Pinot noir","Chardonnay","Syrah"],"style":"Cerise noire, mûre, épices et note florale ; pinot plus dense et sombre, acidité fraîche, tanins fins.","temp":"14 à 16 °C","garde":"4 à 10 ans","prix":3,"accords":["canard","volaille","champignon","poisson_gras","gibier","fromage_molle"],"eviter":["piquant","huitre","fromage_bleu"],"classique":"Pinot noir de Santa Lucia Highlands et canard laqué","note":"Terrasses exposées sud-est sur le flanc de la chaîne de Santa Lucia, dominant la vallée de Salinas (comté de Monterey). Matinées brumeuses, vent violent l'après-midi : saison longue, raisins petits. Pinots noirs intenses, fruit noir, chardonnays mûrs. À servir frais sur un canard ou un gibier.","lat":36.37,"lon":-121.45,"importance":2,"niveau":"decouverte"},{"id":"us-lodi-zinfandel","nom":"Lodi Zinfandel","pays":"États-Unis","region":"Central Valley","sousRegion":"Lodi","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Zinfandel"],"style":"Confiture de mûre, cerise noire, vanille et poivre doux ; rond, chaleureux, tanins fondus, parfois une pointe de sucrosité.","temp":"16 à 18 °C","garde":"2 à 6 ans","prix":2,"accords":["grille","porc","fume","epice_douce","viande_rouge","charcuterie"],"eviter":["huitre","poisson_maigre","acide"],"classique":"Zinfandel de Lodi et burger au bacon","note":"Plaine sablonneuse du delta du Sacramento, climat chaud tempéré par les brises : la plus grande aire de zinfandel au monde, avec des vignes franches de pied plantées avant 1900. Rouge facile et généreux au fruit confit, rarement cher. Le vin des barbecues et des plats fumés, à peine rafraîchi.","lat":38.13,"lon":-121.27,"importance":2,"niveau":"decouverte"},{"id":"us-anderson-valley","nom":"Anderson Valley","pays":"États-Unis","region":"Mendocino","sousRegion":"Anderson Valley","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"bulles","famille":"bulles","note":"Effervescents de méthode traditionnelle (Roederer Estate, Scharffenberger)."},{"couleur":"blanc","famille":"blanc_aromatique","note":"Gewurztraminer et riesling secs, d'inspiration alsacienne."}],"cepages":["Pinot noir","Chardonnay","Gewurztraminer"],"style":"Cerise rouge, canneberge, sous-bois et épices ; corps svelte, acidité fraîche, tanins fins.","temp":"13 à 15 °C","garde":"4 à 10 ans","prix":3,"accords":["volaille","canard","champignon","poisson_gras","fromage_molle","roti"],"eviter":["piquant","viande_rouge","fromage_bleu"],"classique":"Pinot noir d'Anderson Valley et pintade aux morilles","note":"Vallée étroite du comté de Mendocino, à 20 km du Pacifique : brouillard et nuits froides en font une des aires les plus fraîches de l'État. Pinots noirs tendus, cépages alsaciens et effervescents depuis l'arrivée de Roederer en 1982. Vins fins et frais, sur une volaille ou un plat de champignons.","lat":39.05,"lon":-123.5,"importance":2,"niveau":"decouverte"},{"id":"us-napa-valley-cabernet-sauvignon","nom":"Napa Valley Cabernet Sauvignon","pays":"États-Unis","region":"Napa Valley","sousRegion":"","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay riche et boisé, et sauvignon blanc (« Fumé blanc ») plus vif."}],"cepages":["Cabernet Sauvignon","Merlot","Cabernet franc","Petit Verdot"],"style":"Cassis mûr, mûre, cèdre et vanille d'élevage neuf ; corps dense, tanins enrobés, finale longue et chaleureuse.","temp":"16 à 18 °C","garde":"8 à 20 ans","prix":4,"accords":["viande_rouge","grille","roti","agneau","fromage_dure","sauce_vin_rouge"],"eviter":["huitre","poisson_cru","asperge"],"classique":"Cabernet de Napa et côte de bœuf grillée","note":"Vallée de 50 km de long, au nord de San Francisco, révélée au monde par le Jugement de Paris de 1976. Soleil franc tempéré par les brumes matinales : le cabernet y donne des rouges opulents, au fruit noir très mûr et aux tanins soyeux. À ouvrir après quelques années, sur une viande rouge grillée.","lat":38.45,"lon":-122.4,"importance":5,"niveau":"incontournable"},{"id":"us-rutherford-oakville","nom":"Rutherford et Oakville","pays":"États-Unis","region":"Napa Valley","sousRegion":"Rutherford, Oakville","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot","Cabernet franc"],"style":"Cassis et prune, note poudreuse de cacao dite « Rutherford dust », tanins fins et serrés, bois noble, longue finale.","temp":"17 à 18 °C","garde":"10 à 25 ans","prix":4,"accords":["viande_rouge","agneau","roti","grille","fromage_dure","truffe"],"eviter":["poisson_maigre","acide","asiatique"],"classique":"Cabernet d'Oakville et carré d'agneau rôti","note":"Cœur de la Napa Valley : deux aires voisines sur le plancher et les cônes alluviaux de la vallée, berceau des domaines historiques (Inglenook, To Kalon). Cabernets plus structurés et minéraux que la moyenne de Napa, avec une note poudreuse de cacao typique. Vins de garde pour une grande occasion.","lat":38.44,"lon":-122.41,"importance":4,"niveau":"classique"},{"id":"us-stags-leap-district","nom":"Stags Leap District","pays":"États-Unis","region":"Napa Valley","sousRegion":"Stags Leap District","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot"],"style":"Fruit rouge et noir velouté, violette, épices douces ; tanins ronds et texture soyeuse, un cabernet plus souple que la moyenne de Napa.","temp":"16 à 18 °C","garde":"8 à 20 ans","prix":4,"accords":["viande_rouge","roti","agneau","canard","champignon","fromage_dure"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Cabernet de Stags Leap et filet de bœuf au poivre","note":"District sur la rive est de Napa, adossé à des falaises de basalte qui renvoient la chaleur. Le cabernet 1973 de Stag's Leap Wine Cellars y a battu les bordeaux au Jugement de Paris de 1976. Tanins ronds reconnaissables, « un poing de fer dans un gant de velours ». À carafer, sur un bœuf rôti.","lat":38.4,"lon":-122.32,"importance":4,"niveau":"classique"},{"id":"us-howell-mountain","nom":"Howell Mountain","pays":"États-Unis","region":"Napa Valley","sousRegion":"Howell Mountain","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Zinfandel","Merlot"],"style":"Mûre, cassis, cèdre et pierre ; tanins puissants et serrés, acidité préservée, finale longue, longue garde.","temp":"17 à 18 °C","garde":"10 à 25 ans","prix":4,"accords":["viande_rouge","agneau","gibier","roti","grille","fromage_dure"],"eviter":["poisson_cru","huitre","asperge"],"classique":"Cabernet de Howell Mountain et gibier rôti","note":"Première aire de montagne de Napa (1983), au-dessus de 430 m à l'est de St. Helena, hors du brouillard. Sols volcaniques pauvres, petits raisins à peau épaisse : cabernets plus tanniques et plus frais que ceux du plancher de la vallée. Zinfandel historique. Vins de patience pour une viande rôtie.","lat":38.6,"lon":-122.43,"importance":2,"niveau":"decouverte"},{"id":"us-los-carneros","nom":"Los Carneros","pays":"États-Unis","region":"Napa Valley et Sonoma","sousRegion":"Los Carneros","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay tendu, pomme et agrumes, élevage mesuré."},{"couleur":"bulles","famille":"bulles","note":"Effervescents de méthode traditionnelle (Domaine Carneros de Taittinger, Gloria Ferrer)."}],"cepages":["Pinot noir","Chardonnay"],"style":"Cerise rouge, fraise, note de thé et d'épices douces ; corps moyen, acidité fraîche, tanins fins.","temp":"14 à 16 °C","garde":"3 à 8 ans","prix":3,"accords":["volaille","canard","champignon","poisson_gras","roti","fromage_molle"],"eviter":["piquant","viande_rouge","fromage_bleu"],"classique":"Pinot noir de Carneros et magret de canard","note":"Aire à cheval sur Napa et Sonoma, ouverte sur la baie de San Pablo : brouillard le matin, vent frais l'après-midi. Climat tempéré, fait pour le pinot noir et le chardonnay, souvent vinifiés en effervescent. Pinot au fruit rouge frais et acidité vive, à servir rafraîchi sur une volaille ou un canard.","lat":38.25,"lon":-122.35,"importance":3,"niveau":"classique"},{"id":"us-finger-lakes-riesling","nom":"Finger Lakes Riesling","pays":"États-Unis","region":"New York","sousRegion":"Finger Lakes","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Rieslings de vendanges tardives et icewines, abricot et miel."},{"couleur":"rouge","famille":"rouge_leger","note":"Cabernet franc léger, poivré et frais."}],"cepages":["Riesling"],"style":"Citron vert, pomme verte, pêche et pierre mouillée ; sec à demi-sec, acidité tranchante, alcool modéré.","temp":"8 à 10 °C","garde":"3 à 12 ans","prix":2,"accords":["poisson_maigre","crustace","asiatique","piquant","volaille","fromage_chevre"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Riesling des Finger Lakes et crevettes thaï épicées","note":"Lacs glaciaires profonds de l'État de New York, qui tempèrent les hivers et prolongent l'automne. Konstantin Frank y a prouvé dès 1962 que le riesling mûrissait. Schistes et climat frais donnent des blancs tendus de style allemand, du sec au liquoreux. À servir frais sur une cuisine asiatique.","lat":42.55,"lon":-76.95,"importance":3,"niveau":"classique"},{"id":"us-long-island","nom":"Long Island","pays":"États-Unis","region":"New York","sousRegion":"North Fork, The Hamptons","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Sauvignon blanc et chardonnay tendus, note iodée."},{"couleur":"rose","famille":"rose","note":"Rosés secs de merlot, très demandés l'été dans les Hamptons."}],"cepages":["Merlot","Cabernet franc","Chardonnay","Sauvignon blanc"],"style":"Cerise rouge, prune, herbes et poivron ; corps moyen, acidité fraîche, tanins modérés, style proche de Bordeaux.","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":3,"accords":["canard","volaille","viande_rouge","porc","champignon","fromage_dure"],"eviter":["huitre","piquant","chocolat"],"classique":"Merlot de Long Island et canard rôti","note":"Péninsules de North Fork et des Hamptons, à deux heures de New York, entre océan et détroit : climat maritime frais, sols sableux. Premier domaine planté en 1973. Merlot et cabernet franc y donnent des rouges d'équilibre bordelais ; les blancs sont vifs. Les vins de proximité de New York.","lat":41.0,"lon":-72.48,"importance":2,"niveau":"decouverte"},{"id":"us-willamette-valley-pinot-noir","nom":"Willamette Valley Pinot noir","pays":"États-Unis","region":"Oregon","sousRegion":"Willamette Valley","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Pinot gris frais et fruité, cépage blanc historique de l'Oregon ; chardonnay en progrès."}],"cepages":["Pinot noir"],"style":"Cerise rouge, framboise, sous-bois, pétale de rose ; corps moyen, acidité vive, tanins soyeux, style bourguignon.","temp":"14 à 16 °C","garde":"4 à 12 ans","prix":3,"accords":["volaille","canard","champignon","poisson_gras","truffe","fromage_molle"],"eviter":["piquant","viande_rouge","fromage_bleu"],"classique":"Pinot noir de Willamette et saumon du Pacifique grillé","note":"Vallée de l'Oregon au sud de Portland, climat frais et pluvieux proche de la Bourgogne, sols volcaniques des Dundee Hills. Plantée dès 1965, confirmée quand Drouhin s'y est installé en 1987. Pinot noir fin, fruit rouge et acidité vive, souvent bio. À servir frais, sur un saumon ou une volaille.","lat":45.28,"lon":-123.0,"importance":5,"niveau":"incontournable"},{"id":"us-sierra-foothills","nom":"Sierra Foothills","pays":"États-Unis","region":"Sierra Foothills","sousRegion":"Amador, El Dorado","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Zinfandel","Barbera","Syrah"],"style":"Framboise, mûre, poivre et terre ; rustique et généreux, tanins francs, alcool présent.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["grille","porc","mijote","charcuterie","tomate","fromage_dure"],"eviter":["huitre","poisson_maigre","vapeur"],"classique":"Zinfandel d'Amador et chili con carne","note":"Contreforts de la Sierra Nevada, à l'est de Sacramento, plantés dès la ruée vers l'or de 1849 pour abreuver les mineurs. Sols granitiques, altitude et nuits froides. Le zinfandel d'Amador et d'El Dorado y est charpenté et poivré ; barbera et syrah suivent. Rouge de plats mijotés et grillades.","lat":38.48,"lon":-120.85,"importance":2,"niveau":"decouverte"},{"id":"us-russian-river-valley-pinot-noir","nom":"Russian River Valley Pinot noir","pays":"États-Unis","region":"Sonoma","sousRegion":"Russian River Valley","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Pinot noir"],"style":"Cerise noire, framboise, cola et sous-bois ; chair ronde, acidité fraîche, tanins fins et soyeux.","temp":"14 à 16 °C","garde":"4 à 10 ans","prix":3,"accords":["canard","volaille","champignon","poisson_gras","gibier","fromage_molle"],"eviter":["piquant","huitre","fromage_bleu"],"classique":"Pinot noir de Russian River et canard rôti aux cerises","note":"Vallée du comté de Sonoma envahie chaque nuit par le brouillard que la rivière Russian fait remonter du Pacifique. Les nuits froides préservent l'acidité du pinot noir, plus charnu qu'en Bourgogne, au fruit noir et à la note de cola typique. À servir frais sur un canard ou une volaille rôtie.","lat":38.48,"lon":-122.85,"importance":4,"niveau":"classique"},{"id":"us-sonoma-coast","nom":"Sonoma Coast","pays":"États-Unis","region":"Sonoma","sousRegion":"Sonoma Coast","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay tendu et salin, élevage discret, parmi les plus fins de Californie."}],"cepages":["Pinot noir","Chardonnay","Syrah"],"style":"Cerise rouge croquante, canneberge, épices et note saline ; corps svelte, acidité vive, tanins fins.","temp":"13 à 15 °C","garde":"4 à 10 ans","prix":3,"accords":["poisson_gras","volaille","champignon","canard","fromage_molle","roti"],"eviter":["piquant","viande_rouge","fromage_bleu"],"classique":"Pinot noir de Sonoma Coast et saumon grillé","note":"Bande côtière battue par le Pacifique, brouillard et vent : l'une des zones les plus fraîches de Californie. Les crêtes de Fort Ross et Freestone donnent des pinots noirs serrés et salins, loin du style confituré, et des chardonnays vifs. À servir frais sur un poisson gras ou une volaille.","lat":38.42,"lon":-123.05,"importance":4,"niveau":"classique"},{"id":"us-alexander-valley","nom":"Alexander Valley","pays":"États-Unis","region":"Sonoma","sousRegion":"Alexander Valley","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot","Zinfandel"],"style":"Cassis, cerise noire, chocolat et menthol ; corps plein, tanins ronds et soyeux, plus accessible jeune qu'un Napa.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":3,"accords":["viande_rouge","agneau","roti","grille","mijote","fromage_dure"],"eviter":["poisson_cru","huitre","acide"],"classique":"Cabernet d'Alexander Valley et agneau braisé","note":"L'une des vallées les plus chaudes de Sonoma, le long de la rivière Russian autour de Geyserville, plantée de cabernet sauvignon. Graviers alluviaux et chaleur donnent des rouges mûrs et veloutés, à la note de chocolat, prêts plus tôt que ceux de Napa moins chers. Pour une viande rôtie ou braisée.","lat":38.72,"lon":-122.88,"importance":3,"niveau":"classique"},{"id":"us-dry-creek-valley-zinfandel","nom":"Dry Creek Valley Zinfandel","pays":"États-Unis","region":"Sonoma","sousRegion":"Dry Creek Valley","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Sauvignon blanc herbacé et vif, l'autre spécialité de la vallée."}],"cepages":["Zinfandel","Petite Sirah","Carignan"],"style":"Mûre, framboise confite, poivre noir et réglisse ; chaleureux, généreux, tanins mûrs et finale épicée.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":3,"accords":["grille","porc","viande_rouge","epice_douce","fume","fromage_dure"],"eviter":["huitre","poisson_maigre","vapeur"],"classique":"Zinfandel de Dry Creek et travers de porc au barbecue","note":"Vallée près de Healdsburg, chaude le jour et fraîche la nuit, plantée de zinfandel depuis les années 1870 ; des vignes centenaires produisent encore. Cépage emblème de la Californie (le primitivo italien), il donne un rouge solaire au fruit confit et au poivre. Pour les grillades fumées.","lat":38.68,"lon":-122.93,"importance":3,"niveau":"classique"},{"id":"us-russian-river-valley-chardonnay","nom":"Russian River Valley Chardonnay","pays":"États-Unis","region":"Sonoma","sousRegion":"Russian River Valley","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chardonnay"],"style":"Pomme mûre, poire, agrumes, noisette et beurre d'élevage ; bouche ample mais tendue par l'acidité.","temp":"10 à 12 °C","garde":"3 à 8 ans","prix":3,"accords":["volaille","poisson_gras","crustace","creme","champignon","fromage_dure"],"eviter":["piquant","vinaigre","chocolat"],"classique":"Chardonnay de Russian River et homard au beurre","note":"Mêmes brouillards que pour le pinot, même équilibre : le chardonnay de la Russian River marie la maturité californienne (poire, pêche) à une acidité ferme. Élevage en barrique avec bâtonnage, d'où la texture crémeuse et la noisette. Blanc riche, pour une volaille à la crème ou un crustacé au beurre.","lat":38.45,"lon":-122.88,"importance":3,"niveau":"classique"},{"id":"us-texas-hill-country","nom":"Texas Hill Country","pays":"États-Unis","region":"Texas","sousRegion":"Hill Country","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Viognier et roussanne mûrs, pêche et fleurs blanches."}],"cepages":["Tempranillo","Mourvèdre","Tannat","Viognier"],"style":"Cerise noire, cuir, tabac et épices sèches ; chaleureux, tanins mûrs, acidité modérée.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":3,"accords":["grille","viande_rouge","fume","porc","mijote","fromage_dure"],"eviter":["huitre","poisson_maigre","vapeur"],"classique":"Tempranillo du Texas et brisket fumé","note":"Plateau calcaire à l'ouest d'Austin, autour de Fredericksburg, de fondation allemande. Chaleur, orages et calcaire ont fait délaisser le cabernet pour des cépages de climats chauds : tempranillo, mourvèdre, tannat. Deuxième aire des États-Unis par la surface. Rouges épicés pour un barbecue texan.","lat":30.27,"lon":-98.87,"importance":1,"niveau":"decouverte"},{"id":"us-virginia","nom":"Virginie","pays":"États-Unis","region":"Virginie","sousRegion":"Monticello","couleur":"blanc","famille":"blanc_aromatique","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Cabernet franc et petit verdot, rouges frais et poivrés, parfois en assemblage « Meritage »."}],"cepages":["Viognier","Cabernet franc","Petit Verdot","Chardonnay"],"style":"Pêche, abricot, fleur d'oranger et miel sec ; blanc ample et parfumé, acidité modérée, parfois un peu de bois.","temp":"10 à 12 °C","garde":"2 à 5 ans","prix":3,"accords":["crustace","volaille","curry","epice_douce","fromage_molle","fruits_jaunes"],"eviter":["huitre","vinaigre","viande_rouge"],"classique":"Viognier de Virginie et crabe bleu de la Chesapeake","note":"Thomas Jefferson tenta d'y planter la vigne dès 1773 à Monticello, sans succès. La région s'est relancée depuis 1980 autour de Charlottesville, étés chauds et humides. Le viognier, cépage officiel de l'État depuis 2011, donne un blanc parfumé ; cabernet franc et petit verdot réussissent en rouge.","lat":38.03,"lon":-78.48,"importance":2,"niveau":"decouverte"},{"id":"us-columbia-valley","nom":"Columbia Valley","pays":"États-Unis","region":"Washington","sousRegion":"Columbia Valley","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Riesling sec ou demi-sec, pomme verte et citron, rendu célèbre par Chateau Ste. Michelle."}],"cepages":["Cabernet Sauvignon","Merlot","Syrah","Riesling"],"style":"Cassis, cerise noire, cacao et herbes sèches ; fruit net, acidité fraîche, tanins souples.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","grille","roti","volaille","mijote","fromage_dure"],"eviter":["huitre","poisson_cru","asperge"],"classique":"Merlot de Columbia Valley et steak grillé","note":"Immense aire de l'État de Washington, à l'est des Cascades, en climat semi-désertique irrigué par le fleuve Columbia : 300 jours de soleil, nuits très fraîches, latitude de Bordeaux. Rouges au fruit net et à l'acidité conservée, rieslings réputés. Appellation générique, bon rapport prix-plaisir.","lat":46.25,"lon":-119.3,"importance":3,"niveau":"classique"},{"id":"us-red-mountain","nom":"Red Mountain","pays":"États-Unis","region":"Washington","sousRegion":"Red Mountain","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot","Syrah"],"style":"Cassis, mûre, graphite et tabac ; très concentré, tanins puissants et serrés, acidité préservée.","temp":"17 à 18 °C","garde":"8 à 20 ans","prix":4,"accords":["viande_rouge","agneau","roti","grille","gibier","fromage_dure"],"eviter":["poisson_cru","huitre","legumes"],"classique":"Cabernet de Red Mountain et côte de bœuf au jus","note":"Colline près de Benton City, dans l'est de Washington : l'aire la plus chaude et la plus sèche de l'État, sols sablonneux pauvres, vent constant. Cabernets les plus tanniques et structurés du Nord-Ouest (Ciel du Cheval, Klipsun). Vin de longue garde qui réclame une viande rouge et de la patience.","lat":46.28,"lon":-119.45,"importance":3,"niveau":"classique"},{"id":"us-walla-walla-valley","nom":"Walla Walla Valley","pays":"États-Unis","region":"Washington","sousRegion":"Walla Walla Valley","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Syrah","Cabernet Sauvignon","Merlot"],"style":"Mûre, olive noire, fumée, viande et poivre blanc pour la syrah ; dense, frais, tanins fins et longs.","temp":"16 à 18 °C","garde":"6 à 15 ans","prix":3,"accords":["viande_rouge","agneau","gibier","grille","roti","fromage_dure"],"eviter":["huitre","poisson_maigre","acide"],"classique":"Syrah de Walla Walla et agneau grillé aux herbes","note":"Vallée à cheval sur Washington et l'Oregon, autour de Walla Walla. Les galets roulés du secteur The Rocks, côté Oregon, donnent des syrahs sauvages et fumées, proches du Rhône nord ; cabernet et merlot brillent aussi depuis Leonetti et Cayuse. Rouges de garde, pour une viande rouge ou un gibier.","lat":46.06,"lon":-118.34,"importance":3,"niveau":"classique"},{"id":"us-yakima-valley","nom":"Yakima Valley","pays":"États-Unis","region":"Washington","sousRegion":"Yakima Valley","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Riesling et chardonnay frais, ananas et pomme verte."}],"cepages":["Merlot","Cabernet Sauvignon","Syrah","Chardonnay"],"style":"Cerise, prune, herbes et poivron doux ; fruité, acidité fraîche, tanins mi-fermes.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["viande_rouge","volaille","porc","grille","mijote","fromage_dure"],"eviter":["huitre","poisson_cru","acide"],"classique":"Merlot de Yakima et longe de porc rôtie","note":"Première aire reconnue de Washington (1983), au sein de la Columbia Valley, le long de la rivière Yakima ; vergers de pommiers et houblon voisinent avec la vigne. Climat plus frais que Red Mountain : merlots et cabernets fruités, syrahs épicées, blancs tendus. Rouges de table sans prétention.","lat":46.45,"lon":-120.2,"importance":2,"niveau":"decouverte"},{"id":"fr-alsace-gewurztraminer","nom":"Alsace Gewurztraminer","pays":"France","region":"Alsace","sousRegion":"","couleur":"blanc","famille":"blanc_aromatique","variantes":[],"cepages":["Gewurztraminer"],"style":"Litchi, rose, épices douces, gingembre ; gras, peu acide, souvent une pointe de sucre.","temp":"8 à 10 °C","garde":"3 à 10 ans","prix":2,"accords":["fromage_lave","curry","asiatique","foie_gras","epice_douce","fruits_exotiques"],"eviter":["huitre","acide","viande_rouge"],"classique":"Gewurztraminer et munster","note":"Cépage à peau rosée qui donne le blanc le plus parfumé d'Alsace : litchi et rose sont impossibles à confondre. Souvent légèrement sucré et peu acide, il demande des plats puissants : munster, cuisine thaïe ou indienne, foie gras. À servir frais mais pas glacé.","lat":48.08,"lon":7.36,"importance":5,"niveau":"incontournable"},{"id":"fr-alsace-riesling","nom":"Alsace Riesling","pays":"France","region":"Alsace","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Riesling"],"style":"Citron, pêche blanche, pierre à fusil, note de pétrole en vieillissant ; sec, droit, tendu.","temp":"8 à 10 °C","garde":"3 à 15 ans","prix":2,"accords":["poisson_maigre","crustace","porc","fume","asiatique","fromage_lave"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Riesling et choucroute garnie","note":"Cépage roi de l'Alsace, planté sur les coteaux granitiques et calcaires au pied des Vosges. Sec et tendu, loin des rieslings allemands plus doux, il développe avec l'âge une note de pétrole typique. Le vin de la choucroute, des poissons au beurre blanc et du munster.","lat":48.2,"lon":7.32,"importance":5,"niveau":"incontournable"},{"id":"fr-alsace-grand-cru","nom":"Alsace Grand Cru","pays":"France","region":"Alsace","sousRegion":"","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Certains grands crus de gewurztraminer ou de pinot gris gardent du sucre résiduel."}],"cepages":["Riesling","Gewurztraminer","Pinot gris","Muscat"],"style":"Selon le cépage : dense, minéral ou épicé ; longueur et profondeur nettement au-dessus du générique.","temp":"9 à 11 °C","garde":"5 à 20 ans","prix":3,"accords":["poisson_maigre","crustace","volaille","foie_gras","fromage_lave","truffe"],"eviter":["piquant","vinaigre"],"classique":"Riesling grand cru et sandre au riesling","note":"51 lieux-dits classés (Schlossberg, Rangen, Hengst...), rendements limités, quatre cépages nobles sauf exceptions (sylvaner au Zotzenberg, pinot noir sur trois crus depuis 2022). Chaque terroir (granit, grès, calcaire, roche volcanique) marque le vin. Blancs de garde, pour un plat construit.","lat":48.17,"lon":7.3,"importance":4,"niveau":"classique"},{"id":"fr-alsace-pinot-gris","nom":"Alsace Pinot gris","pays":"France","region":"Alsace","sousRegion":"","couleur":"blanc","famille":"blanc_aromatique","variantes":[],"cepages":["Pinot gris"],"style":"Fumé, miel, poire, sous-bois, pointe de sucre ; ample, gras, long.","temp":"9 à 11 °C","garde":"3 à 10 ans","prix":2,"accords":["volaille","foie_gras","champignon","roti","creme","porc"],"eviter":["huitre","acide"],"classique":"Pinot gris et volaille aux morilles","note":"Anciennement « Tokay d'Alsace », nom abandonné en 2007 à la demande de la Hongrie. Plus riche et moins exubérant que le gewurztraminer, il joue sur le fumé et le miel avec une texture grasse. Un blanc de viande : volaille à la crème, rôti de porc, champignons.","lat":48.08,"lon":7.36,"importance":4,"niveau":"classique"},{"id":"fr-alsace-muscat","nom":"Alsace Muscat","pays":"France","region":"Alsace","sousRegion":"","couleur":"blanc","famille":"blanc_aromatique","variantes":[],"cepages":["Muscat d'Alsace","Muscat ottonel"],"style":"Raisin frais croqué, fleur d'oranger, sauge ; sec, léger, aérien.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":2,"accords":["asperge","legumes","fromage_chevre","herbes","asiatique"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Muscat d'Alsace et asperges","note":"Un des rares muscats secs de France, à l'inverse des muscats doux du Sud. Il sent le raisin qu'on vient de croquer et reste léger en bouche. C'est le vin classique des asperges, un plat qui tue la plupart des autres vins. À boire jeune, à l'apéritif ou au printemps.","lat":48.17,"lon":7.3,"importance":3,"niveau":"classique"},{"id":"fr-alsace-pinot-blanc","nom":"Alsace Pinot blanc","pays":"France","region":"Alsace","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Pinot blanc","Auxerrois"],"style":"Pomme, poire, fleurs, texture ronde, acidité douce ; sec et facile.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":1,"accords":["volaille","oeuf","poisson_maigre","vapeur","fromage_frais","legumes"],"eviter":["viande_rouge","piquant"],"classique":"Pinot blanc et quiche lorraine","note":"Souvent assemblé avec l'auxerrois, plus rond, sous le même nom. Blanc sans prétention, ni très aromatique ni très vif, qui sert aussi de base au crémant d'Alsace. Sa souplesse le rend utile sur les quiches, les œufs, les poissons vapeur et les plats de semaine.","lat":48.08,"lon":7.36,"importance":3,"niveau":"classique"},{"id":"fr-alsace-pinot-noir","nom":"Alsace Pinot noir","pays":"France","region":"Alsace","sousRegion":"","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Pinot noir"],"style":"Cerise, framboise, pointe de fumé ; léger, frais, tanins fins, plus dense depuis les années 2010.","temp":"13 à 15 °C","garde":"2 à 8 ans","prix":2,"accords":["volaille","charcuterie","porc","champignon","fromage_molle","poisson_gras"],"eviter":["piquant","fromage_bleu"],"classique":"Pinot noir d'Alsace et baeckeoffe","note":"Seul cépage rouge autorisé en Alsace, longtemps vinifié en rosé foncé. Le réchauffement et des vignerons ambitieux donnent aujourd'hui des rouges plus mûrs ; trois grands crus l'admettent depuis 2022 (Hengst, Kirchberg de Barr, Vorbourg). Un rouge de charcuterie et de volaille.","lat":48.08,"lon":7.36,"importance":3,"niveau":"classique"},{"id":"fr-alsace-vendanges-tardives","nom":"Alsace Vendanges tardives","pays":"France","region":"Alsace","sousRegion":"","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Gewurztraminer","Pinot gris","Riesling","Muscat"],"style":"Abricot confit, miel, coing, épices ; moelleux, sucre tenu par l'acidité, cépage reconnaissable.","temp":"8 à 10 °C","garde":"5 à 20 ans","prix":3,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","fruits_exotiques"],"eviter":["viande_rouge","huitre","vinaigre"],"classique":"Gewurztraminer vendanges tardives et foie gras","note":"Mention créée en 1984 : raisins surmûris, récoltés tard, parfois touchés par la pourriture noble, richesse minimale contrôlée à la vendange. Le sucre reste modéré et le vin garde le profil de son cépage. À servir sur un foie gras, un bleu ou un dessert aux fruits, jamais glacé.","lat":48.08,"lon":7.36,"importance":3,"niveau":"classique"},{"id":"fr-cremant-d-alsace","nom":"Crémant d'Alsace","pays":"France","region":"Alsace","sousRegion":"","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"bulles","famille":"bulles","note":"Crémant rosé, 100 % pinot noir, fraise et framboise."}],"cepages":["Pinot blanc","Auxerrois","Chardonnay","Pinot noir"],"style":"Bulles fines, pomme, fleurs blanches, pointe briochée ; sec, frais, simple.","temp":"6 à 8 °C","garde":"1 à 3 ans","prix":2,"accords":["huitre","coquillage","frit","volaille","fromage_frais","patisserie"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Crémant d'Alsace et kougelhopf salé","note":"Premier crémant de France en volume, méthode traditionnelle reconnue en 1976, neuf mois minimum sur lattes. Pinot blanc et auxerrois en base, chardonnay et pinot noir en appoint. Moins complexe qu'un champagne, trois fois moins cher : l'effervescent d'apéritif et de brunch.","lat":48.08,"lon":7.36,"importance":3,"niveau":"classique"},{"id":"fr-alsace-edelzwicker-gentil","nom":"Alsace Edelzwicker et Gentil","pays":"France","region":"Alsace","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Pinot blanc","Riesling","Gewurztraminer","Sylvaner"],"style":"Fruité simple, fleurs, pomme, touche d'épices ; sec, léger, à boire jeune.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":1,"accords":["charcuterie","oeuf","legumes","poisson_maigre","fromage_frais"],"eviter":["viande_rouge","gibier"],"classique":"Edelzwicker et tarte flambée","note":"Assemblage de cépages blancs d'Alsace, sans proportion imposée : l'Edelzwicker est la version courante, le Gentil impose au moins 50 % de cépages nobles vinifiés à part. Vin de pichet des winstubs, à boire jeune et frais sur une tarte flambée ou une assiette de charcuterie.","lat":48.08,"lon":7.36,"importance":2,"niveau":"decouverte"},{"id":"fr-alsace-selection-grains-nobles","nom":"Alsace Sélection de grains nobles","pays":"France","region":"Alsace","sousRegion":"","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Gewurztraminer","Pinot gris","Riesling","Muscat"],"style":"Confiture d'abricot, miel, safran, orange confite ; liquoreux, très concentré, acidité nette.","temp":"8 à 10 °C","garde":"10 à 30 ans","prix":4,"accords":["foie_gras","fromage_bleu","patisserie","fruits_exotiques","caramel"],"eviter":["viande_rouge","huitre","acide"],"classique":"Sélection de grains nobles et tarte Tatin","note":"Le sommet de l'échelle alsacienne : tri de grains atteints par la pourriture noble, richesse supérieure à celle des vendanges tardives, seulement les bonnes années. Petits volumes, prix élevé. Un vin de méditation ou de foie gras, à ouvrir en petite quantité, bien frais.","lat":48.08,"lon":7.36,"importance":2,"niveau":"decouverte"},{"id":"fr-alsace-sylvaner","nom":"Alsace Sylvaner","pays":"France","region":"Alsace","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Sylvaner"],"style":"Pomme verte, herbe coupée, fleurs blanches, légère amertume ; sec, simple, désaltérant.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":1,"accords":["coquillage","poisson_maigre","charcuterie","oeuf","legumes","fromage_frais"],"eviter":["viande_rouge","epice_douce"],"classique":"Sylvaner et tarte flambée","note":"Cépage en recul en Alsace, longtemps cantonné aux vins de soif, mais le grand cru Zotzenberg à Mittelbergheim lui est ouvert depuis 2005. Sec, léger, un peu amer, il accompagne la tarte flambée, les escargots et la charcuterie du quotidien, sans se faire remarquer.","lat":48.41,"lon":7.45,"importance":2,"niveau":"decouverte"},{"id":"fr-beaujolais","nom":"Beaujolais","pays":"France","region":"Beaujolais","sousRegion":"","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Beaujolais blanc de chardonnay, frais et fruité, une petite part de la production."},{"couleur":"rose","famille":"rose","note":"Rosé de gamay, léger et fruité, à boire dans l'année."}],"cepages":["Gamay"],"style":"Léger et fruité : cerise, framboise, parfois banane et bonbon sur les Nouveaux ; tanins fins, bouche fraîche et gouleyante.","temp":"12 à 14 °C","garde":"1 à 3 ans","prix":1,"accords":["charcuterie","volaille","porc","fromage_chevre","grille"],"eviter":["viande_rouge","piquant","chocolat"],"classique":"Beaujolais et saucisson lyonnais","note":"Appellation régionale du sud du vignoble, sur les sols argilo-calcaires des Pierres dorées. Le gamay y donne un rouge léger, souvent vinifié en macération semi-carbonique, à servir frais dans sa jeunesse. Le Beaujolais Nouveau sort le troisième jeudi de novembre.","lat":45.99,"lon":4.72,"importance":5,"niveau":"incontournable"},{"id":"fr-fleurie","nom":"Fleurie","pays":"France","region":"Beaujolais","sousRegion":"Crus du Beaujolais","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Gamay"],"style":"Iris, violette, rose, fruits rouges ; bouche soyeuse et élégante, tanins fins, finale fraîche et parfumée.","temp":"13 à 15 °C","garde":"2 à 6 ans","prix":2,"accords":["volaille","porc","charcuterie","fromage_molle","roti"],"eviter":["crustace","piquant","chocolat"],"classique":"Fleurie et poulet de Bresse à la crème","note":"Surnommé la reine du Beaujolais pour sa finesse, sur un granit rose qui se délite en sable. Le lieu-dit La Madone, au pied de la chapelle, est le plus réputé. Le cru le plus floral et le plus féminin de la série, à ouvrir entre deux et cinq ans sur une volaille.","lat":46.19,"lon":4.7,"importance":4,"niveau":"classique"},{"id":"fr-morgon","nom":"Morgon","pays":"France","region":"Beaujolais","sousRegion":"Crus du Beaujolais","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Gamay"],"style":"Cerise noire, kirsch, prune et notes terreuses ; bouche charnue, tanins mûrs, le cru qui ressemble le plus à un bourgogne.","temp":"15 à 17 °C","garde":"4 à 10 ans","prix":2,"accords":["viande_rouge","roti","gibier","mijote","charcuterie","fromage_dure"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Morgon et bœuf bourguignon","note":"Autour de Villié-Morgon, sur un schiste décomposé que les vignerons appellent roche pourrie. Le climat Côte du Py, sur une butte volcanique, en est le cœur. Le morgon vieillit bien et prend des notes de kirsch : on dit qu'il morgonne. Le cru le plus dense après Moulin-à-Vent.","lat":46.16,"lon":4.68,"importance":4,"niveau":"incontournable"},{"id":"fr-moulin-a-vent","nom":"Moulin-à-Vent","pays":"France","region":"Beaujolais","sousRegion":"Crus du Beaujolais","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Gamay"],"style":"Fruits noirs, violette, épices et notes de sous-bois avec l'âge ; bouche puissante pour un gamay, tanins serrés.","temp":"15 à 17 °C","garde":"5 à 15 ans","prix":2,"accords":["viande_rouge","gibier","roti","mijote","fromage_dure","truffe"],"eviter":["huitre","poisson_maigre","piquant"],"classique":"Moulin-à-Vent et gigot d'agneau rôti","note":"Le cru le plus structuré du Beaujolais, nommé d'après le moulin du XVe siècle qui domine Romanèche-Thorins. Le granit y est riche en manganèse, ce que la tradition associe à la puissance des vins. Il se goûte comme un bourgogne et demande cinq ans de cave pour s'ouvrir.","lat":46.18,"lon":4.74,"importance":4,"niveau":"incontournable"},{"id":"fr-beaujolais-villages","nom":"Beaujolais-Villages","pays":"France","region":"Beaujolais","sousRegion":"","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Beaujolais-Villages blanc de chardonnay, rare, tendu et floral."}],"cepages":["Gamay"],"style":"Fruits rouges mûrs, note poivrée, un peu plus de chair et de tanins que le Beaujolais simple, finale fraîche.","temp":"13 à 15 °C","garde":"2 à 4 ans","prix":1,"accords":["charcuterie","volaille","porc","grille","fromage_molle"],"eviter":["poisson_cru","piquant","chocolat"],"classique":"Beaujolais-Villages et andouillette grillée","note":"Trente-huit communes du nord du vignoble, sur les coteaux granitiques entre les crus. Un cran au-dessus du Beaujolais régional : plus de matière, plus de fruit mûr, sans perdre la buvabilité. Un rouge de bistrot à servir légèrement rafraîchi, sur la cuisine lyonnaise.","lat":46.16,"lon":4.59,"importance":3,"niveau":"classique"},{"id":"fr-brouilly","nom":"Brouilly","pays":"France","region":"Beaujolais","sousRegion":"Crus du Beaujolais","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Gamay"],"style":"Fruits rouges frais, prune, touche florale ; bouche souple, ronde et friande, tanins légers.","temp":"13 à 15 °C","garde":"2 à 5 ans","prix":2,"accords":["charcuterie","volaille","porc","grille","fromage_molle"],"eviter":["crustace","piquant","chocolat"],"classique":"Brouilly et poulet rôti du dimanche","note":"Le plus vaste et le plus méridional des dix crus, réparti sur six communes au pied du mont Brouilly. Sols variés, granit et roches bleues, qui donnent un gamay rond et fruité, prêt tôt. Le cru d'entrée dans la gamme, à boire jeune sur une table simple.","lat":46.12,"lon":4.69,"importance":3,"niveau":"classique"},{"id":"fr-julienas","nom":"Juliénas","pays":"France","region":"Beaujolais","sousRegion":"Crus du Beaujolais","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Gamay"],"style":"Fraise, pêche de vigne, épices et cannelle ; bouche charnue et vineuse, tanins ronds, bonne longueur.","temp":"14 à 16 °C","garde":"3 à 7 ans","prix":2,"accords":["viande_rouge","charcuterie","roti","mijote","fromage_dure"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Juliénas et coq au vin","note":"Au nord du vignoble, un cru qui doit son nom à Jules César selon la tradition locale. Sols complexes, granit, schistes et argiles, qui donnent un gamay plus vineux que ses voisins, avec de la chair et des épices. Un rouge de plat mijoté, à ouvrir après deux ou trois ans.","lat":46.23,"lon":4.72,"importance":3,"niveau":"classique"},{"id":"fr-saint-amour","nom":"Saint-Amour","pays":"France","region":"Beaujolais","sousRegion":"Crus du Beaujolais","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Gamay"],"style":"Kirsch, pêche, réséda et épices ; bouche tendre et fruitée, tanins fins, deux styles selon la macération.","temp":"13 à 15 °C","garde":"2 à 6 ans","prix":2,"accords":["charcuterie","volaille","porc","fromage_molle","roti"],"eviter":["huitre","piquant","chocolat"],"classique":"Saint-Amour et volaille de Bresse rôtie","note":"Le cru le plus au nord, le seul situé en Saône-et-Loire, à la frontière du Mâconnais. Son nom, hérité d'un soldat romain devenu saint, en fait le vin de la Saint-Valentin. Sols de granit et d'argile : les vignerons y produisent soit un vin léger et tendre, soit un vin plus charpenté.","lat":46.24,"lon":4.74,"importance":3,"niveau":"classique"},{"id":"fr-chenas","nom":"Chénas","pays":"France","region":"Beaujolais","sousRegion":"Crus du Beaujolais","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Gamay"],"style":"Fruits noirs, pivoine, épices et une note boisée ; bouche charnue, tanins présents mais fins, finale longue.","temp":"15 à 17 °C","garde":"4 à 10 ans","prix":2,"accords":["viande_rouge","roti","gibier","champignon","fromage_dure"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Chénas et côte de bœuf aux cèpes","note":"Le plus petit des crus du Beaujolais, voisin direct de Moulin-à-Vent, sur granit et sables. Son nom vient des chênes qui couvraient la colline avant la vigne. Le gamay y est structuré, apte au vieillissement, souvent élevé en fût : un rouge de viande rôtie plus que d'apéritif.","lat":46.21,"lon":4.72,"importance":2,"niveau":"decouverte"},{"id":"fr-chiroubles","nom":"Chiroubles","pays":"France","region":"Beaujolais","sousRegion":"Crus du Beaujolais","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Gamay"],"style":"Violette, pivoine, framboise et groseille ; bouche légère, aérienne, tanins soyeux, très digeste.","temp":"12 à 14 °C","garde":"1 à 4 ans","prix":2,"accords":["charcuterie","volaille","fromage_chevre","legumes","grille"],"eviter":["viande_rouge","gibier","piquant"],"classique":"Chiroubles et terrine de campagne","note":"Le cru le plus haut du Beaujolais, entre 250 et 450 mètres d'altitude, sur un amphithéâtre de granit. L'altitude retarde la maturité et garde l'acidité : c'est le plus léger et le plus floral des dix crus. Un gamay à servir frais, l'été, sur une planche de charcuterie.","lat":46.19,"lon":4.65,"importance":2,"niveau":"decouverte"},{"id":"fr-cote-de-brouilly","nom":"Côte de Brouilly","pays":"France","region":"Beaujolais","sousRegion":"Crus du Beaujolais","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Gamay"],"style":"Cerise noire, violette, note minérale et poivrée ; bouche plus dense et plus tendue que le Brouilly, tanins fins.","temp":"14 à 16 °C","garde":"3 à 8 ans","prix":2,"accords":["volaille","porc","charcuterie","roti","champignon"],"eviter":["poisson_maigre","piquant","chocolat"],"classique":"Côte de Brouilly et caille rôtie aux champignons","note":"Les pentes du mont Brouilly, un ancien volcan dont la roche bleue, une diorite, affleure partout. Exposition de tous côtés et sols pauvres : le gamay y gagne en concentration et en droiture face au Brouilly de plaine. Un cru qui mérite deux ou trois ans de bouteille.","lat":46.1,"lon":4.66,"importance":2,"niveau":"decouverte"},{"id":"fr-regnie","nom":"Régnié","pays":"France","region":"Beaujolais","sousRegion":"Crus du Beaujolais","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Gamay"],"style":"Groseille, framboise, mûre et note florale ; bouche souple, fruitée et droite, tanins légers.","temp":"13 à 15 °C","garde":"2 à 5 ans","prix":2,"accords":["charcuterie","volaille","porc","grille","fromage_chevre"],"eviter":["viande_rouge","gibier","piquant"],"classique":"Régnié et cervelas pistaché","note":"Le dernier-né des crus, classé en 1988, entre Morgon et Brouilly, sur un granit rose sableux. Le village se reconnaît à son église à deux clochers. Le vin est dans le style friand et fruité des crus du sud : un gamay de soif à servir rafraîchi, plus proche de Brouilly que de Morgon.","lat":46.15,"lon":4.65,"importance":2,"niveau":"decouverte"},{"id":"fr-bordeaux","nom":"Bordeaux","pays":"France","region":"Bordelais","sousRegion":"","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Bordeaux blanc : sauvignon et sémillon, sec, agrumes et buis, pour coquillages et poissons."},{"couleur":"rose","famille":"rose","note":"Rosé et clairet, un rosé foncé propre à Bordeaux, pour les grillades d'été."}],"cepages":["Merlot","Cabernet Sauvignon","Cabernet Franc","Petit Verdot"],"style":"Fruits rouges et noirs, cassis, tanins souples, boisé discret ; un rouge de table équilibré, facile à servir.","temp":"16 à 18 °C","garde":"2 à 5 ans","prix":1,"accords":["viande_rouge","grille","volaille","charcuterie","fromage_dure","mijote"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Bordeaux rouge et entrecôte à la bordelaise","note":"L'appellation régionale couvre tout le vignoble girondin, sur les deux rives de la Garonne et de la Dordogne. Le merlot domine et donne un rouge souple, au fruit net et aux tanins fins, à ouvrir jeune sur la cuisine de tous les jours, viandes grillées ou plats mijotés.","lat":44.84,"lon":-0.58,"importance":5,"niveau":"incontournable"},{"id":"fr-margaux","nom":"Margaux","pays":"France","region":"Bordelais","sousRegion":"Médoc","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot","Petit Verdot","Cabernet Franc"],"style":"Le plus fin des Médoc : violette, fruits rouges, cèdre, tanins soyeux et bouche élégante plutôt que massive.","temp":"17 à 18 °C","garde":"8 à 25 ans","prix":3,"accords":["viande_rouge","agneau","roti","volaille","truffe","fromage_dure"],"eviter":["piquant","poisson_cru","vinaigre"],"classique":"Margaux et carré d'agneau rôti aux herbes","note":"Appellation communale du Médoc étendue sur cinq villages, aux graves fines et profondes qui donnent au cabernet sauvignon une finesse réputée. Vingt et un crus classés, dont Château Margaux, Premier cru de 1855. Vin de garde à carafer, à servir sur l'agneau et les viandes rouges peu sauçées.","lat":45.04,"lon":-0.68,"importance":5,"niveau":"incontournable"},{"id":"fr-pauillac","nom":"Pauillac","pays":"France","region":"Bordelais","sousRegion":"Médoc","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"style":"Le plus puissant du Médoc : cassis, cèdre, graphite, tabac ; tanins denses, longue garde, cabernet affirmé.","temp":"17 à 18 °C","garde":"10 à 30 ans","prix":3,"accords":["viande_rouge","agneau","gibier","roti","truffe","fromage_dure"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Pauillac et agneau de Pauillac rôti","note":"Pauillac réunit trois des cinq Premiers crus classés de 1855 (Lafite, Latour, Mouton Rothschild) sur des graves profondes face à l'estuaire. Le cabernet sauvignon y domine et donne des rouges tanniques, longs à s'ouvrir, à servir carafés après dix ans sur l'agneau de lait local ou un gibier.","lat":45.2,"lon":-0.75,"importance":5,"niveau":"incontournable"},{"id":"fr-pomerol","nom":"Pomerol","pays":"France","region":"Bordelais","sousRegion":"Libournais","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon"],"style":"Merlot velouté : prune, truffe, violette, cacao ; texture ample et tanins soyeux, puissance sans dureté.","temp":"17 à 18 °C","garde":"8 à 30 ans","prix":4,"accords":["viande_rouge","truffe","canard","gibier","roti","champignon"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Pomerol et filet de bœuf aux truffes","note":"Plateau de graves et d'argiles bleues au nord-est de Libourne, sans classement officiel mais avec des crus mythiques, Petrus ou Le Pin, à la production minuscule. Le merlot y donne des rouges amples et veloutés, truffés avec l'âge. Appellation parmi les plus chères du monde, pour les grandes tables.","lat":44.93,"lon":-0.2,"importance":5,"niveau":"incontournable"},{"id":"fr-saint-emilion","nom":"Saint-Émilion","pays":"France","region":"Bordelais","sousRegion":"Libournais","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon"],"style":"Merlot et cabernet franc : cerise, prune, épices, note de sous-bois, tanins ronds ; rouge gourmand et accessible.","temp":"16 à 18 °C","garde":"4 à 12 ans","prix":2,"accords":["viande_rouge","canard","roti","volaille","champignon","fromage_dure"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Saint-Émilion et confit de canard","note":"Cité médiévale classée par l'Unesco, Saint-Émilion domine un vignoble de plateau calcaire, de côtes argileuses et de plaine sableuse vers la Dordogne. L'appellation de base, à boire dans les cinq ans, donne des rouges ronds et fruités, merlot en tête, taillés pour la cuisine du Sud-Ouest.","lat":44.89,"lon":-0.16,"importance":5,"niveau":"incontournable"},{"id":"fr-saint-emilion-grand-cru","nom":"Saint-Émilion Grand Cru","pays":"France","region":"Bordelais","sousRegion":"Libournais","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon"],"style":"Plus concentré et plus boisé : fruits noirs, truffe, cacao, tanins mûrs et longs ; le plateau calcaire donne la tension.","temp":"17 à 18 °C","garde":"8 à 25 ans","prix":3,"accords":["viande_rouge","gibier","truffe","roti","agneau","fromage_dure"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Saint-Émilion Grand Cru et entrecôte aux cèpes","note":"Même aire que Saint-Émilion, mais rendement plus bas, degré supérieur et élevage obligatoire. Le classement, révisé environ tous les dix ans depuis 1955, distingue Grands crus classés et Premiers grands crus classés (Pavie, Figeac). Vins de garde à carafer pour les grandes viandes et le gibier.","lat":44.9,"lon":-0.15,"importance":5,"niveau":"incontournable"},{"id":"fr-sauternes","nom":"Sauternes","pays":"France","region":"Bordelais","sousRegion":"Graves","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Sémillon","Sauvignon Blanc","Muscadelle"],"style":"Liquoreux doré : abricot confit, miel, orange amère, safran ; sucre élevé porté par une acidité vive.","temp":"8 à 10 °C","garde":"10 à 50 ans","prix":3,"accords":["foie_gras","fromage_bleu","patisserie","fruits_jaunes","volaille","creme"],"eviter":["viande_rouge","grille","vinaigre"],"classique":"Sauternes et foie gras poêlé","note":"Les brumes d'automne du Ciron, rivière froide qui rejoint la Garonne, déclenchent la pourriture noble (Botrytis cinerea) qui concentre le sémillon sur pied. Récolte par tris successifs, rendements minuscules. Yquem fut le seul Premier cru supérieur en 1855. Frais, sur foie gras ou roquefort.","lat":44.53,"lon":-0.34,"importance":5,"niveau":"incontournable"},{"id":"fr-haut-medoc","nom":"Haut-Médoc","pays":"France","region":"Bordelais","sousRegion":"Médoc","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"style":"Cabernet dominant : cassis, graphite, cèdre, tanins serrés qui s'assouplissent avec les ans ; charpenté et droit.","temp":"17 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["viande_rouge","agneau","roti","grille","gibier","fromage_dure"],"eviter":["poisson_maigre","huitre","asiatique"],"classique":"Haut-Médoc et gigot d'agneau aux haricots","note":"Le Haut-Médoc court de Blanquefort à Saint-Seurin-de-Cadourne, sur les croupes de graves déposées par la Garonne, et englobe les six appellations communales. Cinq crus classés de 1855 y figurent. Les cabernets donnent des rouges droits et structurés, à carafer pour les viandes rouges et l'agneau.","lat":45.11,"lon":-0.73,"importance":4,"niveau":"incontournable"},{"id":"fr-medoc","nom":"Médoc","pays":"France","region":"Bordelais","sousRegion":"Médoc","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"style":"Cassis, cèdre, tabac, tanins fermes mais mûrs ; plus rond et plus merlot que le Haut-Médoc, bon rapport qualité-prix.","temp":"17 à 18 °C","garde":"4 à 10 ans","prix":2,"accords":["viande_rouge","agneau","grille","roti","fromage_dure","gibier"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Médoc et gigot d'agneau rôti","note":"L'appellation Médoc désigne la partie nord de la presqu'île, autour de Lesparre, sur des graves plus mêlées d'argile que le Haut-Médoc. Le merlot y pèse davantage, d'où des rouges un peu plus ronds et prêts plus tôt, souvent des crus bourgeois, parfaits sur un gigot ou une pièce de bœuf.","lat":45.31,"lon":-0.94,"importance":4,"niveau":"incontournable"},{"id":"fr-pessac-leognan","nom":"Pessac-Léognan","pays":"France","region":"Bordelais","sousRegion":"Graves","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Blanc sec de sauvignon et sémillon élevé en barrique : cire, agrumes confits, garde dix ans et plus."}],"cepages":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"style":"Fumée, tabac, cassis, note minérale de graves chaudes ; tanins fins et texture plus soyeuse que le Médoc.","temp":"17 à 18 °C","garde":"8 à 25 ans","prix":3,"accords":["viande_rouge","agneau","roti","gibier","truffe","fromage_dure"],"eviter":["poisson_cru","piquant","sucre_sale"],"classique":"Pessac-Léognan et pigeon rôti","note":"Détachée des Graves en 1987, l'appellation couvre les communes au contact de la ville, où se trouvent tous les crus classés des Graves, Haut-Brion, seul rouge Premier cru de 1855 hors Médoc. Rouge fumé et fin, mais aussi blanc sec de longue garde élevé en barrique, parmi les meilleurs de France.","lat":44.73,"lon":-0.6,"importance":4,"niveau":"incontournable"},{"id":"fr-saint-estephe","nom":"Saint-Estèphe","pays":"France","region":"Bordelais","sousRegion":"Médoc","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"style":"Le Médoc le plus austère jeune : fruits noirs, terre, tanins solides venus des argiles ; s'adoucit après dix ans.","temp":"17 à 18 °C","garde":"8 à 25 ans","prix":3,"accords":["viande_rouge","gibier","mijote","roti","agneau","fromage_dure"],"eviter":["poisson_maigre","poisson_cru","piquant"],"classique":"Saint-Estèphe et civet de chevreuil","note":"Commune la plus au nord des grandes appellations du Médoc, aux graves posées sur des argiles plus fraîches, ce qui retient l'eau en été et donne des vins charpentés, un peu rustiques jeunes. Cinq crus classés, dont Cos d'Estournel et Montrose. Vin de table de gibier et de plats mijotés.","lat":45.26,"lon":-0.77,"importance":4,"niveau":"incontournable"},{"id":"fr-saint-julien","nom":"Saint-Julien","pays":"France","region":"Bordelais","sousRegion":"Médoc","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"style":"Équilibre médocain par excellence : cassis, cèdre, mine de crayon, tanins fins et droits, longueur nette.","temp":"17 à 18 °C","garde":"8 à 25 ans","prix":3,"accords":["viande_rouge","agneau","roti","gibier","champignon","fromage_dure"],"eviter":["poisson_cru","piquant","sucre_sale"],"classique":"Saint-Julien et côte de bœuf grillée aux cèpes","note":"La plus petite des grandes communales du Médoc, serrée entre Margaux et Pauillac, où onze crus classés couvrent la majorité des vignes. Saint-Julien est souvent cité comme la synthèse du Médoc : la structure de Pauillac et la finesse de Margaux. À boire après cinq ans, sur les viandes rôties.","lat":45.15,"lon":-0.74,"importance":4,"niveau":"incontournable"},{"id":"fr-barsac","nom":"Barsac","pays":"France","region":"Bordelais","sousRegion":"Graves","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Sémillon","Sauvignon Blanc","Muscadelle"],"style":"Liquoreux plus léger et plus vif que Sauternes : agrumes confits, miel, fleur d'oranger, finale nerveuse.","temp":"8 à 10 °C","garde":"8 à 40 ans","prix":3,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","crustace","epice_douce"],"eviter":["viande_rouge","grille","chocolat"],"classique":"Barsac et tarte aux pommes","note":"Commune de l'aire de Sauternes qui a gardé le droit à son propre nom : ses sols calcaires, plus plats, donnent des liquoreux plus tendus et moins lourds. Dix crus classés de 1855, dont Climens et Coutet. Même pourriture noble, mais un vin qu'on sert plus tôt, sur les desserts aux fruits ou un crabe.","lat":44.61,"lon":-0.31,"importance":3,"niveau":"classique"},{"id":"fr-bordeaux-superieur","nom":"Bordeaux Supérieur","pays":"France","region":"Bordelais","sousRegion":"","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Un rare blanc moelleux existe sous ce nom, production confidentielle."}],"cepages":["Merlot","Cabernet Sauvignon","Cabernet Franc","Petit Verdot"],"style":"Plus concentré que le Bordeaux : fruits noirs mûrs, réglisse, tanins plus présents, souvent élevé en barrique.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["viande_rouge","roti","agneau","mijote","fromage_dure","sauce_vin_rouge"],"eviter":["poisson_maigre","huitre","sucre_sale"],"classique":"Bordeaux Supérieur et côte de bœuf aux sarments","note":"Même aire que le Bordeaux, mais rendement plus bas, degré minimal plus élevé et élevage d'au moins douze mois avant la vente. Le résultat est un rouge plus dense et plus boisé, qui gagne à attendre deux ou trois ans et accompagne les viandes rôties et les plats en sauce.","lat":44.8,"lon":-0.4,"importance":3,"niveau":"classique"},{"id":"fr-cotes-de-bordeaux","nom":"Côtes de Bordeaux","pays":"France","region":"Bordelais","sousRegion":"Blaye, Cadillac, Castillon, Francs, Sainte-Foy","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Blaye et Francs Côtes de Bordeaux blanc : sauvignon-sémillon sec ; Francs connaît aussi un moelleux."}],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon","Malbec"],"style":"Merlot gourmand : prune, cerise noire, épices douces, tanins ronds ; rouge de coteaux à prix doux.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["viande_rouge","grille","volaille","charcuterie","mijote","fromage_dure"],"eviter":["poisson_cru","huitre","sucre_sale"],"classique":"Castillon Côtes de Bordeaux et confit de canard","note":"Créée en 2009, l'appellation réunit cinq « côtes » de la rive droite : Blaye, Cadillac, Castillon, Francs et, depuis 2016, Sainte-Foy, chaque nom pouvant précéder le sien. Merlot sur argilo-calcaires : rouges charnus proches de Saint-Émilion à Castillon et Francs, plus souples à Blaye et Cadillac.","lat":44.86,"lon":-0.04,"importance":3,"niveau":"classique"},{"id":"fr-cotes-de-bourg","nom":"Côtes de Bourg","pays":"France","region":"Bordelais","sousRegion":"Bourgeais","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Côtes de Bourg blanc : rare blanc sec de sauvignon, sémillon et colombard."}],"cepages":["Merlot","Cabernet Sauvignon","Cabernet Franc","Malbec"],"style":"Rouge charnu et généreux : fruits noirs, épices, tanins fermes mais ronds ; merlot et une part de malbec.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","mijote","grille","charcuterie","canard","fromage_dure"],"eviter":["poisson_cru","huitre","sucre_sale"],"classique":"Côtes de Bourg et lamproie à la bordelaise","note":"Au confluent de la Dordogne et de la Garonne, la « petite Suisse girondine » aligne ses coteaux face au Médoc. Le merlot domine, avec une part notable de malbec, héritage ancien. Rouges charnus, parfois rustiques, de bon rapport qualité-prix, à servir sur des plats mijotés ; un peu de blanc sec.","lat":45.04,"lon":-0.55,"importance":3,"niveau":"classique"},{"id":"fr-entre-deux-mers","nom":"Entre-deux-Mers","pays":"France","region":"Bordelais","sousRegion":"Entre-deux-Mers","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Entre-deux-Mers rouge, admis depuis le millésime 2023 : merlot et cabernets, rouge souple de tous les jours."}],"cepages":["Sauvignon Blanc","Sémillon","Muscadelle","Sauvignon Gris"],"style":"Blanc sec et vif : pamplemousse, buis, fleurs blanches, finale saline ; simple, frais, à boire jeune.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":1,"accords":["huitre","coquillage","crustace","poisson_maigre","fromage_chevre","beurre_citron"],"eviter":["viande_rouge","sauce_vin_rouge","mijote"],"classique":"Entre-deux-Mers et huîtres d'Arcachon","note":"Le plateau entre Garonne et Dordogne, les deux « mers » du nom, est la plus vaste zone viticole de Gironde. L'appellation, longtemps réservée au blanc sec, admet un rouge depuis 2023. Sauvignon dominant, vendange de nuit : un blanc de comptoir, frais et bon marché, pour les huîtres.","lat":44.73,"lon":-0.27,"importance":3,"niveau":"classique"},{"id":"fr-fronsac","nom":"Fronsac","pays":"France","region":"Bordelais","sousRegion":"Libournais","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon"],"style":"Merlot sur calcaire : fruits noirs, truffe, réglisse, tanins fermes qui demandent quelques années ; plus solide que Pomerol.","temp":"17 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["viande_rouge","gibier","roti","mijote","champignon","fromage_dure"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Fronsac et confit de canard aux cèpes","note":"À l'ouest de Libourne, le tertre de Fronsac, où Charlemagne fit bâtir un fort, porte un vignoble de coteaux calcaires et de molasses argileuses. Le merlot y donne des rouges charpentés, longtemps plus réputés que Pomerol, puis oubliés : l'un des meilleurs rapports qualité-prix de la rive droite.","lat":44.92,"lon":-0.27,"importance":3,"niveau":"classique"},{"id":"fr-graves","nom":"Graves","pays":"France","region":"Bordelais","sousRegion":"Graves","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Graves blanc sec : sauvignon et sémillon, agrumes et cire, souvent passé en barrique."},{"couleur":"doux","famille":"blanc_doux","note":"Graves Supérieures : blanc moelleux de sémillon, plus léger qu'un Sauternes."}],"cepages":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"style":"Rouge fumé et souple : fruits rouges, note de fumée et de terre, tanins fins ; blanc sec vif en variante.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","grille","volaille","porc","fume","fromage_dure"],"eviter":["poisson_cru","huitre","sucre_sale"],"classique":"Graves rouge et lamproie à la bordelaise","note":"Au sud de Bordeaux, le vignoble des Graves porte le nom de son sol : galets et graviers déposés par la Garonne, qui drainent et gardent la chaleur. C'est le berceau historique du vin de Bordeaux. Le rouge, merlot et cabernet à parts proches, est souple et un peu fumé ; le blanc sec va au poisson.","lat":44.65,"lon":-0.36,"importance":3,"niveau":"classique"},{"id":"fr-lalande-de-pomerol","nom":"Lalande-de-Pomerol","pays":"France","region":"Bordelais","sousRegion":"Libournais","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon"],"style":"Prune, cerise noire, note de sous-bois, tanins ronds ; un air de Pomerol, plus simple et prêt plus tôt.","temp":"16 à 18 °C","garde":"4 à 12 ans","prix":2,"accords":["viande_rouge","canard","roti","champignon","volaille","fromage_dure"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Lalande-de-Pomerol et magret de canard aux cèpes","note":"Séparée de Pomerol par le ruisseau de la Barbanne, l'appellation réunit Lalande-de-Pomerol et Néac sur des graves et des sables. Merlot dominant, style proche du voisin célèbre, avec moins de densité et un prix plus accessible : une bonne porte d'entrée sur la rive droite, à boire dès quatre ans.","lat":44.95,"lon":-0.22,"importance":3,"niveau":"classique"},{"id":"fr-blaye","nom":"Blaye","pays":"France","region":"Bordelais","sousRegion":"Blayais","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Côtes de Blaye : blanc sec de sauvignon, sémillon et colombard, appellation distincte."}],"cepages":["Merlot","Cabernet Sauvignon","Cabernet Franc","Malbec"],"style":"Rouge dense et rond : cerise noire, mûre, épices, tanins mûrs ; cahier des charges plus strict que le Blaye Côtes de Bordeaux.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["viande_rouge","charcuterie","volaille","grille","fromage_dure"],"eviter":["poisson_cru","huitre","sucre_sale"],"classique":"Blaye rouge et entrecôte à la bordelaise","note":"Face au Médoc, de l'autre côté de l'estuaire, la citadelle de Vauban domine un vignoble de coteaux argilo-calcaires où le merlot domine. L'appellation Blaye, rouge seulement, impose des règles plus exigeantes que Blaye Côtes de Bordeaux (rendements plus bas, élevage plus long) et reste rare.","lat":45.13,"lon":-0.66,"importance":2,"niveau":"classique"},{"id":"fr-cadillac","nom":"Cadillac","pays":"France","region":"Bordelais","sousRegion":"Entre-deux-Mers","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Sémillon","Sauvignon Blanc","Muscadelle"],"style":"Moelleux à liquoreux : fruits jaunes confits, miel léger, finale fraîche ; moins riche que Loupiac et Sainte-Croix.","temp":"8 à 10 °C","garde":"3 à 15 ans","prix":2,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","epice_douce"],"eviter":["viande_rouge","grille","vinaigre"],"classique":"Cadillac et foie gras en terrine","note":"Bastide fondée en 1280 sur la rive droite de la Garonne, Cadillac donne son nom à une appellation de blancs moelleux et liquoreux de sémillon, sur une bande de coteaux d'une vingtaine de kilomètres. Vins plus légers et moins chers que Sauternes, à l'apéritif ou sur un dessert aux fruits.","lat":44.64,"lon":-0.32,"importance":2,"niveau":"classique"},{"id":"fr-canon-fronsac","nom":"Canon-Fronsac","pays":"France","region":"Bordelais","sousRegion":"Libournais","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon"],"style":"Plus dense et plus fin que Fronsac : cerise noire, truffe, graphite, tanins serrés issus du calcaire à astéries.","temp":"17 à 18 °C","garde":"6 à 15 ans","prix":2,"accords":["viande_rouge","gibier","roti","truffe","champignon","fromage_dure"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Canon-Fronsac et entrecôte aux cèpes","note":"Enclave de l'appellation Fronsac sur les communes de Fronsac et Saint-Michel-de-Fronsac, limitée aux coteaux de calcaire à astéries les mieux exposés. Les rouges, merlot dominant, sont plus concentrés et plus longs à s'ouvrir ; une appellation de connaisseurs, à carafer pour les viandes rouges.","lat":44.91,"lon":-0.29,"importance":2,"niveau":"decouverte"},{"id":"fr-cremant-de-bordeaux","nom":"Crémant de Bordeaux","pays":"France","region":"Bordelais","sousRegion":"","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"rose","famille":"bulles","note":"Crémant rosé de merlot et cabernet franc, fruits rouges, pour l'apéritif ou un dessert aux fraises."}],"cepages":["Sémillon","Sauvignon Blanc","Cabernet Franc","Merlot"],"style":"Bulles fines, pomme verte, agrumes, brioche légère ; sec et frais, moins vineux qu'un champagne.","temp":"6 à 8 °C","garde":"1 à 3 ans","prix":2,"accords":["huitre","crustace","poisson_maigre","fromage_frais","patisserie","frit"],"eviter":["viande_rouge","mijote","sauce_vin_rouge"],"classique":"Crémant de Bordeaux et huîtres du bassin d'Arcachon","note":"Reconnu en 1990, ce crémant est fait par la méthode traditionnelle (seconde fermentation en bouteille) à partir des cépages bordelais, sémillon en tête. Blanc ou rosé, il se boit à l'apéritif, sur des huîtres ou des fritures ; il se reconnaît à sa bulle fine et à son fruit blanc net.","lat":44.84,"lon":-0.58,"importance":2,"niveau":"classique"},{"id":"fr-listrac-medoc","nom":"Listrac-Médoc","pays":"France","region":"Bordelais","sousRegion":"Médoc","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"style":"Rouge ferme et droit, fruits noirs, note terreuse, tanins marqués ; plus rustique que Margaux, demande quelques années.","temp":"17 à 18 °C","garde":"5 à 12 ans","prix":2,"accords":["viande_rouge","grille","roti","mijote","fromage_dure","charcuterie"],"eviter":["poisson_cru","huitre","sucre_sale"],"classique":"Listrac-Médoc et entrecôte grillée aux sarments","note":"Listrac occupe le point culminant du Médoc, à 43 mètres, sur des graves pyrénéennes et des argilo-calcaires en retrait de l'estuaire. Sans cru classé, l'appellation vit par ses crus bourgeois : des rouges fermes et honnêtes, qui gagnent à cinq ans de cave, pour les grillades et les viandes braisées.","lat":45.08,"lon":-0.79,"importance":2,"niveau":"classique"},{"id":"fr-loupiac","nom":"Loupiac","pays":"France","region":"Bordelais","sousRegion":"Entre-deux-Mers","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Sémillon","Sauvignon Blanc","Muscadelle"],"style":"Liquoreux de la rive droite : abricot, miel, acacia, bouche douce et fraîche, moins concentré que Sauternes.","temp":"8 à 10 °C","garde":"5 à 20 ans","prix":2,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","volaille","asiatique"],"eviter":["viande_rouge","grille","vinaigre"],"classique":"Loupiac et foie gras mi-cuit","note":"Face à Barsac, sur l'autre rive de la Garonne, Loupiac profite des mêmes brumes matinales et de coteaux argilo-calcaires bien exposés. Ses liquoreux de sémillon offrent une version plus abordable du style Sauternes, à servir frais sur un foie gras, un poulet aux épices ou des fruits jaunes.","lat":44.62,"lon":-0.3,"importance":2,"niveau":"classique"},{"id":"fr-lussac-saint-emilion","nom":"Lussac-Saint-Émilion","pays":"France","region":"Bordelais","sousRegion":"Libournais","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon"],"style":"Fruits rouges et noirs, note florale, tanins souples ; un satellite plus frais, souvent un peu plus léger.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["viande_rouge","volaille","grille","charcuterie","champignon","fromage_dure"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Lussac-Saint-Émilion et poulet rôti","note":"Le plus septentrional des satellites de Saint-Émilion, sur un plateau argilo-calcaire et des pentes de sables et de graves. Le merlot domine, le cabernet franc apporte la fraîcheur. Vins de fruit, un peu plus légers que Montagne, pour un repas de semaine : volaille rôtie, charcuterie, grillade.","lat":44.96,"lon":-0.12,"importance":2,"niveau":"classique"},{"id":"fr-montagne-saint-emilion","nom":"Montagne-Saint-Émilion","pays":"France","region":"Bordelais","sousRegion":"Libournais","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon"],"style":"Merlot souple sur coteaux calcaires : cerise, mûre, épices douces, tanins ronds ; le plus vaste des satellites.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","canard","grille","volaille","champignon","fromage_dure"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Montagne-Saint-Émilion et confit de canard","note":"Au nord de la Barbanne, Montagne est le plus grand des quatre satellites autorisés à accoler le nom de Saint-Émilion, avec des coteaux argilo-calcaires bien exposés. Rouges proches du grand voisin pour une fraction du prix, à boire entre trois et huit ans, sur les plats du Sud-Ouest.","lat":44.93,"lon":-0.13,"importance":2,"niveau":"classique"},{"id":"fr-moulis-en-medoc","nom":"Moulis-en-Médoc","pays":"France","region":"Bordelais","sousRegion":"Médoc","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"style":"Fruits rouges mûrs, cèdre, tanins ronds ; le plus souple des Médoc communaux, accessible dès trois ou quatre ans.","temp":"17 à 18 °C","garde":"4 à 12 ans","prix":2,"accords":["viande_rouge","volaille","roti","canard","fromage_dure","champignon"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Moulis et magret de canard grillé","note":"La plus petite appellation communale du Médoc, en bande étroite entre Margaux et Listrac, avec des croupes de graves au lieu-dit Grand Poujeaux. Sans cru classé mais avec des crus bourgeois réputés (Chasse-Spleen, Poujeaux), elle donne des rouges ronds et charnus, faciles sur une volaille.","lat":45.06,"lon":-0.77,"importance":2,"niveau":"classique"},{"id":"fr-puisseguin-saint-emilion","nom":"Puisseguin-Saint-Émilion","pays":"France","region":"Bordelais","sousRegion":"Libournais","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon"],"style":"Rouge rond et épicé : prune, cerise noire, réglisse, tanins mûrs ; plus solide que Lussac.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","mijote","canard","grille","fromage_dure"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Puisseguin-Saint-Émilion et daube de bœuf","note":"À l'est de Montagne, Puisseguin est, après le minuscule Saint-Georges, le plus petit des satellites, sur un plateau calcaire surmonté d'argiles. Le merlot y donne des rouges plus charpentés que ses voisins du nord, qui supportent cinq ans de cave et vont aux viandes braisées et au canard.","lat":44.93,"lon":-0.08,"importance":2,"niveau":"decouverte"},{"id":"fr-sainte-croix-du-mont","nom":"Sainte-Croix-du-Mont","pays":"France","region":"Bordelais","sousRegion":"Entre-deux-Mers","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Sémillon","Sauvignon Blanc","Muscadelle"],"style":"Liquoreux rond et parfumé : pêche, miel, écorce d'orange, texture onctueuse, belle fraîcheur sur les coteaux.","temp":"8 à 10 °C","garde":"5 à 25 ans","prix":2,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","fruits_exotiques"],"eviter":["viande_rouge","grille","vinaigre"],"classique":"Sainte-Croix-du-Mont et roquefort","note":"Village perché de la rive droite de la Garonne, bâti sur un banc d'huîtres fossiles qui affleure sous l'église. Les coteaux de sémillon font face à Sauternes de l'autre côté du fleuve et reçoivent le même brouillard. Liquoreux de bon rapport prix-plaisir, idéal avec les fromages à pâte persillée.","lat":44.59,"lon":-0.28,"importance":2,"niveau":"classique"},{"id":"fr-cerons","nom":"Cérons","pays":"France","region":"Bordelais","sousRegion":"Graves","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Sémillon","Sauvignon Blanc","Muscadelle"],"style":"Moelleux à liquoreux léger : coing, miel, fleurs blanches, plus frais que Sauternes, souvent moins sucré.","temp":"8 à 10 °C","garde":"5 à 20 ans","prix":2,"accords":["foie_gras","fromage_bleu","fruits_jaunes","volaille","patisserie"],"eviter":["viande_rouge","grille","vinaigre"],"classique":"Cérons et melon au jambon cru","note":"Minuscule appellation de liquoreux enclavée dans les Graves, juste au nord de Barsac, sur la rive gauche de la Garonne. Mêmes cépages et même brouillard du Ciron qu'à Sauternes, mais une production confidentielle et des vins plus légers, à boire plus jeunes, à l'apéritif ou sur un foie gras.","lat":44.64,"lon":-0.33,"importance":1,"niveau":"decouverte"},{"id":"fr-graves-de-vayres","nom":"Graves de Vayres","pays":"France","region":"Bordelais","sousRegion":"Entre-deux-Mers","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Blanc sec de sauvignon et sémillon, frais ; il existe aussi une version moelleuse."}],"cepages":["Merlot","Cabernet Sauvignon","Cabernet Franc"],"style":"Rouge léger et fruité sur graves de Dordogne : fruits rouges, tanins souples ; blanc sec ou moelleux en variante.","temp":"15 à 17 °C","garde":"2 à 5 ans","prix":1,"accords":["charcuterie","grille","volaille","porc","fromage_dure"],"eviter":["poisson_cru","huitre","sucre_sale"],"classique":"Graves de Vayres et grillade de porc","note":"Petite appellation de la rive gauche de la Dordogne, en face de Libourne, sur des terrasses de graves, d'où le nom, sans lien avec les Graves de la Garonne. Rouges légers de merlot à boire jeunes, blancs secs de sauvignon et quelques moelleux : une appellation de proximité, discrète, à prix doux.","lat":44.9,"lon":-0.32,"importance":1,"niveau":"decouverte"},{"id":"fr-saint-georges-saint-emilion","nom":"Saint-Georges-Saint-Émilion","pays":"France","region":"Bordelais","sousRegion":"Libournais","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon"],"style":"Cerise, cassis, note de cuir avec l'âge, tanins fins ; confidentiel, souvent bâti autour du château éponyme.","temp":"16 à 18 °C","garde":"4 à 10 ans","prix":2,"accords":["viande_rouge","canard","roti","champignon","fromage_dure"],"eviter":["poisson_cru","huitre","piquant"],"classique":"Saint-Georges-Saint-Émilion et magret de canard","note":"Minuscule satellite, commune rattachée à Montagne depuis 1973 mais qui a gardé son appellation propre, autour du château Saint-Georges, demeure du XVIIIe siècle visible depuis Saint-Émilion. Coteaux argilo-calcaires, merlot dominant : rouges fins et droits, à chercher chez les cavistes curieux.","lat":44.92,"lon":-0.14,"importance":1,"niveau":"decouverte"},{"id":"fr-chablis","nom":"Chablis","pays":"France","region":"Bourgogne","sousRegion":"Chablis","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Chardonnay"],"style":"Blanc sec, tendu, notes de citron, de pomme verte et de pierre à fusil, finale saline.","temp":"10 à 12 °C","garde":"3 à 8 ans","prix":2,"accords":["huitre","coquillage","poisson_maigre","fromage_chevre","beurre_citron"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Chablis et huîtres de Normandie","note":"Chardonnay planté sur les marnes kimméridgiennes de la vallée du Serein, un ancien fond de mer riche en fossiles d'huîtres. Sans bois ou presque, il se reconnaît à sa droiture et à son goût de pierre mouillée. À servir sur un plateau de fruits de mer.","lat":47.81,"lon":3.8,"importance":5,"niveau":"incontournable"},{"id":"fr-chambertin","nom":"Chambertin","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Pinot noir"],"style":"Rouge profond et structuré, cassis, cerise noire, truffe, cuir, tanins puissants et longs.","temp":"16 à 18 °C","garde":"15 à 30 ans","prix":4,"accords":["viande_rouge","gibier","truffe","roti","sauce_vin_rouge","fromage_lave"],"eviter":["poisson_maigre","acide","piquant"],"classique":"Chambertin et lièvre à la royale","note":"Chambertin et Chambertin-Clos de Bèze sont les deux crus les plus fameux de Gevrey. Le Clos de Bèze, donné aux moines de Bèze en 630, est planté depuis le VIIe siècle ; Chambertin suivit. Vin favori de Napoléon. Sept autres grands crus portent le nom accolé, dont Charmes, Mazis et Latricières.","lat":47.22,"lon":4.96,"importance":5,"niveau":"incontournable"},{"id":"fr-corton-charlemagne","nom":"Corton-Charlemagne","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chardonnay"],"style":"Citron confit, pierre à fusil, noisette, beurre frais, acidité tendue sous une matière dense et longue.","temp":"11 à 13 °C","garde":"8 à 25 ans","prix":4,"accords":["crustace","poisson_gras","volaille","creme","truffe","fromage_dure"],"eviter":["piquant","vinaigre","chocolat"],"classique":"Corton-Charlemagne et homard au beurre blanc","note":"Grand cru blanc du haut de la colline de Corton, sur marnes blanches et exposition ouest et sud-ouest. La légende attribue la plantation de blanc à Charlemagne ; le vin, austère jeune, gagne noisette et miel après 8 ans. Le servir sur un crustacé ou une volaille à la crème.","lat":47.08,"lon":4.85,"importance":5,"niveau":"incontournable"},{"id":"fr-gevrey-chambertin","nom":"Gevrey-Chambertin","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Pinot noir"],"style":"Rouge dense et charnu, cerise noire, réglisse, sous-bois, tanins présents et fins.","temp":"16 à 17 °C","garde":"6 à 15 ans","prix":3,"accords":["viande_rouge","gibier","roti","sauce_vin_rouge","fromage_lave","champignon"],"eviter":["poisson_cru","acide"],"classique":"Gevrey-Chambertin et coq au vin","note":"Plus grand village de la Côte de Nuits, Gevrey abrite neuf grands crus et 26 premiers crus. Ses pinots sont réputés les plus charpentés de la côte, d'où le surnom de « roi des vins ». Le village lui-même offre un rouge sérieux qui gagne à vieillir cinq ans avant la table.","lat":47.23,"lon":4.97,"importance":5,"niveau":"incontournable"},{"id":"fr-meursault","nom":"Meursault","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Rouge très rare (environ 3 %), le plus souvent vendu sous le nom de Volnay-Santenots quand il vient de ce climat."}],"cepages":["Chardonnay"],"style":"Noisette, beurre, pomme mûre, miel et pierre à fusil, bouche grasse et ample portée par une acidité nette.","temp":"11 à 13 °C","garde":"5 à 15 ans","prix":3,"accords":["crustace","poisson_gras","volaille","creme","champignon","fromage_dure"],"eviter":["piquant","vinaigre","chocolat"],"classique":"Meursault et poularde à la crème","note":"Le village blanc le plus étendu de la Côte de Beaune, sans grand cru mais avec des premiers crus de premier plan (Perrières, Genevrières, Charmes). Ses caves profondes ont fait sa réputation d'élevage long sur lies. Mûr vers 5 à 10 ans, sur une volaille à la crème ou un poisson au beurre.","lat":46.98,"lon":4.77,"importance":5,"niveau":"incontournable"},{"id":"fr-montrachet","nom":"Montrachet","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chardonnay"],"style":"Citron confit, noisette, miel, fleurs, fumée, bouche dense, longue et tendue, puissance sans lourdeur.","temp":"12 à 14 °C","garde":"10 à 30 ans","prix":4,"accords":["crustace","poisson_gras","volaille","truffe","creme","foie_gras"],"eviter":["piquant","vinaigre","chocolat"],"classique":"Montrachet et homard à la truffe","note":"Huit hectares à cheval sur Puligny et Chassagne, à mi-coteau, exposés au sud-est : le blanc sec le plus cher du monde, partagé entre une vingtaine de propriétaires (DRC, Lafon, Leflaive). Fermé jeune, il s'ouvre après 10 ans. Le réserver à un crustacé noble ou une volaille truffée.","lat":46.94,"lon":4.74,"importance":5,"niveau":"incontournable"},{"id":"fr-puligny-montrachet","nom":"Puligny-Montrachet","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Rouge anecdotique (moins de 1 %), fin et léger."}],"cepages":["Chardonnay"],"style":"Fleurs blanches, citron, amande fraîche, silex, bouche droite et ciselée, moins grasse qu'un Meursault, longue finale.","temp":"11 à 13 °C","garde":"5 à 15 ans","prix":3,"accords":["crustace","poisson_maigre","poisson_gras","volaille","beurre_citron","fromage_dure"],"eviter":["piquant","vinaigre","chocolat"],"classique":"Puligny-Montrachet et sole meunière","note":"Puligny abrite quatre grands crus (Montrachet et Bâtard en partage avec Chassagne, Chevalier et Bienvenues) et des premiers crus tendus comme les Folatières. La nappe phréatique haute interdit les caves profondes, d'où un élevage en cuverie. Vin de précision plus que de gras, à 5 à 12 ans.","lat":46.95,"lon":4.75,"importance":5,"niveau":"incontournable"},{"id":"fr-romanee-conti","nom":"Romanée-Conti","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Pinot noir"],"style":"Rouge d'une complexité rare, rose, épices orientales, cerise, truffe, texture de soie, finale infinie.","temp":"16 à 17 °C","garde":"20 à 50 ans","prix":4,"accords":["truffe","volaille","canard","viande_rouge","gibier"],"eviter":["piquant","acide","chocolat"],"classique":"Romanée-Conti et poularde de Bresse aux truffes","note":"Un clos de 1,8 hectare au cœur de Vosne-Romanée, monopole du Domaine de la Romanée-Conti, qui n'en tire que 5 000 à 6 000 bouteilles par an. Nommé d'après le prince de Conti, qui l'acheta en 1760. Le vin le plus cher du monde, cultivé en biodynamie, à ouvrir après vingt ans.","lat":47.16,"lon":4.94,"importance":5,"niveau":"incontournable"},{"id":"fr-vosne-romanee","nom":"Vosne-Romanée","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Pinot noir"],"style":"Rouge raffiné et épicé, cerise, cassis, rose, cannelle, tanins fins, bouche veloutée.","temp":"16 à 17 °C","garde":"8 à 20 ans","prix":4,"accords":["volaille","canard","viande_rouge","truffe","champignon","fromage_molle"],"eviter":["piquant","poisson_cru","chocolat"],"classique":"Vosne-Romanée et pigeon rôti","note":"Village qui concentre les grands crus les plus recherchés du monde : Romanée-Conti, La Tâche, Richebourg, Romanée-Saint-Vivant. Son style associe finesse et épices, « velours et dentelle » disent les anciens. Le village et ses premiers crus en donnent une version plus accessible.","lat":47.15,"lon":4.95,"importance":5,"niveau":"incontournable"},{"id":"fr-batard-montrachet","nom":"Bâtard-Montrachet","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chardonnay"],"style":"Beurre noisette, pomme au four, miel, brioche, bouche large et opulente, plus grasse que le Montrachet, longue finale.","temp":"12 à 14 °C","garde":"8 à 25 ans","prix":4,"accords":["crustace","poisson_gras","volaille","creme","truffe","fromage_dure"],"eviter":["piquant","vinaigre","chocolat"],"classique":"Bâtard-Montrachet et turbot sauce hollandaise","note":"Grand cru de 11,9 hectares juste sous le Montrachet, à cheval sur Puligny et Chassagne, sur des sols plus profonds et argileux : d'où un blanc plus riche et plus opulent que son voisin, prêt un peu plus tôt. Bienvenues et Criots sont ses satellites. À 8 à 20 ans sur un poisson noble en sauce.","lat":46.94,"lon":4.75,"importance":4,"niveau":"incontournable"},{"id":"fr-beaune","nom":"Beaune","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Environ 15 % de la production : Chardonnay rond et tendre, de garde moyenne, souvent en premier cru (Clos des Mouches)."}],"cepages":["Pinot noir"],"style":"Cerise, mûre, réglisse et épices douces, tanins fondus, bouche charnue et équilibrée, finale longue.","temp":"15 à 17 °C","garde":"5 à 15 ans","prix":3,"accords":["viande_rouge","roti","volaille","sauce_vin_rouge","champignon","fromage_lave"],"eviter":["poisson_cru","huitre"],"classique":"Beaune et coq au vin","note":"Capitale du vin de Bourgogne et siège des grandes maisons de négoce, Beaune possède le plus grand vignoble de premiers crus de la Côte (Grèves, Clos des Mouches, Teurons). Rouges charnus et équilibrés, mûrs vers 5 à 10 ans ; la vente des Hospices a lieu le troisième dimanche de novembre.","lat":47.02,"lon":4.84,"importance":4,"niveau":"incontournable"},{"id":"fr-bourgogne","nom":"Bourgogne","pays":"France","region":"Bourgogne","sousRegion":"","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Bourgogne blanc de chardonnay, pomme et noisette, souvent sans bois"}],"cepages":["Pinot noir"],"style":"Rouge léger et fruité, cerise, framboise, tanins souples, bouche fraîche.","temp":"14 à 16 °C","garde":"2 à 6 ans","prix":2,"accords":["volaille","charcuterie","porc","champignon","fromage_molle","grille"],"eviter":["poisson_cru","piquant","chocolat"],"classique":"Bourgogne rouge et œufs en meurette","note":"L'appellation régionale couvre toute la Bourgogne, de Chablis au Mâconnais. En rouge, c'est le pinot noir dans sa version la plus simple : fruit, fraîcheur, tanins discrets. Le choix du vigneron fait tout. On le sert sur la cuisine de bistrot, meurette ou volaille rôtie.","lat":47.02,"lon":4.84,"importance":4,"niveau":"classique"},{"id":"fr-chablis-grand-cru","nom":"Chablis Grand Cru","pays":"France","region":"Bourgogne","sousRegion":"Chablis","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Chardonnay"],"style":"Blanc puissant et minéral, miel d'acacia, fruits blancs mûrs, note fumée, longue finale saline.","temp":"12 à 14 °C","garde":"8 à 20 ans","prix":4,"accords":["crustace","poisson_gras","volaille","truffe","creme","fromage_dure"],"eviter":["viande_rouge","piquant","chocolat"],"classique":"Chablis Grand Cru Les Clos et turbot sauce hollandaise","note":"Un seul coteau sur la rive droite du Serein, face à la ville, réunit les sept grands crus : Les Clos, Vaudésir, Valmur, Grenouilles, Blanchot, Bougros et Les Preuses. Souvent élevé en partie sous bois, le vin demande quelques années de cave pour livrer sa richesse.","lat":47.82,"lon":3.81,"importance":4,"niveau":"incontournable"},{"id":"fr-chablis-premier-cru","nom":"Chablis Premier Cru","pays":"France","region":"Bourgogne","sousRegion":"Chablis","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Chardonnay"],"style":"Blanc tendu et plus profond, citron confit, iode, silex, bouche ample qui garde sa fraîcheur.","temp":"11 à 13 °C","garde":"5 à 12 ans","prix":3,"accords":["crustace","poisson_maigre","poisson_gras","volaille","creme","fromage_chevre"],"eviter":["viande_rouge","piquant"],"classique":"Chablis Premier Cru et homard au beurre blanc","note":"Quarante climats de coteaux, dont Montmains, Vaillons, Fourchaume et Montée de Tonnerre, forment les premiers crus. Mieux exposés que le village, ils gagnent en concentration et en longueur tout en gardant la tension chablisienne. Parfait avec un poisson noble en sauce.","lat":47.81,"lon":3.82,"importance":4,"niveau":"classique"},{"id":"fr-chambolle-musigny","nom":"Chambolle-Musigny","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Pinot noir"],"style":"Rouge délicat et parfumé, framboise, rose, violette, texture soyeuse, tanins très fins.","temp":"15 à 17 °C","garde":"6 à 15 ans","prix":3,"accords":["volaille","canard","viande_rouge","champignon","fromage_molle","truffe"],"eviter":["piquant","mijote","poisson_cru"],"classique":"Chambolle-Musigny et poularde à la crème","note":"Village aux sols très calcaires, Chambolle est réputé pour les pinots les plus fins et les plus parfumés de la Côte de Nuits. Le premier cru Les Amoureuses, voisin de Musigny, en est le symbole. On le sert sur des viandes blanches ou un canard rosé, sans sauce trop puissante.","lat":47.18,"lon":4.95,"importance":4,"niveau":"incontournable"},{"id":"fr-chassagne-montrachet","nom":"Chassagne-Montrachet","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Environ un tiers de la production, en recul : Pinot noir fruité et un peu ferme, abordable (Morgeot, Clos Saint-Jean)."}],"cepages":["Chardonnay"],"style":"Pomme mûre, noisette, brioche, pierre chaude, bouche ample et mûre avec une acidité qui tient le tout.","temp":"11 à 13 °C","garde":"5 à 15 ans","prix":3,"accords":["crustace","poisson_gras","volaille","creme","champignon","fromage_dure"],"eviter":["piquant","vinaigre","chocolat"],"classique":"Chassagne-Montrachet et saint-jacques poêlées","note":"Chassagne partage avec Puligny les grands crus Montrachet et Bâtard, et possède seul les Criots-Bâtard. Village longtemps rouge, il est devenu blanc dans les années 1980 ; ses premiers crus (Morgeot, Caillerets, Ruchottes) donnent des blancs plus charnus que Puligny. Mûr vers 5 à 10 ans.","lat":46.93,"lon":4.74,"importance":4,"niveau":"incontournable"},{"id":"fr-clos-de-vougeot","nom":"Clos de Vougeot","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Pinot noir"],"style":"Rouge robuste et terrien, fruits noirs, sous-bois, cuir, tanins fermes, très variable selon la parcelle.","temp":"16 à 18 °C","garde":"10 à 25 ans","prix":4,"accords":["viande_rouge","gibier","roti","sauce_vin_rouge","fromage_lave","truffe"],"eviter":["poisson_maigre","acide"],"classique":"Clos de Vougeot et faisan rôti","note":"Clos de 50 hectares constitué par les moines de Cîteaux dès le XIIe siècle, ceint de murs achevés vers 1336, autour d'un château qui abrite la Confrérie des Chevaliers du Tastevin. Partagé entre quelque 80 propriétaires, du haut au bas de la pente, sa qualité dépend beaucoup de la parcelle.","lat":47.17,"lon":4.96,"importance":4,"niveau":"incontournable"},{"id":"fr-corton","nom":"Corton","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Corton blanc, rare, pris sur les hauts de la colline hors Charlemagne : tendu, puissant, longue garde."}],"cepages":["Pinot noir"],"style":"Cassis, cerise noire, sous-bois et cuir avec l'âge, tanins puissants pour un pinot, longue finale.","temp":"16 à 17 °C","garde":"10 à 25 ans","prix":4,"accords":["viande_rouge","gibier","roti","truffe","sauce_vin_rouge","fromage_lave"],"eviter":["poisson_cru","huitre","sucre_sale"],"classique":"Corton et lièvre à la royale","note":"Seul grand cru rouge de la Côte de Beaune, le Corton couvre la colline partagée entre Aloxe, Ladoix et Pernand, avec une vingtaine de climats (Clos du Roi, Bressandes, Renardes). Le vin est austère jeune et demande 10 ans ; le servir sur un gibier ou une viande rouge en sauce.","lat":47.08,"lon":4.86,"importance":4,"niveau":"incontournable"},{"id":"fr-la-tache","nom":"La Tâche","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Pinot noir"],"style":"Rouge intense et épicé, fruits noirs, réglisse, poivre, texture dense, tanins mûrs et longs.","temp":"16 à 18 °C","garde":"15 à 40 ans","prix":4,"accords":["gibier","viande_rouge","truffe","roti","sauce_vin_rouge"],"eviter":["poisson_maigre","acide","piquant"],"classique":"La Tâche et gigot de chevreuil aux airelles","note":"Monopole de 6 hectares du Domaine de la Romanée-Conti, juste au sud de la Romanée-Conti. Plus puissant et plus sauvage que son voisin, avec une trame épicée qui le rend reconnaissable à l'aveugle. Un vin de garde pour grand gibier, que l'on n'ouvre pas avant quinze ans.","lat":47.15,"lon":4.94,"importance":4,"niveau":"incontournable"},{"id":"fr-musigny","nom":"Musigny","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Musigny blanc, minuscule parcelle de chardonnay du domaine de Vogüé"}],"cepages":["Pinot noir"],"style":"Rouge d'une élégance rare, rose fanée, framboise, épices, texture de velours, longueur immense.","temp":"16 à 17 °C","garde":"15 à 30 ans","prix":4,"accords":["volaille","canard","truffe","viande_rouge","champignon"],"eviter":["piquant","acide","chocolat"],"classique":"Musigny et volaille de Bresse truffée","note":"Grand cru d'un peu plus de 10 hectares au sud de Chambolle, sur un coteau raide et caillouteux. Musigny est tenu pour le pinot noir le plus raffiné de Bourgogne, tout en parfum et en texture plutôt qu'en puissance. Seul grand cru de la Côte de Nuits à produire aussi un peu de blanc.","lat":47.17,"lon":4.95,"importance":4,"niveau":"incontournable"},{"id":"fr-nuits-saint-georges","nom":"Nuits-Saint-Georges","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Blanc rare, de chardonnay ou de pinot blanc"}],"cepages":["Pinot noir"],"style":"Rouge solide et charnu, cerise noire, cassis, réglisse, notes terreuses, tanins fermes.","temp":"16 à 17 °C","garde":"6 à 15 ans","prix":3,"accords":["viande_rouge","gibier","roti","mijote","sauce_vin_rouge","fromage_lave"],"eviter":["poisson_cru","acide"],"classique":"Nuits-Saint-Georges et bœuf bourguignon","note":"Capitale commerçante de la Côte de Nuits, la ville a donné son nom à toute la côte. Ses 41 premiers crus, dont Les Saint-Georges et Les Vaucrains, produisent des rouges plus robustes et terriens que Vosne, taillés pour la garde et les plats mijotés en sauce au vin.","lat":47.14,"lon":4.95,"importance":4,"niveau":"incontournable"},{"id":"fr-pommard","nom":"Pommard","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Pinot noir"],"style":"Cassis, cerise noire, cuir et sous-bois, tanins denses et serrés, bouche puissante pour un pinot, longue garde.","temp":"16 à 17 °C","garde":"8 à 20 ans","prix":3,"accords":["viande_rouge","gibier","roti","sauce_vin_rouge","mijote","fromage_lave"],"eviter":["poisson_cru","huitre","acide"],"classique":"Pommard et côte de bœuf grillée","note":"Appellation rouge uniquement, Pommard donne les vins les plus tanniques de la Côte de Beaune, sur des sols argileux riches en fer. Les premiers crus Rugiens et Épenots sont les plus recherchés. Fermé et sévère jeune, il demande 8 ans ; le servir sur une viande rouge ou un gibier à plume en sauce.","lat":47.01,"lon":4.79,"importance":4,"niveau":"incontournable"},{"id":"fr-pouilly-fuisse","nom":"Pouilly-Fuissé","pays":"France","region":"Bourgogne","sousRegion":"Mâconnais","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chardonnay"],"style":"Pêche, noisette grillée, beurre, miel d'acacia, pierre chaude, bouche ample et mûre, acidité moins marquée qu'en Côte de Beaune.","temp":"11 à 13 °C","garde":"4 à 12 ans","prix":3,"accords":["crustace","poisson_gras","volaille","creme","champignon","fromage_dure"],"eviter":["viande_rouge","piquant","vinaigre"],"classique":"Pouilly-Fuissé et saint-jacques à la crème","note":"Au pied des roches de Solutré et de Vergisson, sur quatre communes (Fuissé, Solutré-Pouilly, Vergisson, Chaintré), c'est le grand blanc du Mâconnais, souvent élevé en fût. Vingt-deux premiers crus reconnus depuis le millésime 2020. Plus solaire qu'un Meursault, à 4 à 10 ans sur un poisson en sauce.","lat":46.28,"lon":4.74,"importance":4,"niveau":"incontournable"},{"id":"fr-richebourg","nom":"Richebourg","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Pinot noir"],"style":"Rouge opulent et velouté, mûre, cerise noire, violette, épices, tanins amples et enrobés.","temp":"16 à 18 °C","garde":"15 à 35 ans","prix":4,"accords":["viande_rouge","gibier","truffe","roti","fromage_lave"],"eviter":["poisson_maigre","acide"],"classique":"Richebourg et filet de bœuf aux truffes","note":"Grand cru de 8 hectares au nord de la Romanée-Conti, partagé entre une dizaine de domaines, dont Leroy et la Romanée-Conti. Son nom dit sa nature : le plus riche et le plus charnu des grands crus de Vosne, avec une rondeur presque sucrée. Il s'épanouit après quinze ans.","lat":47.16,"lon":4.95,"importance":4,"niveau":"incontournable"},{"id":"fr-volnay","nom":"Volnay","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Pinot noir"],"style":"Framboise, cerise, violette et rose, tanins de soie, bouche fine et aérienne, finale longue et délicate.","temp":"14 à 16 °C","garde":"5 à 15 ans","prix":3,"accords":["volaille","canard","agneau","champignon","truffe","fromage_molle"],"eviter":["piquant","huitre","gibier"],"classique":"Volnay et magret de canard aux cerises","note":"Voisin de Pommard mais son opposé : Volnay, appellation rouge seule, est réputé pour la finesse et le parfum de ses pinots sur des sols calcaires légers. Caillerets, Champans, Clos des Ducs et Santenots (sur Meursault) sont ses grands climats. Mûr vers 5 à 10 ans, sur une volaille ou un canard rôti.","lat":47.0,"lon":4.78,"importance":4,"niveau":"incontournable"},{"id":"fr-aloxe-corton","nom":"Aloxe-Corton","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Blanc rare (moins de 5 % du volume), ample et beurré, dans l'ombre du Corton-Charlemagne voisin."}],"cepages":["Pinot noir"],"style":"Cerise noire, mûre, réglisse, tanins plus fermes que la moyenne de la Côte, structure droite.","temp":"15 à 17 °C","garde":"5 à 12 ans","prix":3,"accords":["viande_rouge","roti","gibier","champignon","fromage_lave"],"eviter":["poisson_cru","huitre","acide"],"classique":"Aloxe-Corton et bœuf bourguignon","note":"Au pied de la colline de Corton, le village d'Aloxe donne les rouges les plus charpentés de la Côte de Beaune : sols riches en fer et en marnes, exposition est et sud. Fermé jeune, il s'ouvre après 5 ans ; l'ouvrir sur une viande rouge rôtie ou un plat mijoté au vin.","lat":47.07,"lon":4.86,"importance":3,"niveau":"classique"},{"id":"fr-bonnes-mares","nom":"Bonnes-Mares","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Pinot noir"],"style":"Rouge ample et charpenté, mûre, cerise noire, terre humide, tanins mûrs et puissants.","temp":"16 à 18 °C","garde":"12 à 25 ans","prix":4,"accords":["viande_rouge","gibier","roti","sauce_vin_rouge","fromage_lave"],"eviter":["poisson_maigre","acide"],"classique":"Bonnes-Mares et côte de bœuf au feu de bois","note":"Grand cru de 15 hectares à cheval sur Chambolle-Musigny et Morey-Saint-Denis. Ses deux sols, terres rouges au sud et terres blanches au nord, donnent un vin plus corsé que Musigny, souvent fermé dans sa jeunesse. Il prend sa place à table après dix ans de cave.","lat":47.19,"lon":4.95,"importance":3,"niveau":"classique"},{"id":"fr-bourgogne-aligote","nom":"Bourgogne Aligoté","pays":"France","region":"Bourgogne","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Aligoté"],"style":"Blanc sec, vif et léger, citron, pomme verte, fleurs blanches, bouche nerveuse et franche.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":1,"accords":["huitre","coquillage","frit","fromage_chevre","oeuf"],"eviter":["viande_rouge","mijote"],"classique":"Aligoté et escargots de Bourgogne","note":"Second cépage blanc de Bourgogne, l'aligoté a longtemps servi au kir, mélangé à la crème de cassis. Replanté sur de bons coteaux, il donne aujourd'hui des blancs secs, nerveux et francs. Bien frais, c'est un vin d'apéritif, d'huîtres et de gougères.","lat":47.05,"lon":4.86,"importance":3,"niveau":"classique"},{"id":"fr-clos-de-la-roche","nom":"Clos de la Roche","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Pinot noir"],"style":"Rouge profond et minéral, cerise noire, réglisse, pierre, tanins serrés et longs.","temp":"16 à 18 °C","garde":"12 à 25 ans","prix":4,"accords":["viande_rouge","gibier","truffe","roti","fromage_lave"],"eviter":["poisson_maigre","acide"],"classique":"Clos de la Roche et selle de chevreuil","note":"Plus vaste grand cru de Morey-Saint-Denis, près de 17 hectares sur un sol caillouteux où la roche affleure, d'où le nom. Il donne le rouge le plus structuré du village, proche d'un Chambertin, avec une veine minérale qui s'affirme après dix ans. À réserver aux gibiers.","lat":47.21,"lon":4.96,"importance":3,"niveau":"classique"},{"id":"fr-cremant-de-bourgogne","nom":"Crémant de Bourgogne","pays":"France","region":"Bourgogne","sousRegion":"","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"rose","famille":"bulles","note":"Crémant rosé de pinot noir, fruits rouges et bulle fine"}],"cepages":["Chardonnay","Pinot noir","Aligoté","Gamay"],"style":"Bulles fines, pomme, brioche, agrumes, bouche fraîche et crémeuse à la fois.","temp":"6 à 8 °C","garde":"1 à 4 ans","prix":2,"accords":["huitre","crustace","frit","volaille","patisserie","fromage_frais"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Crémant de Bourgogne et gougères","note":"Élaboré comme le champagne, par seconde fermentation en bouteille et au moins neuf mois sur lattes, avec les cépages bourguignons. Les caves de Bailly, dans l'Yonne, en sont un des foyers historiques. Blanc, blanc de blancs ou rosé, c'est la bulle de l'apéritif.","lat":47.73,"lon":3.63,"importance":3,"niveau":"classique"},{"id":"fr-echezeaux","nom":"Échezeaux","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Pinot noir"],"style":"Rouge parfumé et épicé, framboise, cerise, violette, poivre, tanins fins, bouche élancée.","temp":"16 à 17 °C","garde":"10 à 25 ans","prix":4,"accords":["volaille","canard","viande_rouge","champignon","truffe"],"eviter":["piquant","poisson_cru"],"classique":"Échezeaux et canard aux cerises","note":"Grand cru de 36 hectares sur la commune de Flagey-Échezeaux, juste au-dessus de Vosne-Romanée, avec son voisin plus petit et plus réputé Grands Échezeaux. Son étendue explique des styles variés, mais le fond reste celui de Vosne : fruit rouge, épices douces, finesse de grain.","lat":47.16,"lon":4.96,"importance":3,"niveau":"classique"},{"id":"fr-givry","nom":"Givry","pays":"France","region":"Bourgogne","sousRegion":"Côte chalonnaise","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Un cinquième de la production : Chardonnay floral et frais, de garde courte."}],"cepages":["Pinot noir"],"style":"Framboise, cerise, violette, épices douces, tanins fins et souples, bouche parfumée et fraîche.","temp":"14 à 16 °C","garde":"3 à 10 ans","prix":2,"accords":["volaille","porc","charcuterie","champignon","fromage_molle"],"eviter":["piquant","huitre"],"classique":"Givry et poulet Gaston Gérard","note":"Au sud de Mercurey, Givry donne des rouges plus fins et plus parfumés que son voisin, à prix contenu ; la tradition en fait le vin préféré d'Henri IV. Une trentaine de premiers crus (Clos Salomon, Cellier aux Moines). Prêt dès 3 ans, il tient 8 à 10 ans ; sur une volaille ou une charcuterie.","lat":46.78,"lon":4.75,"importance":3,"niveau":"classique"},{"id":"fr-macon-villages","nom":"Mâcon-Villages","pays":"France","region":"Bourgogne","sousRegion":"Mâconnais","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Chardonnay"],"style":"Pomme, poire, fleur d'acacia, agrumes, bouche souple et fraîche, sans bois, à boire jeune.","temp":"9 à 11 °C","garde":"1 à 4 ans","prix":1,"accords":["poisson_maigre","coquillage","volaille","fromage_chevre","legumes","frit"],"eviter":["viande_rouge","gibier","piquant"],"classique":"Mâcon-Villages et fromage de chèvre du Mâconnais","note":"Appellation blanche seule couvrant une vingtaine de villages du Mâconnais (Lugny, Chardonnay, Uchizy), le village de Chardonnay ayant peut-être donné son nom au cépage. Un blanc simple, fruité et sans bois, le Chardonnay bourguignon le moins cher. À boire dans les 3 ans, frais, sur un chèvre.","lat":46.42,"lon":4.82,"importance":3,"niveau":"classique"},{"id":"fr-mercurey","nom":"Mercurey","pays":"France","region":"Bourgogne","sousRegion":"Côte chalonnaise","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Un dixième de la production : Chardonnay rond et charnu, bon rapport prix-plaisir."}],"cepages":["Pinot noir"],"style":"Cerise noire, cassis, réglisse, note de terre, tanins francs et charnus, bouche solide et chaleureuse.","temp":"15 à 17 °C","garde":"4 à 12 ans","prix":2,"accords":["viande_rouge","roti","mijote","charcuterie","champignon","fromage_lave"],"eviter":["poisson_cru","huitre"],"classique":"Mercurey et pièce de charolais rôtie","note":"La plus grande appellation de la Côte chalonnaise (environ 650 ha) et sa plus connue en rouge : des pinots charpentés et terriens, plus proches de Pommard que de Volnay, avec une trentaine de premiers crus (Clos des Barraults, Champs Martin). À 4 à 10 ans sur une viande rouge rôtie ou mijotée.","lat":46.84,"lon":4.72,"importance":3,"niveau":"classique"},{"id":"fr-morey-saint-denis","nom":"Morey-Saint-Denis","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Un peu de blanc de chardonnay, rare"}],"cepages":["Pinot noir"],"style":"Rouge entre puissance et finesse, fruits noirs, violette, notes terreuses, tanins fins.","temp":"16 à 17 °C","garde":"6 à 15 ans","prix":3,"accords":["viande_rouge","volaille","gibier","champignon","roti","fromage_lave"],"eviter":["poisson_cru","piquant"],"classique":"Morey-Saint-Denis et pintade aux morilles","note":"Entre Gevrey et Chambolle, Morey est un petit village discret qui concentre pourtant cinq grands crus : Clos de la Roche, Clos Saint-Denis, Clos de Tart, Clos des Lambrays et une part de Bonnes-Mares. Ses rouges tiennent le milieu entre la force de Gevrey et la soie de Chambolle.","lat":47.2,"lon":4.96,"importance":3,"niveau":"classique"},{"id":"fr-petit-chablis","nom":"Petit Chablis","pays":"France","region":"Bourgogne","sousRegion":"Chablis","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Chardonnay"],"style":"Blanc léger et vif, agrumes, fleurs blanches, bouche nette et désaltérante.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":2,"accords":["huitre","coquillage","poisson_maigre","frit","fromage_frais"],"eviter":["viande_rouge","mijote"],"classique":"Petit Chablis et moules marinières","note":"Le Petit Chablis pousse sur les plateaux calcaires du Portlandien, plus jeunes et plus hauts que les coteaux du Chablis. Il donne un chardonnay simple, frais et citronné, à boire jeune. C'est le vin de l'apéritif de fruits de mer et des fritures légères.","lat":47.82,"lon":3.78,"importance":3,"niveau":"classique"},{"id":"fr-rully","nom":"Rully","pays":"France","region":"Bourgogne","sousRegion":"Côte chalonnaise","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Un tiers de la production : Pinot noir léger et fruité, à boire dans les 6 ans."},{"couleur":"bulles","famille":"bulles","note":"Rully est le berceau historique du Crémant de Bourgogne, produit ici depuis les années 1820."}],"cepages":["Chardonnay"],"style":"Fleurs blanches, citron, pomme, amande, bouche fraîche et légère, bois discret, finale nette.","temp":"10 à 12 °C","garde":"2 à 7 ans","prix":2,"accords":["poisson_maigre","coquillage","volaille","fromage_chevre","vapeur","beurre_citron"],"eviter":["viande_rouge","gibier","piquant"],"classique":"Rully et quenelles de brochet","note":"Au nord de la Côte chalonnaise, Rully est surtout blanc : un Chardonnay frais et floral, à mi-chemin entre Côte de Beaune et Mâconnais, à un prix plus doux. Vingt-trois premiers crus (Grésigny, Rabourcé, Vauvry). C'est aussi là que le Crémant de Bourgogne a commencé en 1822. À boire dans les 5 ans.","lat":46.88,"lon":4.74,"importance":3,"niveau":"classique"},{"id":"fr-saint-aubin","nom":"Saint-Aubin","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Environ un quart de la production : Pinot noir léger et fruité, à boire dans les 5 ans."}],"cepages":["Chardonnay"],"style":"Citron, fleurs blanches, silex, noisette fraîche, bouche tendue et saline, bois discret.","temp":"10 à 12 °C","garde":"3 à 10 ans","prix":3,"accords":["huitre","coquillage","crustace","poisson_maigre","fromage_chevre","beurre_citron"],"eviter":["viande_rouge","gibier","piquant"],"classique":"Saint-Aubin et huîtres chaudes au beurre","note":"Village en retrait dans une combe derrière Puligny et Chassagne, Saint-Aubin compte une trentaine de premiers crus et deux tiers de blancs. Plus frais et plus tendu que ses voisins (En Remilly touche le Montrachet), il reste abordable. À 3 à 8 ans sur coquillages et poissons.","lat":46.94,"lon":4.7,"importance":3,"niveau":"classique"},{"id":"fr-saint-veran","nom":"Saint-Véran","pays":"France","region":"Bourgogne","sousRegion":"Mâconnais","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Chardonnay"],"style":"Citron, pêche blanche, fleurs d'acacia, amande fraîche, bouche vive et souple, finale nette, peu de bois.","temp":"10 à 12 °C","garde":"2 à 7 ans","prix":2,"accords":["poisson_maigre","coquillage","crustace","volaille","fromage_chevre","vapeur"],"eviter":["viande_rouge","gibier","piquant"],"classique":"Saint-Véran et friture de la Saône","note":"Appellation créée en 1971 sur huit communes qui enserrent Pouilly-Fuissé au nord (Prissé, Davayé) et au sud (Saint-Vérand, Chânes, Leynes), à la limite du Beaujolais. Un Chardonnay plus frais et plus léger que le Pouilly-Fuissé, moins cher. À boire dans les 5 ans, sur une friture ou un chèvre.","lat":46.26,"lon":4.73,"importance":3,"niveau":"classique"},{"id":"fr-santenay","nom":"Santenay","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Un cinquième de la production, en hausse : Chardonnay rond et floral, proche de Chassagne, bon rapport prix-plaisir."}],"cepages":["Pinot noir"],"style":"Cerise noire, mûre, réglisse et terre, tanins francs un peu rustiques, bouche charnue et chaleureuse.","temp":"15 à 17 °C","garde":"4 à 12 ans","prix":2,"accords":["viande_rouge","roti","mijote","charcuterie","champignon","fromage_lave"],"eviter":["poisson_cru","huitre"],"classique":"Santenay et bœuf braisé aux carottes","note":"Dernier village au sud de la Côte de Beaune, Santenay est station thermale et vignoble surtout rouge : des pinots solides et francs, plus terriens que ceux de Volnay, qui gagnent à 4 à 8 ans. Les Gravières et le Clos de Tavannes sont les premiers crus de référence. Un rouge de table abordable.","lat":46.91,"lon":4.69,"importance":3,"niveau":"classique"},{"id":"fr-savigny-les-beaune","nom":"Savigny-lès-Beaune","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Un dixième de la production : Chardonnay léger et floral, à boire jeune."}],"cepages":["Pinot noir"],"style":"Fraise, cerise, violette, bouche souple et croquante, tanins soyeux, buvabilité immédiate.","temp":"14 à 16 °C","garde":"3 à 8 ans","prix":2,"accords":["volaille","charcuterie","porc","champignon","fromage_molle"],"eviter":["piquant","huitre"],"classique":"Savigny-lès-Beaune et œufs en meurette","note":"Grande commune de la Côte de Beaune, Savigny s'étend de part et d'autre du Rhoin : les crus côté Pernand (Vergelesses, Lavières) sont fins, ceux côté Beaune (Marconnets, Jarrons) plus charnus. Un rouge de fruit et de fraîcheur, bon choix de bistrot entre 3 et 6 ans.","lat":47.06,"lon":4.82,"importance":3,"niveau":"classique"},{"id":"fr-auxey-duresses","nom":"Auxey-Duresses","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Un tiers de la production : Chardonnay tendu et noisetté, dans l'esprit d'un Meursault plus frais."}],"cepages":["Pinot noir"],"style":"Cerise, groseille, poivre, tanins francs et un peu fermes, bouche fraîche de combe.","temp":"14 à 16 °C","garde":"3 à 8 ans","prix":2,"accords":["volaille","porc","charcuterie","champignon","fromage_molle"],"eviter":["piquant","poisson_cru"],"classique":"Auxey-Duresses et escargots de Bourgogne","note":"Dans la combe qui monte vers Saint-Romain, Auxey-Duresses est plus frais que la Côte proprement dite : rouges fermes et nerveux, blancs vifs qui rappellent Meursault sans en avoir le prix. Les Duresses, premier cru partagé avec Monthélie, sont le climat phare. Rouge à 3 à 6 ans, blanc à 3 à 8 ans.","lat":46.99,"lon":4.74,"importance":2,"niveau":"decouverte"},{"id":"fr-bouzeron","nom":"Bouzeron","pays":"France","region":"Bourgogne","sousRegion":"Côte chalonnaise","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Aligoté"],"style":"Citron, pomme verte, fleur d'acacia, pierre, bouche vive et saline, plus de chair qu'un Aligoté ordinaire.","temp":"8 à 10 °C","garde":"2 à 6 ans","prix":2,"accords":["huitre","coquillage","poisson_maigre","fromage_chevre","frit","acide"],"eviter":["viande_rouge","gibier","creme"],"classique":"Bouzeron et gougères au comté","note":"Seule appellation village de Bourgogne réservée à l'Aligoté, reconnue en 1998 au nord de la Côte chalonnaise. Sols calcaires et Aligoté doré à petits grains donnent un blanc plus mûr et plus dense que le Bourgogne Aligoté courant ; Aubert de Villaine l'a fait connaître. À 2 à 5 ans, sur huîtres.","lat":46.87,"lon":4.72,"importance":2,"niveau":"decouverte"},{"id":"fr-chorey-les-beaune","nom":"Chorey-lès-Beaune","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Blanc confidentiel, simple et frais."}],"cepages":["Pinot noir"],"style":"Cerise, groseille, pointe épicée, bouche souple et légère, tanins discrets, finale fraîche.","temp":"13 à 15 °C","garde":"2 à 6 ans","prix":2,"accords":["volaille","charcuterie","porc","legumes","fromage_molle"],"eviter":["piquant","gibier"],"classique":"Chorey-lès-Beaune et terrine de campagne","note":"Seul village de la Côte de Beaune situé en plaine, à l'est de la route, Chorey n'a aucun premier cru : ses rouges sont simples, tendres et fruités, à boire jeunes et un peu frais. Une porte d'entrée abordable sur le Pinot noir bourguignon, pour une charcuterie ou une volaille sans sauce.","lat":47.06,"lon":4.86,"importance":2,"niveau":"decouverte"},{"id":"fr-cote-de-nuits-villages","nom":"Côte de Nuits-Villages","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Un peu de chardonnay, rare"}],"cepages":["Pinot noir"],"style":"Rouge franc et fruité, cerise, groseille, tanins souples avec un peu de mâche.","temp":"15 à 16 °C","garde":"3 à 8 ans","prix":2,"accords":["volaille","charcuterie","porc","grille","fromage_molle"],"eviter":["poisson_cru","chocolat"],"classique":"Côte de Nuits-Villages et jambon persillé","note":"Appellation qui regroupe les vignes des deux extrémités de la côte : Fixin et Brochon au nord, Comblanchien, Corgoloin et Prémeaux-Prissey au sud, près des carrières de marbre rose. Elle offre le pinot noir de la Côte de Nuits à prix raisonnable, à boire dans ses cinq ans.","lat":47.11,"lon":4.92,"importance":2,"niveau":"decouverte"},{"id":"fr-fixin","nom":"Fixin","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Pinot noir"],"style":"Rouge ferme et droit, cerise noire, sous-bois, tanins serrés qui se fondent avec l'âge.","temp":"16 à 17 °C","garde":"5 à 12 ans","prix":3,"accords":["viande_rouge","gibier","roti","mijote","fromage_lave"],"eviter":["poisson_maigre","sucre_sale"],"classique":"Fixin et bœuf bourguignon","note":"Premier village de la Côte de Nuits au sud de Marsannay, Fixin donne des pinots plus charpentés que ses voisins, longtemps jugés rustiques. Le climat Clos de la Perrière, ancien domaine des moines de Cîteaux, est son premier cru le plus connu. Un vin de table d'hiver.","lat":47.25,"lon":4.97,"importance":2,"niveau":"decouverte"},{"id":"fr-hautes-cotes-de-beaune","nom":"Hautes-Côtes de Beaune","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Un tiers de la production : Chardonnay vif et floral, à boire dans les 4 ans."},{"couleur":"rose","famille":"rose","note":"Rosé de Pinot noir, léger, anecdotique."}],"cepages":["Pinot noir"],"style":"Groseille, cerise acidulée, pivoine, tanins légers, bouche fraîche et croquante, peu de bois.","temp":"13 à 15 °C","garde":"2 à 6 ans","prix":2,"accords":["charcuterie","volaille","porc","legumes","fromage_frais"],"eviter":["gibier","piquant"],"classique":"Hautes-Côtes de Beaune et jambon persillé","note":"Sur le plateau derrière la Côte, entre 300 et 450 m d'altitude (Nolay, La Rochepot, Meloisey, Orches), ce Bourgogne régional mûrit plus tard et donne des rouges légers et acidulés, des blancs nerveux. Le réchauffement lui réussit ; un bon Pinot noir de semaine, à boire frais dans les 4 ans.","lat":46.96,"lon":4.67,"importance":2,"niveau":"decouverte"},{"id":"fr-hautes-cotes-de-nuits","nom":"Hautes-Côtes de Nuits","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Chardonnay vif des hauteurs, parfois un peu de pinot blanc"}],"cepages":["Pinot noir"],"style":"Rouge léger et vif, fruits rouges croquants, tanins légers, bouche fraîche de hauteur.","temp":"14 à 16 °C","garde":"2 à 6 ans","prix":2,"accords":["charcuterie","volaille","porc","grille","fromage_chevre"],"eviter":["viande_rouge","chocolat"],"classique":"Hautes-Côtes de Nuits et terrine de campagne","note":"Sur les plateaux à l'ouest de la côte, entre 300 et 400 mètres d'altitude, autour de Villars-Fontaine ou Marey-lès-Fussey. L'altitude retarde la maturité et donne des rouges plus légers et plus frais que ceux du bas de la côte. Le réchauffement du climat joue en leur faveur.","lat":47.14,"lon":4.88,"importance":2,"niveau":"decouverte"},{"id":"fr-irancy","nom":"Irancy","pays":"France","region":"Bourgogne","sousRegion":"Auxerrois","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Pinot noir","César"],"style":"Rouge vif aux fruits rouges acidulés, tanins fins parfois rustiques, notes de cerise et de poivre.","temp":"14 à 16 °C","garde":"3 à 10 ans","prix":2,"accords":["volaille","charcuterie","porc","grille","fromage_molle"],"eviter":["poisson_cru","chocolat"],"classique":"Irancy et jambon persillé","note":"Seul rouge d'appellation village de l'Yonne, Irancy est cultivé en cirque autour d'un village de cerisiers. Le pinot noir peut recevoir jusqu'à 10 % de césar, cépage local qui apporte tanin et couleur. Un rouge de fraîcheur, à ouvrir légèrement rafraîchi sur une charcuterie.","lat":47.71,"lon":3.66,"importance":2,"niveau":"decouverte"},{"id":"fr-ladoix","nom":"Ladoix","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay du bas de la colline de Corton, rond et floral, environ un quart de la production."}],"cepages":["Pinot noir"],"style":"Cerise, groseille et violette, tanins fins et légèrement rustiques, finale fraîche.","temp":"14 à 16 °C","garde":"3 à 8 ans","prix":3,"accords":["volaille","porc","charcuterie","champignon","fromage_molle"],"eviter":["piquant","huitre"],"classique":"Ladoix et poulet de Bresse rôti","note":"Village le plus au nord de la Côte de Beaune, Ladoix-Serrigny partage avec Aloxe la colline de Corton, dont quelques parcelles de grand cru. Ses rouges, souvent moins chers que ceux des voisins, mêlent fruit rouge et tanins fins ; à ouvrir entre 3 et 6 ans sur une volaille rôtie.","lat":47.07,"lon":4.87,"importance":2,"niveau":"decouverte"},{"id":"fr-maranges","nom":"Maranges","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Blanc confidentiel (moins de 10 %), simple et frais."}],"cepages":["Pinot noir"],"style":"Cerise noire, cassis, poivre, tanins fermes et rustiques, bouche solide, finale fraîche.","temp":"15 à 17 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","mijote","charcuterie","porc","fromage_lave"],"eviter":["poisson_cru","huitre","sucre_sale"],"classique":"Maranges et bourguignon de joue de bœuf","note":"Appellation créée en 1988 sur trois communes de Saône-et-Loire (Cheilly, Dezize, Sampigny-lès-Maranges), au bout de la Côte de Beaune. Rouges solides et un peu rustiques, autrefois destinés aux assemblages de négoce, bons en plat mijoté entre 3 et 8 ans. Un des Pinot noir les moins chers de la Côte.","lat":46.89,"lon":4.65,"importance":2,"niveau":"decouverte"},{"id":"fr-marsannay","nom":"Marsannay","pays":"France","region":"Bourgogne","sousRegion":"Côte de Nuits","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de pinot noir, seul village de Bourgogne à en produire"},{"couleur":"blanc","famille":"blanc_vif","note":"Chardonnay droit et frais, plus rare"}],"cepages":["Pinot noir"],"style":"Rouge franc et juteux, cerise noire, violette, tanins fins avec un peu de mâche.","temp":"15 à 17 °C","garde":"4 à 10 ans","prix":2,"accords":["volaille","porc","charcuterie","grille","fromage_molle"],"eviter":["poisson_cru","chocolat"],"classique":"Marsannay rosé et jambon persillé","note":"Aux portes de Dijon, Marsannay est la seule appellation village de Bourgogne déclinée en trois couleurs. Son rosé de pinot noir, créé par Joseph Clair en 1919, a fait sa réputation. Les rouges, de plus en plus soignés, offrent un accès abordable à la Côte de Nuits.","lat":47.27,"lon":5.0,"importance":2,"niveau":"decouverte"},{"id":"fr-montagny","nom":"Montagny","pays":"France","region":"Bourgogne","sousRegion":"Côte chalonnaise","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Chardonnay"],"style":"Citron, fleurs blanches, amande, note de pierre, bouche vive et légèrement grasse, finale nette.","temp":"10 à 12 °C","garde":"2 à 6 ans","prix":2,"accords":["poisson_maigre","coquillage","crustace","volaille","fromage_chevre","vapeur"],"eviter":["viande_rouge","gibier","piquant"],"classique":"Montagny et escargots au beurre d'ail","note":"Appellation blanche seule, la plus au sud de la Côte chalonnaise, autour de Montagny-lès-Buxy, Buxy et Saint-Vallerin. Les sols marneux donnent un Chardonnay vif et net, souvent sans bois ; la cave coopérative de Buxy assure une large part du volume. À boire dans les 5 ans.","lat":46.69,"lon":4.68,"importance":2,"niveau":"decouverte"},{"id":"fr-monthelie","nom":"Monthélie","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Environ 15 % du volume : Chardonnay rond et simple, proche d'un petit Meursault."}],"cepages":["Pinot noir"],"style":"Cerise, groseille, épices douces, tanins fins un peu rustiques, bouche fraîche et droite.","temp":"14 à 16 °C","garde":"3 à 8 ans","prix":2,"accords":["volaille","porc","charcuterie","champignon","fromage_molle"],"eviter":["piquant","huitre"],"classique":"Monthélie et poulet aux morilles","note":"Petit village perché entre Volnay et Meursault, Monthélie prolonge les coteaux de Volnay avec une exposition un peu plus fraîche : des rouges parfumés et nerveux, moins chers que leurs voisins. Les Champs Fulliot sont le premier cru le plus connu. À boire entre 3 et 6 ans sur une volaille.","lat":46.99,"lon":4.76,"importance":2,"niveau":"decouverte"},{"id":"fr-pernand-vergelesses","nom":"Pernand-Vergelesses","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Près de la moitié de la production : Chardonnay tendu et minéral, aux portes du Corton-Charlemagne."}],"cepages":["Pinot noir"],"style":"Framboise, cerise, note de pivoine, tanins fins, bouche fraîche et droite avec une pointe de fermeté.","temp":"14 à 16 °C","garde":"4 à 10 ans","prix":3,"accords":["volaille","porc","charcuterie","champignon","fromage_molle"],"eviter":["piquant","huitre"],"classique":"Pernand-Vergelesses et jambon persillé","note":"Village encaissé dans une combe derrière la colline de Corton, Pernand est plus frais que ses voisins : les rouges restent nerveux et fins, les blancs tendus. Le premier cru Île des Vergelesses est son climat le plus réputé. À boire entre 4 et 8 ans sur une charcuterie bourguignonne.","lat":47.08,"lon":4.84,"importance":2,"niveau":"decouverte"},{"id":"fr-pouilly-vinzelles","nom":"Pouilly-Vinzelles","pays":"France","region":"Bourgogne","sousRegion":"Mâconnais","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chardonnay"],"style":"Agrumes, pêche blanche, fleurs, pierre, bouche ample mais tendue, finale saline, bois discret.","temp":"10 à 12 °C","garde":"3 à 10 ans","prix":2,"accords":["poisson_maigre","crustace","volaille","coquillage","beurre_citron","fromage_dure"],"eviter":["viande_rouge","piquant"],"classique":"Pouilly-Vinzelles et quenelles de brochet sauce Nantua","note":"Une cinquantaine d'hectares sur Vinzelles et Loché, au sud-est de Pouilly-Fuissé : des coteaux argilo-calcaires exposés à l'est qui donnent un Chardonnay plus tendu que le Fuissé. Le climat Les Quarts, sur Vinzelles, est le plus réputé. Bon rapport prix-plaisir, à 3 à 8 ans sur un poisson.","lat":46.27,"lon":4.8,"importance":2,"niveau":"decouverte"},{"id":"fr-saint-bris","nom":"Saint-Bris","pays":"France","region":"Bourgogne","sousRegion":"Auxerrois","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Sauvignon blanc","Sauvignon gris"],"style":"Blanc sec aromatique et nerveux, bourgeon de cassis, agrumes, buis, finale droite.","temp":"9 à 11 °C","garde":"1 à 4 ans","prix":1,"accords":["fromage_chevre","asperge","poisson_maigre","coquillage","herbes"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Saint-Bris et chèvre frais aux herbes","note":"Exception bourguignonne : Saint-Bris est la seule appellation de la région réservée au sauvignon, un cépage plus courant à Sancerre, à 100 km de là. Les sols kimméridgiens lui donnent une tension proche du Chablis voisin. À boire jeune, sur des asperges ou un chèvre frais.","lat":47.74,"lon":3.65,"importance":2,"niveau":"decouverte"},{"id":"fr-saint-romain","nom":"Saint-Romain","pays":"France","region":"Bourgogne","sousRegion":"Côte de Beaune","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Près de la moitié de la production : Pinot noir léger, acidulé, à boire jeune."}],"cepages":["Chardonnay"],"style":"Citron, pomme verte, fleurs blanches, craie, bouche tendue et droite, peu ou pas de bois.","temp":"10 à 12 °C","garde":"2 à 7 ans","prix":2,"accords":["huitre","coquillage","poisson_maigre","fromage_chevre","vapeur"],"eviter":["viande_rouge","gibier"],"classique":"Saint-Romain et escargots au beurre persillé","note":"Village haut perché (jusqu'à 400 m) au fond de la combe d'Auxey, Saint-Romain est l'un des plus frais de la Côte de Beaune : sans premier cru, il donne des blancs vifs et minéraux, mûrs tard, à prix raisonnable. À boire dans les 5 ans, sur coquillages ou fromage de chèvre.","lat":46.99,"lon":4.7,"importance":2,"niveau":"decouverte"},{"id":"fr-vire-clesse","nom":"Viré-Clessé","pays":"France","region":"Bourgogne","sousRegion":"Mâconnais","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Mention « levrouté » : raisins surmûris, vin demi-sec à moelleux, tradition locale reconnue en 2017."}],"cepages":["Chardonnay"],"style":"Pêche, miel, fleurs blanches, amande, bouche ronde et mûre, acidité douce, finale gourmande.","temp":"10 à 12 °C","garde":"3 à 8 ans","prix":2,"accords":["poisson_gras","volaille","creme","crustace","fromage_dure","champignon"],"eviter":["viande_rouge","piquant"],"classique":"Viré-Clessé et poulet de Bresse à la crème","note":"Appellation créée en 1999 en réunissant Viré et Clessé, deux villages réputés du nord du Mâconnais. Sur des sols argilo-calcaires, un Chardonnay plus riche et plus mûr qu'un Mâcon-Villages, qui supporte la garde ; Jean Thévenet y a défendu les vendanges surmûries. À 3 à 6 ans, sur une volaille.","lat":46.43,"lon":4.85,"importance":2,"niveau":"decouverte"},{"id":"fr-pouilly-loche","nom":"Pouilly-Loché","pays":"France","region":"Bourgogne","sousRegion":"Mâconnais","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chardonnay"],"style":"Pomme mûre, pêche, amande, miel léger, bouche ronde et souple, finale fraîche, bois discret.","temp":"10 à 12 °C","garde":"3 à 8 ans","prix":2,"accords":["poisson_maigre","poisson_gras","volaille","crustace","creme","fromage_dure"],"eviter":["viande_rouge","piquant"],"classique":"Pouilly-Loché et truite au beurre d'amandes","note":"Toute petite appellation (une trentaine d'hectares) sur la commune de Loché, à l'est de Pouilly-Fuissé, dont elle est la voisine la plus discrète. Le vin peut aussi être vendu sous le nom de Pouilly-Vinzelles. Un Chardonnay rond et mûr, moins puissant que le Fuissé et bien moins cher. À 3 à 6 ans.","lat":46.28,"lon":4.8,"importance":1,"niveau":"decouverte"},{"id":"fr-vezelay","nom":"Vézelay","pays":"France","region":"Bourgogne","sousRegion":"Auxerrois","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Chardonnay"],"style":"Blanc sec et tendu, agrumes, fleurs blanches, pointe minérale, bouche nette.","temp":"9 à 11 °C","garde":"2 à 5 ans","prix":2,"accords":["poisson_maigre","coquillage","fromage_chevre","volaille","vapeur"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Vézelay et truite au beurre blanc","note":"Au pied de la colline de Vézelay et de sa basilique, le vignoble replanté dans les années 1970 est devenu appellation village en 2017, en blanc seulement. Sur des sols calcaires proches de ceux de Chablis, le chardonnay y garde une tension qui rappelle l'Auxerrois voisin.","lat":47.47,"lon":3.75,"importance":1,"niveau":"decouverte"},{"id":"fr-bugey","nom":"Bugey","pays":"France","region":"Bugey","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Gamay, pinot noir ou mondeuse : rouges légers et fruités."},{"couleur":"bulles","famille":"bulles","note":"Bugey mousseux ou pétillant, méthode traditionnelle, cru Montagnieu."}],"cepages":["Chardonnay","Altesse","Jacquère","Mondeuse"],"style":"Pomme, fleurs, pierre, acidité franche ; sec, léger, net.","temp":"8 à 10 °C","garde":"1 à 5 ans","prix":1,"accords":["poisson_maigre","volaille","charcuterie","fromage_dure","legumes","oeuf"],"eviter":["viande_rouge","piquant"],"classique":"Bugey blanc et poulet de Bresse à la crème","note":"Vignoble de l'Ain, entre Jura et Savoie, AOC depuis 2009 avec les crus Montagnieu, Manicle et Cerdon. Chardonnay, altesse et jacquère en blanc ; gamay, pinot noir et mondeuse en rouge. Pays de Brillat-Savarin : vins légers pour la cuisine de la Bresse et des Dombes.","lat":45.76,"lon":5.69,"importance":2,"niveau":"decouverte"},{"id":"fr-bugey-cerdon","nom":"Bugey-Cerdon","pays":"France","region":"Bugey","sousRegion":"Cerdon","couleur":"bulles","famille":"bulles","variantes":[],"cepages":["Gamay","Poulsard"],"style":"Rosé pétillant doux, 8 % vol., fraise, framboise, grenadine ; bulles légères, sucre net.","temp":"6 à 8 °C","garde":"1 à 2 ans","prix":2,"accords":["patisserie","fruits_rouges","glace","chocolat","fromage_frais"],"eviter":["viande_rouge","huitre","fromage_lave"],"classique":"Bugey-Cerdon et fraisier","note":"Rosé pétillant de gamay et poulsard, par méthode ancestrale : la fermentation s'achève en bouteille, sans ajout de sucre ni de liqueur, et s'arrête vers 8 % d'alcool. Doux, fruité, à boire dans l'année, très frais, au dessert ou au goûter, là où un champagne brut tomberait à plat.","lat":46.07,"lon":5.46,"importance":2,"niveau":"decouverte"},{"id":"fr-champagne-brut-non-millesime","nom":"Champagne brut non millésimé","pays":"France","region":"Champagne","sousRegion":"","couleur":"bulles","famille":"bulles","variantes":[],"cepages":["Pinot noir","Chardonnay","Meunier"],"style":"Bulles fines, pomme verte, agrumes, brioche ; sec, vif, tendu par l'acidité.","temp":"8 à 10 °C","garde":"2 à 5 ans","prix":3,"accords":["huitre","crustace","poisson_cru","frit","volaille","fromage_dure"],"eviter":["sauce_vin_rouge","chocolat","piquant"],"classique":"Champagne brut et huîtres","note":"Assemblage de plusieurs années pour un goût de maison constant, élevé au moins quinze mois sur lattes. On le reconnaît à sa bulle fine et à ses notes de brioche venues des levures. À servir frais à l'apéritif, sur des huîtres ou une friture.","lat":49.04,"lon":3.96,"importance":5,"niveau":"incontournable"},{"id":"fr-champagne-millesime-prestige","nom":"Champagne millésimé et cuvées de prestige","pays":"France","region":"Champagne","sousRegion":"","couleur":"bulles","famille":"bulles","variantes":[],"cepages":["Chardonnay","Pinot noir","Meunier"],"style":"Bulles très fines, noisette, miel, pain grillé, fruits secs ; profond, long, complexe.","temp":"10 à 12 °C","garde":"5 à 25 ans","prix":4,"accords":["truffe","crustace","poisson_gras","volaille","fromage_dure","champignon"],"eviter":["piquant","chocolat","vinaigre"],"classique":"Cuvée de prestige et volaille truffée","note":"Vin d'une seule année, élevé au moins trois ans sur lies, souvent sept à dix pour les cuvées de prestige (Dom Pérignon, Cristal) ; certaines, comme Krug Grande Cuvée, restent des assemblages d'années. Noisette et brioche prennent le pas sur le fruit. À ouvrir moins froid, sur un plat de fête.","lat":49.04,"lon":3.96,"importance":5,"niveau":"incontournable"},{"id":"fr-champagne-blanc-de-blancs","nom":"Champagne blanc de blancs","pays":"France","region":"Champagne","sousRegion":"Côte des Blancs","couleur":"bulles","famille":"bulles","variantes":[],"cepages":["Chardonnay"],"style":"Bulles crémeuses, citron, craie, fleurs blanches ; droit, salin, long.","temp":"8 à 10 °C","garde":"3 à 10 ans","prix":3,"accords":["huitre","coquillage","crustace","poisson_cru","poisson_maigre","fromage_chevre"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Blanc de blancs et Saint-Jacques crues","note":"Chardonnay seul, surtout sur la craie de la Côte des Blancs (Avize, Cramant, Le Mesnil-sur-Oger). Plus tendu et plus salin qu'un brut d'assemblage, il prend des notes toastées avec les années. Le champagne des coquillages et des poissons crus, à l'apéritif ou à table.","lat":48.97,"lon":4.01,"importance":4,"niveau":"classique"},{"id":"fr-champagne-rose","nom":"Champagne rosé","pays":"France","region":"Champagne","sousRegion":"","couleur":"bulles","famille":"bulles","variantes":[],"cepages":["Pinot noir","Chardonnay","Meunier"],"style":"Bulles fines, fraise, framboise, pamplemousse rose ; frais, friand, un peu plus de corps.","temp":"8 à 10 °C","garde":"2 à 6 ans","prix":3,"accords":["crustace","poisson_gras","canard","fruits_rouges","asiatique","charcuterie"],"eviter":["chocolat","piquant"],"classique":"Champagne rosé et homard grillé","note":"Seule appellation française autorisée à faire un rosé par assemblage de vin rouge et de vin blanc ; le rosé de saignée existe aussi. Fruits rouges et bulle fine, plus de corps qu'un brut. Il accompagne un repas entier, du homard au canard, jusqu'aux desserts aux fruits rouges.","lat":49.26,"lon":4.03,"importance":4,"niveau":"classique"},{"id":"fr-champagne-blanc-de-noirs","nom":"Champagne blanc de noirs","pays":"France","region":"Champagne","sousRegion":"Montagne de Reims","couleur":"bulles","famille":"bulles","variantes":[],"cepages":["Pinot noir","Meunier"],"style":"Bulles amples, fruits rouges, poire, pain grillé ; vineux, charpenté.","temp":"8 à 10 °C","garde":"3 à 10 ans","prix":3,"accords":["volaille","canard","porc","champignon","fromage_dure","grille"],"eviter":["huitre","chocolat"],"classique":"Blanc de noirs et volaille rôtie","note":"Vin blanc effervescent tiré de raisins noirs (pinot noir, meunier) pressés sans macération, sur la Montagne de Reims et l'Aube. Plus vineux et plus large que le blanc de blancs, avec une pointe de fruits rouges. Il tient le repas : volaille rôtie, pintade, champignons.","lat":49.07,"lon":4.15,"importance":3,"niveau":"classique"},{"id":"fr-champagne-demi-sec","nom":"Champagne demi-sec","pays":"France","region":"Champagne","sousRegion":"","couleur":"bulles","famille":"bulles","variantes":[],"cepages":["Pinot noir","Chardonnay","Meunier"],"style":"Bulles douces, 32 à 50 g de sucre par litre, pomme cuite, miel, brioche ; rond et gourmand.","temp":"6 à 8 °C","garde":"2 à 5 ans","prix":3,"accords":["patisserie","fruits_jaunes","foie_gras","fromage_bleu","sucre_sale"],"eviter":["huitre","poisson_cru"],"classique":"Champagne demi-sec et tarte aux pommes","note":"Même vin qu'un brut, mais dosé entre 32 et 50 g de sucre par litre au dégorgement ; au XIXe siècle, le champagne était plus sucré encore, le brut n'arrivant qu'en fin de siècle. Son sucre lui permet de tenir face aux desserts et au foie gras, là où un brut paraît maigre et acide. Servir bien frais.","lat":49.04,"lon":3.96,"importance":2,"niveau":"decouverte"},{"id":"fr-coteaux-champenois","nom":"Coteaux champenois","pays":"France","region":"Champagne","sousRegion":"","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Blanc tranquille de chardonnay, tendu et crayeux, rare."}],"cepages":["Pinot noir","Meunier","Chardonnay"],"style":"Rouge pâle, cerise, groseille, fine amertume ; léger, frais, peu tannique.","temp":"13 à 15 °C","garde":"3 à 8 ans","prix":3,"accords":["volaille","charcuterie","fromage_molle","champignon","poisson_gras"],"eviter":["viande_rouge","piquant"],"classique":"Bouzy rouge et pintade rôtie","note":"Vin tranquille, sans bulles, de la Champagne : rouge de pinot noir le plus souvent (Bouzy, Aÿ, Cumières), plus rarement blanc ou rosé. Léger et acidulé, il rappelle un bourgogne du nord. Servi légèrement frais, sur une volaille ou une charcuterie fine.","lat":49.07,"lon":4.15,"importance":2,"niveau":"decouverte"},{"id":"fr-rose-des-riceys","nom":"Rosé des Riceys","pays":"France","region":"Champagne","sousRegion":"Côte des Bar","couleur":"rose","famille":"rose","variantes":[],"cepages":["Pinot noir"],"style":"Rosé tranquille soutenu, cerise, noyau, violette ; vineux, sec, peu tannique.","temp":"10 à 12 °C","garde":"3 à 10 ans","prix":3,"accords":["volaille","charcuterie","poisson_gras","fromage_molle","mediterraneen"],"eviter":["sucre_sale","chocolat"],"classique":"Rosé des Riceys et volaille de Bresse","note":"Rosé tranquille de pinot noir, par courte macération, dans l'Aube au sud de la Champagne. Production minuscule, et seulement les années mûres. Sa couleur soutenue et son « goût des Riceys » (noyau, cerise) en font un rosé de table et de garde, pas un rosé d'été.","lat":47.99,"lon":4.37,"importance":2,"niveau":"decouverte"},{"id":"fr-patrimonio","nom":"Patrimonio","pays":"France","region":"Corse","sousRegion":"Haute-Corse","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Blanc de Vermentino pur, floral, citronné et salin, parmi les meilleurs de l'île."},{"couleur":"rose","famille":"rose","note":"Rosé de Nielluccio, vineux et fruité."}],"cepages":["Nielluccio","Vermentino","Grenache"],"style":"Rouge ferme, cerise, cuir, maquis et épices ; tanins droits du Nielluccio, parent du Sangiovese.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["agneau","charcuterie","gibier","mijote","fromage_dure","viande_rouge"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Patrimonio rouge et cabri rôti aux herbes du maquis","note":"Première AOC de Corse (1968), sur les argilo-calcaires du golfe de Saint-Florent, au nord de l'île. Le Nielluccio, frère du Sangiovese toscan, y représente au moins 90 % du rouge : vins tanniques et droits, à attendre quelques années. Le blanc de Vermentino est à ouvrir sur des poissons grillés.","lat":42.7,"lon":9.36,"importance":3,"niveau":"classique"},{"id":"fr-vin-de-corse","nom":"Vin de Corse","pays":"France","region":"Corse","sousRegion":"","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosés de Nielluccio, Sciaccarello et Grenache, francs et fruités, majoritaires en volume."},{"couleur":"blanc","famille":"blanc_vif","note":"Blancs de Vermentino, secs, citronnés, salins."}],"cepages":["Nielluccio","Sciaccarello","Grenache","Vermentino"],"style":"Rouge souple et chaleureux, cerise, myrte et épices du maquis, tanins ronds.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":2,"accords":["charcuterie","grille","agneau","mediterraneen","fromage_dure","mijote"],"eviter":["huitre","poisson_cru"],"classique":"Vin de Corse rouge et civet de sanglier","note":"Appellation générique de l'île, avec cinq dénominations locales (Calvi, Sartène, Figari, Porto-Vecchio, Coteaux du Cap Corse) et la plaine orientale autour d'Aléria. Trois cépages insulaires, Nielluccio, Sciaccarello et Vermentino, donnent des vins de tous les jours, francs et parfumés.","lat":42.1,"lon":9.5,"importance":3,"niveau":"classique"},{"id":"fr-ajaccio","nom":"Ajaccio","pays":"France","region":"Corse","sousRegion":"Corse-du-Sud","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de Sciaccarello, poivré et clair, très apprécié sur l'île."},{"couleur":"blanc","famille":"blanc_vif","note":"Blanc de Vermentino, sec et floral."}],"cepages":["Sciaccarello","Nielluccio","Grenache"],"style":"Rouge clair et parfumé, poivre, fraise, maquis et fumée, tanins fins, acidité fraîche.","temp":"14 à 16 °C","garde":"3 à 10 ans","prix":2,"accords":["charcuterie","volaille","agneau","grille","champignon","fromage_chevre"],"eviter":["huitre","chocolat","piquant"],"classique":"Ajaccio rouge et charcuterie corse (coppa, lonzu)","note":"Sur les sols granitiques de la côte ouest, autour de la ville d'Ajaccio, le Sciaccarello (au moins 40 %) donne des rouges pâles et poivrés qui rappellent un Pinot noir méridional. Ils se servent légèrement rafraîchis sur la charcuterie de l'île, un sanglier ou un fromage de brebis jeune.","lat":41.93,"lon":8.74,"importance":2,"niveau":"classique"},{"id":"fr-muscat-du-cap-corse","nom":"Muscat du Cap Corse","pays":"France","region":"Corse","sousRegion":"Cap Corse","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Muscat blanc à petits grains"],"style":"Vin doux naturel doré, raisin frais, abricot, fleur d'oranger et miel, bouche sucrée mais tendue par le sel.","temp":"8 à 10 °C","garde":"3 à 10 ans","prix":2,"accords":["foie_gras","fruits_jaunes","patisserie","fromage_bleu","fruits_exotiques","fromage_frais"],"eviter":["viande_rouge","sauce_vin_rouge","amer"],"classique":"Muscat du Cap Corse et fiadone (gâteau corse au brocciu)","note":"Sur les schistes abrupts du Cap Corse et de Patrimonio, un vin doux naturel obtenu par mutage à l'alcool du Muscat à petits grains, seul cépage autorisé. Moins lourd que les muscats du Roussillon, il se sert très frais à l'apéritif, sur un foie gras ou sur le fiadone et les gâteaux à la châtaigne.","lat":42.96,"lon":9.42,"importance":2,"niveau":"decouverte"},{"id":"fr-arbois","nom":"Arbois","pays":"France","region":"Jura","sousRegion":"","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Trousseau ou poulsard : rouges clairs, fruits rouges, poivre, tanins légers."}],"cepages":["Chardonnay","Savagnin","Poulsard","Trousseau","Pinot noir"],"style":"Chardonnay tendu ou savagnin sous voile (noix, curry, pomme verte) ; sec, droit, persistant.","temp":"10 à 12 °C","garde":"3 à 15 ans","prix":2,"accords":["fromage_dure","volaille","champignon","creme","poisson_maigre","curry"],"eviter":["sucre_sale","chocolat"],"classique":"Arbois savagnin et comté","note":"Première AOC de France (1936), ville de Pasteur. Deux écoles : blanc « ouillé », fût rempli, fruité et droit ; blanc « sous voile », élevé sous une pellicule de levures, qui donne noix et curry. Le vin du comté, du poulet au vin jaune et des morilles à la crème.","lat":46.9,"lon":5.77,"importance":4,"niveau":"classique"},{"id":"fr-chateau-chalon","nom":"Château-Chalon","pays":"France","region":"Jura","sousRegion":"","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Savagnin"],"style":"Noix fraîche, curry, pomme verte, morille ; sec, puissant, longueur immense.","temp":"14 à 16 °C","garde":"20 à 50 ans","prix":4,"accords":["fromage_dure","volaille","champignon","truffe","curry","noix"],"eviter":["poisson_cru","sucre_sale","huitre"],"classique":"Château-Chalon et poularde aux morilles","note":"L'appellation du vin jaune par excellence, sur quatre communes autour du village perché. Savagnin seul, six ans et trois mois en fût sous voile, mise en « clavelin » de 62 cl. Ouvert la veille, servi à température de cave, sur un comté affiné ou une volaille aux morilles.","lat":46.76,"lon":5.62,"importance":3,"niveau":"classique"},{"id":"fr-cotes-du-jura","nom":"Côtes du Jura","pays":"France","region":"Jura","sousRegion":"","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Poulsard, trousseau ou pinot noir : rouges légers et épicés."}],"cepages":["Chardonnay","Savagnin","Poulsard","Trousseau","Pinot noir"],"style":"Chardonnay noisette et pierre, savagnin noix et épices ; sec, parfois oxydatif.","temp":"10 à 12 °C","garde":"3 à 12 ans","prix":2,"accords":["fromage_dure","volaille","champignon","poisson_maigre","creme"],"eviter":["chocolat","sucre_sale"],"classique":"Côtes du Jura chardonnay et poulet à la crème","note":"Appellation régionale qui couvre tout le vignoble jurassien hors Arbois, L'Étoile et Château-Chalon, de Salins-les-Bains à Saint-Amour. Chardonnay dominant, marnes et calcaires. Même palette qu'Arbois à prix souvent plus doux ; les blancs ouillés y sont de plus en plus fréquents.","lat":46.67,"lon":5.55,"importance":3,"niveau":"classique"},{"id":"fr-vin-jaune","nom":"Vin jaune","pays":"France","region":"Jura","sousRegion":"","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Savagnin"],"style":"Noix, curry, gingembre, pomme verte, sotolon ; sec, intense, persistance très longue.","temp":"14 à 16 °C","garde":"20 à 50 ans","prix":3,"accords":["fromage_dure","volaille","champignon","curry","noix","truffe"],"eviter":["poisson_cru","huitre","chocolat"],"classique":"Vin jaune et comté 36 mois","note":"Savagnin élevé six ans et trois mois en fût non rempli, sous un voile de levures qui freine l'oxydation : il perd un tiers de son volume. Le clavelin de 62 cl rappelle ce qui reste d'un litre. Un vin sec, pas un vin doux, malgré sa robe dorée. Sortir la bouteille le matin pour le soir.","lat":46.84,"lon":5.71,"importance":3,"niveau":"classique"},{"id":"fr-cremant-du-jura","nom":"Crémant du Jura","pays":"France","region":"Jura","sousRegion":"","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"bulles","famille":"bulles","note":"Crémant rosé de pinot noir, poulsard ou trousseau, fruits rouges."}],"cepages":["Chardonnay","Pinot noir","Poulsard","Trousseau"],"style":"Bulles fines, pomme, brioche, noisette ; sec, frais, profil proche d'un chardonnay champenois.","temp":"6 à 8 °C","garde":"1 à 4 ans","prix":2,"accords":["coquillage","frit","volaille","fromage_dure","patisserie"],"eviter":["viande_rouge","piquant"],"classique":"Crémant du Jura et gougères au comté","note":"AOC depuis 1995, chardonnay dominant, méthode traditionnelle, neuf mois sur lattes. Il représente près d'un quart de la production du Jura. Le plus proche du champagne parmi les crémants pour son profil chardonnay, à un prix bien inférieur. Apéritif, gougères, fritures.","lat":46.67,"lon":5.55,"importance":2,"niveau":"classique"},{"id":"fr-l-etoile","nom":"L'Étoile","pays":"France","region":"Jura","sousRegion":"","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chardonnay","Savagnin","Poulsard"],"style":"Fleurs blanches, noisette, pierre à fusil, note de noix si sous voile ; fin, élancé.","temp":"10 à 12 °C","garde":"3 à 10 ans","prix":2,"accords":["poisson_maigre","crustace","fromage_dure","volaille","champignon"],"eviter":["viande_rouge","piquant"],"classique":"L'Étoile et truite au vin blanc","note":"Petite appellation de blancs seulement, nommée d'après les pentacrines, fossiles en étoile de tiges de lys de mer dans le sol marneux, ou les cinq collines disposées en étoile. Chardonnay dominant, plus fin et plus floral que l'Arbois. Un blanc de poisson de rivière et de fromage de montagne.","lat":46.7,"lon":5.51,"importance":2,"niveau":"decouverte"},{"id":"fr-macvin-du-jura","nom":"Macvin du Jura","pays":"France","region":"Jura","sousRegion":"","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Chardonnay","Savagnin","Poulsard"],"style":"Raisin frais, miel, noix, pruneau, pointe d'eau-de-vie ; doux, 16 à 22 % vol.","temp":"8 à 10 °C","garde":"5 à 20 ans","prix":3,"accords":["foie_gras","fromage_bleu","patisserie","noix","chocolat","glace"],"eviter":["poisson_maigre","huitre"],"classique":"Macvin du Jura et melon","note":"Mistelle du Jura : jus de raisin frais muté par du marc du Jura vieilli en fût, puis élevé au moins douze mois. AOC depuis 1991, blanc surtout, rouge et rosé possibles. Doux et chaleureux, à boire frais à l'apéritif, sur un melon, un pain d'épices ou un dessert aux noix.","lat":46.9,"lon":5.77,"importance":2,"niveau":"decouverte"},{"id":"fr-vin-de-paille","nom":"Vin de paille","pays":"France","region":"Jura","sousRegion":"","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Savagnin","Chardonnay","Poulsard","Trousseau"],"style":"Abricot sec, figue, orange confite, miel, noix ; liquoreux, acidité vive.","temp":"8 à 10 °C","garde":"10 à 30 ans","prix":3,"accords":["foie_gras","fromage_bleu","patisserie","noix","caramel"],"eviter":["viande_rouge","huitre"],"classique":"Vin de paille et foie gras poêlé","note":"Raisins séchés au moins six semaines sur paille ou claies, puis pressés : un litre de jus pour quatre kilos de raisin, puis trois ans d'élevage. Liquoreux à l'acidité vive, vendu en bouteille de 37,5 cl. À servir frais, en petit verre, sur un bleu de Gex ou un dessert aux fruits secs.","lat":46.9,"lon":5.77,"importance":2,"niveau":"decouverte"},{"id":"fr-banyuls","nom":"Banyuls","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Roussillon","couleur":"doux","famille":"vdn","variantes":[{"couleur":"doux","famille":"vdn","note":"Banyuls blanc, muté sur grenache blanc et gris, miel et fruits secs"}],"cepages":["Grenache","Grenache gris","Carignan"],"style":"Rimage : cerise noire et cassis frais ; traditionnel : pruneau, cacao, café et noix ; bouche douce et chaude","temp":"12 à 14 °C","garde":"5 à 30 ans","prix":2,"accords":["chocolat","fromage_bleu","foie_gras","caramel","noix","fruits_rouges"],"eviter":["poisson_maigre","huitre","acide"],"classique":"Banyuls et fondant au chocolat noir","note":"Sur les terrasses de schistes de la Côte Vermeille, entre Collioure et l'Espagne, le grenache noir (au moins 50 %) est muté à l'alcool pendant la fermentation. Deux styles : le « rimage », mis en bouteille jeune sur le fruit, et le traditionnel, élevé en fût ou en bonbonne. Le vin du chocolat.","lat":42.48,"lon":3.13,"importance":4,"niveau":"incontournable"},{"id":"fr-igp-pays-d-oc","nom":"IGP Pays d'Oc","pays":"France","region":"Languedoc-Roussillon","sousRegion":"","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Chardonnay, sauvignon ou viognier de cépage, simples, frais et fruités"},{"couleur":"rose","famille":"rose","note":"Rosé de cinsault, grenache ou syrah, léger et à prix doux"}],"cepages":["Merlot","Cabernet Sauvignon","Syrah","Grenache"],"style":"Fruits rouges et noirs, pointe d'épices ; bouche souple, tanins légers, le goût du cépage avant celui du terroir","temp":"14 à 16 °C","garde":"1 à 3 ans","prix":1,"accords":["grille","charcuterie","volaille","porc","mijote","tomate"],"eviter":["huitre","poisson_cru","truffe"],"classique":"Merlot Pays d'Oc et pizza ou burger du quotidien","note":"Créée en 1987 pour répondre aux vins de cépage du Nouveau Monde, l'IGP couvre les quatre départements du Languedoc-Roussillon et produit le plus gros volume de vins de cépage de France, exporté partout. L'étiquette annonce le cépage, pas le lieu. Vins simples, francs et abordables.","lat":43.4,"lon":3.3,"importance":4,"niveau":"classique"},{"id":"fr-blanquette-de-limoux","nom":"Blanquette de Limoux","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"bulles","famille":"bulles","note":"Méthode ancestrale : 100 % mauzac, 6 à 7 % d'alcool, légèrement doux, sur la pomme"}],"cepages":["Mauzac","Chardonnay","Chenin"],"style":"Pomme verte, fleurs blanches et croûte de pain ; bulle fine, bouche vive et légère, finale sèche","temp":"6 à 8 °C","garde":"1 à 3 ans","prix":1,"accords":["crustace","coquillage","poisson_maigre","frit","fromage_chevre","patisserie"],"eviter":["viande_rouge","sauce_vin_rouge","piquant"],"classique":"Blanquette de Limoux à l'apéritif avec une fougasse","note":"Les moines de l'abbaye de Saint-Hilaire auraient produit ici le premier vin effervescent de France, en 1531, bien avant la Champagne. La Blanquette repose à 90 % minimum sur le mauzac, cépage local au goût de pomme, en méthode traditionnelle. Bulle simple et franche pour l'apéritif et les fritures.","lat":43.05,"lon":2.22,"importance":3,"niveau":"classique"},{"id":"fr-corbieres","nom":"Corbières","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Blanc de grenache blanc, bourboulenc et vermentino, sec et chaleureux"},{"couleur":"rose","famille":"rose","note":"Rosé de grenache et cinsault, charnu et épicé"}],"cepages":["Carignan","Grenache","Syrah","Mourvèdre"],"style":"Mûre, garrigue, cuir et épices ; bouche robuste, tanins rustiques adoucis par la macération carbonique","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["grille","charcuterie","mijote","agneau","gibier","mediterraneen"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Corbières et cassoulet ou grillade de saucisse","note":"Avec plus de 10 000 hectares entre Narbonne, Carcassonne et les Pyrénées, les Corbières forment la plus vaste appellation du Languedoc, découpée en onze terroirs. Le vieux carignan en macération carbonique y donne des rouges généreux et épicés. Rouge de bistrot par excellence, à prix doux.","lat":43.08,"lon":2.8,"importance":3,"niveau":"classique"},{"id":"fr-cotes-du-roussillon","nom":"Côtes du Roussillon","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Roussillon","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Blanc de grenache blanc, macabeu et vermentino, rond et chaleureux"},{"couleur":"rose","famille":"rose","note":"Rosé de grenache et syrah, charnu et épicé"}],"cepages":["Grenache","Syrah","Carignan","Mourvèdre"],"style":"Fruits noirs mûrs, garrigue, réglisse et cacao ; bouche chaleureuse et généreuse, tanins souples","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["grille","charcuterie","agneau","mijote","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Côtes du Roussillon et grillade de saucisse catalane","note":"Appellation régionale du Roussillon, reconnue en 1977, elle couvre les coteaux autour de Perpignan, dans l'amphithéâtre fermé par les Corbières et le Canigou. Le grenache noir, roi des lieux, donne des rouges solaires et doux en tanins, à boire jeunes et un peu frais sur une cuisine catalane.","lat":42.63,"lon":2.75,"importance":3,"niveau":"classique"},{"id":"fr-cremant-de-limoux","nom":"Crémant de Limoux","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"bulles","famille":"bulles","note":"Crémant rosé, avec une part de pinot noir, fruits rouges et bulle fine"}],"cepages":["Chardonnay","Chenin","Mauzac","Pinot Noir"],"style":"Agrumes, poire, brioche et amande ; bulle fine et crémeuse, bouche élégante, finale fraîche","temp":"6 à 8 °C","garde":"2 à 5 ans","prix":2,"accords":["crustace","huitre","poisson_maigre","volaille","fromage_frais","patisserie"],"eviter":["viande_rouge","sauce_vin_rouge","piquant"],"classique":"Crémant de Limoux et huîtres de Leucate","note":"Créé en 1990 à côté de la Blanquette, le Crémant de Limoux s'appuie sur le chardonnay et le chenin, avec un peu de mauzac et de pinot noir, et vieillit au moins quinze mois sur lattes. Plus fin et plus proche du champagne que sa sœur au mauzac, c'est une bulle au rapport qualité-prix remarquable.","lat":43.05,"lon":2.22,"importance":3,"niveau":"classique"},{"id":"fr-faugeres","nom":"Faugères","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Blanc de roussanne et grenache blanc, ample et minéral, reconnu en 2005"},{"couleur":"rose","famille":"rose","note":"Rosé épicé de grenache, cinsault et syrah"}],"cepages":["Syrah","Grenache","Carignan","Mourvèdre"],"style":"Mûre, violette, poivre et graphite ; bouche dense, tanins fins, minéralité fumée propre aux schistes","temp":"16 à 18 °C","garde":"4 à 10 ans","prix":2,"accords":["agneau","viande_rouge","gibier","grille","mijote","fromage_lave"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Faugères et épaule d'agneau confite","note":"Faugères est le seul grand terroir de schistes d'un seul tenant du Languedoc, sur sept villages des hauts cantons au nord de Béziers. Ces sols pauvres obligent la vigne à plonger et donnent des rouges concentrés, droits, à la trame fumée reconnaissable. Appellation depuis 1982, largement en bio.","lat":43.57,"lon":3.19,"importance":3,"niveau":"classique"},{"id":"fr-fitou","nom":"Fitou","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Carignan","Grenache","Syrah","Mourvèdre"],"style":"Fruits noirs cuits, garrigue, cuir et épices ; bouche corsée, tanins fermes, notes iodées près de la mer","temp":"16 à 18 °C","garde":"4 à 10 ans","prix":2,"accords":["gibier","viande_rouge","agneau","mijote","grille","fromage_dure"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Fitou et daube de sanglier aux olives","note":"Plus ancienne appellation rouge du Languedoc, reconnue en 1948, Fitou se partage en deux îlots : le Fitou maritime, autour des étangs de Leucate, et le Fitou de montagne, vers Tuchan, dans les Hautes-Corbières. Rouge uniquement, carignan et grenache dominants, élevé au moins neuf mois, à carafer.","lat":42.89,"lon":2.98,"importance":3,"niveau":"classique"},{"id":"fr-languedoc","nom":"Languedoc","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Grenache blanc, roussanne, vermentino : rond, fruits blancs et fenouil"},{"couleur":"rose","famille":"rose","note":"Rosé de grenache et cinsault, fraise et agrumes, à boire jeune"}],"cepages":["Syrah","Grenache","Mourvèdre","Carignan"],"style":"Fruits noirs mûrs, garrigue et poivre ; bouche chaleureuse, tanins souples, finale sur le thym","temp":"15 à 17 °C","garde":"2 à 5 ans","prix":1,"accords":["grille","mediterraneen","agneau","charcuterie","mijote"],"eviter":["huitre","poisson_cru"],"classique":"Languedoc rouge et grillades aux herbes de la garrigue","note":"Appellation régionale créée en 2007 pour remplacer les Coteaux du Languedoc, elle couvre les coteaux de Nîmes à la frontière espagnole. Le rouge d'assemblage syrah, grenache et mourvèdre, solaire et épicé, se sert légèrement rafraîchi sur une cuisine du Sud au quotidien.","lat":43.46,"lon":3.42,"importance":3,"niveau":"classique"},{"id":"fr-maury","nom":"Maury","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Roussillon","couleur":"doux","famille":"vdn","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Maury sec (AOC 2011) : grenache sur schistes, rouge dense, minéral et poivré"}],"cepages":["Grenache","Grenache gris","Macabeu","Carignan"],"style":"Grenat : mûre, cassis, violette ; tuilé : pruneau, cacao, noix et tabac ; bouche douce, tanins présents","temp":"12 à 14 °C","garde":"5 à 30 ans","prix":2,"accords":["chocolat","fromage_bleu","foie_gras","caramel","noix","fruits_rouges"],"eviter":["poisson_maigre","huitre","acide"],"classique":"Maury et dessert au chocolat noir","note":"Dans la haute vallée de l'Agly, sous le château cathare de Quéribus, les schistes noirs de Maury chauffent sous le vent. Le grenache y est muté comme à Banyuls, en style « grenat » sur le fruit ou « tuilé » après un long élevage oxydatif. Depuis 2011, le Maury sec, non muté, porte aussi le nom.","lat":42.81,"lon":2.61,"importance":3,"niveau":"classique"},{"id":"fr-minervois","nom":"Minervois","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Blanc de grenache blanc, marsanne, roussanne et vermentino, rond et floral"},{"couleur":"rose","famille":"rose","note":"Rosé de grenache et cinsault, fruité et léger"}],"cepages":["Syrah","Grenache","Carignan","Mourvèdre"],"style":"Cerise, cassis, thym et poivre ; bouche souple et gourmande, tanins fondus, finale épicée","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["charcuterie","grille","volaille","mijote","mediterraneen","porc"],"eviter":["huitre","poisson_cru"],"classique":"Minervois et cassoulet au confit de canard","note":"Entre Carcassonne et Narbonne, sur un amphithéâtre qui descend de la Montagne Noire vers le canal du Midi, le Minervois tire son nom du village de Minerve. Appellation depuis 1985, elle donne surtout des rouges souples et épicés, faciles à table, le choix sûr d'un restaurant pour un plat mijoté.","lat":43.3,"lon":2.7,"importance":3,"niveau":"classique"},{"id":"fr-muscat-de-frontignan","nom":"Muscat de Frontignan","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Muscat blanc à petits grains"],"style":"Raisin frais, abricot, fleur d'oranger et miel ; bouche douce et onctueuse, 15 % d'alcool, finale sur le zeste","temp":"8 à 10 °C","garde":"2 à 6 ans","prix":1,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","fruits_exotiques","agrumes"],"eviter":["viande_rouge","chocolat","acide"],"classique":"Muscat de Frontignan et tarte aux abricots","note":"Entre Sète et Montpellier, Frontignan est le muscat historique du Languedoc, protégé dès 1936 : les vignes regardent la mer. Le vin est muté à l'alcool en cours de fermentation, ce qui garde le sucre du raisin. Vin d'apéritif, il brille surtout avec un bleu ou un dessert aux fruits.","lat":43.45,"lon":3.75,"importance":3,"niveau":"classique"},{"id":"fr-muscat-de-rivesaltes","nom":"Muscat de Rivesaltes","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Roussillon","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Muscat blanc à petits grains","Muscat d'Alexandrie"],"style":"Raisin frais, citron, fleur d'oranger et menthe ; bouche douce et fraîche, 15 % d'alcool, finale sur le zeste","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":1,"accords":["foie_gras","fromage_bleu","fruits_exotiques","fruits_jaunes","patisserie","asiatique"],"eviter":["viande_rouge","chocolat","acide"],"classique":"Muscat de Rivesaltes et tarte au citron meringuée","note":"Plus grand muscat muté de France, reconnu en 1956 sur tout le Roussillon et une partie des Corbières. Il associe le muscat à petits grains, fin et citronné, au muscat d'Alexandrie, plus exotique et plus résistant à la chaleur. Apéritif catalan, à boire jeune et très frais, ou avec un dessert fruité.","lat":42.75,"lon":2.9,"importance":3,"niveau":"classique"},{"id":"fr-pic-saint-loup","nom":"Pic Saint-Loup","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de saignée ou de pressurage, vineux et frais, sur la groseille"}],"cepages":["Syrah","Grenache","Mourvèdre"],"style":"Cassis, violette, réglisse et laurier ; tanins fermes mais fins, fraîcheur rare pour le Sud","temp":"16 à 18 °C","garde":"4 à 10 ans","prix":2,"accords":["agneau","viande_rouge","gibier","roti","herbes","fromage_dure"],"eviter":["huitre","poisson_maigre","cremeux"],"classique":"Pic Saint-Loup et gigot d'agneau au thym","note":"Au pied d'un pic calcaire au nord de Montpellier, le vignoble profite de nuits fraîches et de pluies plus abondantes que sur le littoral. La syrah y domine et donne des rouges sombres, droits et parfumés, plus frais que la moyenne languedocienne. Cru reconnu en 2017, à ouvrir sur une viande rôtie.","lat":43.78,"lon":3.83,"importance":3,"niveau":"classique"},{"id":"fr-picpoul-de-pinet","nom":"Picpoul de Pinet","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Piquepoul blanc"],"style":"Citron, fleurs blanches et embruns ; bouche vive, saline et légère, finale nette qui appelle l'huître","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":1,"accords":["huitre","coquillage","crustace","poisson_maigre","frit","poisson_cru"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Picpoul de Pinet et huîtres de Bouzigues","note":"Sur les rives de l'étang de Thau, face aux parcs à huîtres de Bouzigues, le piquepoul (« pique-lèvres », pour son acidité) donne un rare blanc sec de cépage unique en Languedoc. Appellation en 2013, devenu le « muscadet du Sud » : vif, salin, à boire jeune avec les coquillages de l'étang.","lat":43.4,"lon":3.51,"importance":3,"niveau":"classique"},{"id":"fr-rivesaltes","nom":"Rivesaltes","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Roussillon","couleur":"doux","famille":"vdn","variantes":[{"couleur":"doux","famille":"vdn","note":"Rivesaltes tuilé : à base de grenache noir, pruneau, cacao et tabac après élevage oxydatif"},{"couleur":"doux","famille":"vdn","note":"Rivesaltes grenat : grenache noir mis en bouteille jeune, sur le fruit noir"}],"cepages":["Grenache blanc","Grenache gris","Macabeu","Grenache"],"style":"Ambré : abricot sec, noix, miel, écorce d'orange et rancio ; bouche douce et longue, chaleur maîtrisée","temp":"10 à 13 °C","garde":"5 à 40 ans","prix":2,"accords":["foie_gras","fromage_bleu","noix","caramel","patisserie","fromage_dure"],"eviter":["poisson_maigre","huitre","acide"],"classique":"Rivesaltes ambré et tarte aux noix","note":"Première appellation de vins doux naturels de France par la surface, reconnue en 1936, elle couvre le Roussillon. L'« ambré » naît des grenaches blanc et gris élevés à l'air, le « tuilé » du grenache noir ; « hors d'âge » et « rancio » signalent les vieux élevages. Au dessert ou au fromage.","lat":42.77,"lon":2.87,"importance":3,"niveau":"classique"},{"id":"fr-saint-chinian","nom":"Saint-Chinian","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Blanc de grenache blanc, roussanne et marsanne, reconnu en 2005"},{"couleur":"rose","famille":"rose","note":"Rosé fruité de grenache et syrah, pour la table d'été"}],"cepages":["Syrah","Grenache","Carignan","Mourvèdre"],"style":"Cerise noire, cassis, réglisse et garrigue ; corps souple sur les schistes, plus charnu sur le calcaire","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":1,"accords":["charcuterie","grille","agneau","mijote","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_cru"],"classique":"Saint-Chinian et cassoulet de Castelnaudary","note":"Au nord de Béziers, l'appellation se partage entre les schistes du nord, qui donnent des rouges fins et épicés, et les argilo-calcaires du sud, plus charnus. Deux villages, Roquebrun et Berlou, ont leur mention propre. Rouge convivial et abordable, parfait avec les plats mijotés du Sud-Ouest.","lat":43.42,"lon":2.95,"importance":3,"niveau":"classique"},{"id":"fr-terrasses-du-larzac","nom":"Terrasses du Larzac","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Syrah","Grenache","Mourvèdre","Carignan"],"style":"Mûre, cerise noire, garrigue et graphite ; bouche dense mais fraîche, tanins mûrs et soyeux","temp":"16 à 18 °C","garde":"4 à 12 ans","prix":2,"accords":["agneau","viande_rouge","mijote","gibier","champignon","fromage_dure"],"eviter":["huitre","poisson_cru","acide"],"classique":"Terrasses du Larzac et daube de bœuf aux olives","note":"Sur les contreforts du causse du Larzac, entre 100 et 400 mètres, le vignoble bénéficie de forts écarts de température entre jour et nuit qui préservent l'acidité. Appellation rouge uniquement, reconnue en 2014, elle rassemble une génération de vignerons en bio. Rouge de table, à carafer jeune.","lat":43.69,"lon":3.5,"importance":3,"niveau":"classique"},{"id":"fr-banyuls-grand-cru","nom":"Banyuls Grand Cru","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Roussillon","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Grenache","Grenache gris","Carignan"],"style":"Figue sèche, noix, café, cacao et écorce d'orange ; bouche ample, rancio profond, finale interminable","temp":"13 à 15 °C","garde":"10 à 50 ans","prix":3,"accords":["chocolat","fromage_bleu","noix","caramel","foie_gras","fromage_dure"],"eviter":["poisson_maigre","huitre","acide"],"classique":"Banyuls Grand Cru et roquefort aux noix","note":"Mention créée en 1962 pour les meilleurs Banyuls : grenache noir à 75 % au minimum, macération d'au moins cinq jours et élevage obligatoire de trente mois sous bois, souvent bien plus. L'oxydation lente donne le « rancio », ces notes de noix et de café. Vin de méditation, après le repas.","lat":42.48,"lon":3.13,"importance":2,"niveau":"decouverte"},{"id":"fr-cabardes","nom":"Cabardès","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé frais de grenache et cabernet, à boire jeune"}],"cepages":["Syrah","Cabernet Sauvignon","Merlot","Grenache"],"style":"Cassis, poivron grillé, garrigue et poivre ; bouche équilibrée, tanins souples, fraîcheur atlantique","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":1,"accords":["volaille","porc","viande_rouge","grille","mijote","charcuterie"],"eviter":["huitre","poisson_cru"],"classique":"Cabardès et cassoulet de Carcassonne","note":"Au nord de Carcassonne, sur les premières pentes de la Montagne Noire, le Cabardès est la seule appellation française qui impose d'assembler cépages méditerranéens (syrah, grenache) et atlantiques (cabernet, merlot), chacun à 40 % au minimum. Il en sort des rouges souples et frais, reconnus en 1999.","lat":43.33,"lon":2.3,"importance":2,"niveau":"decouverte"},{"id":"fr-collioure","nom":"Collioure","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Roussillon","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Blanc de grenache blanc et gris, ample, salin, sur la pêche et le fenouil (AOC 2002)"},{"couleur":"rose","famille":"rose","note":"Rosé vineux et épicé de grenache et syrah, fait pour la table"}],"cepages":["Grenache","Syrah","Mourvèdre","Carignan"],"style":"Fruits noirs confits, figue, garrigue et cacao ; bouche puissante et chaleureuse, tanins mûrs, finale saline","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["agneau","grille","poisson_gras","mediterraneen","viande_rouge","fromage_dure"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Collioure et anchois de Collioure sur une escalivade","note":"Les vins secs de Banyuls : même terroir de schistes en terrasses plongeant dans la mer, mêmes vignerons, mais sans mutage. Le rouge, reconnu en 1971, est solaire, salin et marqué par le grenache ; le blanc, admis en 2002, est devenu un grand blanc de bord de mer. Avec anchois et poissons grillés.","lat":42.53,"lon":3.08,"importance":2,"niveau":"classique"},{"id":"fr-corbieres-boutenac","nom":"Corbières-Boutenac","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Carignan","Grenache","Syrah","Mourvèdre"],"style":"Fruits noirs, garrigue, cuir et cacao ; bouche puissante et veloutée, tanins mûrs, grande longueur","temp":"16 à 18 °C","garde":"5 à 12 ans","prix":2,"accords":["viande_rouge","gibier","agneau","roti","mijote","fromage_dure"],"eviter":["huitre","poisson_maigre","acide"],"classique":"Corbières-Boutenac et civet de sanglier","note":"Cru des Corbières reconnu en 2005, autour de dix communes au pied de la Pinède de Boutenac, sur des sols de galets et de grès rouges. Le carignan y est obligatoire à 30 % minimum et vient souvent de vignes de plus de cinquante ans ; les rouges, élevés au moins six mois, sont charnus et profonds.","lat":43.15,"lon":2.7,"importance":2,"niveau":"decouverte"},{"id":"fr-cotes-du-roussillon-villages","nom":"Côtes du Roussillon Villages","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Roussillon","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Syrah","Grenache","Carignan","Mourvèdre"],"style":"Mûre, cerise noire, schiste chaud, garrigue et poivre ; bouche dense, tanins mûrs, finale épicée et longue","temp":"16 à 18 °C","garde":"4 à 12 ans","prix":2,"accords":["viande_rouge","gibier","agneau","roti","mijote","fromage_dure"],"eviter":["huitre","poisson_maigre","acide"],"classique":"Côtes du Roussillon Villages et civet de sanglier","note":"Réservée aux rouges de la vallée de l'Agly et des Fenouillèdes, au nord du département, sur schistes, gneiss et granits. Quatre villages peuvent ajouter leur nom (Caramany, Latour-de-France, Lesquerde, Tautavel). Vieux carignans et syrah donnent des rouges structurés de garde.","lat":42.77,"lon":2.7,"importance":2,"niveau":"classique"},{"id":"fr-igp-cotes-catalanes","nom":"IGP Côtes Catalanes","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Roussillon","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Blancs de grenache gris, macabeu et carignan blanc : amples, salins, parmi les plus recherchés du Sud"}],"cepages":["Grenache","Carignan","Syrah","Mourvèdre"],"style":"Cerise, mûre, schiste et garrigue ; bouche fraîche et énergique, tanins fins, souvent sans bois","temp":"15 à 17 °C","garde":"3 à 10 ans","prix":2,"accords":["agneau","grille","poisson_gras","mediterraneen","charcuterie","fromage_dure"],"eviter":["huitre","cremeux","sucre_sale"],"classique":"Côtes Catalanes blanc et poisson grillé aux herbes","note":"Indication géographique de tout le Roussillon, refuge des vignerons qui sortent du cadre des AOC : vieux carignans en monocépage, blancs de grenache gris et macabeu, vins nature. Depuis les années 2000, beaucoup des vins les plus cotés du Roussillon naissent sous cette étiquette.","lat":42.76,"lon":2.76,"importance":2,"niveau":"decouverte"},{"id":"fr-la-clape","nom":"La Clape","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Bourboulenc majoritaire : blanc iodé, gras et salin, fait pour les poissons"}],"cepages":["Syrah","Grenache","Mourvèdre","Carignan"],"style":"Fruits noirs, romarin et notes iodées ; bouche puissante, tanins serrés, finale saline","temp":"16 à 18 °C","garde":"4 à 10 ans","prix":2,"accords":["agneau","grille","viande_rouge","mediterraneen","poisson_gras"],"eviter":["huitre","sucre_sale","cremeux"],"classique":"La Clape blanc et bourride sétoise","note":"Ancienne île devenue massif calcaire entre Narbonne et la mer, La Clape est l'un des coins les plus secs et venteux de France. Cru en 2015, elle donne des rouges puissants marqués par la garrigue et, originalité, des blancs de bourboulenc à l'air marin. À servir sur une cuisine de pêcheur.","lat":43.15,"lon":3.1,"importance":2,"niveau":"decouverte"},{"id":"fr-limoux-blanc","nom":"Limoux blanc","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Limoux rouge, merlot majoritaire avec syrah, grenache ou cabernet, souple et frais"}],"cepages":["Chardonnay","Chenin","Mauzac"],"style":"Pomme mûre, poire, noisette et beurre frais ; bouche ample et boisée, tenue par une acidité de montagne","temp":"10 à 12 °C","garde":"3 à 8 ans","prix":2,"accords":["volaille","poisson_gras","creme","champignon","fromage_dure","viande_blanche"],"eviter":["piquant","vinaigre","chocolat"],"classique":"Limoux blanc et poularde à la crème et aux morilles","note":"Dans la haute vallée de l'Aude, au sud de Carcassonne, Limoux est le pays du chardonnay en Languedoc : l'altitude et l'influence pyrénéenne apportent une fraîcheur rare. Le blanc tranquille, reconnu en 1993, doit être vinifié et élevé en fût de chêne, d'où un style proche d'un bourgogne à prix doux.","lat":43.05,"lon":2.22,"importance":2,"niveau":"decouverte"},{"id":"fr-minervois-la-liviniere","nom":"Minervois-La Livinière","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Syrah","Grenache","Mourvèdre","Carignan"],"style":"Fruits noirs confits, réglisse, cacao et garrigue ; bouche ample, tanins mûrs et serrés, longue finale","temp":"16 à 18 °C","garde":"5 à 12 ans","prix":2,"accords":["viande_rouge","agneau","gibier","roti","mijote","fromage_dure"],"eviter":["huitre","poisson_maigre","acide"],"classique":"Minervois-La Livinière et carré d'agneau rôti","note":"Premier cru du Languedoc, reconnu en 1999 sur six communes autour de La Livinière, sur le piémont de la Montagne Noire. Rendements limités, syrah et mourvèdre à 40 % au minimum, élevage obligatoire : des rouges plus concentrés et plus longs que le Minervois générique, à attendre deux ou trois ans.","lat":43.3,"lon":2.63,"importance":2,"niveau":"decouverte"},{"id":"fr-muscat-de-saint-jean-de-minervois","nom":"Muscat de Saint-Jean-de-Minervois","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Muscat blanc à petits grains"],"style":"Fleur d'oranger, litchi, citron et menthe ; douceur aérienne, acidité vive, le plus fin des muscats du Languedoc","temp":"8 à 10 °C","garde":"2 à 6 ans","prix":1,"accords":["foie_gras","fromage_bleu","fruits_exotiques","fruits_jaunes","patisserie","asiatique"],"eviter":["viande_rouge","chocolat","acide"],"classique":"Muscat de Saint-Jean-de-Minervois et foie gras poêlé","note":"Seul muscat de l'intérieur des terres, perché à 250 mètres sur un plateau calcaire au nord de Saint-Chinian, il mûrit trois semaines plus tard que ceux du littoral. Cette altitude lui donne une fraîcheur et une finesse florale qui le distinguent. Appellation en 1949, 200 hectares à peine.","lat":43.38,"lon":2.8,"importance":2,"niveau":"decouverte"},{"id":"fr-clairette-du-languedoc","nom":"Clairette du Languedoc","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Version moelleuse, voire « rancio » après trois ans d'élevage oxydatif, miel et noix"}],"cepages":["Clairette"],"style":"Pomme, poire, fenouil et amande amère ; bouche ronde et chaleureuse, acidité modérée, finale légèrement amère","temp":"9 à 11 °C","garde":"1 à 4 ans","prix":1,"accords":["poisson_gras","coquillage","volaille","legumes","mediterraneen","fromage_chevre"],"eviter":["viande_rouge","sauce_vin_rouge","piquant"],"classique":"Clairette du Languedoc et tielle sétoise","note":"Reconnue dès 1948 autour d'Adissan et Paulhan, près de Pézenas, c'est l'une des rares appellations de blanc de cépage unique du Languedoc. La clairette, cépage ancien et fragile, donne un vin rond et peu acide, sec ou moelleux, qui s'oxyde vite : à boire jeune et frais avec les poissons de la mer.","lat":43.56,"lon":3.43,"importance":1,"niveau":"decouverte"},{"id":"fr-igp-cotes-de-thongue","nom":"IGP Côtes de Thongue","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Blancs de viognier, sauvignon ou chardonnay, parfumés et frais"}],"cepages":["Syrah","Merlot","Cabernet Sauvignon","Grenache"],"style":"Cerise, mûre, poivre et herbes ; bouche souple et fruitée, tanins légers, finale fraîche","temp":"14 à 16 °C","garde":"2 à 5 ans","prix":1,"accords":["grille","charcuterie","volaille","porc","mediterraneen","legumes"],"eviter":["huitre","poisson_cru","truffe"],"classique":"Côtes de Thongue et poulet grillé aux herbes","note":"Petite IGP de la vallée de la Thongue, entre Béziers et Pézenas, animée par un collectif de vignerons qui s'est imposé une charte de qualité (rendements, vinification au domaine). Liberté des cépages, beaucoup d'assemblages syrah-merlot ou cabernet : des vins de domaine sincères, à boire jeunes.","lat":43.45,"lon":3.36,"importance":1,"niveau":"decouverte"},{"id":"fr-gres-de-montpellier","nom":"Languedoc Grès de Montpellier","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Syrah","Grenache","Mourvèdre","Carignan"],"style":"Fruits noirs, garrigue, olive noire et épices ; bouche ample et chaleureuse, tanins mûrs, finale réglissée","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["agneau","grille","viande_rouge","mijote","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Grès de Montpellier et gardiane de taureau","note":"Dénomination de l'AOC Languedoc, reconnue en 2003, pour les rouges d'une quarantaine de communes autour de Montpellier, entre le Pic Saint-Loup et la mer. Grenache à 20 % au minimum et élevage d'un an obligatoire : des rouges généreux et solaires, marqués par la garrigue et la douceur du littoral.","lat":43.6,"lon":3.8,"importance":1,"niveau":"decouverte"},{"id":"fr-malepere","nom":"Malepère","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de cabernet franc majoritaire, vif et fruité"}],"cepages":["Merlot","Cabernet Franc","Cot","Cabernet Sauvignon"],"style":"Cerise, prune, poivron et sous-bois ; bouche ronde et souple, tanins fins, finale fraîche","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["volaille","porc","charcuterie","viande_blanche","champignon","mijote"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Malepère et confit de canard aux cèpes","note":"Au sud-ouest de Carcassonne, sur le massif de la Malepère, c'est l'appellation la plus atlantique du Languedoc : le merlot y est obligatoire à 50 % au minimum, complété par les cabernets et le cot. Rouges souples, bordelais dans l'esprit, à boire jeunes sur les volailles et le canard. AOC en 2007.","lat":43.14,"lon":2.14,"importance":1,"niveau":"decouverte"},{"id":"fr-muscat-de-lunel","nom":"Muscat de Lunel","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Muscat blanc à petits grains"],"style":"Raisin muscaté, pêche, citron confit et tilleul ; douceur fine, plus légère que Frontignan, finale fraîche","temp":"8 à 10 °C","garde":"2 à 5 ans","prix":1,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","fruits_exotiques"],"eviter":["viande_rouge","chocolat","acide"],"classique":"Muscat de Lunel et melon de Lunel au jambon cru","note":"Aux portes de la Camargue, entre Montpellier et Nîmes, Lunel cultive le muscat à petits grains sur des galets roulés qui restituent la chaleur. Appellation en 1943, c'est l'un des plus confidentiels des muscats languedociens, apprécié pour sa finesse citronnée. Très frais, avec le melon ou un bleu.","lat":43.68,"lon":4.11,"importance":1,"niveau":"decouverte"},{"id":"fr-muscat-de-mireval","nom":"Muscat de Mireval","pays":"France","region":"Languedoc-Roussillon","sousRegion":"Languedoc","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Muscat blanc à petits grains"],"style":"Raisin frais, abricot, miel et notes iodées ; bouche douce et tendue par une pointe saline, finale citronnée","temp":"8 à 10 °C","garde":"2 à 5 ans","prix":1,"accords":["foie_gras","fromage_bleu","fruits_jaunes","fruits_exotiques","patisserie"],"eviter":["viande_rouge","chocolat","acide"],"classique":"Muscat de Mireval et roquefort","note":"Voisin immédiat de Frontignan, entre le massif de la Gardiole et l'étang de Vic, Mireval produit le même muscat à petits grains muté, protégé depuis 1959, mais sur des sols plus calcaires et caillouteux. Rabelais l'évoquait déjà. Un peu plus salin et tendu que son voisin, idéal avec un fromage bleu.","lat":43.51,"lon":3.8,"importance":1,"niveau":"decouverte"},{"id":"fr-cotes-de-provence","nom":"Côtes de Provence","pays":"France","region":"Provence","sousRegion":"","couleur":"rose","famille":"rose","variantes":[{"couleur":"rouge","famille":"rouge_solaire","note":"Rouges de Syrah et Mourvèdre, garrigue et fruit noir, surtout dans les crus Sainte-Victoire et La Londe."},{"couleur":"blanc","famille":"blanc_vif","note":"Blancs de Rolle (Vermentino), secs et citronnés, rares mais frais."}],"cepages":["Grenache","Cinsault","Syrah","Tibouren"],"style":"Rosé pâle, pêche blanche, agrumes et petits fruits rouges, bouche sèche, fraîche et légèrement saline.","temp":"8 à 10 °C","garde":"1 à 2 ans","prix":2,"accords":["poisson_maigre","grille","mediterraneen","legumes","charcuterie","tomate"],"eviter":["sauce_vin_rouge","chocolat","fromage_bleu"],"classique":"Côtes de Provence rosé et bouillabaisse","note":"Plus grande appellation de Provence, du Var aux portes de Marseille, elle produit près de 90 % de rosé par pressurage direct. Sa robe très pâle et son fruit croquant en font le vin d'été par excellence, à boire jeune, frais, sur les grillades et la cuisine à l'huile d'olive.","lat":43.45,"lon":6.45,"importance":5,"niveau":"incontournable"},{"id":"fr-bandol","nom":"Bandol","pays":"France","region":"Provence","sousRegion":"","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de Mourvèdre, plus vineux et structuré que les autres rosés provençaux, il tient deux à trois ans."}],"cepages":["Mourvèdre","Grenache","Cinsault"],"style":"Rouge dense, mûre, cuir, garrigue, réglisse ; tanins fermes et finale longue, animale avec l'âge.","temp":"16 à 18 °C","garde":"8 à 20 ans","prix":3,"accords":["agneau","gibier","viande_rouge","roti","mijote","truffe"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Bandol rouge et gigot d'agneau aux herbes","note":"Sur des restanques face à la mer, entre Toulon et La Ciotat, le Mourvèdre trouve la chaleur qu'il exige : au moins 50 % de l'assemblage rouge, élevé 18 mois en foudre. C'est le seul grand rouge de garde de Provence, à carafer jeune ou à attendre dix ans sur un gibier.","lat":43.17,"lon":5.76,"importance":4,"niveau":"incontournable"},{"id":"fr-cassis","nom":"Cassis","pays":"France","region":"Provence","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rose","famille":"rose","note":"Rosés de Grenache et Cinsault, un tiers de la production, assez vineux."}],"cepages":["Marsanne","Clairette","Ugni blanc","Bourboulenc"],"style":"Blanc sec et rond, fleurs blanches, poire, amande, pointe iodée et finale saline sans lourdeur.","temp":"9 à 11 °C","garde":"2 à 5 ans","prix":2,"accords":["poisson_maigre","coquillage","crustace","huitre","grille","mediterraneen"],"eviter":["viande_rouge","chocolat","sauce_vin_rouge"],"classique":"Cassis blanc et bourride","note":"Petit amphithéâtre calcaire entre le cap Canaille et les calanques, Cassis est l'une des premières AOC de France (1936) et la seule de Provence dominée par le blanc. La Marsanne apporte le gras, la Clairette la fraîcheur : un vin de poissons grillés et de bourride, à boire dans les quatre ans.","lat":43.21,"lon":5.54,"importance":3,"niveau":"classique"},{"id":"fr-coteaux-d-aix-en-provence","nom":"Coteaux d'Aix-en-Provence","pays":"France","region":"Provence","sousRegion":"Aix-en-Provence","couleur":"rose","famille":"rose","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Rouges Grenache, Syrah et Cabernet Sauvignon, fruités et souples, parfois plus structurés en coteaux."}],"cepages":["Grenache","Syrah","Cabernet Sauvignon","Cinsault"],"style":"Rosé pâle et vif, fraise, agrumes, note de garrigue, finale sèche et désaltérante.","temp":"8 à 10 °C","garde":"1 à 2 ans","prix":1,"accords":["grille","legumes","mediterraneen","volaille","poisson_maigre","tomate"],"eviter":["sauce_vin_rouge","chocolat"],"classique":"Coteaux d'Aix rosé et tian de légumes","note":"Entre Durance et Méditerranée, autour d'Aix, sols calcaires balayés par le mistral. Le Cabernet Sauvignon y est autorisé, ce qui est rare en Provence : il a été popularisé ici dans les années 1960 par le château Vignelaure. Rosés simples et francs, rouges à boire dans les trois ans.","lat":43.53,"lon":5.45,"importance":3,"niveau":"classique"},{"id":"fr-les-baux-de-provence","nom":"Les Baux-de-Provence","pays":"France","region":"Provence","sousRegion":"Alpilles","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"rose","famille":"rose","note":"Rosés de Grenache et Syrah, charnus, souvent bio comme tout le vignoble."}],"cepages":["Grenache","Syrah","Mourvèdre","Cabernet Sauvignon"],"style":"Rouge chaleureux, fruits noirs, olive, laurier et thym, tanins mûrs et finale épicée.","temp":"16 à 18 °C","garde":"5 à 12 ans","prix":2,"accords":["agneau","grille","mediterraneen","roti","viande_rouge","herbes"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Les Baux rouge et agneau grillé au thym","note":"Sur les versants des Alpilles, autour du village des Baux, un vignoble de 300 hectares presque entièrement cultivé en bio ou biodynamie, une première en France pour une appellation. Rouges solaires mais relevés par le mistral, à servir sur les viandes grillées aux herbes de la garrigue.","lat":43.74,"lon":4.8,"importance":3,"niveau":"classique"},{"id":"fr-bellet","nom":"Bellet","pays":"France","region":"Provence","sousRegion":"Nice","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Rouge et rosé de Braquet et Folle noire, cépages niçois, légers, poivrés, floraux."}],"cepages":["Rolle","Braquet","Folle noire"],"style":"Blanc de Rolle sec et tendu, tilleul, poire, amande fraîche, finale minérale qui vieillit bien.","temp":"9 à 11 °C","garde":"3 à 8 ans","prix":3,"accords":["poisson_maigre","legumes","mediterraneen","fromage_chevre","vapeur","crustace"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Bellet blanc et petits farcis niçois","note":"Vignoble enclavé dans la commune de Nice, sur des galets et sables en terrasses à 300 mètres, à peine 60 hectares. Les cépages Braquet et Folle noire n'existent nulle part ailleurs. Vins rares, prix élevés, à chercher sur place avec la cuisine niçoise, pissaladière ou daube pour le rouge.","lat":43.73,"lon":7.22,"importance":2,"niveau":"decouverte"},{"id":"fr-coteaux-varois-en-provence","nom":"Coteaux varois en Provence","pays":"France","region":"Provence","sousRegion":"","couleur":"rose","famille":"rose","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Rouges de Syrah, Grenache et Mourvèdre, fruit noir et thym, plus tendus que sur la côte."}],"cepages":["Grenache","Cinsault","Syrah","Mourvèdre"],"style":"Rosé pâle, plus tendu et moins solaire que ses voisins, fruits rouges acidulés et fenouil.","temp":"8 à 10 °C","garde":"1 à 2 ans","prix":1,"accords":["grille","legumes","charcuterie","poisson_maigre","herbes","mediterraneen"],"eviter":["sauce_vin_rouge","chocolat"],"classique":"Coteaux varois rosé et pissaladière","note":"Au cœur du Var, autour de Brignoles, à 350 mètres d'altitude en moyenne, entre les massifs de la Sainte-Baume et des Bessillons. Les nuits fraîches donnent des rosés plus acides et plus légers que ceux du littoral, un bon rapport prix-plaisir pour un apéritif ou un pique-nique.","lat":43.41,"lon":6.06,"importance":2,"niveau":"decouverte"},{"id":"fr-palette","nom":"Palette","pays":"France","region":"Provence","sousRegion":"Aix-en-Provence","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Blanc de Clairette élevé en fût, cire, miel, noisette, qui vieillit vingt ans."}],"cepages":["Grenache","Mourvèdre","Cinsault"],"style":"Rouge profond, cerise noire, résine de pin, épices, tanins serrés par un long élevage en fût.","temp":"16 à 18 °C","garde":"10 à 25 ans","prix":4,"accords":["gibier","agneau","viande_rouge","truffe","mijote","fromage_dure"],"eviter":["huitre","poisson_cru","fruits_exotiques"],"classique":"Palette rouge et daube provençale","note":"Minuscule appellation (une cinquantaine d'hectares) au pied de la Sainte-Victoire, sur des éboulis calcaires exposés plein sud, longtemps portée par un seul domaine, Château Simone. Rouges et blancs de très longue garde, élevés en vieux foudres, à ouvrir sur une daube ou une truffe.","lat":43.49,"lon":5.5,"importance":2,"niveau":"decouverte"},{"id":"fr-pierrevert","nom":"Pierrevert","pays":"France","region":"Provence","sousRegion":"Haute-Provence","couleur":"rose","famille":"rose","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Rouges Grenache-Syrah de montagne, fruités et frais, à boire jeunes."}],"cepages":["Grenache","Syrah","Cinsault"],"style":"Rosé vif et léger, groseille, agrumes, finale fraîche marquée par l'altitude.","temp":"8 à 10 °C","garde":"1 à 2 ans","prix":1,"accords":["grille","legumes","charcuterie","volaille","herbes"],"eviter":["sauce_vin_rouge","chocolat"],"classique":"Pierrevert rosé et chèvre frais de Banon","note":"Vignoble le plus haut de Provence, à 450 mètres, autour de Manosque dans les Alpes-de-Haute-Provence. Les nuits froides donnent des rosés et des rouges plus acides et plus légers que dans le Var, proches de certains vins du Rhône sud en altitude. Vins de table simples, bon marché, à boire jeunes.","lat":43.81,"lon":5.75,"importance":1,"niveau":"decouverte"},{"id":"fr-chignin-bergeron","nom":"Chignin-Bergeron","pays":"France","region":"Savoie","sousRegion":"Combe de Savoie","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Roussanne"],"style":"Abricot, coing, miel, amande, aubépine ; ample, gras, fraîcheur en finale.","temp":"10 à 12 °C","garde":"3 à 8 ans","prix":2,"accords":["poisson_gras","crustace","volaille","creme","fromage_dure","champignon"],"eviter":["viande_rouge","acide"],"classique":"Chignin-Bergeron et omble chevalier","note":"Roussanne, appelée bergeron en Savoie, sur les coteaux abrupts de Chignin, Francin et Montmélian. Le blanc le plus riche de la région : abricot et miel, texture grasse. Il tient les poissons de lac au beurre, les volailles à la crème et les fromages affinés comme le beaufort.","lat":45.53,"lon":6.02,"importance":3,"niveau":"classique"},{"id":"fr-vin-de-savoie-apremont","nom":"Vin de Savoie Apremont","pays":"France","region":"Savoie","sousRegion":"Combe de Savoie","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Jacquère"],"style":"Fleurs blanches, pomme verte, pierre, légère perle ; sec, léger, très frais.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":1,"accords":["fromage_dure","poisson_maigre","vapeur","legumes","fromage_frais","creme"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Apremont et fondue savoyarde","note":"Cru planté sur les éboulis du mont Granier, effondré en 1248. Jacquère, cépage local peu alcoolisé, qui donne un blanc léger et perlant à boire dans l'année. Le vin de la fondue, de la raclette et de la tartiflette : sa fraîcheur allège le fromage fondu.","lat":45.51,"lon":5.96,"importance":3,"niveau":"classique"},{"id":"fr-roussette-de-savoie","nom":"Roussette de Savoie","pays":"France","region":"Savoie","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Altesse"],"style":"Bergamote, noisette, miel, fleurs ; sec, fin, acidité nette, gagne en gras avec l'âge.","temp":"9 à 11 °C","garde":"3 à 10 ans","prix":2,"accords":["poisson_maigre","poisson_gras","crustace","volaille","fromage_dure","creme"],"eviter":["viande_rouge","piquant"],"classique":"Roussette de Savoie et féra du lac","note":"Altesse seule, cépage fin que la légende fait venir de Chypre. Quatre crus : Frangy, Marestel, Monthoux, Monterminod. Plus de nerf et de longueur que la jacquère, elle gagne en miel et en gras au bout de trois ans. Blanc de poisson de lac, de volaille et de beaufort.","lat":45.73,"lon":5.78,"importance":2,"niveau":"classique"},{"id":"fr-seyssel","nom":"Seyssel","pays":"France","region":"Savoie","sousRegion":"Haute vallée du Rhône","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"bulles","famille":"bulles","note":"Seyssel mousseux : méthode traditionnelle, molette et altesse, fin et floral."}],"cepages":["Altesse","Molette"],"style":"Violette, fleurs blanches, pierre, pointe d'amande ; sec, délicat, fin.","temp":"8 à 10 °C","garde":"2 à 6 ans","prix":2,"accords":["poisson_maigre","crustace","coquillage","volaille","fromage_frais"],"eviter":["viande_rouge","epice_douce"],"classique":"Seyssel et quenelles de brochet","note":"Plus vieille appellation savoyarde (1942), à cheval sur l'Ain et la Haute-Savoie, de part et d'autre du Rhône. Altesse seule pour le blanc tranquille, molette ajoutée pour le mousseux, connu depuis le XIXe siècle. Un blanc discret et floral pour les poissons de rivière.","lat":45.96,"lon":5.84,"importance":2,"niveau":"decouverte"},{"id":"fr-abymes","nom":"Vin de Savoie Abymes","pays":"France","region":"Savoie","sousRegion":"Combe de Savoie","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Jacquère"],"style":"Citron, pomme, fleur d'aubépine, perle légère ; sec, vif, désaltérant.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":1,"accords":["fromage_dure","poisson_maigre","coquillage","vapeur","legumes"],"eviter":["viande_rouge","epice_douce"],"classique":"Abymes et raclette","note":"Voisin et jumeau d'Apremont sur le même éboulis du Granier, côté Les Marches et Chapareillan, jusqu'en Isère. Le nom vient de la catastrophe de 1248, les « abîmes ». Jacquère, blanc perlant, à boire jeune et frais, sur les plats au fromage de la montagne.","lat":45.5,"lon":5.98,"importance":2,"niveau":"classique"},{"id":"fr-mondeuse-arbin","nom":"Vin de Savoie Arbin (Mondeuse)","pays":"France","region":"Savoie","sousRegion":"Combe de Savoie","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Mondeuse"],"style":"Fruits noirs, violette, poivre, note fumée ; tanins fermes, acidité vive, alcool modéré.","temp":"14 à 16 °C","garde":"3 à 12 ans","prix":2,"accords":["charcuterie","porc","gibier","viande_rouge","mijote","fromage_dure"],"eviter":["poisson_cru","huitre"],"classique":"Mondeuse d'Arbin et diots au vin blanc","note":"Cépage rouge historique de la Savoie, cousin éloigné de la syrah. Le cru Arbin, au pied des Bauges, lui est réservé et donne la version la plus structurée : poivre, violette, tanins francs. À carafer jeune, sur une charcuterie de montagne, un civet ou un gratin de crozets.","lat":45.51,"lon":6.1,"importance":2,"niveau":"classique"},{"id":"fr-cahors","nom":"Cahors","pays":"France","region":"Sud-Ouest","sousRegion":"Lot","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Malbec","Merlot","Tannat"],"style":"Rouge sombre, presque noir, mûre, prune, violette, cacao et graphite ; tanins denses, finale longue.","temp":"16 à 18 °C","garde":"5 à 20 ans","prix":2,"accords":["canard","viande_rouge","truffe","gibier","mijote","fromage_dure"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Cahors et confit de canard aux truffes du Quercy","note":"Au moins 70 % de Malbec (ici appelé Côt ou Auxerrois) sur les terrasses du Lot et les causses calcaires. Ce « vin noir » servi aux tsars et exporté par Bordeaux dès le Moyen Âge a inspiré le Malbec argentin. Puissant et tannique, il demande un plat gras ou quelques années de cave ; à carafer jeune.","lat":44.45,"lon":1.44,"importance":4,"niveau":"incontournable"},{"id":"fr-madiran","nom":"Madiran","pays":"France","region":"Sud-Ouest","sousRegion":"Gascogne","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Tannat","Cabernet Franc","Cabernet Sauvignon"],"style":"Rouge massif, mûre, cassis, cacao, tabac et cuir ; tanins très denses, longue finale, s'arrondit avec l'âge.","temp":"16 à 18 °C","garde":"6 à 20 ans","prix":2,"accords":["canard","viande_rouge","gibier","mijote","roti","fromage_dure"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Madiran et magret de canard grillé","note":"Aux confins du Gers, des Hautes-Pyrénées et des Pyrénées-Atlantiques, le Tannat (60 à 80 %) donne le rouge le plus tannique de France : la micro-oxygénation a été inventée ici pour l'assouplir. Vin de garde, à carafer longuement ou à attendre, sur le canard, le cassoulet ou une côte de bœuf.","lat":43.55,"lon":-0.06,"importance":4,"niveau":"incontournable"},{"id":"fr-bergerac","nom":"Bergerac","pays":"France","region":"Sud-Ouest","sousRegion":"Bergeracois","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Bergerac sec, Sauvignon et Sémillon, vif et fruité, dans l'esprit d'un Bordeaux blanc."},{"couleur":"rose","famille":"rose","note":"Rosé de Merlot et Cabernet, fruits rouges, simple et frais."}],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon","Malbec"],"style":"Rouge souple et fruité, cassis, prune, note de sous-bois, tanins fondus ; les Côtes de Bergerac sont plus charpentés.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["volaille","canard","charcuterie","grille","porc","fromage_dure"],"eviter":["huitre","poisson_cru","fruits_exotiques"],"classique":"Bergerac rouge et confit de canard","note":"Prolongement de Bordeaux vers l'amont de la Dordogne, autour de Bergerac, avec les mêmes cépages mais des prix plus doux. Le rouge générique est un vin de repas quotidien, rond et prêt jeune ; l'appellation Côtes de Bergerac impose un rendement plus bas et donne des vins plus concentrés, de garde.","lat":44.85,"lon":0.48,"importance":3,"niveau":"classique"},{"id":"fr-cotes-de-gascogne","nom":"Côtes de Gascogne","pays":"France","region":"Sud-Ouest","sousRegion":"Gascogne","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de Merlot, Cabernet et Tannat, léger et fruité."},{"couleur":"doux","famille":"blanc_doux","note":"Moelleux de Gros et Petit Manseng, exotique et bon marché."}],"cepages":["Colombard","Ugni blanc","Gros Manseng","Sauvignon"],"style":"Blanc sec léger et très aromatique, pamplemousse, fruit de la passion, buis, bouche vive et désaltérante.","temp":"8 à 10 °C","garde":"1 à 2 ans","prix":1,"accords":["huitre","coquillage","poisson_maigre","fromage_chevre","asiatique","legumes"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Côtes de Gascogne blanc et huîtres du bassin d'Arcachon","note":"Pays de l'Armagnac, dans le Gers, où les cépages à eau-de-vie (Colombard, Ugni blanc) ont été réorientés dans les années 1980 vers des blancs secs frais et parfumés, vinifiés à basse température. Premier IGP blanc de France en volume : le blanc d'apéritif et de fruits de mer à petit prix.","lat":43.86,"lon":0.1,"importance":3,"niveau":"classique"},{"id":"fr-jurancon-moelleux","nom":"Jurançon moelleux","pays":"France","region":"Sud-Ouest","sousRegion":"Béarn","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Petit Manseng","Gros Manseng","Petit Courbu"],"style":"Moelleux doré, ananas rôti, mangue, abricot confit, miel et épices, sucre équilibré par une acidité vive.","temp":"8 à 10 °C","garde":"5 à 25 ans","prix":2,"accords":["foie_gras","fromage_bleu","fruits_exotiques","patisserie","volaille","epice_douce"],"eviter":["viande_rouge","vinaigre","amer"],"classique":"Jurançon moelleux et foie gras","note":"Vin du baptême d'Henri IV en 1553, produit sur les coteaux au sud de Pau. Le Petit Manseng, à petites baies épaisses, est vendangé passerillé sur pied jusqu'en décembre : il concentre le sucre sans pourriture noble, d'où une fraîcheur exotique unique parmi les liquoreux. Foie gras ou bleu.","lat":43.33,"lon":-0.58,"importance":3,"niveau":"classique"},{"id":"fr-jurancon-sec","nom":"Jurançon sec","pays":"France","region":"Sud-Ouest","sousRegion":"Béarn","couleur":"blanc","famille":"blanc_aromatique","variantes":[],"cepages":["Gros Manseng","Petit Manseng","Petit Courbu"],"style":"Blanc sec et tendu, pamplemousse, fruit de la passion, fleurs blanches, finale saline et longue.","temp":"9 à 11 °C","garde":"3 à 8 ans","prix":2,"accords":["poisson_gras","crustace","volaille","fromage_dure","asiatique","creme"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Jurançon sec et truite des Pyrénées","note":"Sur les coteaux pentus au sud de Pau, face aux Pyrénées, le Gros Manseng vendangé à maturité donne un sec aromatique à l'acidité marquée, appellation distincte depuis 1975. Il supporte la garde et le fût. À servir sur les poissons de rivière, l'ossau-iraty ou une cuisine aux agrumes.","lat":43.29,"lon":-0.4,"importance":3,"niveau":"classique"},{"id":"fr-monbazillac","nom":"Monbazillac","pays":"France","region":"Sud-Ouest","sousRegion":"Bergeracois","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Sémillon","Muscadelle","Sauvignon"],"style":"Liquoreux doré, abricot confit, miel, coing et écorce d'orange, bouche onctueuse soutenue par une acidité nette.","temp":"8 à 10 °C","garde":"5 à 25 ans","prix":2,"accords":["foie_gras","fromage_bleu","patisserie","fruits_jaunes","volaille","fruits_exotiques"],"eviter":["viande_rouge","vinaigre","amer"],"classique":"Monbazillac et foie gras du Périgord","note":"Sur la rive gauche de la Dordogne, face à Bergerac, les brumes d'automne favorisent la pourriture noble (Botrytis cinerea) qui concentre les raisins. Mêmes cépages que Sauternes, avec plus de Muscadelle, pour un liquoreux moins cher et plus accessible, l'accord de fête des foies gras du Périgord.","lat":44.79,"lon":0.49,"importance":3,"niveau":"classique"},{"id":"fr-buzet","nom":"Buzet","pays":"France","region":"Sud-Ouest","sousRegion":"Lot-et-Garonne","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de Merlot et Cabernet, frais et fruité, un quart de la production."}],"cepages":["Merlot","Cabernet Franc","Cabernet Sauvignon"],"style":"Rouge rond et charnu, mûre, cassis, vanille d'un élevage en fût, tanins souples.","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":1,"accords":["canard","viande_rouge","grille","volaille","porc","charcuterie"],"eviter":["huitre","poisson_cru","fruits_exotiques"],"classique":"Buzet rouge et cassoulet","note":"Sur la rive gauche de la Garonne, entre Agen et Marmande, l'appellation est portée depuis 1953 par la coopérative Les Vignerons de Buzet, qui vinifie plus de 90 % du vignoble, conduit sans herbicide. Rouges de style bordelais, mûrs et accessibles, pour les plats du Sud-Ouest.","lat":44.26,"lon":0.3,"importance":2,"niveau":"decouverte"},{"id":"fr-cotes-de-duras","nom":"Côtes de Duras","pays":"France","region":"Sud-Ouest","sousRegion":"Lot-et-Garonne","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Blanc sec de Sauvignon, herbacé et vif, la moitié de la production ; existe aussi en moelleux."}],"cepages":["Merlot","Cabernet Sauvignon","Cabernet Franc","Malbec"],"style":"Rouge fruité et souple, cassis, violette, tanins ronds, parfois plus boisé et structuré.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["volaille","charcuterie","grille","porc","canard","fromage_dure"],"eviter":["huitre","poisson_cru"],"classique":"Côtes de Duras rouge et poulet rôti","note":"Au sud de Bergerac, entre Dordogne et Garonne, autour de la bastide de Duras et de son château. L'une des premières AOC de France (1937), avec les cépages bordelais sur des coteaux calcaires. Rouges de tous les jours et blancs de Sauvignon francs, bon marché, à boire dans les trois ans.","lat":44.68,"lon":0.18,"importance":2,"niveau":"decouverte"},{"id":"fr-floc-de-gascogne","nom":"Floc de Gascogne","pays":"France","region":"Sud-Ouest","sousRegion":"Gascogne","couleur":"doux","famille":"vdn","variantes":[{"couleur":"rose","famille":"vdn","note":"Floc rosé : moût de Merlot, Cabernet et Tannat muté à l'Armagnac, fruits rouges, sucre et chaleur."}],"cepages":["Colombard","Ugni blanc","Gros Manseng"],"style":"Mistelle dorée, raisin frais, poire, miel et pointe d'eau-de-vie, douce et franche, 16 à 18 % d'alcool.","temp":"6 à 8 °C","garde":"1 à 3 ans","prix":2,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","glace"],"eviter":["viande_rouge","poisson_cru","amer"],"classique":"Floc de Gascogne et foie gras mi-cuit","note":"Apéritif gascon obtenu en mutant du moût de raisin frais avec de l'Armagnac jeune (un tiers environ), sur le modèle du Pineau des Charentes, AOC depuis 1990. Le producteur doit faire lui-même le vin et l'eau-de-vie. Servi très frais, pur ou avec un glaçon, à l'apéritif, sur le foie gras ou un melon.","lat":43.96,"lon":0.37,"importance":2,"niveau":"decouverte"},{"id":"fr-fronton","nom":"Fronton","pays":"France","region":"Sud-Ouest","sousRegion":"Haute-Garonne","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de Négrette, floral et poivré, très bu à Toulouse."}],"cepages":["Négrette","Syrah","Cabernet Franc"],"style":"Rouge parfumé et souple, violette, cassis, poivre et réglisse, tanins fins, bouche fraîche.","temp":"14 à 16 °C","garde":"2 à 6 ans","prix":1,"accords":["charcuterie","grille","volaille","porc","mijote","fromage_dure"],"eviter":["huitre","poisson_cru","chocolat"],"classique":"Fronton et saucisse de Toulouse grillée","note":"Entre Toulouse et Montauban, sur des terrasses de graves pauvres, l'appellation repose sur la Négrette, cépage que l'on ne trouve presque qu'ici (50 % minimum). Son parfum de violette est sa signature : le « vin des Toulousains », à boire jeune et frais sur la cuisine de bistrot.","lat":43.84,"lon":1.39,"importance":2,"niveau":"classique"},{"id":"fr-gaillac","nom":"Gaillac","pays":"France","region":"Sud-Ouest","sousRegion":"Tarn","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Gaillac perlé : blanc sec de Mauzac et Loin de l'œil, légèrement perlant, pomme verte, à l'apéritif."},{"couleur":"doux","famille":"blanc_doux","note":"Doux et vendanges tardives de Mauzac ou Loin de l'œil, coing et miel ; existe aussi en méthode ancestrale."}],"cepages":["Duras","Braucol","Syrah","Mauzac"],"style":"Rouge épicé et fruité, poivre, framboise, cassis, note de sous-bois du Braucol, tanins souples.","temp":"15 à 17 °C","garde":"2 à 7 ans","prix":1,"accords":["charcuterie","grille","volaille","porc","canard","champignon"],"eviter":["huitre","poisson_cru","fruits_exotiques"],"classique":"Gaillac rouge et cassoulet","note":"L'un des plus vieux vignobles de France, planté par les Romains le long du Tarn, en amont d'Albi. Sa richesse tient à ses cépages locaux : Duras et Braucol pour les rouges, Mauzac et Loin de l'œil pour les blancs, du sec perlé jusqu'au doux et à la bulle ancestrale. Tous les styles, à petits prix.","lat":43.9,"lon":1.9,"importance":2,"niveau":"classique"},{"id":"fr-irouleguy","nom":"Irouléguy","pays":"France","region":"Sud-Ouest","sousRegion":"Pays basque","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de Tannat et Cabernet, vineux et fruité, servi sur la cuisine basque."},{"couleur":"blanc","famille":"blanc_vif","note":"Blanc de Gros et Petit Manseng et Petit Courbu, tendu, salin, rare."}],"cepages":["Tannat","Cabernet Franc","Cabernet Sauvignon"],"style":"Rouge charpenté, cassis, mûre, poivre et note de fumée, tanins serrés mais fraîcheur montagnarde.","temp":"16 à 18 °C","garde":"4 à 12 ans","prix":2,"accords":["agneau","charcuterie","viande_rouge","mijote","fromage_dure","piquant"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Irouléguy rouge et axoa de veau au piment d'Espelette","note":"Seule appellation du Pays basque français, en terrasses sur les pentes de grès rouge autour de Saint-Étienne-de-Baïgorry et Saint-Jean-Pied-de-Port, 250 hectares sauvés par la coopérative dans les années 1950. Rouges de Tannat plus frais qu'à Madiran, sur l'axoa, la piperade ou l'ossau-iraty.","lat":43.18,"lon":-1.28,"importance":2,"niveau":"classique"},{"id":"fr-pacherenc-du-vic-bilh","nom":"Pacherenc du Vic-Bilh","pays":"France","region":"Sud-Ouest","sousRegion":"Gascogne","couleur":"doux","famille":"blanc_doux","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Pacherenc sec : Petit Courbu et Gros Manseng, pamplemousse, fleurs blanches, gras et tendu."}],"cepages":["Petit Manseng","Gros Manseng","Petit Courbu","Arrufiac"],"style":"Moelleux doré, ananas, abricot, coing et miel, sucre porté par une acidité vive, finale longue.","temp":"8 à 10 °C","garde":"4 à 15 ans","prix":2,"accords":["foie_gras","fromage_bleu","fruits_exotiques","patisserie","volaille","fruits_jaunes"],"eviter":["viande_rouge","vinaigre","amer"],"classique":"Pacherenc moelleux et foie gras poêlé","note":"Blanc de l'aire de Madiran, dont le nom gascon signifie « piquets en rang du vieux pays ». Les Mansengs sont vendangés passerillés sur pied, souvent en novembre, sans pourriture noble. Le moelleux domine, servi sur le foie gras ; le sec, plus rare, accompagne poissons en sauce et volailles.","lat":43.57,"lon":-0.05,"importance":2,"niveau":"decouverte"},{"id":"fr-pecharmant","nom":"Pécharmant","pays":"France","region":"Sud-Ouest","sousRegion":"Bergeracois","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Merlot","Cabernet Sauvignon","Cabernet Franc","Malbec"],"style":"Rouge charpenté, fruits noirs, cuir, sous-bois et épices, tanins fermes qui demandent du temps.","temp":"16 à 18 °C","garde":"5 à 12 ans","prix":2,"accords":["canard","viande_rouge","gibier","mijote","roti","fromage_dure"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Pécharmant et magret de canard aux cèpes","note":"Coteaux exposés sud au nord-est de Bergerac, sur des sables et graviers reposant sur une couche ferrugineuse appelée « tran », qui donne au vin sa structure. Le seul rouge du Bergeracois exclusivement de garde : à attendre cinq ans, puis à ouvrir sur un magret, un civet ou un cèpe poêlé.","lat":44.87,"lon":0.52,"importance":2,"niveau":"classique"},{"id":"fr-saint-mont","nom":"Saint-Mont","pays":"France","region":"Sud-Ouest","sousRegion":"Gascogne","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Blanc sec de Gros Manseng, Arrufiac et Petit Courbu, agrumes et fleurs, gras et vif."},{"couleur":"rose","famille":"rose","note":"Rosé de Tannat et Cabernet, framboise, franc."}],"cepages":["Tannat","Pinenc","Cabernet Sauvignon","Cabernet Franc"],"style":"Rouge structuré, mûre, cassis, poivre et épices du Pinenc, tanins fermes mais plus souples qu'à Madiran.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":1,"accords":["canard","viande_rouge","grille","mijote","charcuterie","fromage_dure"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Saint-Mont rouge et poule au pot","note":"Sur les coteaux du Gers autour du village de Saint-Mont, voisin de Madiran, AOC depuis 2011 après trente ans de VDQS. Vignoble porté par la cave Plaimont, qui a sauvé les cépages locaux : Tannat, Pinenc (Fer Servadou), Arrufiac. Rouges de garde moyenne, blancs secs parfumés, à petit prix.","lat":43.65,"lon":-0.04,"importance":2,"niveau":"decouverte"},{"id":"fr-bearn","nom":"Béarn","pays":"France","region":"Sud-Ouest","sousRegion":"Béarn","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de Bellocq, Tannat et Cabernet, saumoné et vineux, historiquement le plus connu de l'appellation."}],"cepages":["Tannat","Cabernet Franc","Cabernet Sauvignon"],"style":"Rouge rustique et fruité, cerise noire, poivre, tanins fermes mais moins massifs qu'à Madiran.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["charcuterie","grille","porc","mijote","volaille","fromage_dure"],"eviter":["huitre","poisson_cru"],"classique":"Béarn rouge et garbure","note":"Appellation en trois îlots : Bellocq près de Salies-de-Béarn (le cœur historique), et les aires de Jurançon et Madiran, qui y revendiquent leurs rouges et rosés. Cépages pyrénéens, Tannat et Cabernets, pour des vins simples de tous les jours, le rosé de Bellocq étant le plus réputé. Prix très doux.","lat":43.48,"lon":-0.93,"importance":1,"niveau":"decouverte"},{"id":"fr-cotes-du-marmandais","nom":"Côtes du Marmandais","pays":"France","region":"Sud-Ouest","sousRegion":"Lot-et-Garonne","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Blanc sec de Sauvignon et Sémillon, marginal en volume."}],"cepages":["Merlot","Cabernet Franc","Abouriou","Syrah"],"style":"Rouge souple et gourmand, fruits rouges, poivre, touche rustique de l'Abouriou, tanins légers.","temp":"15 à 17 °C","garde":"2 à 5 ans","prix":1,"accords":["charcuterie","grille","volaille","porc","mijote","fromage_dure"],"eviter":["huitre","poisson_cru","fruits_exotiques"],"classique":"Côtes du Marmandais et saucisse grillée aux haricots","note":"De part et d'autre de la Garonne autour de Marmande, entre Bordeaux et Agen. Le cahier des charges impose des cépages locaux (Abouriou, Fer Servadou, Syrah, Gamay) à côté du Merlot et des Cabernets, d'où des rouges plus épicés qu'un Bordeaux. Production largement coopérative, bon marché.","lat":44.5,"lon":0.17,"importance":1,"niveau":"decouverte"},{"id":"fr-marcillac","nom":"Marcillac","pays":"France","region":"Sud-Ouest","sousRegion":"Aveyron","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Fer Servadou"],"style":"Rouge vif et rustique, framboise, poivre, cassis et note de sang, tanins fermes, acidité franche.","temp":"14 à 16 °C","garde":"2 à 6 ans","prix":1,"accords":["charcuterie","abats","mijote","porc","fromage_dure","volaille"],"eviter":["huitre","poisson_cru","cremeux"],"classique":"Marcillac et tripous de l'Aveyron","note":"Vallon aux sols rouges de grès ferrugineux, le « rougier », à l'ouest de Rodez. Le Fer Servadou, appelé Mansois ici, fait au moins 90 % de l'assemblage : un rouge campagnard, poivré et acidulé, qui se boit frais sur les tripous, l'aligot-saucisse ou un morceau de laguiole. Prix très doux.","lat":44.47,"lon":2.46,"importance":1,"niveau":"decouverte"},{"id":"fr-montravel","nom":"Montravel","pays":"France","region":"Sud-Ouest","sousRegion":"Bergeracois","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Montravel rouge, Merlot dominant, élevé en fût, dense et moderne (AOC depuis 2001)."},{"couleur":"doux","famille":"blanc_doux","note":"Côtes de Montravel et Haut-Montravel : moelleux et liquoreux de Sémillon."}],"cepages":["Sauvignon","Sémillon","Muscadelle"],"style":"Blanc sec vif et aromatique, buis, pamplemousse, pêche blanche, parfois élevé sur lies pour plus de gras.","temp":"9 à 11 °C","garde":"2 à 5 ans","prix":1,"accords":["poisson_maigre","fromage_chevre","coquillage","asperge","legumes","volaille"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Montravel sec et friture de la Dordogne","note":"À l'extrême ouest du Bergeracois, aux portes de Saint-Émilion, autour de Vélines et Montcaret, au pays de Montaigne. Le blanc sec, sur Sauvignon et Sémillon, est le visage principal ; les mentions Côtes de Montravel et Haut-Montravel désignent les moelleux et liquoreux de la même aire.","lat":44.86,"lon":0.1,"importance":1,"niveau":"decouverte"},{"id":"fr-rosette","nom":"Rosette","pays":"France","region":"Sud-Ouest","sousRegion":"Bergeracois","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Sémillon","Muscadelle","Sauvignon"],"style":"Blanc demi-sec à moelleux léger, pêche, acacia, miel discret, bouche tendre et fraîche, peu sucrée.","temp":"8 à 10 °C","garde":"2 à 6 ans","prix":1,"accords":["foie_gras","volaille","fromage_frais","fruits_jaunes","creme","asiatique"],"eviter":["viande_rouge","vinaigre","amer"],"classique":"Rosette et volaille à la crème et aux cèpes","note":"Minuscule appellation (une trentaine d'hectares) sur les coteaux au nord de Bergerac, presque oubliée avant d'être relancée par quelques vignerons. Avec 25 à 51 grammes de sucre, c'est un moelleux léger, loin des liquoreux de Monbazillac : un vin d'apéritif ou de volaille à la crème, à boire jeune.","lat":44.88,"lon":0.5,"importance":1,"niveau":"decouverte"},{"id":"fr-saussignac","nom":"Saussignac","pays":"France","region":"Sud-Ouest","sousRegion":"Bergeracois","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Sémillon","Muscadelle","Sauvignon"],"style":"Liquoreux dense et frais, mangue, pêche rôtie, miel d'acacia, finale longue et pure.","temp":"8 à 10 °C","garde":"5 à 20 ans","prix":2,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","fruits_exotiques"],"eviter":["viande_rouge","vinaigre","amer"],"classique":"Saussignac et roquefort","note":"Petite appellation voisine de Monbazillac, à l'ouest, sur des coteaux argilo-calcaires plus élevés. Vendanges par tries successives obligatoires et chaptalisation interdite : des liquoreux souvent plus concentrés que la moyenne des Monbazillac, produits par une poignée de domaines, beaucoup en bio.","lat":44.8,"lon":0.32,"importance":1,"niveau":"decouverte"},{"id":"fr-tursan","nom":"Tursan","pays":"France","region":"Sud-Ouest","sousRegion":"Landes","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Blanc de Baroque, cépage propre au Tursan, sec, pomme verte et fleurs, à boire jeune."}],"cepages":["Tannat","Cabernet Franc","Cabernet Sauvignon"],"style":"Rouge souple et épicé, fruits noirs, poivre, tanins ronds, bouche de taille moyenne.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["canard","charcuterie","grille","volaille","porc","mijote"],"eviter":["huitre","poisson_cru"],"classique":"Tursan rouge et magret de canard des Landes","note":"Petit vignoble des Landes autour de Geaune et Aire-sur-l'Adour, AOC depuis 2011, sur des coteaux sableux et argileux. Il abrite le Baroque, cépage blanc que l'on ne trouve nulle part ailleurs, et des rouges de Tannat adoucis par les Cabernets. Vins de table de la cuisine landaise : canard, garbure.","lat":43.63,"lon":-0.38,"importance":1,"niveau":"decouverte"},{"id":"fr-sancerre","nom":"Sancerre","pays":"France","region":"Vallée de la Loire","sousRegion":"Centre-Loire","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Sancerre rouge : pinot noir léger, cerise et épices, à servir frais."},{"couleur":"rose","famille":"rose","note":"Sancerre rosé : pinot noir pâle, groseille, très sec."}],"cepages":["Sauvignon blanc","Pinot noir"],"style":"Sauvignon sur calcaire et silex : agrumes, buis, pierre à fusil, fumé ; tension et longueur.","temp":"9 à 11 °C","garde":"2 à 8 ans","prix":3,"accords":["fromage_chevre","poisson_maigre","coquillage","huitre","asperge","herbes"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Sancerre et crottin de Chavignol","note":"Colline au-dessus de la Loire, à l'est du Berry, où trois sols signent le sauvignon : terres blanches (marnes) pour l'ampleur, caillottes (calcaire) pour le fruit, silex pour la fumée. Le pinot noir, cépage historique, donne rouges et rosés. Référence mondiale du sauvignon, parfait sur le chèvre.","lat":47.33,"lon":2.84,"importance":5,"niveau":"incontournable"},{"id":"fr-chinon","nom":"Chinon","pays":"France","region":"Vallée de la Loire","sousRegion":"Touraine","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Chinon blanc : chenin sec, rare, tendu et floral."},{"couleur":"rose","famille":"rose","note":"Rosé sec de cabernet franc, fruits rouges, frais."}],"cepages":["Cabernet franc","Cabernet sauvignon"],"style":"Fruité et frais : framboise, poivron grillé, graphite ; tanins fins, plus charnus sur les coteaux.","temp":"14 à 16 °C","garde":"3 à 12 ans","prix":2,"accords":["charcuterie","volaille","porc","grille","roti","fromage_chevre"],"eviter":["huitre","chocolat","piquant"],"classique":"Chinon et rillettes de Tours","note":"Pays de Rabelais, au confluent de la Vienne et de la Loire. Les sols changent le vin : graviers en bord de rivière pour des rouges légers à boire frais, tuffeau des coteaux pour des cuvées plus denses qui vieillissent dix ans. Un blanc de chenin confidentiel complète l'appellation.","lat":47.17,"lon":0.24,"importance":4,"niveau":"incontournable"},{"id":"fr-muscadet-sevre-et-maine","nom":"Muscadet Sèvre-et-Maine","pays":"France","region":"Vallée de la Loire","sousRegion":"Pays nantais","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Melon de Bourgogne"],"style":"Sec, léger et salin : citron, pomme verte, iode ; les cuvées sur lie gardent un léger perlant.","temp":"8 à 10 °C","garde":"1 à 3 ans (crus communaux 5 à 10 ans)","prix":1,"accords":["huitre","coquillage","crustace","poisson_maigre","beurre_citron","fromage_chevre"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Muscadet sur lie et huîtres de Vendée","note":"Le melon de Bourgogne pousse sur gneiss et granites entre Sèvre et Maine, au sud de Nantes. L'élevage sur lie garde le vin au contact des levures tout l'hiver, d'où sa fraîcheur et son léger perlant. Vin d'huîtres par excellence, à boire jeune ; les crus communaux (Clisson, Gorges) vieillissent.","lat":47.16,"lon":-1.27,"importance":4,"niveau":"incontournable"},{"id":"fr-pouilly-fume","nom":"Pouilly-Fumé","pays":"France","region":"Vallée de la Loire","sousRegion":"Centre-Loire","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Sauvignon blanc"],"style":"Sauvignon fumé : pierre à fusil, pamplemousse, cassis végétal, bouche ronde et tendue.","temp":"9 à 11 °C","garde":"2 à 8 ans","prix":3,"accords":["poisson_maigre","crustace","fromage_chevre","huitre","asperge","fume"],"eviter":["viande_rouge","chocolat"],"classique":"Pouilly-Fumé et saumon fumé","note":"Rive droite de la Loire, face à Sancerre, autour de Pouilly-sur-Loire. Le nom vient du « blanc fumé », surnom local du sauvignon, et des silex qui donnent l'odeur de pierre à fusil. Vins un peu plus ronds que les Sancerre, sans rouge ni rosé. Servir sur poissons fumés et fruits de mer.","lat":47.28,"lon":2.95,"importance":4,"niveau":"incontournable"},{"id":"fr-saumur-champigny","nom":"Saumur-Champigny","pays":"France","region":"Vallée de la Loire","sousRegion":"Saumurois","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Cabernet franc","Cabernet sauvignon"],"style":"Cabernet franc sur tuffeau : framboise, violette, poivre, tanins fins et frais, buvable jeune.","temp":"14 à 16 °C","garde":"3 à 10 ans","prix":2,"accords":["charcuterie","volaille","agneau","grille","fromage_chevre","champignon"],"eviter":["huitre","chocolat","piquant"],"classique":"Saumur-Champigny et fouées aux rillettes","note":"Neuf communes au sud-est de Saumur, sur le plateau de tuffeau, pour un rouge de cabernet franc. Le sous-sol crayeux garde la fraîcheur et donne un fruit croquant, ce qui en a fait le rouge de bistrot parisien dans les années 1980. Servir frais, jeune ; les cuvées de garde tiennent dix ans.","lat":47.23,"lon":-0.06,"importance":4,"niveau":"incontournable"},{"id":"fr-vouvray","nom":"Vouvray","pays":"France","region":"Vallée de la Loire","sousRegion":"Touraine","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Demi-sec et moelleux : coing, miel, abricot ; les grandes années, liquoreux de garde."},{"couleur":"bulles","famille":"bulles","note":"Vouvray brut et pétillant : fines bulles de chenin, pomme et brioche."}],"cepages":["Chenin blanc"],"style":"Sec tendu : coing, pomme verte, tilleul, craie ; demi-sec et moelleux plus ronds, bulles fines.","temp":"9 à 11 °C","garde":"5 à 30 ans","prix":2,"accords":["poisson_maigre","volaille","creme","fromage_chevre","asperge","fruits_jaunes"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Vouvray et Sainte-Maure de Touraine","note":"Rive nord de la Loire à l'est de Tours : vignes sur le plateau de tuffeau, caves creusées dans la falaise. Le chenin y décline tous les styles selon le millésime, du sec au liquoreux en passant par les bulles. Vins de longue garde ; un sec sur les poissons de rivière, un demi-sec sur le chèvre.","lat":47.41,"lon":0.8,"importance":4,"niveau":"incontournable"},{"id":"fr-anjou-blanc","nom":"Anjou blanc","pays":"France","region":"Vallée de la Loire","sousRegion":"Anjou","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chenin blanc","Chardonnay","Sauvignon blanc"],"style":"Sec, chenin sur schistes : coing, pomme mûre, miel léger, acidité droite, souvent élevé en fût.","temp":"10 à 12 °C","garde":"3 à 10 ans","prix":2,"accords":["poisson_maigre","volaille","creme","fromage_chevre","legumes","champignon"],"eviter":["viande_rouge","piquant"],"classique":"Anjou blanc et sandre au beurre blanc","note":"Chenin à 80 % minimum (chardonnay et sauvignon tolérés), sur les schistes sombres du Massif armoricain, près d'Angers. Longtemps terre de moelleux, l'Anjou produit depuis les années 2000 des secs profonds, souvent élevés en fût. Se sert sur poissons en sauce et volailles à la crème.","lat":47.47,"lon":-0.55,"importance":3,"niveau":"classique"},{"id":"fr-bourgueil","nom":"Bourgueil","pays":"France","region":"Vallée de la Loire","sousRegion":"Touraine","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé sec de cabernet franc, framboise, à boire dans l'année."}],"cepages":["Cabernet franc","Cabernet sauvignon"],"style":"Framboise, cassis, note de poivron et de violette ; tanins fins sur graviers, plus fermes sur tuffeau.","temp":"14 à 16 °C","garde":"3 à 10 ans","prix":2,"accords":["charcuterie","volaille","porc","grille","fromage_chevre","champignon"],"eviter":["huitre","chocolat"],"classique":"Bourgueil et rillons de Touraine","note":"Rive nord de la Loire, à l'ouest de Tours, sur une terrasse de graviers et de sables adossée à un coteau de tuffeau. Le cabernet franc, appelé breton, y donne un rouge plus tannique et plus ferme que Chinon, qui mérite deux ou trois ans. Servir légèrement frais sur la charcuterie tourangelle.","lat":47.28,"lon":0.17,"importance":3,"niveau":"classique"},{"id":"fr-cabernet-d-anjou","nom":"Cabernet d'Anjou","pays":"France","region":"Vallée de la Loire","sousRegion":"Anjou","couleur":"rose","famille":"rose","variantes":[],"cepages":["Cabernet franc","Cabernet sauvignon"],"style":"Rosé demi-sec, saumon pâle : fraise, bonbon anglais, douceur nette et finale fraîche.","temp":"6 à 8 °C","garde":"1 à 3 ans (les meilleurs 10 ans et plus)","prix":1,"accords":["sucre_sale","asiatique","epice_douce","fruits_rouges","charcuterie","fromage_frais"],"eviter":["huitre","viande_rouge","acide"],"classique":"Cabernet d'Anjou et melon au jambon cru","note":"Rosé tendre à base des deux cabernets, 10 g de sucre résiduel au minimum, premier rosé demi-sec de France. Sa douceur l'a longtemps déconsidéré, mais les vieilles cuvées (années 1950, 1960) prouvent qu'il vieillit. Servir très frais sur des plats sucrés-salés ou une cuisine asiatique.","lat":47.23,"lon":-0.42,"importance":3,"niveau":"classique"},{"id":"fr-coteaux-du-layon","nom":"Coteaux du Layon","pays":"France","region":"Vallée de la Loire","sousRegion":"Anjou","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Chenin blanc"],"style":"Moelleux doré : abricot, coing, miel, fleur d'acacia, botrytis ; acidité qui garde le vin léger.","temp":"8 à 10 °C","garde":"5 à 30 ans","prix":2,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","epice_douce","sucre_sale"],"eviter":["viande_rouge","chocolat","vinaigre"],"classique":"Coteaux du Layon et foie gras poêlé aux pommes","note":"Vallée du Layon, affluent sud de la Loire, où les brumes d'automne favorisent la pourriture noble sur le chenin. Vendangé par tries, le vin peut porter le nom de sa commune (Rochefort, Beaulieu, etc.) ; Chaume en est le premier cru depuis 2011. Moins lourd qu'un sauternes, il se boit sur un bleu.","lat":47.31,"lon":-0.59,"importance":3,"niveau":"classique"},{"id":"fr-coulee-de-serrant","nom":"Coulée de Serrant","pays":"France","region":"Vallée de la Loire","sousRegion":"Anjou","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chenin blanc"],"style":"Sec oxydatif et profond : coing confit, noix, miel sec, cire ; grande longueur, à carafer.","temp":"12 à 14 °C","garde":"10 à 30 ans","prix":4,"accords":["volaille","poisson_maigre","creme","truffe","champignon","fromage_dure"],"eviter":["piquant","chocolat"],"classique":"Coulée de Serrant et poularde à la crème aux morilles","note":"Monopole de sept hectares planté par des moines cisterciens en 1130, sur un éperon de schistes au-dessus de la Loire, à Savennières. Conduit en biodynamie depuis les années 1980 par la famille Joly. Style ample et oxydatif, à ouvrir longtemps à l'avance ; un vin de table plus que d'apéritif.","lat":47.39,"lon":-0.64,"importance":3,"niveau":"classique"},{"id":"fr-cremant-de-loire","nom":"Crémant de Loire","pays":"France","region":"Vallée de la Loire","sousRegion":"Saumurois","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"rose","famille":"bulles","note":"Crémant rosé de cabernet franc, fruits rouges, pour l'apéritif."}],"cepages":["Chenin blanc","Chardonnay","Cabernet franc","Pinot noir"],"style":"Méthode traditionnelle, bulle fine : pomme, brioche légère, agrumes, fraîcheur de chenin.","temp":"6 à 8 °C","garde":"1 à 4 ans","prix":2,"accords":["huitre","crustace","poisson_cru","volaille","fromage_chevre","patisserie"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Crémant de Loire et rillettes de Tours à l'apéritif","note":"Appellation créée en 1975 pour les effervescents d'Anjou, de Saumur et de Touraine élaborés par seconde fermentation en bouteille, douze mois minimum sur lattes. Les caves de tuffeau de Saumur en sont le centre ; le chenin domine, avec chardonnay et cabernet franc. Alternative au champagne.","lat":47.27,"lon":-0.11,"importance":3,"niveau":"classique"},{"id":"fr-montlouis-sur-loire","nom":"Montlouis-sur-Loire","pays":"France","region":"Vallée de la Loire","sousRegion":"Touraine","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Demi-sec et moelleux de chenin, les années de botrytis."},{"couleur":"bulles","famille":"bulles","note":"Pétillant naturel (pét-nat) et méthode traditionnelle, bulles de chenin."}],"cepages":["Chenin blanc"],"style":"Sec vif et salin : pomme, poire, agrumes, craie ; pétillants naturels et moelleux selon l'année.","temp":"9 à 11 °C","garde":"4 à 20 ans","prix":2,"accords":["poisson_maigre","coquillage","volaille","fromage_chevre","asperge","creme"],"eviter":["viande_rouge","chocolat"],"classique":"Montlouis sec et sandre de Loire au beurre blanc","note":"Face à Vouvray, sur la rive sud de la Loire, entre Loire et Cher. Sols plus sableux et siliceux, vins souvent plus vifs et plus secs que leurs voisins. Berceau du pétillant naturel (pét-nat) moderne dans les années 2000. Chenin à boire jeune pour les secs, à attendre pour les moelleux.","lat":47.39,"lon":0.83,"importance":3,"niveau":"classique"},{"id":"fr-quarts-de-chaume","nom":"Quarts de Chaume","pays":"France","region":"Vallée de la Loire","sousRegion":"Anjou","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Chenin blanc"],"style":"Liquoreux concentré : abricot sec, coing, orange confite, safran, finale longue et fraîche.","temp":"8 à 10 °C","garde":"10 à 50 ans","prix":4,"accords":["foie_gras","fromage_bleu","fruits_jaunes","fruits_exotiques","patisserie","epice_douce"],"eviter":["viande_rouge","chocolat","vinaigre"],"classique":"Quarts de Chaume et roquefort","note":"Seul grand cru de la Loire (depuis 2011), 40 hectares de schistes sur la commune de Rochefort-sur-Loire. Le nom vient d'un droit seigneurial médiéval : le seigneur gardait le quart de la récolte, celui des meilleures pentes. Rendement limité à 20 hl/ha, vin très concentré, à garder des décennies.","lat":47.34,"lon":-0.63,"importance":3,"niveau":"classique"},{"id":"fr-saint-nicolas-de-bourgueil","nom":"Saint-Nicolas-de-Bourgueil","pays":"France","region":"Vallée de la Loire","sousRegion":"Touraine","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Cabernet franc","Cabernet sauvignon"],"style":"Léger, gouleyant : fraise, framboise, pointe végétale, tanins doux ; vin de soif.","temp":"13 à 15 °C","garde":"2 à 6 ans","prix":2,"accords":["charcuterie","volaille","porc","grille","fromage_chevre","legumes"],"eviter":["gibier","chocolat"],"classique":"Saint-Nicolas-de-Bourgueil et andouillette grillée","note":"Commune voisine de Bourgueil, séparée en appellation propre dès 1937. Ses sols plus sableux et graveleux, sur les terrasses de la Loire, donnent un cabernet franc plus souple et plus léger que le Bourgueil, à boire jeune et frais. Rouge de charcuterie et de bistrot par excellence.","lat":47.28,"lon":0.13,"importance":3,"niveau":"classique"},{"id":"fr-saumur","nom":"Saumur","pays":"France","region":"Vallée de la Loire","sousRegion":"Saumurois","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Saumur rouge : cabernet franc frais et léger, moins dense que le Champigny."},{"couleur":"bulles","famille":"bulles","note":"Saumur brut : bulles fines de chenin, méthode traditionnelle, caves de tuffeau."}],"cepages":["Chenin blanc","Cabernet franc","Chardonnay"],"style":"Blanc sec et droit : pomme, agrumes, craie ; les rouges sont frais et légers, les bulles fines.","temp":"9 à 11 °C","garde":"2 à 8 ans","prix":2,"accords":["poisson_maigre","coquillage","fromage_chevre","volaille","legumes","asperge"],"eviter":["viande_rouge","chocolat"],"classique":"Saumur blanc et fromage de chèvre frais","note":"Autour de Saumur, le chenin pousse sur le tuffeau, calcaire crayeux qui donne des blancs secs et minéraux, cousins des Vouvray. Les caves creusées dans la roche abritent aussi la plus ancienne production de bulles de la Loire (Ackerman, 1811). Rouge et rosé complètent la gamme.","lat":47.26,"lon":-0.08,"importance":3,"niveau":"classique"},{"id":"fr-savennieres","nom":"Savennières","pays":"France","region":"Vallée de la Loire","sousRegion":"Anjou","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chenin blanc"],"style":"Sec, puissant et tendu : coing, cire, tilleul, pierre à fusil, amertume noble en finale.","temp":"11 à 13 °C","garde":"5 à 20 ans","prix":3,"accords":["poisson_maigre","volaille","creme","champignon","fromage_dure","truffe"],"eviter":["piquant","chocolat","sucre_sale"],"classique":"Savennières et brochet au beurre blanc","note":"Sur la rive nord de la Loire, face au Layon, trois coteaux de schistes volcaniques exposés plein sud. Le chenin y donne un sec dense, austère dans sa jeunesse, qui s'ouvre après cinq ans sur le coing et la cire. Deux crus en son sein : Roche-aux-Moines et Coulée de Serrant. Servir peu frais, carafé.","lat":47.38,"lon":-0.66,"importance":3,"niveau":"classique"},{"id":"fr-touraine","nom":"Touraine","pays":"France","region":"Vallée de la Loire","sousRegion":"Touraine","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Touraine gamay : rouge léger de soif, à servir frais ; le côt donne plus de densité."},{"couleur":"rose","famille":"rose","note":"Rosé sec d'assemblage, simple et fruité."}],"cepages":["Sauvignon blanc","Gamay","Cabernet franc","Côt"],"style":"Sauvignon frais et direct : agrumes, buis, bourgeon de cassis, finale vive ; gamays croquants.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":1,"accords":["fromage_chevre","poisson_maigre","coquillage","asperge","legumes","herbes"],"eviter":["viande_rouge","chocolat"],"classique":"Touraine sauvignon et Sainte-Maure de Touraine","note":"Appellation régionale autour de Tours, vallées du Cher et de l'Indre. Le sauvignon y donne un blanc simple et vif, le gamay un rouge de soif, le côt des rouges plus denses. Des dénominations communales (Chenonceaux, Oisly, Amboise, Mesland, Azay-le-Rideau) distinguent les meilleurs secteurs.","lat":47.34,"lon":1.18,"importance":3,"niveau":"classique"},{"id":"fr-anjou-rouge","nom":"Anjou rouge","pays":"France","region":"Vallée de la Loire","sousRegion":"Anjou","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Cabernet franc","Cabernet sauvignon"],"style":"Fruité : framboise, poivron doux, tanins fins et frais, corps léger à moyen.","temp":"15 à 17 °C","garde":"2 à 5 ans","prix":1,"accords":["charcuterie","volaille","porc","grille","fromage_chevre","legumes"],"eviter":["gibier","fromage_bleu"],"classique":"Anjou rouge et rillauds d'Anjou","note":"Rouge de cabernet franc, parfois complété de cabernet sauvignon, sur les schistes et grès de l'Anjou noir, au sud-ouest d'Angers. Plus simple que l'Anjou-Villages, c'est le rouge de bistrot de la région : fruit croquant, tanins légers, à servir un peu frais sur la charcuterie et les plats du jour.","lat":47.36,"lon":-0.66,"importance":2,"niveau":"classique"},{"id":"fr-anjou-villages","nom":"Anjou-Villages","pays":"France","region":"Vallée de la Loire","sousRegion":"Anjou","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Cabernet franc","Cabernet sauvignon"],"style":"Plus dense que l'Anjou : cassis, mûre, graphite, tanins mûrs et serrés, finale fraîche.","temp":"16 à 18 °C","garde":"4 à 10 ans","prix":2,"accords":["viande_rouge","agneau","roti","mijote","fromage_dure","canard"],"eviter":["poisson_maigre","huitre"],"classique":"Anjou-Villages et magret de canard rôti","note":"Créée en 1991 pour les meilleures parcelles de rouge d'Anjou, réservée aux deux cabernets, avec une mention Brissac pour les coteaux de l'Aubance. Les sols de schistes et de grès donnent un rouge plus charpenté que l'Anjou simple, qui gagne à trois ou quatre ans de bouteille. Vin de viandes rôties.","lat":47.36,"lon":-0.44,"importance":2,"niveau":"classique"},{"id":"fr-bonnezeaux","nom":"Bonnezeaux","pays":"France","region":"Vallée de la Loire","sousRegion":"Anjou","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Chenin blanc"],"style":"Liquoreux : coing, miel, pêche confite, parfois rhubarbe, acidité vive qui porte la douceur.","temp":"8 à 10 °C","garde":"10 à 40 ans","prix":3,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","fruits_exotiques"],"eviter":["viande_rouge","chocolat","vinaigre"],"classique":"Bonnezeaux et tarte Tatin","note":"Trois coteaux de schistes et de phtanites, très pentus, sur la commune de Thouarcé, dans le Layon. L'appellation, créée en 1951, ne produit que du liquoreux de chenin botrytisé ou passerillé. Moins célèbre que Quarts de Chaume, il offre une douceur comparable à un prix plus accessible.","lat":47.27,"lon":-0.5,"importance":2,"niveau":"classique"},{"id":"fr-cheverny","nom":"Cheverny","pays":"France","region":"Vallée de la Loire","sousRegion":"Touraine","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Assemblage pinot noir et gamay, rouge léger et frais."},{"couleur":"rose","famille":"rose","note":"Rosé sec de gamay et pinot noir, vin d'été."}],"cepages":["Sauvignon blanc","Chardonnay","Pinot noir","Gamay"],"style":"Blanc sauvignon-chardonnay : agrumes, fleurs blanches, rondeur discrète ; rouges légers pinot-gamay.","temp":"9 à 11 °C","garde":"2 à 4 ans","prix":2,"accords":["poisson_maigre","fromage_chevre","asperge","volaille","legumes"],"eviter":["viande_rouge","chocolat"],"classique":"Cheverny blanc et asperges de Sologne","note":"Au sud de Blois, aux portes de la Sologne, sur sables et argiles à silex. Particularité : les vins sont obligatoirement des assemblages, sauvignon avec chardonnay en blanc, pinot noir avec gamay en rouge. Blancs frais pour les poissons de Loire, rouges légers à servir frais sur une volaille.","lat":47.5,"lon":1.46,"importance":2,"niveau":"classique"},{"id":"fr-menetou-salon","nom":"Menetou-Salon","pays":"France","region":"Vallée de la Loire","sousRegion":"Centre-Loire","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Pinot noir fruité et léger, un tiers de la production."},{"couleur":"rose","famille":"rose","note":"Rosé sec de pinot noir, fraise et groseille."}],"cepages":["Sauvignon blanc","Pinot noir"],"style":"Sauvignon frais et floral : agrumes, bourgeon de cassis, calcaire ; rouges pinot noir fruités.","temp":"9 à 11 °C","garde":"2 à 6 ans","prix":2,"accords":["fromage_chevre","poisson_maigre","coquillage","asperge","volaille"],"eviter":["viande_rouge","chocolat"],"classique":"Menetou-Salon et crottin de Chavignol","note":"Au nord de Bourges, sur les mêmes marnes kimméridgiennes que Sancerre et Chablis. Longtemps dans l'ombre de son voisin, Menetou offre un sauvignon plus tendre et souvent moins cher, et un pinot noir qui compte pour un tiers de la production. Vin de chèvre et de poissons de rivière.","lat":47.23,"lon":2.49,"importance":2,"niveau":"classique"},{"id":"fr-quincy","nom":"Quincy","pays":"France","region":"Vallée de la Loire","sousRegion":"Centre-Loire","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Sauvignon blanc","Sauvignon gris"],"style":"Sauvignon sur sables et graviers : agrumes, fleurs blanches, pointe fumée, bouche tendre et nette.","temp":"9 à 11 °C","garde":"1 à 4 ans","prix":2,"accords":["fromage_chevre","poisson_maigre","coquillage","asperge","legumes"],"eviter":["viande_rouge","chocolat"],"classique":"Quincy et fromage de chèvre du Berry","note":"Parmi les premières AOC de France, la première de la Loire (août 1936), sur les terrasses de sables et de graviers du Cher, à l'ouest de Bourges. Blanc seulement, de sauvignon avec un peu de sauvignon gris. Moins tendu que Sancerre, plus souple, c'est un sauvignon de plaisir immédiat.","lat":47.02,"lon":2.17,"importance":2,"niveau":"classique"},{"id":"fr-rose-de-loire","nom":"Rosé de Loire","pays":"France","region":"Vallée de la Loire","sousRegion":"Anjou","couleur":"rose","famille":"rose","variantes":[],"cepages":["Cabernet franc","Grolleau","Gamay","Pineau d'Aunis"],"style":"Rosé sec, pâle et vif : groseille, agrumes, finale nette et désaltérante.","temp":"8 à 10 °C","garde":"1 à 2 ans","prix":1,"accords":["charcuterie","grille","legumes","mediterraneen","poisson_maigre","fromage_chevre"],"eviter":["gibier","chocolat"],"classique":"Rosé de Loire et pique-nique de rillettes","note":"Appellation régionale (Anjou, Saumur, Touraine) créée en 1974 pour un rosé sec, par opposition au Cabernet d'Anjou et au Rosé d'Anjou, demi-secs. Assemblage à base de cabernet franc avec grolleau, gamay ou pineau d'Aunis. Rosé d'été simple, qui se boit dans l'année.","lat":47.35,"lon":-0.76,"importance":2,"niveau":"classique"},{"id":"fr-chateaumeillant","nom":"Châteaumeillant","pays":"France","region":"Vallée de la Loire","sousRegion":"Centre-Loire","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"rose","famille":"rose","note":"Vin gris de gamay, très pâle, pressé directement, sec et léger."}],"cepages":["Gamay","Pinot noir"],"style":"Rouge léger de gamay : cerise, fruits rouges, poivre ; vin gris pâle et sec.","temp":"13 à 15 °C","garde":"1 à 4 ans","prix":1,"accords":["charcuterie","grille","volaille","porc","fromage_chevre"],"eviter":["gibier","chocolat"],"classique":"Châteaumeillant et pâté berrichon","note":"Tout au sud du Berry, à la limite du Massif central, sur sables et graviers. Longtemps VDQS, AOC en 2010, pour rouges et gris à base de gamay complété de pinot noir. Le gris, rosé très pâle pressé directement, est une spécialité. Rouges légers à servir frais sur la charcuterie.","lat":46.56,"lon":2.2,"importance":1,"niveau":"decouverte"},{"id":"fr-cote-roannaise","nom":"Côte Roannaise","pays":"France","region":"Vallée de la Loire","sousRegion":"Forez-Roannais","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé sec de gamay, fraise et poivre, vin d'été."}],"cepages":["Gamay"],"style":"Gamay sur granite : framboise, cerise, poivre, tanins fins, finale fraîche et légèrement saline.","temp":"13 à 15 °C","garde":"2 à 5 ans","prix":1,"accords":["charcuterie","volaille","porc","grille","fromage_dure","champignon"],"eviter":["gibier","chocolat"],"classique":"Côte Roannaise et saucisson chaud aux pommes de terre","note":"Coteaux granitiques des monts de la Madeleine, à l'ouest de Roanne, dans le département de la Loire. Le gamay Saint-Romain, clone local, est seul autorisé en rouge et rosé, comme en Beaujolais voisin. AOC depuis 1994, blancs en IGP. Rouges frais et fruités, à servir légèrement rafraîchis.","lat":46.05,"lon":3.93,"importance":1,"niveau":"decouverte"},{"id":"fr-coteaux-de-l-aubance","nom":"Coteaux de l'Aubance","pays":"France","region":"Vallée de la Loire","sousRegion":"Anjou","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Chenin blanc"],"style":"Moelleux fin et aérien : poire, acacia, miel léger, moins riche qu'un Layon, finale fraîche.","temp":"8 à 10 °C","garde":"5 à 20 ans","prix":2,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","fromage_chevre"],"eviter":["viande_rouge","chocolat"],"classique":"Coteaux de l'Aubance et foie gras mi-cuit","note":"Petite rivière entre Angers et le Layon, coteaux de schistes où le chenin passerille sur pied plus souvent qu'il ne botrytise. L'appellation ne couvre que le moelleux ; les secs portent le nom d'Anjou. Fruit net, douceur mesurée : un vin d'apéritif ou de dessert aux fruits.","lat":47.4,"lon":-0.55,"importance":1,"niveau":"decouverte"},{"id":"fr-coteaux-du-giennois","nom":"Coteaux du Giennois","pays":"France","region":"Vallée de la Loire","sousRegion":"Centre-Loire","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Assemblage obligatoire gamay et pinot noir, rouge léger et fruité."},{"couleur":"rose","famille":"rose","note":"Rosé sec gamay-pinot noir, simple et frais."}],"cepages":["Sauvignon blanc","Gamay","Pinot noir"],"style":"Sauvignon léger et frais, agrumes et silex ; rouges d'assemblage gamay-pinot noir, fruités.","temp":"9 à 11 °C","garde":"1 à 4 ans","prix":2,"accords":["fromage_chevre","poisson_maigre","charcuterie","legumes","volaille"],"eviter":["viande_rouge","chocolat"],"classique":"Coteaux du Giennois et crottin de chèvre","note":"Entre Gien et Cosne-sur-Loire, de part et d'autre de la Loire, AOC depuis 1998. Le sauvignon domine en blanc ; les rouges doivent assembler gamay et pinot noir, aucun des deux ne pouvant dépasser 80 %. Vignoble modeste, voisin nord de Pouilly, pour des vins simples et frais.","lat":47.41,"lon":2.93,"importance":1,"niveau":"decouverte"},{"id":"fr-coteaux-du-vendomois","nom":"Coteaux du Vendômois","pays":"France","region":"Vallée de la Loire","sousRegion":"Vallée du Loir","couleur":"rose","famille":"rose","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Rouge léger et poivré de pineau d'Aunis, gamay et pinot noir."},{"couleur":"blanc","famille":"blanc_vif","note":"Chenin sec, vif et simple."}],"cepages":["Pineau d'Aunis","Gamay","Pinot noir","Chenin blanc"],"style":"Gris de pineau d'Aunis : pâle, poivre blanc, groseille, très sec ; rouges légers poivrés.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":1,"accords":["charcuterie","grille","legumes","poisson_maigre","fromage_chevre","asiatique"],"eviter":["gibier","chocolat"],"classique":"Gris du Vendômois et rillettes de Vendôme","note":"Vallée du Loir autour de Vendôme, AOC depuis 2001. Le vin gris, rosé très pâle de pineau d'Aunis pressé directement, est la signature locale : poivré, sec, désaltérant. Les rouges assemblent pineau d'Aunis, gamay et pinot noir, les blancs sont de chenin. Vins simples, à boire dans l'année.","lat":47.79,"lon":1.07,"importance":1,"niveau":"decouverte"},{"id":"fr-cotes-d-auvergne","nom":"Côtes d'Auvergne","pays":"France","region":"Vallée de la Loire","sousRegion":"Auvergne","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de gamay, dont le Corent, dénomination réservée au rosé."},{"couleur":"blanc","famille":"blanc_vif","note":"Chardonnay vif sur sols volcaniques, petite production."}],"cepages":["Gamay","Pinot noir","Chardonnay"],"style":"Gamay sur sols volcaniques : cerise, poivre, pointe fumée, tanins légers ; rosés et blancs frais.","temp":"13 à 15 °C","garde":"2 à 5 ans","prix":1,"accords":["charcuterie","porc","volaille","grille","fromage_dure","fromage_bleu"],"eviter":["gibier","chocolat"],"classique":"Côtes d'Auvergne et saint-nectaire","note":"Autour de Clermont-Ferrand, sur basaltes et pouzzolanes des volcans de la chaîne des Puys. AOC depuis 2011 avec cinq dénominations : Boudes, Chanturgue, Châteaugay, Corent (rosé), Madargue. Gamay dominant, parfois pinot noir. Rouges fumés et légers, parfaits sur les fromages d'Auvergne.","lat":45.78,"lon":3.09,"importance":1,"niveau":"decouverte"},{"id":"fr-cotes-du-forez","nom":"Côtes du Forez","pays":"France","region":"Vallée de la Loire","sousRegion":"Forez-Roannais","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé sec de gamay, léger et fruité."}],"cepages":["Gamay"],"style":"Gamay sur granite et basalte : fruits rouges, pointe de pierre, léger, frais et gouleyant.","temp":"13 à 15 °C","garde":"1 à 4 ans","prix":1,"accords":["charcuterie","grille","volaille","porc","fromage_dure"],"eviter":["gibier","chocolat"],"classique":"Côtes du Forez et fourme de Montbrison","note":"Plaine du Forez, au nord de Saint-Étienne, sur les contreforts granitiques et volcaniques des monts du Forez. Vignoble le plus en amont sur le fleuve, 100 % gamay, AOC depuis 2000, moins de 200 hectares. Rouges et rosés légers, de soif, qui s'accordent à la fourme de Montbrison.","lat":45.75,"lon":4.01,"importance":1,"niveau":"decouverte"},{"id":"fr-cour-cheverny","nom":"Cour-Cheverny","pays":"France","region":"Vallée de la Loire","sousRegion":"Touraine","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Romorantin"],"style":"Sec tendu : miel d'acacia, coing, pomme, pointe de cire ; vieillit vers la noix et le pain d'épices.","temp":"10 à 12 °C","garde":"5 à 20 ans","prix":2,"accords":["poisson_maigre","volaille","creme","fromage_chevre","champignon"],"eviter":["viande_rouge","chocolat"],"classique":"Cour-Cheverny et brochet au beurre blanc","note":"Seule appellation au monde consacrée au romorantin, cépage que François Ier aurait fait planter en 1519 près de Romorantin. Une dizaine de communes autour de Cheverny, sur sables et argiles. Vin sec, nerveux, longtemps austère, qui développe cire et miel après cinq ans. Une curiosité à faire goûter.","lat":47.51,"lon":1.45,"importance":1,"niveau":"decouverte"},{"id":"fr-fiefs-vendeens","nom":"Fiefs Vendéens","pays":"France","region":"Vallée de la Loire","sousRegion":"Vendée","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé sec de gamay et pinot noir, vin de plage."},{"couleur":"blanc","famille":"blanc_vif","note":"Chenin et chardonnay, blanc vif et simple."}],"cepages":["Pinot noir","Cabernet franc","Négrette","Gamay"],"style":"Rouge léger et frais : fruits rouges, pointe poivrée, tanins souples ; rosés et blancs vifs.","temp":"14 à 16 °C","garde":"2 à 5 ans","prix":1,"accords":["charcuterie","volaille","grille","porc","fromage_chevre"],"eviter":["gibier","chocolat"],"classique":"Fiefs Vendéens rouge et préfou vendéen","note":"Cinq secteurs (Mareuil, Brem, Vix, Pissotte, Chantonnay) à l'arrière des plages vendéennes, AOC depuis 2011. Les rouges assemblent pinot noir, cabernet franc et parfois négrette ; les blancs mêlent chenin et chardonnay. Vins de vacances, servis frais sur grillades et charcuterie.","lat":46.53,"lon":-1.23,"importance":1,"niveau":"decouverte"},{"id":"fr-gros-plant-du-pays-nantais","nom":"Gros Plant du Pays nantais","pays":"France","region":"Vallée de la Loire","sousRegion":"Pays nantais","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Folle blanche"],"style":"Très sec, nerveux, acidulé : citron, pomme verte, finale saline ; peu d'alcool.","temp":"8 à 10 °C","garde":"1 à 2 ans","prix":1,"accords":["huitre","coquillage","crustace","poisson_maigre","frit"],"eviter":["viande_rouge","fromage_bleu","chocolat"],"classique":"Gros Plant et plateau de fruits de mer","note":"La folle blanche, cépage historique du cognac, donne ici un blanc tranchant et peu alcoolisé, AOC depuis 2011 après des décennies en VDQS. Souvent élevé sur lie comme le muscadet, il se boit très frais, l'été, sur les huîtres et les coquillages de la côte atlantique.","lat":47.17,"lon":-1.47,"importance":1,"niveau":"decouverte"},{"id":"fr-jasnieres","nom":"Jasnières","pays":"France","region":"Vallée de la Loire","sousRegion":"Vallée du Loir","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Demi-sec ou moelleux de chenin, seulement les années chaudes."}],"cepages":["Chenin blanc"],"style":"Sec très tendu, presque austère jeune : pomme verte, silex, coing ; moelleux les bonnes années.","temp":"10 à 12 °C","garde":"5 à 20 ans","prix":2,"accords":["poisson_maigre","coquillage","volaille","fromage_chevre","creme"],"eviter":["viande_rouge","chocolat"],"classique":"Jasnières et rillettes du Mans","note":"Un seul coteau de quatre kilomètres exposé plein sud, sur la rive nord du Loir (sans e), dans la Sarthe, communes de Lhomme et Ruillé-sur-Loir. Vignoble septentrional du chenin, à la limite de maturité, d'où des secs très droits et des moelleux seulement les grandes années. Carafer les jeunes.","lat":47.74,"lon":0.67,"importance":1,"niveau":"decouverte"},{"id":"fr-pouilly-sur-loire","nom":"Pouilly-sur-Loire","pays":"France","region":"Vallée de la Loire","sousRegion":"Centre-Loire","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Chasselas","Sauvignon blanc"],"style":"Chasselas léger et discret : fleurs blanches, pomme, amande, bouche douce et peu acide.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":2,"accords":["poisson_maigre","fromage_frais","coquillage","legumes","frit"],"eviter":["viande_rouge","fromage_bleu","chocolat"],"classique":"Pouilly-sur-Loire et friture de Loire","note":"Même aire que le Pouilly-Fumé, mais cépage chasselas, raisin de table qui fit la fortune de Pouilly avant le phylloxéra, quand il partait pour Paris. Vignoble résiduel de quelques dizaines d'hectares. Vin léger, peu acide, à boire dans l'année sur une friture ou un fromage frais.","lat":47.28,"lon":2.95,"importance":1,"niveau":"decouverte"},{"id":"fr-reuilly","nom":"Reuilly","pays":"France","region":"Vallée de la Loire","sousRegion":"Centre-Loire","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé gris de pinot gris, pâle, tendre et fruité : la spécialité locale."},{"couleur":"rouge","famille":"rouge_leger","note":"Pinot noir léger, cerise et épices."}],"cepages":["Sauvignon blanc","Pinot noir","Pinot gris"],"style":"Sauvignon net : citron, fleurs blanches, silex ; rosé gris de pinot gris tendre ; rouges légers.","temp":"9 à 11 °C","garde":"1 à 4 ans","prix":2,"accords":["fromage_chevre","poisson_maigre","coquillage","charcuterie","asperge"],"eviter":["viande_rouge","chocolat"],"classique":"Reuilly rosé gris et charcuterie du Berry","note":"Petite appellation de l'Indre et du Cher, au sud-ouest de Bourges, relancée depuis les années 1980. Trois couleurs : sauvignon en blanc, pinot noir en rouge, et un rosé gris de pinot gris qui fait sa réputation. Vins frais et simples, à boire jeunes, à un prix encore raisonnable.","lat":47.08,"lon":2.04,"importance":1,"niveau":"decouverte"},{"id":"fr-saint-pourcain","nom":"Saint-Pourçain","pays":"France","region":"Vallée de la Loire","sousRegion":"Bourbonnais","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Chardonnay et tressallier, blanc vif et floral, à boire jeune."},{"couleur":"rose","famille":"rose","note":"Rosé sec de gamay, fruits rouges."}],"cepages":["Gamay","Pinot noir","Chardonnay","Tressallier"],"style":"Rouge gamay-pinot léger et frais, cerise et épices ; blanc chardonnay-tressallier vif, floral.","temp":"13 à 15 °C","garde":"2 à 5 ans","prix":1,"accords":["charcuterie","volaille","porc","grille","fromage_dure","champignon"],"eviter":["gibier","chocolat"],"classique":"Saint-Pourçain et pâté aux pommes de terre bourbonnais","note":"Vallée de la Sioule, dans l'Allier, vignoble du Bourbonnais rattaché à la Loire. AOC depuis 2009. Les rouges assemblent gamay et pinot noir ; les blancs doivent contenir du tressallier, cépage local (le sacy de l'Yonne), avec le chardonnay. Vins de table simples, servis frais.","lat":46.31,"lon":3.29,"importance":1,"niveau":"decouverte"},{"id":"fr-valencay","nom":"Valençay","pays":"France","region":"Vallée de la Loire","sousRegion":"Touraine","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Assemblage gamay, pinot noir et côt : rouge léger, frais et poivré."},{"couleur":"rose","famille":"rose","note":"Rosé sec d'assemblage, fruits rouges."}],"cepages":["Sauvignon blanc","Gamay","Pinot noir","Côt"],"style":"Sauvignon vif, agrumes et buis, pointe de chardonnay ; rouges légers gamay-pinot-côt, frais et poivrés.","temp":"9 à 11 °C","garde":"1 à 4 ans","prix":1,"accords":["fromage_chevre","poisson_maigre","asperge","legumes","charcuterie"],"eviter":["viande_rouge","chocolat"],"classique":"Valençay blanc et fromage de Valençay (la pyramide)","note":"Nord de l'Indre, autour du château de Talleyrand, à la jonction de la Touraine et du Berry. AOC depuis 2004, elle partage son nom avec un chèvre AOP à la pyramide tronquée. Blancs d'assemblage à base de sauvignon, rouges légers à base de gamay, pinot noir et côt. Vins simples et frais.","lat":47.16,"lon":1.57,"importance":1,"niveau":"decouverte"},{"id":"fr-chateauneuf-du-pape","nom":"Châteauneuf-du-Pape","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Grenache blanc, roussanne, clairette : gras, fleurs blanches, poire, miel ; rare et cher."}],"cepages":["Grenache","Syrah","Mourvèdre","Cinsault"],"style":"Kirsch, fruits noirs confits, garrigue, cuir, réglisse ; ample, chaleureux, tanins enrobés, longue finale.","temp":"16 à 18 °C","garde":"5 à 20 ans","prix":3,"accords":["gibier","agneau","roti","mijote","truffe","fromage_lave"],"eviter":["huitre","poisson_cru","acide"],"classique":"Châteauneuf-du-Pape et lièvre à la royale","note":"Première AOC de France (1936), sur les galets roulés qui rendent la chaleur du jour à la vigne. Treize cépages autorisés, grenache en tête. Rouge opulent, riche en alcool, à carafer, pour les gibiers, l'agneau de sept heures et les plats truffés ; le blanc, rare, va sur les poissons en sauce.","lat":44.06,"lon":4.83,"importance":5,"niveau":"incontournable"},{"id":"fr-cote-rotie","nom":"Côte-Rôtie","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône septentrional","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Syrah","Viognier"],"style":"Violette, cassis, lard fumé, poivre et olive noire ; bouche dense mais élégante, tanins fins, grande longueur.","temp":"16 à 18 °C","garde":"8 à 20 ans","prix":4,"accords":["viande_rouge","gibier","agneau","roti","truffe","champignon"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Côte-Rôtie et gigot d'agneau en croûte d'herbes","note":"Des terrasses abruptes au-dessus d'Ampuis, soutenues par des murets, où l'on vendange à la main depuis l'Antiquité. La Côte Brune donne des vins puissants, la Côte Blonde des vins plus fins. La syrah peut y être co-fermentée avec jusqu'à 20 % de viognier, d'où le parfum de violette.","lat":45.49,"lon":4.81,"importance":5,"niveau":"incontournable"},{"id":"fr-cotes-du-rhone","nom":"Côtes-du-Rhône","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Grenache blanc, clairette, viognier : rond, fleurs blanches, à boire jeune."},{"couleur":"rose","famille":"rose","note":"Rosé fruité de grenache et cinsault, pour la table d'été."}],"cepages":["Grenache","Syrah","Mourvèdre","Carignan"],"style":"Fruits rouges mûrs, garrigue, poivre doux ; tanins souples, bouche ronde et facile.","temp":"15 à 17 °C","garde":"2 à 5 ans","prix":1,"accords":["charcuterie","grille","viande_rouge","mijote","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_cru"],"classique":"Côtes-du-Rhône et daube provençale","note":"Appellation régionale de 170 communes entre Vienne et Avignon, mais produite surtout au sud, sur le grenache. Le vin de tous les jours du Rhône : nez de fruits rouges et de garrigue, tanins souples. À servir légèrement rafraîchi sur une grillade ou une daube.","lat":44.14,"lon":4.81,"importance":5,"niveau":"incontournable"},{"id":"fr-hermitage","nom":"Hermitage","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône septentrional","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Hermitage blanc de marsanne et roussanne : miel, noisette, cire, très long en bouche, garde de 10 à 30 ans."}],"cepages":["Syrah","Marsanne","Roussanne"],"style":"Cassis, mûre, poivre, cuir, truffe et goudron avec l'âge ; bouche puissante et profonde, tanins serrés, garde très longue.","temp":"16 à 18 °C","garde":"10 à 30 ans","prix":4,"accords":["viande_rouge","gibier","agneau","truffe","roti","fromage_dure"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Hermitage et lièvre à la royale","note":"Une seule colline de granit au-dessus de Tain, plein sud, 137 hectares découpés en lieux-dits comme Les Bessards ou Le Méal. Les rouges comptaient parmi les vins les plus chers du monde au XIXe siècle. Le blanc, un tiers de la surface, est l'un des grands blancs de garde de France.","lat":45.07,"lon":4.85,"importance":5,"niveau":"incontournable"},{"id":"fr-condrieu","nom":"Condrieu","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône septentrional","couleur":"blanc","famille":"blanc_aromatique","variantes":[],"cepages":["Viognier"],"style":"Abricot, pêche, violette, fleur d'oranger ; bouche ample, grasse, presque huileuse, peu d'acidité, finale longue.","temp":"10 à 12 °C","garde":"2 à 5 ans","prix":3,"accords":["crustace","poisson_gras","volaille","creme","epice_douce","asiatique"],"eviter":["vinaigre","fromage_bleu","chocolat"],"classique":"Condrieu et homard à la crème de safran","note":"Le berceau mondial du viognier, sur des terrasses de granit et d'arzelle, un sable de mica, au sud de Côte-Rôtie. L'appellation a failli disparaître dans les années 1960 avant d'être relancée. Un blanc opulent et parfumé, à boire jeune, à une température jamais trop froide.","lat":45.46,"lon":4.77,"importance":4,"niveau":"incontournable"},{"id":"fr-cornas","nom":"Cornas","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône septentrional","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Syrah"],"style":"Mûre, myrtille, poivre, graphite, viande fumée ; bouche sombre et tannique jeune, puis veloutée après cinq ans.","temp":"16 à 18 °C","garde":"6 à 20 ans","prix":3,"accords":["viande_rouge","gibier","agneau","roti","mijote","fromage_dure"],"eviter":["huitre","poisson_maigre","piquant"],"classique":"Cornas et civet de sanglier","note":"Un amphithéâtre de granit face à Valence, protégé du mistral, dont le nom signifierait terre brûlée en celte. La seule appellation du Rhône nord qui n'autorise que la syrah, sans blanc ni cépage d'assemblage. Un rouge rustique et sombre dans sa jeunesse, qui demande du temps en cave.","lat":44.96,"lon":4.84,"importance":4,"niveau":"incontournable"},{"id":"fr-cotes-du-rhone-villages","nom":"Côtes-du-Rhône Villages","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Rare : grenache blanc et roussanne, rond et floral."}],"cepages":["Grenache","Syrah","Mourvèdre"],"style":"Plus dense qu'un Côtes-du-Rhône : cerise noire, réglisse, épices, tanins plus présents.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["agneau","roti","mijote","viande_rouge","herbes","fromage_dure"],"eviter":["coquillage","poisson_maigre"],"classique":"Côtes-du-Rhône Villages et gigot d'agneau aux herbes","note":"Niveau intermédiaire de la hiérarchie rhodanienne : rendements plus bas, grenache à 50 % minimum, et une vingtaine de villages (Séguret, Sablet, Visan, Chusclan…) ont le droit d'ajouter leur nom. Rouge de caractère pour un rôti ou un plat du dimanche, à prix sage.","lat":44.2,"lon":4.95,"importance":4,"niveau":"classique"},{"id":"fr-crozes-hermitage","nom":"Crozes-Hermitage","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône septentrional","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Crozes-Hermitage blanc de marsanne : fleurs blanches, poire, bouche ronde et douce."}],"cepages":["Syrah","Marsanne","Roussanne"],"style":"Fruits noirs, poivre, violette, olive et note fumée ; bouche gourmande, tanins souples, à boire jeune.","temp":"15 à 17 °C","garde":"2 à 8 ans","prix":2,"accords":["viande_rouge","grille","charcuterie","volaille","mijote","fromage_dure"],"eviter":["huitre","poisson_cru","chocolat"],"classique":"Crozes-Hermitage et saucisson brioché","note":"La plus vaste appellation du Rhône nord, onze communes autour de Tain-l'Hermitage, surtout sur les terrasses de galets de la plaine. Elle encercle la colline de l'Hermitage sans en avoir la densité : c'est la syrah du nord pour tous les jours, fruitée et poivrée, à un prix raisonnable.","lat":45.09,"lon":4.86,"importance":4,"niveau":"classique"},{"id":"fr-gigondas","nom":"Gigondas","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé rare et vineux, de grenache."},{"couleur":"blanc","famille":"blanc_ample","note":"Autorisé depuis 2023 : clairette majoritaire, ample et floral."}],"cepages":["Grenache","Syrah","Mourvèdre"],"style":"Cerise noire, kirsch, garrigue, poivre ; corps puissant, tanins fermes mais mûrs, finale longue.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":3,"accords":["agneau","gibier","roti","mijote","viande_rouge","fromage_dure"],"eviter":["huitre","poisson_maigre","acide"],"classique":"Gigondas et civet de sanglier","note":"Cru de 1971 au pied des Dentelles de Montmirail, sur des terrasses calcaires qui grimpent jusqu'à 500 m : l'altitude lui garde de la fraîcheur malgré le soleil. Plus structuré et plus abordable que Châteauneuf, il demande quelques années et des plats de caractère : gibier, agneau, daube.","lat":44.16,"lon":5.0,"importance":4,"niveau":"incontournable"},{"id":"fr-muscat-de-beaumes-de-venise","nom":"Muscat de Beaumes-de-Venise","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Muscat blanc à petits grains"],"style":"Raisin frais, abricot, fleur d'oranger, miel ; sucre franc tenu par l'alcool du mutage, finale nette.","temp":"8 à 10 °C","garde":"2 à 5 ans","prix":2,"accords":["foie_gras","fruits_jaunes","patisserie","fruits_exotiques","fromage_bleu","epice_douce"],"eviter":["viande_rouge","chocolat","acide"],"classique":"Muscat de Beaumes-de-Venise et tarte aux abricots","note":"Vin doux naturel d'AOC depuis 1945 : la fermentation est stoppée par ajout d'alcool, ce qui garde le sucre du raisin et l'arôme du muscat à petits grains. Aromatique, frais, autour de 15 %, il se sert bien froid à l'apéritif, sur un foie gras, un dessert aux fruits jaunes ou un bleu.","lat":44.12,"lon":5.03,"importance":4,"niveau":"classique"},{"id":"fr-saint-joseph","nom":"Saint-Joseph","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône septentrional","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Saint-Joseph blanc de marsanne et roussanne : aubépine, poire, amande, bouche ronde."}],"cepages":["Syrah","Marsanne","Roussanne"],"style":"Cassis, framboise, poivre noir, violette ; bouche souple et fraîche, tanins fins, la syrah du nord la plus accessible.","temp":"15 à 17 °C","garde":"3 à 10 ans","prix":3,"accords":["viande_rouge","agneau","grille","charcuterie","roti","fromage_dure"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Saint-Joseph et entrecôte grillée au poivre","note":"Une longue bande de coteaux granitiques sur la rive droite du Rhône, de Chavanay à Guilherand, face à l'Hermitage. Le cœur historique est autour de Tournon et Mauves. Le rouge est la syrah la plus souple du nord, prête après deux ou trois ans ; le blanc, environ dix pour cent, gagne à être connu.","lat":45.07,"lon":4.83,"importance":4,"niveau":"classique"},{"id":"fr-tavel","nom":"Tavel","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rose","famille":"rose","variantes":[],"cepages":["Grenache","Cinsault","Clairette","Syrah"],"style":"Rosé foncé et vineux : fraise, grenade, amande, épices ; bouche pleine, presque tannique, finale sèche.","temp":"10 à 12 °C","garde":"2 à 5 ans","prix":2,"accords":["mediterraneen","grille","volaille","poisson_gras","charcuterie","epice_douce"],"eviter":["chocolat","huitre"],"classique":"Tavel et bouillabaisse","note":"Première appellation de France réservée au rosé (1936), dans le Gard, sur des sables, des galets et des lauzes calcaires. Vin de macération courte et non de pressurage : couleur soutenue, corps de petit rouge, capacité de garde. Il tient tête à une bouillabaisse, un aïoli ou une grillade de thon.","lat":44.01,"lon":4.7,"importance":4,"niveau":"classique"},{"id":"fr-cairanne","nom":"Cairanne","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Clairette, grenache blanc, roussanne : gras, fleurs blanches, amande."}],"cepages":["Grenache","Syrah","Mourvèdre"],"style":"Fruits noirs, garrigue, olive, poivre ; bouche charnue, tanins mûrs, finale chaleureuse.","temp":"16 à 18 °C","garde":"4 à 10 ans","prix":2,"accords":["agneau","grille","mijote","gibier","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_maigre","vinaigre"],"classique":"Cairanne et agneau aux olives","note":"Village du Vaucluse promu cru des Côtes-du-Rhône en 2016, sur des coteaux de galets et d'argile exposés plein sud. Rouge solaire et épicé, à mi-chemin entre la souplesse d'un Villages et la puissance d'un Gigondas. Il aime les viandes grillées aux herbes et les plats d'olives.","lat":44.23,"lon":4.93,"importance":3,"niveau":"classique"},{"id":"fr-chateau-grillet","nom":"Château-Grillet","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône septentrional","couleur":"blanc","famille":"blanc_aromatique","variantes":[],"cepages":["Viognier"],"style":"Pêche blanche, miel, amande, épices douces ; plus retenu et plus tendu que Condrieu, long élevage, finale saline.","temp":"11 à 13 °C","garde":"5 à 15 ans","prix":4,"accords":["crustace","poisson_gras","volaille","creme","truffe"],"eviter":["vinaigre","piquant","chocolat"],"classique":"Château-Grillet et quenelle de brochet sauce Nantua","note":"Une des plus petites appellations de France, 3,5 hectares d'un seul tenant en amphithéâtre de granit, enclavée dans Condrieu, et propriété d'un seul domaine. Le viognier y est vendangé tard et élevé longuement : un blanc de garde, rare et cher, plus droit que son voisin.","lat":45.45,"lon":4.75,"importance":3,"niveau":"decouverte"},{"id":"fr-clairette-de-die","nom":"Clairette de Die","pays":"France","region":"Vallée du Rhône","sousRegion":"Diois","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"bulles","famille":"bulles","note":"Clairette de Die brut, en méthode traditionnelle, à base de clairette seule, sec et plus neutre."}],"cepages":["Muscat blanc à petits grains","Clairette"],"style":"Raisin frais, pêche, fleur d'oranger, bulle fine et légère ; bouche douce, peu alcoolisée (7 à 9 %), très fruitée.","temp":"6 à 8 °C","garde":"1 à 2 ans","prix":1,"accords":["patisserie","fruits_jaunes","fruits_exotiques","fromage_frais","fromage_bleu"],"eviter":["viande_rouge","sauce_vin_rouge","amer"],"classique":"Clairette de Die et tarte aux abricots","note":"Effervescent du Diois, dans la vallée de la Drôme au pied du Vercors, à 400 mètres d'altitude. La méthode dioise, dite ancestrale, arrête la fermentation par le froid et la termine en bouteille sans ajout de sucre : le muscat garde son goût de raisin. Un vin de dessert léger, à servir très frais.","lat":44.75,"lon":5.37,"importance":3,"niveau":"classique"},{"id":"fr-costieres-de-nimes","nom":"Costières de Nîmes","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé fruité de grenache et syrah, un tiers de la production."},{"couleur":"blanc","famille":"blanc_ample","note":"Grenache blanc, roussanne, vermentino : rond, fleurs blanches, agrumes."}],"cepages":["Syrah","Grenache","Mourvèdre","Carignan"],"style":"Fruits noirs, olive, garrigue, poivre ; tanins souples, corps moyen, chaleur du sud tempérée par la brise de mer.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["grille","charcuterie","mijote","viande_rouge","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_cru"],"classique":"Costières de Nîmes et gardiane de taureau","note":"Appellation la plus au sud du Rhône, entre Nîmes et la Camargue, sur une terrasse de galets roulés balayée par la brise marine. Rattachée administrativement au Rhône en 2004 après le Languedoc. Rouge souple et épicé, dominé par la syrah, à servir sur une gardiane ou une grillade.","lat":43.78,"lon":4.4,"importance":3,"niveau":"classique"},{"id":"fr-lirac","nom":"Lirac","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Grenache blanc, clairette, roussanne : rond, floral, un peu anisé."},{"couleur":"rose","famille":"rose","note":"Rosé vineux, frère de Tavel, pour la cuisine provençale."}],"cepages":["Grenache","Syrah","Mourvèdre","Cinsault"],"style":"Fruits noirs, garrigue, poivre, un peu de cacao ; corps plein, tanins mûrs, moins lourd que Châteauneuf.","temp":"16 à 18 °C","garde":"4 à 10 ans","prix":2,"accords":["agneau","roti","mijote","viande_rouge","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_maigre"],"classique":"Lirac et épaule d'agneau rôtie à l'ail","note":"Cru de la rive droite du Rhône, dans le Gard, face à Châteauneuf dont il partage les galets roulés et les cépages. Avec Vacqueyras, l’un des rares crus du sud en trois couleurs. Le rouge offre le profil châteauneuvois à prix doux : on le sert sur un agneau rôti ou un plat provençal.","lat":44.09,"lon":4.69,"importance":3,"niveau":"classique"},{"id":"fr-luberon","nom":"Luberon","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Plus de la moitié de la production : rosé pâle et frais de syrah et grenache."},{"couleur":"blanc","famille":"blanc_vif","note":"Grenache blanc, vermentino, roussanne : frais, fleurs, agrumes."}],"cepages":["Syrah","Grenache","Cinsault","Carignan"],"style":"Fruits rouges, violette, poivre, un peu de garrigue ; corps moyen, tanins souples, finale fraîche.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":2,"accords":["grille","volaille","legumes","charcuterie","mediterraneen","fromage_chevre"],"eviter":["huitre","gibier"],"classique":"Luberon et ratatouille","note":"AOC de 1988 sur les deux versants du massif du Luberon, entre Apt et Pertuis, dans le parc naturel régional. Un climat un peu plus frais que la plaine d'Avignon et la part de syrah donnent des rouges légers et des rosés dominants. Vins d'été, pour la cuisine provençale et les chèvres.","lat":43.85,"lon":5.35,"importance":3,"niveau":"classique"},{"id":"fr-rasteau","nom":"Rasteau","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"doux","famille":"vdn","note":"Vin doux naturel de grenache, rouge ou ambré rancio : cerise à l'eau-de-vie, cacao, noix."}],"cepages":["Grenache","Syrah","Mourvèdre"],"style":"Rouge sec dense : mûre, cerise noire, réglisse, épices ; tanins amples, bouche généreuse.","temp":"16 à 18 °C","garde":"4 à 10 ans","prix":2,"accords":["viande_rouge","agneau","mijote","gibier","sauce_vin_rouge","fromage_dure"],"eviter":["poisson_cru","coquillage"],"classique":"Rasteau et bœuf braisé aux olives noires","note":"Village du Vaucluse connu d'abord pour son vin doux naturel (AOC 1944), le rouge sec n'est devenu cru qu'en 2010. Sur des coteaux argilo-calcaires chauds, le grenache donne un rouge charnu pour les viandes braisées ; le VDN, muté à l'alcool, se sert frais avec le chocolat ou un bleu.","lat":44.23,"lon":4.98,"importance":3,"niveau":"classique"},{"id":"fr-vacqueyras","nom":"Vacqueyras","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Grenache blanc, roussanne, viognier : gras, pêche, fleurs blanches."},{"couleur":"rose","famille":"rose","note":"Rosé vineux de grenache et cinsault, pour les grillades."}],"cepages":["Grenache","Syrah","Mourvèdre"],"style":"Fruits noirs, réglisse, thym, poivre ; bouche charnue et chaleureuse, tanins mûrs un peu rustiques.","temp":"16 à 18 °C","garde":"4 à 10 ans","prix":2,"accords":["grille","agneau","mijote","viande_rouge","mediterraneen","fromage_dure"],"eviter":["poisson_cru","huitre"],"classique":"Vacqueyras et côtes d'agneau grillées au thym","note":"Voisin de Gigondas, cru depuis 1990, sur le plateau de garrigue des Garrigues et les terrasses de l'Ouvèze. Le rouge est un peu plus chaleureux et plus direct que son voisin, à boire plus tôt. C'est le vin des grillades d'été et des viandes aux herbes de Provence.","lat":44.14,"lon":4.98,"importance":3,"niveau":"classique"},{"id":"fr-ventoux","nom":"Ventoux","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé frais de grenache et cinsault, très répandu."},{"couleur":"blanc","famille":"blanc_vif","note":"Clairette, grenache blanc, roussanne : vif et floral grâce à l'altitude."}],"cepages":["Grenache","Syrah","Carignan","Cinsault"],"style":"Fruits rouges croquants, poivre, violette ; corps moyen, tanins souples, fraîcheur due à l'altitude.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["charcuterie","grille","volaille","legumes","mediterraneen","fromage_chevre"],"eviter":["huitre","poisson_cru"],"classique":"Ventoux et tian de légumes provençal","note":"Grande appellation (AOC 1973) sur les pentes sud et ouest du mont Ventoux, autour de Carpentras et Bédoin, jusqu'à 450 m. Les nuits fraîches de la montagne tempèrent le soleil : rouges plus légers et plus frais que la plaine. Vin de table quotidien, bon sur les légumes, la volaille et les grillades.","lat":44.06,"lon":5.1,"importance":3,"niveau":"classique"},{"id":"fr-beaumes-de-venise","nom":"Beaumes-de-Venise","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Grenache","Syrah","Mourvèdre"],"style":"Fruits rouges et noirs, garrigue, un trait de fraîcheur ; tanins fins, corps moyen à plein.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["agneau","grille","volaille","mijote","herbes","fromage_dure"],"eviter":["poisson_maigre","huitre"],"classique":"Beaumes-de-Venise rouge et épaule d'agneau confite","note":"Le rouge sec de Beaumes-de-Venise est cru depuis 2005, sur des sols de trias (argiles rouges) au pied sud des Dentelles de Montmirail. Il est moins connu que le muscat du même village : rouge épicé et plutôt frais pour la zone, qui va bien sur un agneau ou une volaille rôtie aux herbes.","lat":44.12,"lon":5.03,"importance":2,"niveau":"decouverte"},{"id":"fr-grignan-les-adhemar","nom":"Grignan-les-Adhémar","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé frais de grenache et cinsault."},{"couleur":"blanc","famille":"blanc_ample","note":"Viognier, grenache blanc, roussanne : floral et rond."}],"cepages":["Grenache","Syrah","Cinsault","Carignan"],"style":"Fruits rouges, poivre, lavande, garrigue ; corps moyen, tanins souples, fraîcheur du mistral.","temp":"15 à 17 °C","garde":"2 à 5 ans","prix":1,"accords":["charcuterie","grille","volaille","truffe","mediterraneen","fromage_chevre"],"eviter":["huitre","poisson_cru"],"classique":"Grignan-les-Adhémar et brouillade à la truffe","note":"Ancien Coteaux du Tricastin, rebaptisé en 2010 du nom du château de Grignan, dans la Drôme provençale entre lavande et truffières. Le mistral et l'altitude modérée donnent des rouges plus légers que le Vaucluse voisin. Vin de tous les jours ; il accompagne bien la truffe noire locale.","lat":44.42,"lon":4.91,"importance":2,"niveau":"decouverte"},{"id":"fr-igp-collines-rhodaniennes","nom":"IGP Collines Rhodaniennes","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône septentrional et moyen","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Viognier hors AOC : abricot, fleurs blanches, à prix doux."}],"cepages":["Syrah","Viognier","Gamay","Merlot"],"style":"Syrah jeune : fruits noirs, violette, poivre ; corps moyen, tanins souples, fraîcheur du nord.","temp":"14 à 16 °C","garde":"2 à 5 ans","prix":1,"accords":["charcuterie","grille","volaille","porc","fromage_dure","fume"],"eviter":["huitre","poisson_cru"],"classique":"Syrah des Collines Rhodaniennes et saucisson chaud","note":"Vin de pays des coteaux qui bordent le Rhône entre Lyon et Valence, hors des parcelles classées en Côte-Rôtie, Condrieu ou Saint-Joseph. Les mêmes vignerons y vinifient syrah et viognier jeunes, sur des terrains plus hauts ou plus récents. La porte d'entrée abordable du goût rhodanien.","lat":45.4,"lon":4.75,"importance":2,"niveau":"decouverte"},{"id":"fr-saint-peray","nom":"Saint-Péray","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône septentrional","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"bulles","famille":"bulles","note":"Saint-Péray mousseux de méthode traditionnelle, l'historique de l'appellation, de plus en plus rare."}],"cepages":["Marsanne","Roussanne"],"style":"Aubépine, poire, amande fraîche, miel léger ; bouche ronde et grasse, finale amère élégante.","temp":"10 à 12 °C","garde":"3 à 8 ans","prix":2,"accords":["poisson_maigre","volaille","crustace","creme","champignon","fromage_chevre"],"eviter":["viande_rouge","sauce_vin_rouge","piquant"],"classique":"Saint-Péray et poisson de rivière au beurre blanc","note":"L'appellation la plus au sud du Rhône nord, face à Valence, sur granit et calcaire, en blanc seulement, de marsanne et roussanne. Célèbre au XIXe siècle pour son mousseux, que Wagner aurait commandé pendant l'écriture de Parsifal. Aujourd'hui, c'est surtout un blanc tranquille, rond et accessible.","lat":44.95,"lon":4.85,"importance":2,"niveau":"decouverte"},{"id":"fr-vinsobres","nom":"Vinsobres","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Grenache","Syrah","Mourvèdre"],"style":"Cassis, violette, poivre, garrigue ; tanins fins, fraîcheur nette pour le sud, corps moyen à plein.","temp":"16 à 17 °C","garde":"3 à 8 ans","prix":2,"accords":["agneau","viande_rouge","grille","canard","herbes","fromage_dure"],"eviter":["huitre","poisson_cru"],"classique":"Vinsobres et magret de canard au poivre","note":"Premier cru de la Drôme (2006), sur des coteaux entre 200 et 450 m au nord de l'aire méridionale. La syrah y pèse plus qu'ailleurs dans le sud et le climat plus frais donne un rouge poivré, moins alcoolisé que ses voisins vauclusiens. Un bon pont entre Rhône nord et sud, sur un canard ou un agneau.","lat":44.33,"lon":5.06,"importance":2,"niveau":"decouverte"},{"id":"fr-chatillon-en-diois","nom":"Châtillon-en-Diois","pays":"France","region":"Vallée du Rhône","sousRegion":"Diois","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Blanc d'aligoté et de chardonnay, vif et léger, de montagne."},{"couleur":"rose","famille":"rose","note":"Rosé de gamay, frais et discret, à boire dans l'année."}],"cepages":["Gamay","Pinot noir","Syrah"],"style":"Fruits rouges acidulés, fraise, poivre léger ; bouche légère, fraîche et peu tannique, un rouge de montagne.","temp":"12 à 14 °C","garde":"1 à 3 ans","prix":2,"accords":["charcuterie","volaille","legumes","fromage_chevre","grille"],"eviter":["viande_rouge","gibier","piquant"],"classique":"Châtillon-en-Diois et picodon de la Drôme","note":"Une des plus petites appellations de la vallée du Rhône en vins tranquilles, dans la haute vallée de la Drôme au pied du Glandasse. Les vignes montent au-delà de 500 mètres : le gamay y donne un rouge très léger et acidulé, les blancs sont vifs. Un vin local, rarement vu hors du Diois.","lat":44.69,"lon":5.48,"importance":1,"niveau":"decouverte"},{"id":"fr-clairette-de-bellegarde","nom":"Clairette de Bellegarde","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Clairette"],"style":"Fleurs blanches, pomme mûre, amande, pointe de miel ; bouche grasse, peu acide, finale légèrement amère.","temp":"9 à 11 °C","garde":"1 à 3 ans","prix":1,"accords":["coquillage","poisson_maigre","crustace","vapeur","fromage_chevre","legumes"],"eviter":["viande_rouge","piquant"],"classique":"Clairette de Bellegarde et tellines de Camargue","note":"Minuscule AOC (1949) de la commune de Bellegarde, entre Nîmes et Arles, réservée au blanc sec de clairette pure. Cépage méridional peu acide : vin rond et floral, à boire dans l'année, servi bien frais. Il accompagne les coquillages et les poissons de la Camargue voisine.","lat":43.75,"lon":4.52,"importance":1,"niveau":"decouverte"},{"id":"fr-cotes-du-vivarais","nom":"Côtes du Vivarais","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé léger de grenache et syrah, la moitié de la production."},{"couleur":"blanc","famille":"blanc_vif","note":"Clairette, grenache blanc, marsanne : simple et frais."}],"cepages":["Syrah","Grenache","Cinsault"],"style":"Fruits rouges frais, poivre, violette ; corps léger à moyen, tanins fins, finale désaltérante.","temp":"14 à 16 °C","garde":"2 à 4 ans","prix":1,"accords":["charcuterie","grille","volaille","legumes","fromage_chevre","porc"],"eviter":["gibier","huitre"],"classique":"Côtes du Vivarais et caillette ardéchoise","note":"Petite AOC de 1999 sur les plateaux calcaires de l'Ardèche méridionale, autour des gorges et de l'aven d'Orgnac, à 200 ou 300 m d'altitude. Syrah et grenache à parts égales : un rouge léger et poivré, loin de l'opulence du Vaucluse. Vin de pique-nique et de charcuterie locale, à servir frais.","lat":44.35,"lon":4.45,"importance":1,"niveau":"decouverte"},{"id":"fr-duche-d-uzes","nom":"Duché d'Uzès","pays":"France","region":"Vallée du Rhône","sousRegion":"Rhône méridional","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Viognier et grenache blanc obligatoires : abricot, fleurs, bouche ronde."},{"couleur":"rose","famille":"rose","note":"Rosé de grenache et syrah, frais et fruité."}],"cepages":["Syrah","Grenache","Mourvèdre","Carignan"],"style":"Fruits noirs, garrigue, poivre, un trait de réglisse ; tanins souples, corps moyen.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["grille","charcuterie","volaille","mijote","mediterraneen","fromage_chevre"],"eviter":["huitre","poisson_cru"],"classique":"Duché d’Uzès et poulet grillé aux herbes de garrigue","note":"Jeune AOC (2013) autour d'Uzès, dans le Gard, entre les garrigues et les vallées du Gardon. Syrah et grenache dominent le rouge ; le blanc impose le viognier, signe de la proximité du Rhône nord. Rouge souple et épicé à petit prix, pour la cuisine gardoise, brandade ou grillade.","lat":44.01,"lon":4.42,"importance":1,"niveau":"decouverte"},{"id":"ge-kakheti-saperavi","nom":"Kakhétie Saperavi","pays":"Géorgie","region":"Kakhétie","sousRegion":"Mukuzani, Kindzmarauli, Napareuli","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Kindzmarauli : Saperavi demi-doux naturel, mûre et cerise noire, très populaire en Géorgie."},{"couleur":"rouge","famille":"rouge_puissant","note":"Saperavi vinifié en qvevri : plus brut, tanins marqués, notes de cerise noire et de terre."}],"cepages":["Saperavi"],"style":"Rouge très sombre, dense et frais : mûre, cerise noire, prune, réglisse, poivre ; tanins fermes, acidité haute.","temp":"16 à 18 °C","garde":"5 à 20 ans","prix":2,"accords":["viande_rouge","agneau","grille","gibier","herbes","fromage_dure"],"eviter":["huitre","poisson_maigre","fruits_exotiques"],"classique":"Saperavi de Mukuzani et mtsvadi (brochettes de porc au feu de sarments)","note":"La Kakhétie, à l'est de la Géorgie au pied du Caucase, porte les trois quarts des vignes d'un pays qui fait du vin depuis 8 000 ans. Le Saperavi est un cépage à pulpe rouge, d'où une robe presque noire ; il reste frais et tannique malgré la chaleur. Mukuzani en est le cru sec élevé en fût.","lat":41.92,"lon":45.47,"importance":4,"niveau":"incontournable"},{"id":"ge-rkatsiteli-qvevri","nom":"Rkatsiteli en qvevri","pays":"Géorgie","region":"Kakhétie","sousRegion":"Kvareli, Telavi","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Rkatsiteli vinifié à l'européenne, sans peaux : blanc sec simple, pomme et agrumes, à boire jeune."},{"couleur":"blanc","famille":"blanc_ample","note":"Kisi et Mtsvane en qvevri : mêmes méthodes, plus aromatiques (abricot, fleurs)."}],"cepages":["Rkatsiteli","Mtsvane","Kisi"],"style":"Blanc ambré, tannique et sec : abricot sec, noix, thé noir, écorce d'orange, miel sans sucre ; finale astringente.","temp":"12 à 14 °C","garde":"3 à 10 ans","prix":2,"accords":["volaille","porc","noix","fromage_dure","herbes","legumes"],"eviter":["huitre","patisserie","glace"],"classique":"Rkatsiteli ambré et poulet aux noix (satsivi)","note":"Le qvevri est une jarre d'argile enterrée, inscrite à l'Unesco en 2013 : le moût y fermente et vieillit six mois sur ses peaux, d'où une robe ambrée et des tanins. Le Rkatsiteli, cépage blanc dominant de Kakhétie, est la base de ces vins « orange ». Servir frais, sur plats aux noix et volailles.","lat":41.95,"lon":45.81,"importance":3,"niveau":"classique"},{"id":"gr-retsina","nom":"Retsina","pays":"Grèce","region":"Attique","sousRegion":"Mesogaia","couleur":"blanc","famille":"blanc_aromatique","variantes":[{"couleur":"rose","famille":"rose","note":"Kokkineli : retsina rosée, plus rare, même résine sur un fruit rouge léger."}],"cepages":["Savatiano","Roditis","Assyrtiko"],"style":"Blanc sec résiné : pin, romarin, citron, pomme ; corps léger, finale amère et fraîche.","temp":"7 à 9 °C","garde":"1 à 2 ans","prix":1,"accords":["frit","mediterraneen","poisson_gras","legumes","herbes","fromage_frais"],"eviter":["viande_rouge","patisserie","chocolat"],"classique":"Retsina et petits poissons frits (marides) avec tzatziki","note":"Héritière des amphores scellées à la résine de l'Antiquité, la retsina est un blanc auquel on ajoute de la résine de pin d'Alep pendant la fermentation. L'Attique, autour d'Athènes, en est le berceau, sur le Savatiano. Vin de taverne, elle revient en version fine. Très froide, sur fritures.","lat":37.9,"lon":23.87,"importance":3,"niveau":"classique"},{"id":"gr-santorin-assyrtiko","nom":"Santorin Assyrtiko","pays":"Grèce","region":"Cyclades","sousRegion":"Santorin","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Vinsanto : Assyrtiko et Aidani séchés au soleil, ambré, caramel, abricot, acidité intacte."},{"couleur":"blanc","famille":"blanc_ample","note":"Nykteri : vendangé la nuit, élevé en fût, plus riche et alcoolisé."}],"cepages":["Assyrtiko","Athiri","Aidani"],"style":"Blanc sec, très tendu et salin : citron, pamplemousse, silex, fumée volcanique ; acidité haute malgré 13 à 14 degrés.","temp":"9 à 11 °C","garde":"3 à 10 ans","prix":3,"accords":["huitre","crustace","poisson_gras","poisson_maigre","fromage_chevre","beurre_citron"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Assyrtiko de Santorin et poulpe grillé au citron","note":"Sur Santorin, les vignes d'Assyrtiko poussent franches de pied, tressées en paniers (kouloura) au ras du sol contre le vent, sur pierre ponce et cendres du volcan. Le résultat est un blanc d'une acidité rare pour le sud, fumé et salé. Vin de poisson et de poulpe grillés ; il vieillit bien.","lat":36.38,"lon":25.45,"importance":4,"niveau":"incontournable"},{"id":"gr-samos-muscat","nom":"Samos Muscat","pays":"Grèce","region":"Égée orientale","sousRegion":"Samos","couleur":"doux","famille":"vdn","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Samos Nectar : raisins séchés au soleil, non muté, élevé trois ans en fût, caramel et abricot."},{"couleur":"blanc","famille":"blanc_aromatique","note":"Muscat sec de Samos : léger, raisin frais et fleurs, à boire jeune."}],"cepages":["Muscat blanc à petits grains"],"style":"Doux muté, doré : raisin frais, abricot, miel, fleur d'oranger, zeste d'orange ; sucre franc, finale fraîche.","temp":"8 à 10 °C","garde":"3 à 15 ans","prix":1,"accords":["fruits_jaunes","patisserie","fromage_bleu","foie_gras","fruits_exotiques","cremeux"],"eviter":["viande_rouge","huitre","amer"],"classique":"Samos Vin Doux et baklava","note":"Sur l'île de Samos, face à la Turquie, le Muscat blanc à petits grains pousse en terrasses jusqu'à 900 m sur le mont Ambelos. Le Samos Vin Doux est muté à l'alcool, comme un muscat de Rivesaltes, ce qui garde le raisin frais et le miel. Vin de desserts aux fruits et de baklava.","lat":37.76,"lon":26.9,"importance":3,"niveau":"classique"},{"id":"gr-robola-cephalonie","nom":"Robola de Céphalonie","pays":"Grèce","region":"Îles Ioniennes","sousRegion":"Céphalonie","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Robola"],"style":"Blanc sec, droit et citronné : citron, pomme verte, pierre à fusil, pointe fumée ; acidité élevée, finale saline.","temp":"9 à 11 °C","garde":"2 à 6 ans","prix":2,"accords":["poisson_maigre","coquillage","crustace","beurre_citron","legumes","fromage_chevre"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Robola et daurade grillée au citron","note":"Sur Céphalonie, dans la mer Ionienne, la Robola pousse franche de pied sur les pentes calcaires du mont Ainos et la vallée d'Omala, jusqu'à 800 m. Les Vénitiens l'appelaient « vino di sasso », vin de pierre. Blanc tendu et citronné, sans parenté prouvée avec la Ribolla, pour poissons et coquillages.","lat":38.17,"lon":20.58,"importance":2,"niveau":"decouverte"},{"id":"gr-naoussa","nom":"Naoussa Xinomavro","pays":"Grèce","region":"Macédoine","sousRegion":"Naoussa","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé et « blanc de noirs » de Xinomavro : fraise, acidité vive, versions récentes."}],"cepages":["Xinomavro"],"style":"Rouge pâle mais tannique : tomate séchée, olive, cerise, violette, cuir ; acidité haute, tanins secs, longue garde.","temp":"16 à 18 °C","garde":"5 à 20 ans","prix":2,"accords":["agneau","roti","gibier","mijote","tomate","fromage_dure"],"eviter":["poisson_maigre","huitre","patisserie"],"classique":"Naoussa et agneau au four aux tomates et herbes","note":"Naoussa, sur les contreforts du mont Vermio en Macédoine grecque, est l'appellation phare du Xinomavro (« noir acide »), souvent comparé au Nebbiolo : robe claire, tanins fermes, acidité haute, tomate séchée et violette, longue garde. À carafer ou à attendre, sur agneau et plats mijotés à la tomate.","lat":40.63,"lon":22.07,"importance":3,"niveau":"classique"},{"id":"gr-nemea","nom":"Nemea Agiorgitiko","pays":"Grèce","region":"Péloponnèse","sousRegion":"Nemea","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Cuvées des hauteurs (Koutsi, Asprokambos) élevées en fût : plus denses, cassis et épices, 10 ans de garde."},{"couleur":"rose","famille":"rose","note":"Rosé d'Agiorgitiko : fraise et groseille, rond, apéritif."}],"cepages":["Agiorgitiko"],"style":"Rouge souple et fruité : cerise, fraise, prune, épices douces, pointe de vanille ; tanins veloutés, acidité modérée.","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":2,"accords":["agneau","porc","mijote","tomate","mediterraneen","charcuterie"],"eviter":["huitre","poisson_cru","fruits_exotiques"],"classique":"Nemea et moussaka","note":"Nemea, à l'est du Péloponnèse près de Corinthe, est la plus grande appellation rouge de Grèce ; l'Agiorgitiko (« de Saint-Georges ») en est le seul cépage. Le « sang d'Hercule » est un rouge souple et velouté, plus frais quand les vignes montent à 900 m. Vin de moussaka, d'agneau et de tomate.","lat":37.81,"lon":22.66,"importance":3,"niveau":"classique"},{"id":"gr-mantinia","nom":"Mantinia Moschofilero","pays":"Grèce","region":"Péloponnèse","sousRegion":"Mantinia","couleur":"blanc","famille":"blanc_aromatique","variantes":[{"couleur":"bulles","famille":"bulles","note":"Moschofilero effervescent (méthode traditionnelle ou cuve close) : rose et agrumes, apéritif."},{"couleur":"rose","famille":"rose","note":"Rosé de Moschofilero (peau grise) : pâle, floral, très frais."}],"cepages":["Moschofilero"],"style":"Blanc sec, léger et parfumé : rose, fleur d'oranger, litchi, citron vert ; acidité vive, alcool faible.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":2,"accords":["legumes","poisson_maigre","asiatique","fromage_frais","herbes","agrumes"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Mantinia et salade grecque à la feta","note":"Le plateau de Mantinia, en Arcadie au centre du Péloponnèse, est à 650 m d'altitude : vendanges en octobre, vins légers en alcool. Le Moschofilero, à peau grise, est aromatique comme un muscat par ses parfums de rose, mais sec et vif. Vin d'apéritif, de mezze et de cuisine aux herbes.","lat":37.51,"lon":22.37,"importance":2,"niveau":"decouverte"},{"id":"gr-mavrodaphne-patras","nom":"Mavrodaphne de Patras","pays":"Grèce","region":"Péloponnèse","sousRegion":"Patras","couleur":"doux","famille":"vdn","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Mavrodaphne vinifié en sec, tendance récente : rouge sombre, mûre, cuir, tanins fermes."}],"cepages":["Mavrodaphne","Korinthiaki"],"style":"Rouge doux muté, oxydatif : raisin sec, figue, chocolat, café, noix ; sucre rond, chaleur, finale longue.","temp":"12 à 14 °C","garde":"5 à 30 ans","prix":1,"accords":["chocolat","fromage_bleu","noix","caramel","patisserie","fruits_rouges"],"eviter":["huitre","poisson_maigre","acide"],"classique":"Mavrodaphne de Patras et gâteau au chocolat","note":"Autour de Patras, au nord du Péloponnèse, le Mavrodaphne (« laurier noir ») est muté puis élevé en fût au soleil, méthode mise au point par Gustav Clauss en 1873. Il rappelle un porto tawny ou un Banyuls rancio : figue, noix, chocolat. Vin de dessert au chocolat et de fromages bleus.","lat":38.25,"lon":21.73,"importance":2,"niveau":"decouverte"},{"id":"hu-somlo","nom":"Somló","pays":"Hongrie","region":"Balaton","sousRegion":"Somló","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Juhfark","Furmint","Hárslevelű","Olaszrizling"],"style":"Blanc sec et austère : fumée, pierre chaude, coing, miel sans sucre ; acidité haute, texture dense, finale salée.","temp":"10 à 12 °C","garde":"5 à 15 ans","prix":2,"accords":["volaille","poisson_gras","champignon","fromage_dure","creme","fume"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Somló Juhfark et poulet paprikás à la crème","note":"Somló est un ancien volcan isolé au nord-ouest du Balaton, le plus petit vignoble de Hongrie. Le basalte donne des blancs fumés, tendus et salins, dont le Juhfark (« queue de mouton »), cépage qu'on ne trouve presque qu'ici. Vins de garde, à ouvrir après quelques années sur une volaille à la crème.","lat":47.13,"lon":17.37,"importance":2,"niveau":"decouverte"},{"id":"hu-egri-bikaver","nom":"Egri Bikavér","pays":"Hongrie","region":"Haute-Hongrie","sousRegion":"Eger","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Egri Csillag, l'« étoile d'Eger » : assemblage blanc sec, pendant du Bikavér."}],"cepages":["Kékfrankos","Kadarka","Merlot","Cabernet Franc"],"style":"Rouge d'assemblage, fruité et épicé : cerise, mûre, poivre, pointe de fumée ; tanins souples, acidité fraîche.","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":1,"accords":["mijote","porc","epice_douce","charcuterie","viande_rouge","champignon"],"eviter":["huitre","poisson_cru","patisserie"],"classique":"Egri Bikavér et goulasch au paprika","note":"Le « sang de taureau » d'Eger, au nord de la Hongrie, assemble au moins quatre cépages dominés par le Kékfrankos (Blaufränkisch), élevés en fût dans des caves creusées dans le tuf. Il se reconnaît à sa cerise épicée et sa fraîcheur. Vin de goulasch, de mijotés et de charcuterie, dans ses cinq ans.","lat":47.9,"lon":20.37,"importance":3,"niveau":"classique"},{"id":"hu-villany","nom":"Villány","pays":"Hongrie","region":"Pannonie","sousRegion":"Villány-Siklós","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Portugieser (Kékoportó) : rouge léger et fruité à boire jeune, souvent en vin de soif."}],"cepages":["Cabernet Franc","Kékfrankos","Merlot","Cabernet Sauvignon"],"style":"Rouge charpenté, mûr et boisé : cassis, prune, poivron grillé, cèdre ; tanins denses et finale chaleureuse.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["viande_rouge","agneau","gibier","grille","roti","fromage_dure"],"eviter":["huitre","poisson_maigre","fruits_exotiques"],"classique":"Villányi Franc et côte de bœuf grillée","note":"À l'extrême sud de la Hongrie, près de la Croatie, Villány est la région la plus chaude du pays : calcaire et loess, étés longs. Le Cabernet Franc y donne un style mûr et dense, labellisé « Villányi Franc ». Vin de viandes rouges et de gibier, à attendre quelques années pour fondre le bois.","lat":45.87,"lon":18.45,"importance":3,"niveau":"classique"},{"id":"hu-tokaji-aszu","nom":"Tokaji Aszú","pays":"Hongrie","region":"Tokaj","sousRegion":"","couleur":"doux","famille":"blanc_doux","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Tokaji Eszencia : nectar des seules baies aszú, quasi sirop, cuvée de collection."},{"couleur":"doux","famille":"blanc_doux","note":"Tokaji Szamorodni édes : vendange entière partiellement botrytisée, moins riche."}],"cepages":["Furmint","Hárslevelű","Sárgamuskotály"],"style":"Liquoreux ambré : abricot sec, miel, coing, safran, écorce d'orange ; sucre porté par une acidité tranchante.","temp":"10 à 12 °C","garde":"15 à 50 ans","prix":3,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","caramel","sucre_sale"],"eviter":["viande_rouge","piquant","chocolat"],"classique":"Tokaji Aszú 5 puttonyos et foie gras poêlé","note":"Au pied des Carpates, les brumes de la Bodrog et de la Tisza favorisent la pourriture noble sur le Furmint. Les baies aszú, cueillies une à une, macèrent dans un vin de base ; les puttonyos mesuraient leur richesse. Abricot sec et miel tenus par une acidité vive. Vin de fin de repas, servi frais.","lat":48.12,"lon":21.41,"importance":5,"niveau":"incontournable"},{"id":"hu-tokaj-furmint-sec","nom":"Tokaj Furmint sec","pays":"Hongrie","region":"Tokaj","sousRegion":"Mád, Tarcal, Tolcsva","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Cuvées parcellaires élevées en fût : plus larges, notes de poire mûre et de fumée."}],"cepages":["Furmint","Hárslevelű"],"style":"Sec, tendu, fumé : poire, coing, citron, pierre à fusil ; acidité élevée, finale saline et légèrement amère.","temp":"9 à 11 °C","garde":"3 à 10 ans","prix":2,"accords":["poisson_maigre","crustace","volaille","fromage_chevre","asperge","beurre_citron"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Furmint sec de Mád et sandre du Balaton au beurre citronné","note":"Depuis les années 2000, Tokaj vinifie le Furmint en sec sur ses sols volcaniques (rhyolite, zéolite), et les crus de Mád ou Tarcal se dégustent comme des villages de Bourgogne. On le reconnaît à sa tension, son fumé minéral et sa poire sans sucre. À servir sur un poisson d'eau douce ou une volaille.","lat":48.19,"lon":21.28,"importance":3,"niveau":"classique"},{"id":"in-nashik","nom":"Nashik","pays":"Inde","region":"Maharashtra","sousRegion":"Nashik","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Shiraz et Cabernet souples, souvent un peu sucrés."},{"couleur":"bulles","famille":"bulles","note":"Effervescents de méthode traditionnelle (Chandon India, Sula Brut)."}],"cepages":["Sauvignon blanc","Chenin blanc","Shiraz","Cabernet Sauvignon"],"style":"Sauvignon tropical : fruit de la passion, citron vert, herbe coupée ; Chenin demi-sec facile à boire.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":2,"accords":["curry","asiatique","epice_douce","volaille","legumes","piquant"],"eviter":["viande_rouge","fromage_bleu","sauce_vin_rouge"],"classique":"Sauvignon de Nashik et poulet tikka","note":"À 600 m sur le plateau du Deccan, à trois heures de Mumbai, Nashik est la « capitale du vin » indienne depuis que Sula a planté ses premières vignes en 1997. Vendanges en février, avant la mousson. Les blancs vifs, parfois un peu sucrés, tiennent face aux épices ; le marché reste surtout domestique.","lat":19.99,"lon":73.79,"importance":2,"niveau":"decouverte"},{"id":"il-collines-de-judee","nom":"Collines de Judée","pays":"Israël","region":"Collines de Judée","sousRegion":"","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay élevé en fût, comme le « C » du Domaine du Castel."}],"cepages":["Cabernet Sauvignon","Merlot","Petit Verdot"],"style":"Cassis, cèdre, tabac blond et graphite ; tanins fins, élevage soigné, le plus bordelais des rouges israéliens.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":4,"accords":["viande_rouge","agneau","roti","sauce_vin_rouge","truffe","fromage_dure"],"eviter":["poisson_maigre","huitre","piquant"],"classique":"Grand Vin de Castel et carré d'agneau rôti","note":"À l'ouest de Jérusalem, les collines calcaires de Judée montent à 700 m ; des terrasses y portaient déjà des vignes à l'époque biblique. Domaine du Castel, créé en 1988 par Eli Ben Zaken, a montré qu'un assemblage bordelais pouvait y vieillir avec élégance. Rouges fins, prix élevés.","lat":31.75,"lon":35.05,"importance":3,"niveau":"classique"},{"id":"il-galilee","nom":"Galilée","pays":"Israël","region":"Galilée","sousRegion":"Haute-Galilée","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Syrah","Merlot","Petit Verdot"],"style":"Fruits noirs, garrigue, poivre et un boisé net ; tanins serrés, bouche dense mais tenue par l'altitude.","temp":"16 à 18 °C","garde":"4 à 12 ans","prix":3,"accords":["viande_rouge","agneau","grille","mijote","mediterraneen","fromage_dure"],"eviter":["poisson_cru","huitre","sucre_sale"],"classique":"Rouge de Haute-Galilée et kebab d'agneau au feu de bois","note":"La Haute-Galilée, autour de Safed et de la vallée de Kadesh, est avec le Golan la région la plus plantée d'Israël : collines calcaires et basaltiques jusqu'à 900 m. Galil Mountain, Recanati ou Dalton y font des rouges d'assemblage bordelais ou rhodanien, denses et épicés.","lat":33.03,"lon":35.48,"importance":2,"niveau":"decouverte"},{"id":"il-golan","nom":"Golan","pays":"Israël","region":"Plateau du Golan","sousRegion":"","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay et Sauvignon blanc d'altitude, souvent boisés."},{"couleur":"bulles","famille":"bulles","note":"Effervescents de méthode traditionnelle (Yarden Blanc de Blancs)."}],"cepages":["Cabernet Sauvignon","Merlot","Syrah"],"style":"Cassis, mûre, menthe et cèdre ; corps plein, tanins mûrs et bois toasté, dans l'esprit californien.","temp":"16 à 18 °C","garde":"5 à 12 ans","prix":3,"accords":["viande_rouge","agneau","grille","roti","sauce_vin_rouge","fromage_dure"],"eviter":["huitre","poisson_maigre","piquant"],"classique":"Cabernet du Golan et côtelettes d'agneau grillées","note":"Sur les sols volcaniques du plateau du Golan, entre 400 et 1 200 m d'altitude, les vignes profitent de nuits froides et parfois de neige. Golan Heights Winery (marque Yarden) a lancé la viticulture moderne israélienne en 1983 avec des Cabernet de style californien. Rouges mûrs mais frais.","lat":32.99,"lon":35.69,"importance":3,"niveau":"classique"},{"id":"it-montepulciano-d-abruzzo","nom":"Montepulciano d'Abruzzo","pays":"Italie","region":"Abruzzes","sousRegion":"","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Colline Teramane DOCG et Riserva, plus denses et de garde"}],"cepages":["Montepulciano"],"style":"Robe sombre, mûre, prune, violette, réglisse ; tanins moelleux, acidité modérée, rouge facile et généreux.","temp":"16 à 18 °C","garde":"2 à 8 ans","prix":1,"accords":["charcuterie","grille","mijote","porc","agneau","tomate"],"eviter":["poisson_cru","huitre"],"classique":"Montepulciano d'Abruzzo et arrosticini (brochettes de mouton)","note":"Le cépage Montepulciano, cultivé entre Apennins et Adriatique, rien à voir avec la ville toscane. Rouge sombre, mûre, prune, violette, tanins moelleux et acidité modérée : l'un des rouges les plus faciles et abordables d'Italie. Les grands producteurs (Valentini, Emidio Pepe) font des vins de garde.","lat":42.35,"lon":14.17,"importance":4,"niveau":"incontournable"},{"id":"it-trebbiano-d-abruzzo","nom":"Trebbiano d'Abruzzo","pays":"Italie","region":"Abruzzes","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Trebbiano abruzzese","Trebbiano toscano"],"style":"Pomme, citron, fleurs, légère amertume ; blanc simple et frais, ou cireux et salin chez les grands.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":1,"accords":["poisson_maigre","coquillage","legumes","frit","fromage_frais","vapeur"],"eviter":["viande_rouge","gibier"],"classique":"Trebbiano d'Abruzzo et brodetto (soupe de poissons)","note":"Blanc simple en général : pomme, citron, fleurs, légère amertume, à boire dans l'année sur poissons et légumes. Mais le Trebbiano abruzzese, cépage distinct du toscan, donne chez Valentini ou Emidio Pepe des vins de garde étonnants, cireux et salins. Deux visages pour un même nom.","lat":42.43,"lon":13.99,"importance":3,"niveau":"classique"},{"id":"it-cerasuolo-d-abruzzo","nom":"Cerasuolo d'Abruzzo","pays":"Italie","region":"Abruzzes","sousRegion":"","couleur":"rose","famille":"rose","variantes":[],"cepages":["Montepulciano"],"style":"Robe cerise soutenue, fruits rouges, amande, pointe tannique ; rosé de corps, frais et sapide.","temp":"10 à 12 °C","garde":"1 à 3 ans","prix":1,"accords":["charcuterie","grille","poisson_gras","tomate","mediterraneen","porc"],"eviter":["sucre_sale","chocolat"],"classique":"Cerasuolo et pizza","note":"Rosé de Montepulciano obtenu par courte macération, d'où une robe cerise soutenue (cerasa). Plus de corps et de tanin qu'un rosé de Provence : fruits rouges, amande, finale fraîche. Il tient tête aux plats de l'Adriatique et aux grillades ; servir frais, à 10 ou 12 °C, dans l'année.","lat":42.4,"lon":14.1,"importance":2,"niveau":"decouverte"},{"id":"it-aglianico-del-vulture","nom":"Aglianico del Vulture","pays":"Italie","region":"Basilicate","sousRegion":"Vulture","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Aglianico"],"style":"Mûre, violette, cendre, réglisse ; tanins serrés, acidité vive, corps dense, un peu sauvage.","temp":"17 à 18 °C","garde":"5 à 20 ans","prix":2,"accords":["viande_rouge","agneau","mijote","grille","fromage_dure","gibier"],"eviter":["poisson_maigre","coquillage"],"classique":"Aglianico del Vulture et agneau braisé","note":"Sur les pentes du Vulture, volcan éteint de Basilicate, l'Aglianico pousse à 400-700 m d'altitude. Rouge dense, mûre, violette, cendre, tanins serrés et acidité vive ; vendange en novembre. Moins cher et un peu plus sauvage que le Taurasi. Agneau, viandes braisées, pecorino affiné.","lat":40.93,"lon":15.67,"importance":3,"niveau":"classique"},{"id":"it-ciro","nom":"Cirò","pays":"Italie","region":"Calabre","sousRegion":"Côte ionienne","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Cirò Bianco au Greco bianco"},{"couleur":"rose","famille":"rose","note":"Cirò Rosato"}],"cepages":["Gaglioppo"],"style":"Robe claire, grenat, rose séchée, cerise, orange ; tanins secs, acidité vive, proche d'un Nebbiolo du Sud.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":2,"accords":["agneau","porc","grille","charcuterie","piquant","fromage_dure"],"eviter":["poisson_maigre","huitre"],"classique":"Cirò et 'nduja (charcuterie piquante de Calabre)","note":"Le plus ancien vin de Calabre, sur la côte ionienne, offert dit-on aux athlètes des Jeux olympiques antiques. Le Gaglioppo donne un rouge clair, grenat, rose séchée, cerise, tanins secs et acidité vive, proche d'un Nebbiolo du Sud. Charcuteries épicées, agneau, porc. Boire dans les cinq ans.","lat":39.37,"lon":17.13,"importance":2,"niveau":"decouverte"},{"id":"it-falanghina","nom":"Falanghina del Sannio","pays":"Italie","region":"Campanie","sousRegion":"Sannio","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"bulles","famille":"bulles","note":"Falanghina spumante, effervescent méthode Charmat"}],"cepages":["Falanghina"],"style":"Agrumes, pomme verte, fleurs, pointe saline ; blanc frais, simple et net, à boire jeune.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":1,"accords":["poisson_maigre","coquillage","frit","legumes","fromage_frais","herbes"],"eviter":["viande_rouge","gibier"],"classique":"Falanghina et mozzarella di bufala","note":"Cépage campanien replanté massivement depuis les années 1990, cultivé autour de Bénévent (Sannio) et dans les Campi Flegrei. Blanc frais et simple : agrumes, pomme verte, fleurs, pointe saline. Le blanc de tous les jours de Naples, sur mozzarella, friture et pizza blanche, à boire dans les deux ans.","lat":41.13,"lon":14.78,"importance":3,"niveau":"classique"},{"id":"it-fiano-di-avellino","nom":"Fiano di Avellino","pays":"Italie","region":"Campanie","sousRegion":"Irpinia","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Fiano"],"style":"Poire, noisette, miel, fumée ; texture ample, acidité qui porte, finale longue, blanc de garde.","temp":"10 à 12 °C","garde":"3 à 10 ans","prix":2,"accords":["poisson_gras","crustace","volaille","champignon","noix","creme"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Fiano di Avellino et pâtes aux fruits de mer","note":"Cépage antique d'Irpinia (Campanie), cultivé en altitude sur sols volcaniques. Blanc sec et ample : poire, noisette, miel, fumée, acidité qui le porte dix ans. Le plus riche des trois blancs campaniens, le Greco étant plus tendu et la Falanghina plus simple. Poissons gras, volaille, champignons.","lat":40.91,"lon":14.79,"importance":3,"niveau":"classique"},{"id":"it-greco-di-tufo","nom":"Greco di Tufo","pays":"Italie","region":"Campanie","sousRegion":"Irpinia","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Greco","Coda di Volpe"],"style":"Pêche, agrumes, fumée, pierre ; tendu, minéral, finale amère et saline, plus droit que le Fiano.","temp":"10 à 12 °C","garde":"2 à 8 ans","prix":2,"accords":["crustace","coquillage","poisson_maigre","frit","legumes","agrumes"],"eviter":["viande_rouge","gibier"],"classique":"Greco di Tufo et friture de calamars","note":"Autour du village de Tufo, bâti sur du tuf volcanique et des mines de soufre, en Irpinia. Le Greco donne un blanc tendu, pêche, agrumes, note fumée et minérale, finale amère et saline. Plus droit que le Fiano voisin. Crustacés, coquillages et fritures ; les meilleurs vieillissent cinq à huit ans.","lat":41.01,"lon":14.82,"importance":3,"niveau":"classique"},{"id":"it-lacryma-christi-del-vesuvio","nom":"Lacryma Christi del Vesuvio","pays":"Italie","region":"Campanie","sousRegion":"Vésuve","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Lacryma Christi Bianco, Coda di Volpe et Falanghina, frais et salin"},{"couleur":"rose","famille":"rose","note":"Lacryma Christi Rosato"}],"cepages":["Piedirosso","Aglianico"],"style":"Cerise, fruits rouges, pierre à fusil, herbes ; rouge léger, sapide, tanins fins, acidité fraîche.","temp":"15 à 17 °C","garde":"2 à 5 ans","prix":2,"accords":["tomate","porc","charcuterie","grille","mediterraneen","fromage_molle"],"eviter":["poisson_cru","sucre_sale"],"classique":"Lacryma Christi et pizza napolitaine","note":"Sur les pentes du Vésuve, au-dessus de Naples : sols de lave et de cendres, vignes franches de pied. Le rouge (Piedirosso) est léger et sapide, cerise, pierre à fusil ; le blanc (Coda di Volpe) frais et salin. La légende dit que le Christ y pleura sur le golfe. Pizza, pâtes à la tomate, charcuterie.","lat":40.82,"lon":14.43,"importance":3,"niveau":"classique"},{"id":"it-taurasi","nom":"Taurasi","pays":"Italie","region":"Campanie","sousRegion":"Irpinia","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Aglianico"],"style":"Cerise noire, fumée, goudron, cuir ; acidité haute, tanins fermes et serrés, grande garde.","temp":"17 à 18 °C","garde":"10 à 25 ans","prix":3,"accords":["viande_rouge","gibier","mijote","roti","fromage_dure","truffe"],"eviter":["poisson_maigre","coquillage","cru"],"classique":"Taurasi et ragù napolitain","note":"Le « Barolo du Sud », sur les collines volcaniques d'Irpinia, à l'est de Naples. Aglianico vendangé tard, trois ans d'élevage minimum : cerise noire, fumée, goudron, acidité haute et tanins fermes qui demandent dix ans. Mastroberardino l'a fait connaître. Viandes braisées, gibier, fromages affinés.","lat":41.01,"lon":14.96,"importance":3,"niveau":"classique"},{"id":"it-lambrusco","nom":"Lambrusco","pays":"Italie","region":"Émilie-Romagne","sousRegion":"Modène et Reggio Emilia","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"rose","famille":"rose","note":"Lambrusco rosato, pétillant pâle et fraise, surtout à Sorbara"}],"cepages":["Lambrusco di Sorbara","Lambrusco Grasparossa","Lambrusco Salamino"],"style":"Rouge pétillant sec : fraise, cerise, violette, mousse rouge, tanins légers (Sorbara) à charnus (Grasparossa).","temp":"8 à 12 °C","garde":"1 à 2 ans","prix":1,"accords":["charcuterie","porc","fromage_dure","frit","mijote","tomate"],"eviter":["poisson_cru","huitre","chocolat"],"classique":"Lambrusco et gnocco fritto au jambon de Parme","note":"Autour de Modène et Reggio Emilia, plusieurs lambruschi autochtones donnent un rouge pétillant sec, vinifié en cuve close, qui tranche le gras de la cuisine émilienne. Le Sorbara est clair et acidulé, le Grasparossa sombre et tannique. Rien à voir avec les versions sucrées des années 1980.","lat":44.65,"lon":10.93,"importance":4,"niveau":"classique"},{"id":"it-romagna-albana","nom":"Romagna Albana","pays":"Italie","region":"Émilie-Romagne","sousRegion":"Romagne","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Albana passito, raisins séchés, abricot, miel et safran"}],"cepages":["Albana"],"style":"Abricot, pêche jaune, fleurs et miel, bouche ample et sèche avec une légère astringence inhabituelle pour un blanc.","temp":"10 à 12 °C","garde":"2 à 6 ans","prix":2,"accords":["poisson_gras","volaille","charcuterie","fromage_dure","creme","legumes"],"eviter":["viande_rouge","huitre"],"classique":"Albana secco et piadina au squacquerone","note":"Premier blanc italien élevé en DOCG (1987), l'albana pousse sur les collines de Bertinoro et Forlì, entre Bologne et Rimini. Cépage à peau épaisse, il donne un blanc sec un peu tannique, à la robe dorée, et un passito doux remarquable. Longtemps sous-estimé, il revient avec des macérations courtes.","lat":44.15,"lon":12.14,"importance":2,"niveau":"decouverte"},{"id":"it-collio","nom":"Collio","pays":"Italie","region":"Frioul-Vénétie Julienne","sousRegion":"Collio Goriziano","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Collio Rosso et Merlot, rouges frais et poivrés"}],"cepages":["Friulano","Ribolla gialla","Malvasia istriana","Pinot grigio"],"style":"Blancs d'assemblage ou monocépages, riches et secs : pêche, amande, miel léger, trame saline, finale longue.","temp":"10 à 12 °C","garde":"3 à 8 ans","prix":3,"accords":["poisson_gras","crustace","volaille","charcuterie","fromage_dure","creme"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Collio Bianco et frico (galette de Montasio et pommes de terre)","note":"Collines à cheval sur la frontière slovène, autour de Cormons et Gorizia, sur les mêmes marnes ponca que les Colli Orientali. Berceau des grands blancs italiens modernes (Gravner, Jermann, Schiopetto) et des vins orange macérés. Blancs plus denses et plus chers que la moyenne du Frioul.","lat":45.96,"lon":13.47,"importance":3,"niveau":"classique"},{"id":"it-friuli-colli-orientali-friulano","nom":"Friuli Colli Orientali (Friulano)","pays":"Italie","region":"Frioul-Vénétie Julienne","sousRegion":"Colli Orientali del Friuli","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Refosco dal peduncolo rosso et Schioppettino, rouges poivrés et frais"},{"couleur":"doux","famille":"blanc_doux","note":"Picolit et Ramandolo (verduzzo), raisins passerillés, DOCG"}],"cepages":["Friulano","Ribolla gialla","Sauvignon","Refosco"],"style":"Friulano : poire, amande fraîche, foin et fleurs blanches, bouche ample, sèche, finale légèrement amère.","temp":"9 à 11 °C","garde":"2 à 6 ans","prix":2,"accords":["charcuterie","poisson_maigre","asperge","legumes","fromage_dure","oeuf"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Friulano et prosciutto di San Daniele","note":"Sur les collines de « ponca » (marnes et grès en strates) autour de Cividale, le friulano, ex-tocai, est le blanc quotidien du Frioul, servi au comptoir avec le jambon de San Daniele. L'appellation couvre une vingtaine de cépages, blancs surtout, souvent en monocépage. Vin sec, rond, goût d'amande.","lat":46.09,"lon":13.43,"importance":2,"niveau":"decouverte"},{"id":"it-ribolla-gialla","nom":"Ribolla gialla","pays":"Italie","region":"Frioul-Vénétie Julienne","sousRegion":"Collio Goriziano","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Version macérée (vin orange), ambrée, tannique, abricot sec et thé"},{"couleur":"bulles","famille":"bulles","note":"Ribolla gialla spumante, bulle simple et citronnée"}],"cepages":["Ribolla gialla"],"style":"Citron, pomme verte, fleurs blanches, bouche légère et vive, acidité tranchante, finale saline.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":2,"accords":["huitre","coquillage","poisson_cru","poisson_maigre","frit","legumes"],"eviter":["viande_rouge","sauce_vin_rouge","mijote"],"classique":"Ribolla gialla et sardines frites de l'Adriatique","note":"Cépage ancien du Collio et de la Slovénie voisine (rebula), concentré autour d'Oslavia. Vinifié classiquement, il donne un blanc nerveux et citronné ; macéré sur peaux pendant des semaines, il devient le vin orange tannique rendu célèbre par Gravner et Radikon. Deux vins différents sous un même nom.","lat":45.97,"lon":13.59,"importance":2,"niveau":"decouverte"},{"id":"it-frascati","nom":"Frascati","pays":"Italie","region":"Latium","sousRegion":"Castelli Romani","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Cannellino di Frascati, version douce"}],"cepages":["Malvasia bianca di Candia","Trebbiano toscano","Malvasia del Lazio"],"style":"Fleurs blanches, pomme, amande, pointe d'agrumes ; sec, léger, simple, à boire frais et jeune.","temp":"8 à 10 °C","garde":"1 à 2 ans","prix":1,"accords":["poisson_maigre","frit","legumes","porc","fromage_frais","artichaut"],"eviter":["viande_rouge","gibier"],"classique":"Frascati et porchetta","note":"Le blanc des Castelli Romani, au sud-est de Rome, bu dans les trattorias depuis l'Antiquité. Sols volcaniques, Malvasia et Trebbiano : fleurs blanches, pomme, amande, léger et sec. À boire jeune et frais sur la cuisine romaine, artichauts, friture, porchetta. Le Cannellino en est la version douce.","lat":41.81,"lon":12.68,"importance":3,"niveau":"classique"},{"id":"it-cesanese-del-piglio","nom":"Cesanese del Piglio","pays":"Italie","region":"Latium","sousRegion":"Ciociaria","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Cesanese di Affile","Cesanese comune"],"style":"Cerise noire, poivre, violette, épices ; tanins souples, alcool présent, rouge chaleureux et parfumé.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["agneau","porc","roti","charcuterie","mijote","fromage_dure"],"eviter":["poisson_maigre","huitre"],"classique":"Cesanese et abbacchio (agneau de lait romain)","note":"Seul rouge DOCG du Latium, dans les collines de Ciociaria à l'est de Rome. Le Cesanese, cépage local, donne un rouge épicé : cerise noire, poivre, violette, tanins souples, alcool présent. Longtemps vinifié doux, il est aujourd'hui sec. Agneau rôti, porc, charcuterie, plats de la cuisine romaine.","lat":41.83,"lon":13.13,"importance":1,"niveau":"decouverte"},{"id":"it-cinque-terre","nom":"Cinque Terre","pays":"Italie","region":"Ligurie","sousRegion":"Riviera du Levant","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Sciacchetrà, raisins passerillés, miel, abricot et noix, très rare"}],"cepages":["Bosco","Albarola","Vermentino"],"style":"Agrumes, herbes de maquis, sel et amande, bouche sèche et légère, acidité moyenne, finale iodée.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":3,"accords":["poisson_maigre","coquillage","crustace","frit","herbes","mediterraneen"],"eviter":["viande_rouge","sauce_vin_rouge","gibier"],"classique":"Cinque Terre et anchois de Monterosso","note":"Sur les terrasses vertigineuses entre Monterosso et Riomaggiore, les vignes se vendangent en monorail. Le bosco, cépage local, domine l'assemblage avec albarola et vermentino : un blanc sec et salin. Le Sciacchetrà, doux de raisins séchés, est la rareté du lieu. Le prix suit le coût des vignes.","lat":44.12,"lon":9.7,"importance":2,"niveau":"decouverte"},{"id":"it-franciacorta","nom":"Franciacorta","pays":"Italie","region":"Lombardie","sousRegion":"Franciacorta","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"rose","famille":"bulles","note":"Franciacorta rosé, au moins 35 % de pinot noir, fruits rouges et vinosité"}],"cepages":["Chardonnay","Pinot nero","Pinot bianco"],"style":"Méthode traditionnelle : pomme mûre, brioche, noisette, bulle fine et crémeuse, moins acide qu'un champagne.","temp":"7 à 9 °C","garde":"2 à 8 ans","prix":3,"accords":["crustace","poisson_gras","frit","volaille","fromage_dure","cremeux"],"eviter":["viande_rouge","sauce_vin_rouge","piquant"],"classique":"Franciacorta et risotto au safran milanais","note":"Au sud du lac d'Iseo, la Franciacorta est la première DOCG italienne (1995) réservée à la méthode traditionnelle, 18 mois minimum sur lies. Le climat, plus doux qu'en Champagne, donne des bulles plus rondes. Le Satèn, sans pinot noir et à pression réduite, est sa cuvée la plus soyeuse.","lat":45.6,"lon":9.97,"importance":4,"niveau":"incontournable"},{"id":"it-lugana","nom":"Lugana","pays":"Italie","region":"Lombardie","sousRegion":"Lac de Garde","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Turbiana"],"style":"Agrumes, amande, fleurs blanches et touche saline, bouche droite et fraîche ; gagne en miel avec quelques années.","temp":"8 à 10 °C","garde":"2 à 6 ans","prix":2,"accords":["poisson_maigre","coquillage","crustace","vapeur","legumes","fromage_frais"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Lugana et poisson du lac de Garde grillé","note":"Au sud du lac de Garde, entre Sirmione et Peschiera, sur des argiles blanches, le turbiana (parent du verdicchio) donne un blanc sec et salin, longtemps bu sur place par les touristes allemands. Il tient bien trois ou quatre ans et prend des notes de miel et de cire. Un vin de poisson d'eau douce.","lat":45.45,"lon":10.66,"importance":3,"niveau":"classique"},{"id":"it-valtellina-superiore","nom":"Valtellina Superiore","pays":"Italie","region":"Lombardie","sousRegion":"Valtellina","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Sforzato di Valtellina, raisins passerillés, sec et puissant (14 % minimum)"}],"cepages":["Nebbiolo"],"style":"Nebbiolo alpin : fraise des bois, rose, herbes de montagne et pierre, tanins fins, corps léger, acidité fraîche.","temp":"15 à 17 °C","garde":"5 à 15 ans","prix":3,"accords":["viande_rouge","gibier","champignon","fromage_dure","charcuterie"],"eviter":["poisson_cru","piquant"],"classique":"Valtellina Superiore et pizzoccheri (pâtes de sarrasin au fromage)","note":"Dans la vallée de l'Adda, au nord de Bergame, le nebbiolo, appelé chiavennasca, pousse sur des terrasses de pierre sèche plein sud, à 300-700 m. Le vin est plus léger et plus floral que dans les Langhe. Cinq sous-zones (Sassella, Grumello, Inferno, Valgella, Maroggia) ; 24 mois d'élevage minimum.","lat":46.17,"lon":9.87,"importance":3,"niveau":"decouverte"},{"id":"it-oltrepo-pavese","nom":"Oltrepò Pavese","pays":"Italie","region":"Lombardie","sousRegion":"Oltrepò Pavese","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"bulles","famille":"bulles","note":"Oltrepò Pavese Metodo Classico, pinot noir majoritaire, DOCG"},{"couleur":"blanc","famille":"blanc_vif","note":"Riesling et pinot grigio secs, vifs et simples"}],"cepages":["Croatina","Barbera","Pinot nero","Riesling"],"style":"Bonarda (croatina) : mûre, prune, violette, tanins doux, souvent légèrement perlant ; rouge de table gourmand.","temp":"14 à 16 °C","garde":"1 à 5 ans","prix":1,"accords":["charcuterie","porc","mijote","tomate","fromage_dure"],"eviter":["poisson_cru","huitre"],"classique":"Bonarda dell'Oltrepò et salame di Varzi","note":"Au sud de Pavie, de l'autre côté du Pô, ces collines sont le premier vignoble de pinot noir d'Italie, surtout destiné aux bulles. Le rouge courant est la Bonarda, faite de croatina, souvent frizzante et bue sur la charcuterie locale. Zone vaste et inégale : choisir un producteur plutôt qu'un nom.","lat":45.01,"lon":9.13,"importance":2,"niveau":"decouverte"},{"id":"it-verdicchio-dei-castelli-di-jesi","nom":"Verdicchio dei Castelli di Jesi","pays":"Italie","region":"Marches","sousRegion":"Castelli di Jesi","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Riserva et vieilles vignes : plus de gras, garde 10 ans"},{"couleur":"bulles","famille":"bulles","note":"Verdicchio spumante"}],"cepages":["Verdicchio"],"style":"Citron, amande amère, fenouil, pomme verte ; acidité tendue, finale saline, gras avec l'âge.","temp":"10 à 12 °C","garde":"3 à 10 ans","prix":2,"accords":["poisson_maigre","coquillage","crustace","frit","legumes","fromage_frais"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Verdicchio et friture de poissons de l'Adriatique","note":"Collines derrière Ancône, dans les Marches. Le Verdicchio est l'un des grands blancs italiens de garde : citron, amande amère, fenouil, acidité tendue et finale saline. Jeune, il accompagne la friture ; les Riserva, en DOCG depuis 2010, gagnent miel et cire en vieillissant.","lat":43.48,"lon":13.15,"importance":3,"niveau":"classique"},{"id":"it-rosso-conero","nom":"Rosso Conero","pays":"Italie","region":"Marches","sousRegion":"Conero","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Conero Riserva DOCG, plus dense, 2 ans d'élevage"}],"cepages":["Montepulciano","Sangiovese"],"style":"Fruits noirs, réglisse, épices ; tanins ronds, chaleur tempérée par la mer, corps moyen à plein.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","grille","mijote","charcuterie","porc","fromage_dure"],"eviter":["poisson_maigre","huitre"],"classique":"Rosso Conero et vincisgrassi (lasagnes des Marches)","note":"Sur le promontoire calcaire du Conero, qui plonge dans l'Adriatique au sud d'Ancône. Montepulciano à 85 % minimum : fruits noirs, réglisse, tanins ronds, chaleur maîtrisée par la brise de mer. La version Riserva (Conero DOCG) tient dix ans. Un rouge de table pour grillades et pâtes au four.","lat":43.55,"lon":13.57,"importance":2,"niveau":"decouverte"},{"id":"it-montefalco-sagrantino","nom":"Montefalco Sagrantino","pays":"Italie","region":"Ombrie","sousRegion":"Montefalco","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Montefalco Rosso, Sangiovese dominant, plus abordable"},{"couleur":"doux","famille":"blanc_doux","note":"Sagrantino Passito, rouge doux historique"}],"cepages":["Sagrantino"],"style":"Mûre, prune noire, cuir, épices ; tanins parmi les plus puissants d'Italie, corps massif, longue garde.","temp":"17 à 18 °C","garde":"8 à 25 ans","prix":3,"accords":["viande_rouge","gibier","mijote","roti","fromage_dure","truffe"],"eviter":["poisson_maigre","coquillage","cru"],"classique":"Sagrantino et pigeon rôti","note":"Cépage ombrien cultivé autour du bourg de Montefalco, longtemps vinifié en passito doux. Le Sagrantino sec a parmi les tanins les plus puissants d'Italie : mûre, cuir, épices, trame serrée qui demande des années. Au moins 37 mois d'élevage. Gibier, viandes braisées, truffe noire d'Ombrie.","lat":42.89,"lon":12.65,"importance":3,"niveau":"classique"},{"id":"it-orvieto","nom":"Orvieto","pays":"Italie","region":"Ombrie","sousRegion":"Orvieto","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Orvieto Abboccato, Amabile ou Muffa Nobile (botrytis)"}],"cepages":["Grechetto","Trebbiano toscano (Procanico)"],"style":"Pomme, fleurs blanches, amande, pointe de citron ; sec, léger, simple et désaltérant.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":1,"accords":["poisson_maigre","legumes","volaille","vapeur","fromage_frais","herbes"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Orvieto et pâtes aux légumes de printemps","note":"La cité étrusque d'Orvieto domine une aire de tuf volcanique entre Ombrie et Latium. Jadis doux, le vin est aujourd'hui surtout sec : pomme, fleurs blanches, amande, finale légère. Les versions botrytisées (Muffa Nobile) rappellent ce passé. Un blanc simple et frais de tous les jours.","lat":42.72,"lon":12.11,"importance":3,"niveau":"classique"},{"id":"it-barbaresco","nom":"Barbaresco","pays":"Italie","region":"Piémont","sousRegion":"Langhe","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Nebbiolo"],"style":"Plus fin que Barolo : framboise, rose, épices et feuille de thé, tanins soyeux mais présents, finale élancée.","temp":"16 à 18 °C","garde":"8 à 25 ans","prix":4,"accords":["viande_rouge","volaille","truffe","champignon","roti","fromage_dure"],"eviter":["poisson_cru","piquant","sucre_sale"],"classique":"Barbaresco et tajarin à la truffe blanche d'Alba","note":"Au nord-est d'Alba, sur des sols plus sableux et un climat un peu plus doux que Barolo, le nebbiolo mûrit plus tôt et donne un vin plus accessible jeune. Angelo Gaja l'a fait connaître dans le monde dans les années 1970. À ouvrir après cinq ans sur un rôti ou des pâtes à la truffe.","lat":44.73,"lon":8.08,"importance":5,"niveau":"incontournable"},{"id":"it-barolo","nom":"Barolo","pays":"Italie","region":"Piémont","sousRegion":"Langhe","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Nebbiolo"],"style":"Robe claire mais tanins serrés : rose fanée, cerise, goudron et réglisse, acidité haute, longue finale.","temp":"16 à 18 °C","garde":"10 à 30 ans","prix":4,"accords":["viande_rouge","gibier","truffe","mijote","roti","fromage_dure"],"eviter":["poisson_cru","huitre","sucre_sale"],"classique":"Barolo et brasato al Barolo (bœuf braisé au vin)","note":"Sur les marnes calcaires des Langhe, au sud d'Alba, le nebbiolo donne ici son vin le plus structuré : robe pâle trompeuse, nez de rose et de goudron, tanins fermes. Il demande dix ans de cave et une table riche ; l'automne de la truffe blanche est sa saison.","lat":44.61,"lon":7.94,"importance":5,"niveau":"incontournable"},{"id":"it-asti-spumante","nom":"Asti spumante","pays":"Italie","region":"Piémont","sousRegion":"Monferrato","couleur":"bulles","famille":"bulles","variantes":[],"cepages":["Moscato bianco"],"style":"Mousse franche, raisin muscat, pêche et fleurs, bouche douce et aérienne, 7 à 9 % d'alcool.","temp":"6 à 8 °C","garde":"1 à 2 ans","prix":2,"accords":["patisserie","fruits_jaunes","fruits_exotiques","cremeux"],"eviter":["viande_rouge","fume","amer"],"classique":"Asti spumante et pandoro","note":"Grand frère mousseux du Moscato d'Asti, l'Asti est élaboré par la méthode Martinotti (cuve close) avec le même muscat blanc. Pression complète, un peu plus d'alcool, toujours du sucre : le mousseux de dessert des fêtes italiennes. Une version secco existe depuis 2017, mais le doux reste la norme.","lat":44.9,"lon":8.21,"importance":4,"niveau":"classique"},{"id":"it-barbera-d-asti","nom":"Barbera d'Asti","pays":"Italie","region":"Piémont","sousRegion":"Monferrato","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Barbera"],"style":"Fruit rouge et noir juteux, acidité franche, tanins légers ; plus droit et plus frais que la version d'Alba.","temp":"15 à 17 °C","garde":"2 à 8 ans","prix":2,"accords":["charcuterie","tomate","porc","mijote","volaille","fromage_dure"],"eviter":["poisson_maigre","huitre"],"classique":"Barbera d'Asti et bagna cauda","note":"Dans le Monferrato, autour d'Asti, le barbera est le cépage historique de la table paysanne. DOCG depuis 2008, rouge souple et acidulé, sans bois dans sa version de base ; Nizza, ex-sous-zone devenue DOCG en 2014, en est la version la plus ambitieuse. Vin de pâtes, de charcuterie et de mijotés.","lat":44.9,"lon":8.21,"importance":4,"niveau":"classique"},{"id":"it-gavi","nom":"Gavi","pays":"Italie","region":"Piémont","sousRegion":"Alessandrino","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Cortese"],"style":"Citron, pomme verte, amande et pierre mouillée, bouche sèche et tendue, finale légèrement amère.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":2,"accords":["poisson_maigre","crustace","coquillage","vapeur","legumes","fromage_frais"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Gavi et poisson de la Riviera ligure au four","note":"Au sud-est du Piémont, près de la Ligurie, le cortese donne un blanc sec et minéral que les Génois ont longtemps bu avec leurs poissons. « Gavi di Gavi » désigne les vins de la commune même. Peu aromatique, c'est un vin de précision à servir frais à l'apéritif ou sur des fruits de mer.","lat":44.69,"lon":8.8,"importance":4,"niveau":"classique"},{"id":"it-moscato-d-asti","nom":"Moscato d'Asti","pays":"Italie","region":"Piémont","sousRegion":"Monferrato","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Moscato bianco"],"style":"Raisin frais, pêche, fleur d'oranger et sauge, légèrement perlant, sucré mais léger (5,5 % d'alcool).","temp":"6 à 8 °C","garde":"1 à 2 ans","prix":2,"accords":["patisserie","fruits_jaunes","fruits_rouges","fromage_bleu","cremeux"],"eviter":["viande_rouge","chocolat","piquant"],"classique":"Moscato d'Asti et panettone de Noël","note":"Autour de Canelli, le muscat blanc à petits grains fermente en cuve close et la fermentation est arrêtée très tôt : il garde son sucre naturel, un fin perlant et seulement 5,5 % d'alcool. Rien à voir avec l'Asti mousseux, plus pressurisé. Le vin de dessert léger par excellence, à boire dans l'année.","lat":44.72,"lon":8.29,"importance":4,"niveau":"classique"},{"id":"it-barbera-d-alba","nom":"Barbera d'Alba","pays":"Italie","region":"Piémont","sousRegion":"Langhe","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Barbera"],"style":"Cerise noire et mûre, acidité vive, tanins faibles, robe profonde ; souvent un peu de bois dans la version d'Alba.","temp":"15 à 17 °C","garde":"3 à 10 ans","prix":2,"accords":["charcuterie","tomate","mijote","porc","fromage_dure","champignon"],"eviter":["poisson_cru","huitre"],"classique":"Barbera d'Alba et tajarin au ragù","note":"Autour d'Alba, le barbera occupe les coteaux que le nebbiolo ne prend pas. Le cépage conjugue robe sombre, tanins doux et acidité haute, ce qui en fait le rouge des plats en sauce tomate. La version d'Alba est plus concentrée et souvent élevée en fût ; à boire entre deux et huit ans.","lat":44.7,"lon":8.03,"importance":3,"niveau":"classique"},{"id":"it-dolcetto-d-alba","nom":"Dolcetto d'Alba","pays":"Italie","region":"Piémont","sousRegion":"Langhe","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Dolcetto"],"style":"Mûre et cerise noire, note d'amande amère en finale, acidité modérée, tanins doux ; à boire jeune.","temp":"14 à 16 °C","garde":"1 à 4 ans","prix":2,"accords":["charcuterie","porc","volaille","tomate","fromage_molle"],"eviter":["poisson_cru","huitre"],"classique":"Dolcetto d'Alba et salami de Langhe","note":"Le « petit doux » ne désigne pas du sucre mais la douceur de son raisin ; le vin est sec. Dans les Langhe, c'est le rouge de tous les jours, vinifié sans bois, à boire dans les trois ans. Reconnaissable à sa pointe d'amande amère en finale ; parfait avec la charcuterie et les antipasti.","lat":44.7,"lon":8.03,"importance":3,"niveau":"classique"},{"id":"it-gattinara","nom":"Gattinara","pays":"Italie","region":"Piémont","sousRegion":"Alto Piemonte","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Nebbiolo","Vespolina","Uva Rara"],"style":"Nebbiolo du nord : fruit rouge, violette, pierre à fusil et fer, tanins fins mais fermes, acidité haute, corps moyen.","temp":"16 à 18 °C","garde":"8 à 20 ans","prix":3,"accords":["viande_rouge","gibier","champignon","mijote","fromage_dure"],"eviter":["poisson_cru","sucre_sale"],"classique":"Gattinara et risotto aux cèpes","note":"Au pied des Alpes, sur des sols volcaniques (porphyre) qui marquent le vin d'une note ferreuse, Gattinara fut plus réputé que Barolo au XIXe siècle. Le nebbiolo, appelé ici spanna, y est plus élancé et plus salin. DOCG depuis 1990, à ouvrir après six ans sur un gibier ou un risotto.","lat":45.61,"lon":8.37,"importance":3,"niveau":"decouverte"},{"id":"it-langhe-nebbiolo","nom":"Langhe Nebbiolo","pays":"Italie","region":"Piémont","sousRegion":"Langhe","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Nebbiolo"],"style":"Le nebbiolo en version jeune : cerise rouge, rose, un peu de goudron, tanins encore vifs mais fruit en avant.","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":2,"accords":["charcuterie","viande_rouge","champignon","mijote","fromage_dure"],"eviter":["poisson_maigre","huitre"],"classique":"Langhe Nebbiolo et risotto aux champignons des Langhe","note":"Appellation large des Langhe où les producteurs de Barolo et Barbaresco logent leurs jeunes vignes ou les parcelles hors des crus. C'est la porte d'entrée au cépage : même parfum de rose et de cerise, moins d'attente en cave. À servir un peu frais sur une charcuterie ou un plat de pâtes.","lat":44.7,"lon":8.03,"importance":3,"niveau":"classique"},{"id":"it-roero-arneis","nom":"Roero Arneis","pays":"Italie","region":"Piémont","sousRegion":"Roero","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Arneis"],"style":"Poire, abricot, amande fraîche et fleurs blanches, bouche ronde, acidité modérée, finale douce-amère.","temp":"9 à 11 °C","garde":"1 à 4 ans","prix":2,"accords":["volaille","poisson_maigre","legumes","creme","fromage_frais","asperge"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Roero Arneis et vitello tonnato","note":"L'arneis (« le petit rebelle » en piémontais, pour sa culture capricieuse) a failli disparaître avant d'être relancé dans les années 1980 par quelques vignerons du Roero. Il donne un blanc tendre et parfumé, peu acide, à boire jeune. Le compagnon des antipasti piémontais et des viandes froides.","lat":44.8,"lon":7.99,"importance":3,"niveau":"classique"},{"id":"it-brachetto-d-acqui","nom":"Brachetto d'Acqui","pays":"Italie","region":"Piémont","sousRegion":"Monferrato","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Brachetto"],"style":"Rouge mousseux et doux : fraise, rose, framboise, bulle légère, sucre net, 5 à 7 % d'alcool.","temp":"8 à 10 °C","garde":"1 à 2 ans","prix":2,"accords":["chocolat","fruits_rouges","patisserie","glace"],"eviter":["viande_rouge","poisson_maigre","fromage_dure"],"classique":"Brachetto d'Acqui et fraises au chocolat","note":"Autour d'Acqui Terme, le brachetto, cépage rouge très aromatique, donne un mousseux doux et léger, rouge rubis clair, qui sent la rose et la fraise. DOCG depuis 1996, c'est l'un des rares vins à tenir face au chocolat noir. À servir bien frais en fin de repas, jamais en garde.","lat":44.68,"lon":8.47,"importance":2,"niveau":"decouverte"},{"id":"it-ghemme","nom":"Ghemme","pays":"Italie","region":"Piémont","sousRegion":"Alto Piemonte","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Nebbiolo","Vespolina","Uva Rara"],"style":"Rose séchée, cerise, épices et sous-bois, tanins droits, trame fraîche ; un nebbiolo de montagne.","temp":"16 à 18 °C","garde":"8 à 20 ans","prix":3,"accords":["viande_rouge","gibier","mijote","champignon","fromage_dure"],"eviter":["poisson_cru","piquant"],"classique":"Ghemme et paniscia novarese (risotto aux haricots et saucisse)","note":"Voisin de Gattinara, sur l'autre rive de la Sesia, Ghemme pousse sur des moraines glaciaires et des argiles. Le nebbiolo y est assemblé à un peu de vespolina, qui apporte le poivre. Élevage long obligatoire (34 mois minimum), production minuscule : un vin de garde confidentiel à prix raisonnable.","lat":45.6,"lon":8.42,"importance":2,"niveau":"decouverte"},{"id":"it-roero","nom":"Roero","pays":"Italie","region":"Piémont","sousRegion":"Roero","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Nebbiolo"],"style":"Nebbiolo sur sables : fruit rouge croquant, violette, tanins plus fins et plus précoces que de l'autre côté du Tanaro.","temp":"15 à 17 °C","garde":"4 à 12 ans","prix":3,"accords":["viande_rouge","volaille","champignon","mijote","fromage_dure"],"eviter":["poisson_cru","huitre"],"classique":"Roero et agnolotti del plin au jus de rôti","note":"Sur la rive gauche du Tanaro, face aux Langhe, le Roero pousse sur des sables marins qui assouplissent le nebbiolo. DOCG depuis 2004, il reste moins cher que ses voisins pour un profil proche, plus floral et plus vite prêt. Le vin du dimanche piémontais, avec les pâtes farcies.","lat":44.8,"lon":7.99,"importance":2,"niveau":"decouverte"},{"id":"it-primitivo-di-manduria","nom":"Primitivo di Manduria","pays":"Italie","region":"Pouilles","sousRegion":"Salento (Tarente)","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Primitivo di Manduria Dolce Naturale DOCG, rouge doux"}],"cepages":["Primitivo"],"style":"Confiture de mûre, figue, chocolat, épices ; 14 à 15 % d'alcool, tanins doux, corps opulent.","temp":"16 à 18 °C","garde":"2 à 8 ans","prix":2,"accords":["grille","viande_rouge","mijote","charcuterie","epice_douce","fromage_dure"],"eviter":["huitre","poisson_maigre","cru"],"classique":"Primitivo et orecchiette au ragù","note":"Le Primitivo est le même cépage que le Zinfandel californien (Tribidrag croate) ; il mûrit tôt, d'où son nom, sur la plaine chaude entre Tarente et Manduria. Rouge opulent : confiture de mûre, figue, chocolat, 14 à 15 % d'alcool, tanins doux. Vin de grillades et de plats riches ; à boire jeune, un peu rafraîchi.","lat":40.4,"lon":17.63,"importance":4,"niveau":"incontournable"},{"id":"it-negroamaro-salento","nom":"Negroamaro du Salento","pays":"Italie","region":"Pouilles","sousRegion":"Salento","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"rose","famille":"rose","note":"Rosés de Negroamaro, tradition du Salento (Five Roses)"}],"cepages":["Negroamaro"],"style":"Robe noire, prune, cacao, tabac, herbes ; tanins ronds, finale amère caractéristique, plus de nerf que le Primitivo.","temp":"16 à 18 °C","garde":"2 à 8 ans","prix":1,"accords":["grille","mijote","viande_rouge","charcuterie","mediterraneen","legumes"],"eviter":["poisson_cru","huitre"],"classique":"Negroamaro et polpette (boulettes) à la sauce tomate","note":"Cépage emblématique des Pouilles, vinifié sous l'IGT Salento ou en DOC (Salice, Copertino, Brindisi). Robe noire, prune, cacao, tabac, finale amère caractéristique. Moins sucré que le Primitivo, plus de nerf. Il donne aussi les rosés les plus anciens d'Italie. Vin du quotidien sur cuisine du Sud.","lat":40.35,"lon":18.17,"importance":3,"niveau":"classique"},{"id":"it-salice-salentino","nom":"Salice Salentino","pays":"Italie","region":"Pouilles","sousRegion":"Salento","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"rose","famille":"rose","note":"Salice Salentino Rosato, rosé de Negroamaro"}],"cepages":["Negroamaro","Malvasia nera"],"style":"Fruits noirs, cuir, herbes sèches, cacao ; tanins souples, amertume légère en finale, corps chaud.","temp":"16 à 18 °C","garde":"2 à 8 ans","prix":1,"accords":["grille","mijote","charcuterie","agneau","mediterraneen","fromage_dure"],"eviter":["poisson_maigre","huitre"],"classique":"Salice Salentino et braciole (roulades de bœuf à la tomate)","note":"Appellation du Salento, au talon de l'Italie, autour du village de Salice. Negroamaro avec un peu de Malvasia nera : fruits noirs, cuir, herbes sèches, amertume légère en finale (negro-amaro = noir-amer). Souple et bon marché, Riserva après deux ans. Grillades, roulades de bœuf, légumes mijotés.","lat":40.38,"lon":17.96,"importance":3,"niveau":"classique"},{"id":"it-cannonau-di-sardegna","nom":"Cannonau di Sardegna","pays":"Italie","region":"Sardaigne","sousRegion":"","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Cannonau (Grenache)"],"style":"Fraise mûre, garrigue, poivre, cuir ; alcool généreux, tanins doux, rouge chaleureux et rustique.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["agneau","roti","gibier","porc","grille","fromage_dure"],"eviter":["poisson_maigre","huitre"],"classique":"Cannonau et porceddu (cochon de lait rôti)","note":"Le Cannonau est le Grenache, présent en Sardaigne depuis des siècles, concentré dans le Nuorese et l'Ogliastra. Rouge chaleureux : fraise mûre, garrigue, poivre, alcool généreux, tanins doux. La version Riserva vieillit deux ans. Vin des rôtis sardes, porcelet, agneau, pecorino sardo.","lat":40.32,"lon":9.33,"importance":3,"niveau":"classique"},{"id":"it-vermentino-di-gallura","nom":"Vermentino di Gallura","pays":"Italie","region":"Sardaigne","sousRegion":"Gallura","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Vermentino"],"style":"Agrumes, poire, fleurs, note amère de pamplemousse ; sec, salin, plus de corps que sur le continent.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":2,"accords":["coquillage","crustace","poisson_maigre","poisson_cru","legumes","herbes"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Vermentino di Gallura et spaghetti à la bottarga","note":"Seule DOCG de Sardaigne, au nord-est de l'île, sur les granits de Gallura, face à la Corse. Vermentino sec et salin : agrumes, poire, fleurs, finale amère de pamplemousse, plus de corps que sur le continent. Fruits de mer, bottarga, poissons grillés. Le Vermentino di Sardegna DOC est plus simple.","lat":40.9,"lon":9.1,"importance":3,"niveau":"classique"},{"id":"it-carignano-del-sulcis","nom":"Carignano del Sulcis","pays":"Italie","region":"Sardaigne","sousRegion":"Sulcis","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Carignano (Carignan)"],"style":"Mûre, prune, garrigue, cacao ; tanins ronds et mûrs, corps dense, plus poli que les Carignan du Languedoc.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["agneau","mijote","grille","charcuterie","viande_rouge","fromage_dure"],"eviter":["poisson_maigre","huitre"],"classique":"Carignano del Sulcis et agneau au myrte","note":"Au sud-ouest de la Sardaigne, sur les sables du Sulcis, le Carignan pousse en gobelet, franc de pied, parfois centenaire. Rouge dense et mûr : mûre, prune, garrigue, tanins ronds, plus poli que les Carignan du Languedoc. La cave de Santadi (Terre Brune) l'a fait connaître. Agneau, plats mijotés.","lat":39.09,"lon":8.72,"importance":2,"niveau":"decouverte"},{"id":"it-etna-rosso","nom":"Etna Rosso","pays":"Italie","region":"Sicile","sousRegion":"Etna","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Nerello Mascalese","Nerello Cappuccio"],"style":"Robe pâle, fraise, cendre, herbes, orange sanguine ; tanins fins, acidité tendue, finale saline.","temp":"15 à 16 °C","garde":"3 à 12 ans","prix":3,"accords":["volaille","porc","champignon","poisson_gras","fromage_dure","grille"],"eviter":["sucre_sale","piquant"],"classique":"Etna Rosso et pâtes alla Norma","note":"Vignes à 600-1000 m sur les laves du volcan, souvent franches de pied, parcelles appelées contrade. Le Nerello Mascalese donne un rouge pâle, fraise, cendre, herbes, tanins fins et acidité tendue, souvent comparé au Bourgogne ou au Barolo. Servir à 15-16 °C sur volaille, champignons, thon.","lat":37.82,"lon":15.08,"importance":4,"niveau":"incontournable"},{"id":"it-marsala","nom":"Marsala","pays":"Italie","region":"Sicile","sousRegion":"Marsala (Trapani)","couleur":"doux","famille":"vdn","variantes":[{"couleur":"doux","famille":"vdn","note":"Vergine et Riserva secs, oxydatifs, 5 à 10 ans de fût"}],"cepages":["Grillo","Catarratto","Inzolia"],"style":"Ambre, noix, fruits secs, caramel, note oxydative ; muté, sec à doux selon la mention, long en bouche.","temp":"12 à 14 °C","garde":"10 à 30 ans","prix":2,"accords":["fromage_bleu","fromage_dure","noix","patisserie","caramel","foie_gras"],"eviter":["poisson_maigre","acide","piquant"],"classique":"Marsala Vergine et pecorino affiné","note":"Vin muté créé en 1773 par le négociant anglais John Woodhouse à Marsala, à l'ouest de la Sicile, sur le modèle du Xérès. Du Fine (1 an) au Vergine (5 ans) et Riserva (10 ans) : noix, fruits secs, caramel, oxydatif. Secco, semisecco ou dolce. Les Vergine secs sont de grands vins d'apéritif.","lat":37.8,"lon":12.44,"importance":4,"niveau":"classique"},{"id":"it-nero-d-avola","nom":"Nero d'Avola (Sicilia DOC)","pays":"Italie","region":"Sicile","sousRegion":"","couleur":"rouge","famille":"rouge_solaire","variantes":[],"cepages":["Nero d'Avola"],"style":"Mûre, prune, réglisse, épices ; corps chaud, tanins ronds, rouge généreux du soleil sicilien.","temp":"16 à 18 °C","garde":"2 à 8 ans","prix":1,"accords":["grille","viande_rouge","mijote","agneau","mediterraneen","epice_douce"],"eviter":["huitre","poisson_maigre"],"classique":"Nero d'Avola et caponata","note":"Cépage rouge majeur de Sicile, originaire d'Avola au sud-est mais planté sur toute l'île. Mûre, prune, réglisse, épices, corps chaud et tanins ronds ; les versions de Noto et Pachino sont les plus denses. Souvent bon marché, parfois ambitieux. Grillades, agneau, aubergines, cuisine sicilienne.","lat":37.55,"lon":13.9,"importance":4,"niveau":"incontournable"},{"id":"it-etna-bianco","nom":"Etna Bianco","pays":"Italie","region":"Sicile","sousRegion":"Etna","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Carricante","Catarratto"],"style":"Citron vert, pomme verte, fumée, pierre ; acidité très haute, salinité, notes de pétrole avec l'âge.","temp":"10 à 12 °C","garde":"3 à 12 ans","prix":3,"accords":["huitre","coquillage","poisson_maigre","poisson_cru","agrumes","legumes"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Etna Bianco et crudo de poisson","note":"Sur le versant est du volcan, autour de Milo (Etna Bianco Superiore), le Carricante donne un blanc tranchant : citron vert, pomme verte, fumée, salinité, acidité très haute. Il vieillit dix ans en prenant des notes de pétrole proches d'un Riesling. Coquillages, poisson cru, agrumes.","lat":37.72,"lon":15.11,"importance":3,"niveau":"classique"},{"id":"it-passito-di-pantelleria","nom":"Passito di Pantelleria","pays":"Italie","region":"Sicile","sousRegion":"Pantelleria","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Zibibbo (Muscat d'Alexandrie)"],"style":"Abricot confit, orange, miel, fleur d'oranger, figue ; douceur dense équilibrée par le sel et l'amertume.","temp":"8 à 10 °C","garde":"5 à 15 ans","prix":3,"accords":["patisserie","fruits_jaunes","fromage_bleu","fruits_exotiques","foie_gras","caramel"],"eviter":["viande_rouge","acide","piquant"],"classique":"Passito di Pantelleria et cassata sicilienne","note":"Sur l'île volcanique de Pantelleria, entre Sicile et Tunisie, le Zibibbo pousse en gobelet dans des cuvettes creusées contre le vent (pratique inscrite à l'UNESCO). Raisins séchés au soleil : abricot confit, orange, miel, fleur d'oranger, douceur équilibrée par le sel. Desserts aux amandes, bleus.","lat":36.79,"lon":11.99,"importance":3,"niveau":"classique"},{"id":"it-cerasuolo-di-vittoria","nom":"Cerasuolo di Vittoria","pays":"Italie","region":"Sicile","sousRegion":"Vittoria (Raguse)","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Nero d'Avola","Frappato"],"style":"Cerise, fraise, fleurs, épices douces ; tanins légers, corps moyen, parfumé, à servir un peu frais.","temp":"14 à 16 °C","garde":"2 à 8 ans","prix":2,"accords":["volaille","porc","charcuterie","poisson_gras","tomate","mediterraneen"],"eviter":["huitre","sucre_sale"],"classique":"Cerasuolo di Vittoria et thon à la sicilienne","note":"Seule DOCG de Sicile, dans le sud-est autour de Vittoria. Assemblage de Nero d'Avola (corps) et de Frappato (fraîcheur, parfum de fraise) : rouge cerise, floral, tanins légers, à servir un peu frais. COS et Arianna Occhipinti l'ont rendu célèbre. Thon, volaille, charcuterie, cuisine à la tomate.","lat":36.95,"lon":14.53,"importance":2,"niveau":"decouverte"},{"id":"it-malvasia-delle-lipari","nom":"Malvasia delle Lipari","pays":"Italie","region":"Sicile","sousRegion":"Îles Éoliennes","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Malvasia di Lipari","Corinto nero"],"style":"Doré, abricot, miel, herbes de maquis, agrumes confits ; doux mais aérien, moins lourd qu'un passito.","temp":"8 à 10 °C","garde":"3 à 10 ans","prix":3,"accords":["patisserie","fruits_jaunes","fromage_bleu","fromage_frais","agrumes","noix"],"eviter":["viande_rouge","acide"],"classique":"Malvasia delle Lipari et pâtisseries aux amandes","note":"Dans les îles Éoliennes, surtout à Salina, la Malvasia est récoltée puis séchée dix jours sur des claies de roseaux. Vin doux doré : abricot, miel, herbes de maquis, agrumes confits, moins lourd qu'un Passito de Pantelleria. Production minuscule. Desserts, ricotta sucrée, fromages bleus.","lat":38.56,"lon":14.84,"importance":2,"niveau":"decouverte"},{"id":"it-brunello-di-montalcino","nom":"Brunello di Montalcino","pays":"Italie","region":"Toscane","sousRegion":"Montalcino","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Sangiovese"],"style":"Fruits noirs, cuir, tabac, sous-bois ; tanins denses, acidité haute, longue finale, grande garde.","temp":"17 à 18 °C","garde":"10 à 30 ans","prix":4,"accords":["viande_rouge","gibier","roti","truffe","fromage_dure","champignon"],"eviter":["poisson_maigre","huitre","acide"],"classique":"Brunello et pappardelle au sanglier","note":"Sangiovese pur (clone Brunello) élevé au moins deux ans en fût, mis en vente cinq ans après la vendange. Colline sèche au sud de Sienne : fruits noirs, cuir, tabac, tanins denses et longue finale. Un vin de garde qui demande du temps et un plat riche : gibier, viande rôtie, truffe.","lat":43.06,"lon":11.49,"importance":5,"niveau":"incontournable"},{"id":"it-chianti","nom":"Chianti","pays":"Italie","region":"Toscane","sousRegion":"Chianti","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Sangiovese","Canaiolo","Colorino"],"style":"Cerise rouge, violette, pointe d'herbes sèches ; tanins fins, acidité franche, corps léger à moyen.","temp":"16 à 18 °C","garde":"2 à 5 ans","prix":1,"accords":["tomate","charcuterie","mijote","porc","fromage_dure","mediterraneen"],"eviter":["poisson_cru","huitre"],"classique":"Chianti et pâtes au ragù","note":"Appellation étendue entre Florence et Sienne, divisée en sous-zones (Rufina, Colli Senesi). Le Sangiovese y donne un rouge vif, à l'acidité marquée et aux tanins légers, qui appelle la table : tomate, charcuterie, ragù. À boire jeune, légèrement rafraîchi l'été.","lat":43.6,"lon":11.2,"importance":5,"niveau":"incontournable"},{"id":"it-chianti-classico","nom":"Chianti Classico","pays":"Italie","region":"Toscane","sousRegion":"Chianti Classico","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Riserva et Gran Selezione : plus de structure et d'élevage"}],"cepages":["Sangiovese","Canaiolo","Colorino"],"style":"Cerise noire, cuir, thé, violette ; tanins fermes, acidité qui tient, corps moyen, finale sèche.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["viande_rouge","grille","roti","mijote","fromage_dure","tomate"],"eviter":["poisson_maigre","sucre_sale"],"classique":"Chianti Classico et bistecca alla fiorentina","note":"Le cœur historique du Chianti, entre Florence et Sienne, reconnaissable au coq noir sur la collerette. Sangiovese à 80 % minimum, sols de galestro et d'alberese : cerise, cuir, note de thé, tanins fermes et acidité qui tient. Un vin de viande, grillée ou rôtie, à carafer jeune.","lat":43.48,"lon":11.37,"importance":5,"niveau":"incontournable"},{"id":"it-bolgheri","nom":"Bolgheri","pays":"Italie","region":"Toscane","sousRegion":"Côte toscane (Maremme)","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Bolgheri Bianco, Vermentino dominant"},{"couleur":"rose","famille":"rose","note":"Rosé de cépages bordelais, minoritaire"}],"cepages":["Cabernet Sauvignon","Merlot","Cabernet Franc","Syrah"],"style":"Cassis, cèdre, herbes du maquis, graphite ; tanins mûrs et enrobés, corps plein, bois bien fondu.","temp":"17 à 18 °C","garde":"5 à 20 ans","prix":3,"accords":["viande_rouge","agneau","grille","roti","sauce_vin_rouge","fromage_dure"],"eviter":["poisson_maigre","huitre","vinaigre"],"classique":"Bolgheri et côte de bœuf grillée","note":"Sur la côte toscane, face à la mer, le marquis Incisa della Rocchetta a planté le Cabernet en 1944 (Sassicaia) ; la DOC Bolgheri, de style bordelais au soleil méditerranéen, n'a admis les rouges qu'en 1994. Cassis, cèdre, herbes, tanins mûrs et enrobés. Les Superiore se gardent dix ans ; servir sur viande rouge grillée.","lat":43.23,"lon":10.61,"importance":4,"niveau":"incontournable"},{"id":"it-supertoscans","nom":"Supertoscans (IGT Toscana)","pays":"Italie","region":"Toscane","sousRegion":"","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Cabernet Sauvignon","Sangiovese","Merlot","Syrah"],"style":"Fruits noirs mûrs, cèdre, vanille, tabac ; tanins denses et polis, corps plein, boisé marqué, longue finale.","temp":"17 à 18 °C","garde":"8 à 25 ans","prix":4,"accords":["viande_rouge","roti","gibier","sauce_vin_rouge","fromage_dure","truffe"],"eviter":["poisson_maigre","huitre","acide"],"classique":"Tignanello et filet de bœuf rôti","note":"Nés à la fin des années 1960 (Sassicaia 1968, Cabernet pur de Bolgheri) et dans les années 1970 (Tignanello 1971, Sangiovese et Cabernet hors des règles du Chianti), vendus comme « vins de table ». Aujourd'hui IGT Toscana pour la plupart, Sassicaia ayant sa propre DOC : vins ambitieux, boisés, denses, chers. Garde longue, grande table de viande.","lat":43.32,"lon":11.33,"importance":4,"niveau":"incontournable"},{"id":"it-vino-nobile-di-montepulciano","nom":"Vino Nobile di Montepulciano","pays":"Italie","region":"Toscane","sousRegion":"Montepulciano","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Rosso di Montepulciano, version jeune et souple"}],"cepages":["Sangiovese","Canaiolo","Mammolo"],"style":"Prune, violette, cuir, épices ; tanins fermes mais ronds, acidité moyenne, corps plein.","temp":"17 à 18 °C","garde":"5 à 15 ans","prix":3,"accords":["viande_rouge","roti","agneau","mijote","fromage_dure","truffe"],"eviter":["poisson_maigre","coquillage"],"classique":"Vino Nobile et agneau rôti aux herbes","note":"Autour du bourg de Montepulciano, au sud-est de Sienne, le Sangiovese prend ici le nom de Prugnolo Gentile. Deux ans d'élevage minimum : prune, violette, cuir, tanins fermes mais plus ronds qu'à Montalcino. Ne pas confondre avec le Montepulciano d'Abruzzo, qui est un cépage. Carafer, viande rôtie.","lat":43.1,"lon":11.78,"importance":4,"niveau":"classique"},{"id":"it-rosso-di-montalcino","nom":"Rosso di Montalcino","pays":"Italie","region":"Toscane","sousRegion":"Montalcino","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Sangiovese"],"style":"Cerise croquante, prune, épices douces ; tanins souples, acidité fraîche, plus accessible que le Brunello.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":2,"accords":["charcuterie","volaille","mijote","tomate","fromage_dure","champignon"],"eviter":["poisson_cru","sucre_sale"],"classique":"Rosso di Montalcino et pici à l'aglione","note":"Le « petit frère » du Brunello : même cépage, même aire, mais un an d'élevage seulement et une mise en vente l'année suivante. Fruit rouge croquant, tanins souples, acidité fraîche. Il donne une idée du terroir de Montalcino sans attendre dix ans, à table avec pâtes, volaille, charcuterie.","lat":43.06,"lon":11.49,"importance":3,"niveau":"classique"},{"id":"it-vernaccia-di-san-gimignano","nom":"Vernaccia di San Gimignano","pays":"Italie","region":"Toscane","sousRegion":"San Gimignano","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Vernaccia"],"style":"Citron, pomme, amande, fleurs blanches ; sec, droit, finale légèrement amère, les Riserva plus amples.","temp":"10 à 12 °C","garde":"2 à 5 ans","prix":2,"accords":["poisson_maigre","crustace","legumes","volaille","fromage_frais","herbes"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Vernaccia et crostini aux fèves et pecorino frais","note":"Premier vin italien reconnu DOC en 1966, cité par Dante, autour des tours de San Gimignano. Blanc sec, citron, amande, finale légèrement amère typique du cépage ; les Riserva prennent du gras. Un blanc de table toscan pour poissons, légumes et fromages frais, à boire dans les trois ans.","lat":43.47,"lon":11.04,"importance":3,"niveau":"classique"},{"id":"it-vin-santo","nom":"Vin Santo del Chianti","pays":"Italie","region":"Toscane","sousRegion":"Chianti","couleur":"doux","famille":"blanc_doux","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Occhio di Pernice, version rosée au Sangiovese"}],"cepages":["Trebbiano toscano","Malvasia bianca"],"style":"Ambre, noix, abricot sec, caramel, note oxydative ; doux mais pas lourd, longue finale.","temp":"10 à 12 °C","garde":"10 à 30 ans","prix":3,"accords":["patisserie","noix","fromage_bleu","fromage_dure","caramel","foie_gras"],"eviter":["viande_rouge","piquant","acide"],"classique":"Vin Santo et cantucci aux amandes","note":"Vin de raisins passerillés sur claies pendant l'hiver, puis vieilli plusieurs années en petits fûts (caratelli) sous les toits, sans ouillage. Ambre, noix, abricot sec, caramel, oxydatif. Servi en Toscane avec les cantucci que l'on trempe dedans ; aussi sur fromages bleus.","lat":43.55,"lon":11.3,"importance":3,"niveau":"classique"},{"id":"it-carmignano","nom":"Carmignano","pays":"Italie","region":"Toscane","sousRegion":"Carmignano","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Barco Reale di Carmignano, version jeune"}],"cepages":["Sangiovese","Cabernet Sauvignon","Canaiolo","Cabernet Franc"],"style":"Cerise, cassis, violette, cuir ; tanins droits, acidité vive, structure plus serrée qu'un Chianti.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":3,"accords":["viande_rouge","roti","gibier","mijote","fromage_dure"],"eviter":["poisson_maigre","coquillage"],"classique":"Carmignano et lapin aux olives","note":"Petite appellation à l'ouest de Florence, protégée par un édit des Médicis dès 1716. Le Cabernet y est obligatoire (10 à 20 %) depuis bien avant les Supertoscans : Sangiovese renforcé de cassis et d'une structure plus droite. Rouge de garde moyenne, sur viandes rôties et plats mijotés.","lat":43.81,"lon":11.02,"importance":2,"niveau":"decouverte"},{"id":"it-morellino-di-scansano","nom":"Morellino di Scansano","pays":"Italie","region":"Toscane","sousRegion":"Maremme","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Sangiovese","Alicante","Ciliegiolo"],"style":"Cerise mûre, mûre, garrigue ; tanins doux, acidité modérée, rouge gourmand et solaire à boire jeune.","temp":"15 à 17 °C","garde":"2 à 5 ans","prix":2,"accords":["charcuterie","grille","porc","tomate","mijote","mediterraneen"],"eviter":["poisson_cru","huitre"],"classique":"Morellino et saucisse toscane grillée","note":"En Maremme, près de la côte sud de la Toscane, le Sangiovese (appelé Morellino) mûrit vite sous un climat chaud : fruit mûr, moins d'acidité qu'en Chianti, tanins doux. Un rouge gourmand à boire jeune, souvent bon marché, parfait sur les grillades et la charcuterie de l'été.","lat":42.69,"lon":11.33,"importance":2,"niveau":"classique"},{"id":"it-alto-adige-gewurztraminer","nom":"Alto Adige Gewürztraminer","pays":"Italie","region":"Trentin-Haut-Adige","sousRegion":"Haut-Adige","couleur":"blanc","famille":"blanc_aromatique","variantes":[],"cepages":["Gewürztraminer"],"style":"Litchi, rose, gingembre et fruits exotiques, bouche sèche mais grasse, alcool présent, acidité basse.","temp":"10 à 12 °C","garde":"2 à 6 ans","prix":2,"accords":["asiatique","curry","epice_douce","fromage_lave","foie_gras","fruits_exotiques"],"eviter":["huitre","acide","vinaigre"],"classique":"Gewürztraminer et Schlutzkrapfen au fromage de montagne","note":"Le village de Tramin (Termeno), au sud de Bolzano, a donné son nom au cépage, même s'il vient probablement d'ailleurs. Sur ces coteaux calcaires, il est vinifié plus sec et plus tendu qu'en Alsace, avec moins de sucre résiduel. Un blanc de cuisine épicée et de fromages à croûte lavée.","lat":46.34,"lon":11.24,"importance":3,"niveau":"classique"},{"id":"it-alto-adige-lagrein","nom":"Alto Adige Lagrein","pays":"Italie","region":"Trentin-Haut-Adige","sousRegion":"Haut-Adige","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rose","famille":"rose","note":"Lagrein Kretzer, rosé foncé et fruité, servi frais"}],"cepages":["Lagrein"],"style":"Robe très sombre, mûre, violette, cacao et graphite, tanins charnus un peu rustiques, acidité fraîche.","temp":"16 à 18 °C","garde":"4 à 12 ans","prix":2,"accords":["viande_rouge","gibier","mijote","grille","fromage_dure","charcuterie"],"eviter":["poisson_maigre","huitre","vapeur"],"classique":"Lagrein et goulasch de bœuf tyrolien","note":"Cépage autochtone de Bolzano, fils du teroldego et cousin de la syrah, le lagrein mûrit dans la plaine alluviale chaude et caillouteuse de Gries. Rouge le plus coloré d'Italie du Nord, tannique et frais à la fois ; le bois adoucit sa rusticité. Vin de montagne pour mijotés et grillades.","lat":46.5,"lon":11.35,"importance":3,"niveau":"decouverte"},{"id":"it-trentodoc","nom":"Trentodoc","pays":"Italie","region":"Trentin-Haut-Adige","sousRegion":"Trentin","couleur":"bulles","famille":"bulles","variantes":[],"cepages":["Chardonnay","Pinot nero","Pinot bianco"],"style":"Méthode traditionnelle de montagne : pomme, agrumes, pain grillé, bulle fine, acidité vive et finale saline.","temp":"7 à 9 °C","garde":"2 à 10 ans","prix":3,"accords":["crustace","poisson_cru","huitre","frit","volaille","fromage_dure"],"eviter":["viande_rouge","sauce_vin_rouge","piquant"],"classique":"Trentodoc et canederli (boulettes de pain au speck)","note":"Première appellation italienne de bulles méthode traditionnelle (1993), dans les vallées du Trentin où le chardonnay monte jusqu'à 800 m. L'altitude donne une acidité plus tendue que la Franciacorta. Ferrari, fondée à Trente en 1902, en est la maison emblématique. À ouvrir sur une friture.","lat":46.07,"lon":11.12,"importance":3,"niveau":"classique"},{"id":"it-teroldego-rotaliano","nom":"Teroldego Rotaliano","pays":"Italie","region":"Trentin-Haut-Adige","sousRegion":"Trentin","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Teroldego"],"style":"Mûre, cassis, violette et note de pierre, robe foncée, tanins doux, acidité vive ; fruité et droit.","temp":"15 à 17 °C","garde":"3 à 10 ans","prix":2,"accords":["charcuterie","viande_rouge","porc","mijote","champignon","fromage_dure"],"eviter":["poisson_cru","huitre"],"classique":"Teroldego et polenta aux champignons","note":"Le teroldego ne pousse presque que dans la plaine Rotaliana, un cône de graviers à la confluence du Noce et de l'Adige, au nord de Trente. Cépage autochtone, parent du lagrein, il donne un rouge foncé, frais et peu tannique. Foradori l'a sorti de la production de masse dans les années 1990.","lat":46.21,"lon":11.09,"importance":2,"niveau":"decouverte"},{"id":"it-amarone-della-valpolicella","nom":"Amarone della Valpolicella","pays":"Italie","region":"Vénétie","sousRegion":"Valpolicella","couleur":"rouge","famille":"rouge_puissant","variantes":[],"cepages":["Corvina","Corvinone","Rondinella"],"style":"Cerise noire séchée, pruneau, cacao, tabac, 15 à 17 % d'alcool, bouche ample et veloutée, finale amère sèche.","temp":"17 à 18 °C","garde":"8 à 25 ans","prix":4,"accords":["viande_rouge","gibier","mijote","fromage_dure","fromage_bleu","roti"],"eviter":["poisson_maigre","huitre","vapeur"],"classique":"Amarone et Monte Veronese affiné 24 mois","note":"Les raisins sèchent trois à quatre mois sur claies (appassimento) avant une fermentation menée jusqu'au sec : le sucre devient alcool et le vin « amaro », amer, par opposition au Recioto doux. Né d'un accident dans les années 1930, DOCG depuis 2010. Vin de fin de repas, fromages et viandes braisées.","lat":45.53,"lon":10.94,"importance":5,"niveau":"incontournable"},{"id":"it-pinot-grigio-delle-venezie","nom":"Pinot grigio delle Venezie","pays":"Italie","region":"Vénétie","sousRegion":"Trivénétie","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Pinot grigio"],"style":"Poire, citron, pomme, bouche légère, sèche et neutre, acidité modérée ; un blanc simple et net.","temp":"8 à 10 °C","garde":"1 à 2 ans","prix":1,"accords":["poisson_maigre","coquillage","legumes","vapeur","fromage_frais"],"eviter":["viande_rouge","gibier","sauce_vin_rouge"],"classique":"Pinot grigio et spaghetti alle vongole","note":"La DOC delle Venezie (2017) couvre la Vénétie, le Frioul et le Trentin : la plus grande source mondiale de pinot grigio, vinifié sans bois, pressé vite pour rester pâle et léger. Son succès vient de sa neutralité, qui va avec tout. Les versions de l'Alto Adige et du Frioul sont plus denses.","lat":45.67,"lon":12.24,"importance":5,"niveau":"classique"},{"id":"it-prosecco-conegliano-valdobbiadene","nom":"Prosecco (Conegliano Valdobbiadene)","pays":"Italie","region":"Vénétie","sousRegion":"Conegliano Valdobbiadene","couleur":"bulles","famille":"bulles","variantes":[],"cepages":["Glera"],"style":"Poire, pomme verte, fleur d'acacia, bulle légère et sucre discret (brut à extra dry), 11 à 12 % d'alcool.","temp":"6 à 8 °C","garde":"1 à 2 ans","prix":2,"accords":["crustace","charcuterie","frit","poisson_maigre","fromage_frais"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Prosecco et cicchetti vénitiens","note":"La zone DOCG historique, sur les collines escarpées entre Conegliano et Valdobbiadene (Unesco 2019), produit le prosecco d'origine, à ne pas confondre avec la DOC de plaine. Méthode Martinotti en cuve close, qui garde le fruit frais de la glera. Le cru Cartizze (107 ha) est son sommet.","lat":45.9,"lon":12.03,"importance":5,"niveau":"incontournable"},{"id":"it-soave","nom":"Soave","pays":"Italie","region":"Vénétie","sousRegion":"Soave","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Recioto di Soave, raisins séchés, miel et abricot, DOCG"}],"cepages":["Garganega","Trebbiano di Soave"],"style":"Poire, amande, fleur de tilleul et note fumée sur le Classico, bouche sèche, saline, acidité moyenne.","temp":"8 à 10 °C","garde":"2 à 6 ans","prix":1,"accords":["poisson_maigre","crustace","legumes","vapeur","fromage_frais","asperge"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Soave et risotto aux asperges","note":"À l'est de Vérone, la garganega pousse sur des collines volcaniques (basaltes) dans la zone Classico et sur des plaines calcaires ailleurs. Longtemps vendu en masse, le Soave est redevenu un blanc sérieux, sec et salin, qui vieillit bien. Le Classico des coteaux est le plus intéressant.","lat":45.42,"lon":11.25,"importance":4,"niveau":"classique"},{"id":"it-valpolicella","nom":"Valpolicella","pays":"Italie","region":"Vénétie","sousRegion":"Valpolicella","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Corvina","Corvinone","Rondinella","Molinara"],"style":"Cerise griotte, amande amère, poivre léger, bouche légère et fraîche, tanins fins ; à boire jeune et un peu frais.","temp":"14 à 16 °C","garde":"1 à 4 ans","prix":1,"accords":["charcuterie","volaille","porc","tomate","fromage_molle","legumes"],"eviter":["huitre","poisson_cru"],"classique":"Valpolicella et pasta e fagioli","note":"Au nord de Vérone, sur des collines calcaires, la corvina et ses compagnons donnent le Valpolicella de base : un rouge léger qui sent la griotte et l'amande, sans bois, à boire dans les deux ans. Classico désigne la zone historique (Fumane, Marano, Negrar). Le rouge de la trattoria véronaise.","lat":45.52,"lon":10.88,"importance":4,"niveau":"classique"},{"id":"it-bardolino","nom":"Bardolino","pays":"Italie","region":"Vénétie","sousRegion":"Lac de Garde","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"rose","famille":"rose","note":"Chiaretto di Bardolino, rosé pâle et vif, l'un des plus produits d'Italie"}],"cepages":["Corvina","Rondinella","Molinara"],"style":"Rouge très léger : cerise, fraise, pointe d'épices, tanins presque absents, à servir frais.","temp":"13 à 15 °C","garde":"1 à 3 ans","prix":1,"accords":["charcuterie","poisson_gras","volaille","legumes","tomate","grille"],"eviter":["viande_rouge","gibier","fromage_bleu"],"classique":"Bardolino et lavaret du lac grillé","note":"Sur la rive est du lac de Garde, les mêmes cépages que le Valpolicella donnent, sur des moraines plus légères, un rouge encore plus léger, à boire frais, presque comme un rosé. Le Chiaretto rosé est devenu la star de l'appellation. Vin d'été et de terrasse, qui accompagne même le poisson.","lat":45.55,"lon":10.72,"importance":3,"niveau":"classique"},{"id":"it-recioto-della-valpolicella","nom":"Recioto della Valpolicella","pays":"Italie","region":"Vénétie","sousRegion":"Valpolicella","couleur":"doux","famille":"blanc_doux","variantes":[],"cepages":["Corvina","Corvinone","Rondinella"],"style":"Rouge doux de raisins séchés : cerise confite, figue, chocolat, épices, sucre net équilibré par les tanins.","temp":"12 à 14 °C","garde":"5 à 20 ans","prix":3,"accords":["chocolat","fromage_bleu","patisserie","fruits_rouges","noix"],"eviter":["poisson_maigre","acide","vinaigre"],"classique":"Recioto della Valpolicella et gâteau au chocolat noir","note":"L'ancêtre de l'Amarone : mêmes raisins séchés sur claies, mais la fermentation est arrêtée pour garder le sucre. Le nom viendrait des « recie », les oreilles de la grappe, les plus exposées au soleil. Rouge doux et tannique, l'un des rares vins à tenir face au chocolat ; à servir légèrement frais.","lat":45.52,"lon":10.88,"importance":3,"niveau":"decouverte"},{"id":"it-valpolicella-ripasso","nom":"Valpolicella Ripasso","pays":"Italie","region":"Vénétie","sousRegion":"Valpolicella","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Corvina","Corvinone","Rondinella"],"style":"Cerise confite, figue, cacao et épices douces, bouche ronde et chaleureuse, tanins fondus ; entre Valpolicella et Amarone.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":2,"accords":["viande_rouge","mijote","roti","fromage_dure","champignon","porc"],"eviter":["poisson_maigre","huitre","acide"],"classique":"Valpolicella Ripasso et risotto all'Amarone","note":"Le Ripasso est un Valpolicella « repassé » sur les marcs encore chauds de l'Amarone, qui relancent une fermentation et donnent corps, alcool et notes de fruits secs. Pratique paysanne codifiée en 2010 : le « petit Amarone », bien moins cher, prêt plus tôt. Vin de mijotés et de fromages affinés.","lat":45.52,"lon":10.88,"importance":3,"niveau":"classique"},{"id":"jp-koshu-yamanashi","nom":"Koshu du Yamanashi","pays":"Japon","region":"Yamanashi","sousRegion":"Katsunuma (Kōshū)","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Muscat Bailey A, rouge léger et fruité, autre cépage emblématique du Japon."}],"cepages":["Koshu"],"style":"Yuzu, poire japonaise, fleur blanche et une amertume fine de zeste ; blanc léger (11 à 12 %) et discret.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":3,"accords":["poisson_cru","poisson_maigre","vapeur","asiatique","legumes","coquillage"],"eviter":["viande_rouge","fromage_bleu","sauce_vin_rouge"],"classique":"Koshu et sashimi de daurade","note":"Le Koshu, raisin à peau rose arrivé par la route de la Soie il y a un millénaire, est cultivé autour de Katsunuma, au pied du mont Fuji. Longtemps raisin de table, il donne depuis les années 2000 des blancs secs, fins et légers, reconnus par l'OIV en 2010. Fait pour la cuisine japonaise.","lat":35.66,"lon":138.73,"importance":3,"niveau":"classique"},{"id":"lb-bekaa","nom":"Bekaa (Château Musar)","pays":"Liban","region":"Vallée de la Bekaa","sousRegion":"","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Musar blanc d'Obaideh et Merwah, cépages indigènes, élevage long et style oxydatif."}],"cepages":["Cabernet Sauvignon","Cinsault","Carignan"],"style":"Fruits rouges mûrs, figue, cuir, épices orientales et notes volatiles ; tanins fondus par de longs élevages.","temp":"16 à 18 °C","garde":"10 à 30 ans","prix":3,"accords":["agneau","gibier","mijote","epice_douce","mediterraneen","fromage_dure"],"eviter":["huitre","poisson_cru","vapeur"],"classique":"Château Musar et agneau confit aux sept épices","note":"Haut plateau à 1 000 m entre deux chaînes de montagnes, la Bekaa vinifie depuis l'Antiquité. Château Musar, fondé en 1930 par Gaston Hochar et porté par son fils Serge, assemble Cabernet, Cinsault et Carignan et ne sort ses rouges qu'après sept ans. Vins de garde, à carafer.","lat":33.85,"lon":35.9,"importance":4,"niveau":"incontournable"},{"id":"lu-cremant","nom":"Crémant de Luxembourg","pays":"Luxembourg","region":"Moselle luxembourgeoise","sousRegion":"","couleur":"bulles","famille":"bulles","variantes":[{"couleur":"bulles","famille":"bulles","note":"Crémant rosé de Pinot noir : fraise et framboise, bulle fine."}],"cepages":["Pinot blanc","Auxerrois","Riesling","Chardonnay"],"style":"Effervescent méthode traditionnelle, frais et fin : pomme, poire, agrumes, pointe briochée ; bulle fine, dosage brut.","temp":"6 à 8 °C","garde":"1 à 4 ans","prix":2,"accords":["huitre","crustace","poisson_maigre","frit","fromage_frais","patisserie"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Crémant de Luxembourg et bouchée à la reine","note":"Créée en 1991, l'appellation Crémant de Luxembourg suit les règles des crémants français : méthode traditionnelle, neuf mois minimum sur lattes, pressurage doux. Elle pèse environ un cinquième de la production du pays, sur Pinot blanc, Auxerrois et Riesling. Apéritif et vin de fête du pays.","lat":49.61,"lon":6.4,"importance":2,"niveau":"decouverte"},{"id":"lu-moselle-riesling","nom":"Riesling de la Moselle luxembourgeoise","pays":"Luxembourg","region":"Moselle luxembourgeoise","sousRegion":"Remich, Wormeldange, Grevenmacher","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Pinot gris, Auxerrois et Gewürztraminer luxembourgeois : plus ronds et parfumés, souvent les meilleurs rapports prix."},{"couleur":"doux","famille":"blanc_doux","note":"Vendanges tardives et vin de glace (Äiswäin) de Riesling, rares et vifs."}],"cepages":["Riesling"],"style":"Blanc sec, fin et minéral : citron, pomme, pêche blanche, pierre mouillée ; acidité vive, corps léger.","temp":"8 à 10 °C","garde":"3 à 10 ans","prix":2,"accords":["poisson_maigre","crustace","volaille","beurre_citron","asperge","fromage_chevre"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Riesling de Moselle et friture d'ablettes (Friture de la Moselle)","note":"Sur 42 km de rive gauche de la Moselle, face à l'Allemagne, le vignoble luxembourgeois pousse sur marnes du keuper au sud (Remich) et calcaire coquillier au nord (Grevenmacher). Les Riesling y sont presque toujours secs, plus fins qu'en Allemagne, moins mûrs qu'en Alsace. Vins de poisson de rivière.","lat":49.54,"lon":6.37,"importance":2,"niveau":"decouverte"},{"id":"ma-meknes","nom":"Meknès (Guerrouane)","pays":"Maroc","region":"Meknès","sousRegion":"Guerrouane et Beni M'Tir","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"rose","famille":"rose","note":"Vins gris et rosés pâles de Cinsault et Grenache, les plus bus au Maroc."}],"cepages":["Syrah","Cabernet Sauvignon","Carignan","Grenache"],"style":"Fruits noirs cuits, épices, cuir et garrigue ; bouche chaude, tanins souples, parfois un boisé moderne.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["agneau","mijote","epice_douce","grille","mediterraneen","legumes"],"eviter":["huitre","poisson_cru","fromage_frais"],"classique":"Rouge de Meknès et tajine d'agneau aux pruneaux","note":"Au pied du Moyen Atlas, à 600 m d'altitude, Meknès concentre l'essentiel du vignoble marocain (appellations Guerrouane et Beni M'Tir). Les Celliers de Meknès et Castel y produisent des rouges solaires de Syrah et Cabernet, et des gris très populaires. Vin de tajine, à servir légèrement frais.","lat":33.89,"lon":-5.55,"importance":2,"niveau":"decouverte"},{"id":"mx-valle-de-guadalupe","nom":"Valle de Guadalupe","pays":"Mexique","region":"Basse-Californie","sousRegion":"Ensenada","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay et chenin ronds et solaires"}],"cepages":["Cabernet Sauvignon","Nebbiolo","Tempranillo","Grenache"],"style":"Rouge chaud et épicé, fruits noirs confits, cuir, garrigue, tanins mûrs, pointe saline.","temp":"16 à 18 °C","garde":"3 à 8 ans","prix":3,"accords":["viande_rouge","grille","mediterraneen","epice_douce","fromage_dure"],"eviter":["poisson_cru","huitre"],"classique":"Rouge de Guadalupe et tacos de bœuf grillé","note":"À 30 km de l'océan au nord de la Basse-Californie, la Valle de Guadalupe, climat méditerranéen et sols salins, produit près de 90 % du vin mexicain. Ses rouges d'assemblage, souvent avec du nebbiolo, sont solaires et épicés : à servir légèrement frais sur des grillades.","lat":32.1,"lon":-116.58,"importance":2,"niveau":"decouverte"},{"id":"md-purcari","nom":"Purcari","pays":"Moldavie","region":"Ștefan Vodă","sousRegion":"Purcari","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rouge","famille":"rouge_souple","note":"Rara neagră en monocépage : rouge plus léger, cerise acidulée et herbes, propre à la Moldavie."}],"cepages":["Cabernet Sauvignon","Saperavi","Rara neagră","Merlot"],"style":"Rouge profond et structuré : cassis, mûre, cuir, poivre noir, fût ; tanins fermes, acidité du Saperavi.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["viande_rouge","agneau","gibier","roti","sauce_vin_rouge","fromage_dure"],"eviter":["huitre","poisson_maigre","fruits_exotiques"],"classique":"Negru de Purcari et gigot d'agneau rôti","note":"Purcari, village du sud-est de la Moldavie près du Dniestr, a une cave fondée en 1827 ; son « Negru de Purcari » fut médaillé à Paris en 1878. Assemblage de Cabernet Sauvignon, de Saperavi géorgien et de Rara neagră locale, c'est le rouge de garde du pays. Pour viandes rouges rôties et gibier.","lat":46.52,"lon":29.86,"importance":2,"niveau":"decouverte"},{"id":"nz-waiheke-island","nom":"Waiheke Island","pays":"Nouvelle-Zélande","region":"Auckland","sousRegion":"Waiheke Island","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Syrah poivrée et florale, aujourd'hui le cépage montant de l'île (Man O' War, Passage Rock)."},{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay et quelques blancs aromatiques (viognier, pinot gris) pour la table des restaurants de l'île."}],"cepages":["Cabernet Sauvignon","Merlot","Syrah","Cabernet Franc"],"style":"Cassis, mûre, cèdre, herbes et notes salines ; corps plein, tanins mûrs et fermes, finale longue.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":4,"accords":["viande_rouge","agneau","roti","sauce_vin_rouge","gibier","fromage_dure"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Assemblage bordelais de Waiheke et agneau de lait rôti","note":"Île du golfe de Hauraki, à 35 minutes de ferry d'Auckland, plus chaude et plus sèche que la ville grâce à la mer. Stonyridge y a planté le cabernet en 1982 et lancé un style d'assemblage bordelais mûr et salin. Petits domaines, prix élevés, vins à ouvrir sur l'agneau ou le bœuf.","lat":-36.8,"lon":175.1,"importance":2,"niveau":"decouverte"},{"id":"nz-waipara","nom":"North Canterbury (Waipara)","pays":"Nouvelle-Zélande","region":"Canterbury","sousRegion":"Waipara Valley","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Riesling et pinot gris du sec au demi-sec, souvent la signature la plus citée de la vallée."},{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay tendu sur calcaire, de domaines comme Bell Hill ou Pyramid Valley."}],"cepages":["Pinot Noir","Riesling","Chardonnay"],"style":"Cerise, framboise, épices et notes de terre ; corps moyen, tanins fins, acidité ferme, finale calcaire.","temp":"14 à 16 °C","garde":"3 à 10 ans","prix":3,"accords":["canard","volaille","champignon","agneau","porc","fromage_molle"],"eviter":["huitre","piquant"],"classique":"Pinot noir de Waipara et canard aux cerises","note":"Vallée à une heure au nord de Christchurch, abritée des vents froids du Pacifique par les collines de Teviotdale, sur des argiles calcaires rares en Nouvelle-Zélande. Pinot noir fin, riesling et chardonnay de domaines pointus et souvent en biodynamie. Rouge de table frais pour la volaille.","lat":-43.06,"lon":172.76,"importance":2,"niveau":"decouverte"},{"id":"nz-central-otago-pinot-noir","nom":"Central Otago Pinot noir","pays":"Nouvelle-Zélande","region":"Central Otago","sousRegion":"Cromwell Basin","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Pinot gris et riesling, du sec au demi-sec, aromatiques et frais."},{"couleur":"rose","famille":"rose","note":"Rosé de pinot noir, fraise et pamplemousse, sec."}],"cepages":["Pinot Noir"],"style":"Cerise noire, prune, thym et terre sèche ; fruit intense, corps moyen, tanins ronds, acidité vive.","temp":"14 à 16 °C","garde":"3 à 12 ans","prix":3,"accords":["canard","agneau","volaille","champignon","gibier","fromage_molle"],"eviter":["huitre","piquant"],"classique":"Pinot noir de Central Otago et magret de canard","note":"Au sud de l'île du Sud, l'un des vignobles les plus australs du monde, à 45° de latitude, continental et semi-aride entre les Alpes néo-zélandaises. Étés chauds et secs, nuits froides, gels fréquents. Le pinot noir y est plus mûr et plus fruité qu'en Bourgogne. Idéal sur le canard et l'agneau.","lat":-45.04,"lon":169.2,"importance":4,"niveau":"incontournable"},{"id":"nz-gisborne","nom":"Gisborne","pays":"Nouvelle-Zélande","region":"Gisborne","sousRegion":"Poverty Bay","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Gewurztraminer, viognier et pinot gris opulents, tradition de la région."},{"couleur":"bulles","famille":"bulles","note":"Bases d'effervescents de chardonnay, région de climat chaud mais vendangée tôt."}],"cepages":["Chardonnay","Gewurztraminer","Pinot Gris"],"style":"Pêche, melon, ananas et vanille ; ample, rond, acidité modérée, bois souvent marqué.","temp":"11 à 13 °C","garde":"2 à 6 ans","prix":2,"accords":["volaille","creme","crustace","poisson_gras","curry","fromage_molle"],"eviter":["viande_rouge","vinaigre"],"classique":"Chardonnay de Gisborne et langouste au beurre","note":"Sur la côte est de l'île du Nord, la première ville au monde à voir le soleil se lever ; climat chaud et pluvieux, sols fertiles. Longtemps réservoir de chardonnay en vrac des grandes marques, elle garde quelques domaines (Millton, pionnier de la biodynamie). Blancs ronds pour les plats crémeux.","lat":-38.66,"lon":178.02,"importance":2,"niveau":"decouverte"},{"id":"nz-hawkes-bay","nom":"Hawke's Bay (Gimblett Gravels)","pays":"Nouvelle-Zélande","region":"Hawke's Bay","sousRegion":"Gimblett Gravels","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Syrah de climat tempéré, poivre blanc et violette, dans l'esprit du Rhône nord."},{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay riche et boisé, le blanc de référence de la baie."}],"cepages":["Merlot","Cabernet Sauvignon","Syrah","Cabernet Franc"],"style":"Cassis, prune, cèdre et graphite ; corps plein, tanins mûrs mais fermes, fraîcheur de climat tempéré.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":3,"accords":["viande_rouge","agneau","roti","sauce_vin_rouge","gibier","fromage_dure"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Assemblage bordelais des Gimblett Gravels et agneau rôti","note":"Sur la côte est de l'île du Nord, la deuxième région du pays et la plus ancienne (1851). Les Gimblett Gravels, lit de galets abandonné par la rivière Ngaruroro en 1867, emmagasinent la chaleur et font mûrir merlot, cabernet et syrah. Rouges structurés, dans l'esprit de Bordeaux.","lat":-39.62,"lon":176.75,"importance":3,"niveau":"classique"},{"id":"nz-marlborough-sauvignon-blanc","nom":"Marlborough Sauvignon blanc","pays":"Nouvelle-Zélande","region":"Marlborough","sousRegion":"Wairau Valley","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Pinot noir fruité et accessible, surtout dans les Southern Valleys et l'Awatere."},{"couleur":"bulles","famille":"bulles","note":"Effervescents de méthode traditionnelle (Cloudy Bay Pelorus, Deutz Marlborough) de chardonnay et pinot noir."},{"couleur":"blanc","famille":"blanc_aromatique","note":"Pinot gris et riesling aromatiques, parfois avec un peu de sucre résiduel."}],"cepages":["Sauvignon Blanc"],"style":"Fruit de la passion, groseille à maquereau, poivron, citron vert ; explosif, très vif, sec et net.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":2,"accords":["fromage_chevre","asperge","coquillage","poisson_maigre","asiatique","herbes"],"eviter":["viande_rouge","sauce_vin_rouge","fromage_bleu"],"classique":"Sauvignon de Marlborough et moules vertes à la coriandre","note":"Au nord de l'île du Sud, la vallée de la Wairau, plantée en 1973 par Montana, concentre les deux tiers du vignoble néo-zélandais. Soleil intense, nuits froides et sols de galets donnent le sauvignon le plus aromatique au monde, reconnu dès Cloudy Bay (1985). À boire jeune, sur du vert.","lat":-41.51,"lon":173.95,"importance":5,"niveau":"incontournable"},{"id":"nz-nelson","nom":"Nelson","pays":"Nouvelle-Zélande","region":"Nelson","sousRegion":"Moutere Hills","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Pinot noir souple et parfumé, surtout sur les argiles des collines de Moutere."},{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay charnu et noisetté (Neudorf), le vin le plus réputé de la région."}],"cepages":["Sauvignon Blanc","Chardonnay","Pinot Noir","Pinot Gris"],"style":"Agrumes, fruit de la passion, herbes fraîches ; sec, vif, plus discret et plus rond qu'à Marlborough.","temp":"8 à 10 °C","garde":"1 à 4 ans","prix":2,"accords":["coquillage","poisson_maigre","crustace","asperge","fromage_chevre","legumes"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Sauvignon de Nelson et coquilles Saint-Jacques poêlées","note":"À l'ouest de Marlborough, à la pointe nord de l'île du Sud, la ville la plus ensoleillée du pays, protégée par les montagnes. Deux terroirs : les plaines de graviers de la Waimea et les argiles des Moutere Hills. Petits domaines, vins plus doux de profil que ceux de Marlborough. Sur des coquillages.","lat":-41.27,"lon":173.1,"importance":2,"niveau":"decouverte"},{"id":"nz-martinborough","nom":"Martinborough","pays":"Nouvelle-Zélande","region":"Wairarapa","sousRegion":"Martinborough","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Pinot gris, riesling et sauvignon blanc d'un style plus retenu qu'à Marlborough."},{"couleur":"blanc","famille":"blanc_ample","note":"Chardonnay tendu et discrètement boisé."}],"cepages":["Pinot Noir","Sauvignon Blanc","Pinot Gris"],"style":"Cerise, prune rouge, épices, sous-bois et notes sauvages ; plus structuré et terrien que l'Otago.","temp":"14 à 16 °C","garde":"4 à 12 ans","prix":3,"accords":["canard","gibier","champignon","agneau","volaille","fromage_molle"],"eviter":["huitre","poisson_cru"],"classique":"Pinot noir de Martinborough et pigeon rôti aux champignons","note":"Petite ville au sud de l'île du Nord, à une heure de Wellington, sur une terrasse de graviers drainants cernée de vents. Un rapport de 1978 y a identifié le climat du pinot noir : Dry River, Ata Rangi et Martinborough Vineyard ont suivi dès 1979. Rouges sérieux, à servir sur le gibier à plumes.","lat":-41.22,"lon":175.46,"importance":3,"niveau":"classique"},{"id":"pe-ica","nom":"Ica","pays":"Pérou","region":"Ica","sousRegion":"","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Blancs secs de torontel, albilla et sauvignon, floraux"}],"cepages":["Tannat","Malbec","Petit Verdot","Quebranta"],"style":"Fruits noirs mûrs, épices douces, tanins ronds, chaleur solaire tempérée par le vent du Pacifique.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":2,"accords":["viande_rouge","porc","mijote","epice_douce","charcuterie"],"eviter":["poisson_cru","huitre"],"classique":"Rouge d'Ica et lomo saltado","note":"Plus vieux vignoble d'Amérique du Sud, planté par les Espagnols dès les années 1540, Ica est un désert côtier irrigué, surtout voué au pisco. Quelques domaines, dont Tacama (1540), y produisent des rouges solaires de tannat et malbec, à servir frais sur la cuisine péruvienne.","lat":-14.07,"lon":-75.73,"importance":1,"niveau":"decouverte"},{"id":"pt-acores-pico","nom":"Pico (Açores)","pays":"Portugal","region":"Açores","sousRegion":"Pico","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Arinto dos Açores","Verdelho","Terrantez do Pico"],"style":"Blanc sec et salin : citron, iode, pierre volcanique, herbes ; acidité tranchante, finale saline persistante.","temp":"9 à 11 °C","garde":"3 à 10 ans","prix":3,"accords":["huitre","coquillage","poisson_cru","poisson_gras","crustace","fume"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Pico et lapas grillées (patelles au beurre d'ail)","note":"Île volcanique des Açores, en plein Atlantique. Les vignes poussent dans les fissures de la lave noire, abritées du vent et des embruns par des murets de pierre : ce paysage de « currais » est classé par l'Unesco. Les blancs, relancés depuis 2010, sont salins. À servir sur les fruits de mer.","lat":38.53,"lon":-28.53,"importance":2,"niveau":"decouverte"},{"id":"pt-alentejo","nom":"Alentejo","pays":"Portugal","region":"Alentejo","sousRegion":"","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Antão Vaz, Arinto, Roupeiro : blancs ronds, fruits jaunes et amande, acidité modérée."},{"couleur":"rouge","famille":"rouge_souple","note":"Vinho de talha : vin fermenté en jarre d'argile, méthode romaine encore vivante à Vidigueira, plus léger et rustique."}],"cepages":["Aragonez","Trincadeira","Alicante Bouschet","Touriga Nacional"],"style":"Fruits noirs confiturés, prune, cacao, épices douces ; bouche pleine et chaleureuse, tanins mûrs, 14 % ou plus.","temp":"16 à 18 °C","garde":"3 à 10 ans","prix":1,"accords":["viande_rouge","agneau","porc","grille","mijote","fromage_dure"],"eviter":["huitre","poisson_maigre","vapeur"],"classique":"Alentejo et agneau mijoté (ensopado de borrego)","note":"Grande plaine du sud-est, chaude et sèche, plantée de chênes-lièges et d'oliviers ; vignes sur schiste, granit et argile autour d'Évora, Reguengos, Borba et Vidigueira. Rouges solaires et généreux, les plus vendus du pays, souvent à moins de 10 €. À servir sur une viande braisée ou grillée.","lat":38.57,"lon":-7.91,"importance":4,"niveau":"incontournable"},{"id":"pt-algarve","nom":"Algarve","pays":"Portugal","region":"Algarve","sousRegion":"","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Arinto, Síria et Verdelho : blancs ronds et parfumés pour les terrasses du littoral."},{"couleur":"rose","famille":"rose","note":"Rosé de Negra Mole ou de Syrah, léger et fruité, à boire à la plage."}],"cepages":["Negra Mole","Castelão","Syrah","Touriga Nacional"],"style":"Fruits rouges mûrs, figue, garrigue ; bouche souple et chaleureuse, tanins légers, acidité basse.","temp":"14 à 16 °C","garde":"1 à 4 ans","prix":2,"accords":["grille","poisson_gras","porc","mediterraneen","charcuterie"],"eviter":["huitre","sauce_vin_rouge","chocolat"],"classique":"Algarve rouge et cataplana de fruits de mer","note":"Côte sud du pays, la plus chaude et ensoleillée, avec quatre DOC (Lagos, Portimão, Lagoa, Tavira) longtemps réduites à des vins de volume pour les touristes. Depuis 2000, quelques domaines relancent la Negra Mole, cépage local léger. Vins de soif, à servir rafraîchis sur la cuisine de la mer.","lat":37.14,"lon":-8.45,"importance":1,"niveau":"decouverte"},{"id":"pt-bairrada","nom":"Bairrada","pays":"Portugal","region":"Beira Atlântico","sousRegion":"Bairrada","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"bulles","famille":"bulles","note":"Espumante de Baga, de Bical ou de Maria Gomes, méthode traditionnelle : la Bairrada est le berceau des bulles portugaises."},{"couleur":"blanc","famille":"blanc_vif","note":"Bical et Maria Gomes : blancs secs, pomme et fleurs, vifs et simples."}],"cepages":["Baga"],"style":"Cerise acidulée, mûre, tabac, terre humide ; tanins marqués et acidité haute, qui s'assouplissent avec dix ans de bouteille.","temp":"16 à 18 °C","garde":"8 à 25 ans","prix":2,"accords":["porc","roti","gibier","viande_rouge","mijote","fromage_dure"],"eviter":["poisson_maigre","huitre","cremeux"],"classique":"Bairrada et cochon de lait rôti (leitão da Bairrada)","note":"Argiles et calcaires près de la côte, entre Coimbra et Aveiro, sous un climat frais et humide. La Baga, cépage tardif à petites baies, donne des rouges austères et tanniques dans leur jeunesse, qui évoluent sur dix à vingt ans. Le cochon de lait de la région est son accord historique.","lat":40.44,"lon":-8.44,"importance":3,"niveau":"classique"},{"id":"pt-beira-interior","nom":"Beira Interior","pays":"Portugal","region":"Beira Interior","sousRegion":"","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Síria et Fonte Cal : blancs d'altitude, citron et fleurs, acidité vive, bon rapport prix-plaisir."}],"cepages":["Touriga Nacional","Tinta Roriz","Rufete","Jaen"],"style":"Fruits rouges frais, poivre et herbes sèches ; tanins souples, acidité nette, alcool modéré pour le Portugal.","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":1,"accords":["charcuterie","porc","agneau","grille","fromage_dure","mijote"],"eviter":["huitre","poisson_cru"],"classique":"Beira Interior et fromage de brebis Serra da Estrela","note":"Région de granit la plus haute du Portugal, entre la Serra da Estrela et l'Espagne, avec des vignes à 500 à 800 m. Hivers rudes, étés chauds mais courts : rouges frais et blancs tendus. Encore peu connue hors du pays, elle offre des prix doux. À servir sur la cuisine de montagne.","lat":40.54,"lon":-7.27,"importance":1,"niveau":"decouverte"},{"id":"pt-dao","nom":"Dão","pays":"Portugal","region":"Dão","sousRegion":"","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Encruzado : blanc sec de granit, agrumes et noisette, souvent élevé en fût, l'un des meilleurs blancs du pays."}],"cepages":["Touriga Nacional","Jaen","Alfrocheiro","Tinta Roriz"],"style":"Fruits rouges et noirs, violette, pin et sous-bois ; tanins fins, acidité fraîche, corps moyen, finale droite.","temp":"15 à 17 °C","garde":"4 à 12 ans","prix":2,"accords":["viande_rouge","porc","roti","mijote","champignon","fromage_molle"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Dão et porc noir rôti aux châtaignes","note":"Plateau de granit à 400 à 700 m autour de Viseu, cerné de montagnes qui coupent les vents atlantiques. La Touriga Nacional en est originaire. Les nuits froides donnent des rouges plus frais et moins massifs que ceux du Douro, comparés au pinot noir pour leur finesse. À ouvrir après quatre ans.","lat":40.66,"lon":-7.91,"importance":3,"niveau":"classique"},{"id":"pt-porto-ruby","nom":"Porto ruby","pays":"Portugal","region":"Douro","sousRegion":"Porto","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Touriga Nacional","Touriga Franca","Tinta Roriz","Tinta Barroca"],"style":"Rouge rubis, jeune et fruité : cerise noire, mûre, cassis, chocolat ; sucre franc, 19 à 20 % d'alcool, tanins doux.","temp":"14 à 16 °C","garde":"1 à 3 ans","prix":1,"accords":["chocolat","fruits_rouges","fromage_bleu","patisserie","glace"],"eviter":["poisson_maigre","huitre","vinaigre"],"classique":"Porto ruby et fondant au chocolat","note":"Le Porto est un vin muté : on arrête la fermentation en ajoutant de l'eau-de-vie, ce qui garde le sucre du raisin. Le ruby vieillit deux à trois ans en grandes cuves, à l'abri de l'oxygène, pour rester rouge et fruité. Il se boit jeune, sans carafage, sur un dessert au chocolat ou un bleu.","lat":41.17,"lon":-7.66,"importance":5,"niveau":"incontournable"},{"id":"pt-porto-tawny","nom":"Porto tawny 10 et 20 ans","pays":"Portugal","region":"Douro","sousRegion":"Porto","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Touriga Nacional","Touriga Franca","Tinta Roriz","Tinta Barroca"],"style":"Robe ambrée à fauve : noix, caramel, figue sèche, orange confite, cannelle ; douceur enrobée par le rancio, finale longue.","temp":"12 à 14 °C","garde":"5 à 20 ans","prix":3,"accords":["noix","caramel","fromage_dure","fromage_bleu","patisserie","foie_gras"],"eviter":["poisson_cru","acide","vinaigre"],"classique":"Tawny 20 ans et tarte aux amandes (toucinho do céu)","note":"« Tawny » signifie fauve : ce Porto vieillit en petits fûts, au contact de l'air, dans les chais de Vila Nova de Gaia. Le fruit laisse place à la noix, au caramel et aux fruits secs. La mention 10, 20, 30 ou 40 ans est un âge moyen d'assemblage. Il se sert frais, prêt à boire, sans décantation.","lat":41.21,"lon":-7.45,"importance":5,"niveau":"incontournable"},{"id":"pt-porto-vintage","nom":"Porto vintage","pays":"Portugal","region":"Douro","sousRegion":"Porto","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Touriga Nacional","Touriga Franca","Tinta Roriz","Sousão"],"style":"Rouge opaque, puissant : cassis, mûre, violette, eucalyptus, cacao ; tanins fermes jeune, cuir et épices avec l'âge.","temp":"16 à 18 °C","garde":"15 à 50 ans","prix":4,"accords":["fromage_bleu","chocolat","noix","gibier","fruits_rouges"],"eviter":["poisson_maigre","huitre","acide"],"classique":"Vintage et stilton aux noix","note":"Déclaré seulement les grandes années, trois par décennie environ, par chaque maison. Le vin passe deux ans en fût puis vieillit en bouteille, non filtré : il forme un dépôt et se décante. Massif jeune, il s'affine après vingt ans. On l'ouvre dans la journée et on finit sur un bleu ou des noix.","lat":41.19,"lon":-7.54,"importance":5,"niveau":"incontournable"},{"id":"pt-douro","nom":"Douro rouge","pays":"Portugal","region":"Douro","sousRegion":"","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de Touriga Nacional, fruits rouges et corps vineux, encore minoritaire."}],"cepages":["Touriga Nacional","Touriga Franca","Tinta Roriz","Tinta Barroca"],"style":"Mûre, cassis, violette et graphite ; tanins serrés, bouche dense, souvent 14 %, élevage en fût fréquent.","temp":"16 à 18 °C","garde":"5 à 15 ans","prix":2,"accords":["viande_rouge","agneau","gibier","roti","mijote","fromage_dure"],"eviter":["huitre","poisson_maigre","vapeur"],"classique":"Douro rouge et cabrito assado (chevreau rôti)","note":"Les mêmes terrasses de schiste que le Porto, le long du fleuve en amont de Régua, inscrites au patrimoine mondial. Depuis les années 1990, les cépages du Porto y donnent des rouges secs, concentrés et tanniques, à ouvrir après cinq ans sur une viande rôtie ou un ragoût.","lat":41.16,"lon":-7.79,"importance":4,"niveau":"incontournable"},{"id":"pt-porto-lbv","nom":"Porto LBV","pays":"Portugal","region":"Douro","sousRegion":"Porto","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Touriga Nacional","Touriga Franca","Tinta Roriz","Tinta Barroca"],"style":"Rouge profond et charnu : prune, mûre, cacao, réglisse ; plus de densité et de tanin qu'un ruby, sans la longueur d'un vintage.","temp":"15 à 17 °C","garde":"3 à 10 ans","prix":2,"accords":["fromage_bleu","chocolat","fruits_rouges","gibier","noix"],"eviter":["huitre","poisson_maigre","vapeur"],"classique":"LBV et stilton, l'accord anglais","note":"Late Bottled Vintage : vin d'une seule année, mis en bouteille après quatre à six ans de fût, donc prêt à boire là où le vintage demande des décennies. Créé par Taylor's en 1970, il offre la matière d'un millésime à prix contenu. La plupart sont filtrés et se servent sans carafe.","lat":41.16,"lon":-7.79,"importance":4,"niveau":"classique"},{"id":"pt-porto-blanc","nom":"Porto blanc","pays":"Portugal","region":"Douro","sousRegion":"Porto","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Malvasia Fina","Códega","Gouveio","Rabigato"],"style":"Blanc muté, du sec au doux : pomme mûre, miel, amande, zeste d'orange ; 19 à 20 % d'alcool, bouche ronde.","temp":"6 à 8 °C","garde":"1 à 5 ans","prix":1,"accords":["noix","foie_gras","fruits_jaunes","fromage_dure","patisserie"],"eviter":["viande_rouge","sauce_vin_rouge","vinaigre"],"classique":"Porto tonic, le Porto blanc avec tonic, glace et citron","note":"Porto de raisins blancs, muté comme le rouge, vendu sec, demi-sec ou doux (lágrima pour le plus sucré). Vieilli surtout en cuve, parfois en fût pour les 10 ans et plus. Il se sert très frais à l'apéritif, pur ou allongé de tonic, et accompagne amandes salées, foie gras ou tarte aux fruits.","lat":41.15,"lon":-7.41,"importance":3,"niveau":"classique"},{"id":"pt-douro-blanc","nom":"Douro blanc","pays":"Portugal","region":"Douro","sousRegion":"","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Rabigato","Viosinho","Gouveio","Códega do Larinho"],"style":"Blanc sec ample : poire, agrumes confits, amande, note minérale de schiste ; élevage en fût courant, acidité ferme en altitude.","temp":"10 à 12 °C","garde":"3 à 8 ans","prix":2,"accords":["poisson_gras","volaille","creme","champignon","fromage_dure","beurre_citron"],"eviter":["viande_rouge","piquant"],"classique":"Douro blanc et morue à la crème (bacalhau com natas)","note":"Les blancs secs du Douro viennent des parcelles les plus hautes, entre 400 et 700 m, où les nuits fraîches gardent l'acidité. Assemblage de cépages locaux, souvent élevé en fût, ils ont du corps et une amertume noble. À servir sur une morue en sauce ou une volaille à la crème.","lat":41.19,"lon":-7.55,"importance":2,"niveau":"decouverte"},{"id":"pt-bucelas","nom":"Bucelas","pays":"Portugal","region":"Lisboa","sousRegion":"Bucelas","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"bulles","famille":"bulles","note":"Espumante d'Arinto, méthode traditionnelle, tendu et citronné."}],"cepages":["Arinto"],"style":"Blanc sec et nerveux : citron, pomme verte, pierre mouillée, pointe de cire avec l'âge ; acidité élevée, corps léger.","temp":"8 à 10 °C","garde":"2 à 8 ans","prix":1,"accords":["huitre","coquillage","poisson_maigre","frit","beurre_citron","fromage_chevre"],"eviter":["viande_rouge","sauce_vin_rouge"],"classique":"Bucelas et palourdes à la coriandre (amêijoas à Bulhão Pato)","note":"Petite appellation de blancs à 25 km au nord de Lisbonne, dans la vallée du Trancão, sur calcaire. L'Arinto, au moins 75 % de l'assemblage, garde son acidité même sous le soleil. Le vin était apprécié en Angleterre au XIXe siècle sous le nom de « Lisbon hock ». À servir sur les coquillages.","lat":38.9,"lon":-9.12,"importance":2,"niveau":"decouverte"},{"id":"pt-colares","nom":"Colares","pays":"Portugal","region":"Lisboa","sousRegion":"Colares","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Malvasia de Colares : blanc salin et vif, cire d'abeille et iode, rare."}],"cepages":["Ramisco"],"style":"Robe claire, parfum de groseille, de violette et d'iode ; tanins rugueux et acidité haute jeune, souplesse et notes de cèdre après dix ans.","temp":"15 à 17 °C","garde":"10 à 30 ans","prix":3,"accords":["poisson_gras","grille","viande_rouge","gibier","fromage_dure"],"eviter":["cremeux","chocolat","piquant"],"classique":"Colares et thon grillé à la portugaise","note":"Vignes plantées dans le sable des dunes face à l'Atlantique, à l'ouest de Sintra. Le phylloxéra n'a jamais atteint ces racines dans le sable : les ceps de Ramisco sont francs de pied, couchés au ras du sol contre le vent. Quelques hectares seulement ; vins austères qui demandent l'âge.","lat":38.8,"lon":-9.45,"importance":2,"niveau":"decouverte"},{"id":"pt-lisboa","nom":"Lisboa","pays":"Portugal","region":"Lisboa","sousRegion":"","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Arinto, Fernão Pires et Chardonnay : blancs frais et simples, bons à l'apéritif."},{"couleur":"rose","famille":"rose","note":"Rosé de Castelão ou de Touriga, fruits rouges, à boire dans l'année."}],"cepages":["Castelão","Touriga Nacional","Aragonez","Syrah"],"style":"Fruits rouges mûrs, prune, poivre doux ; tanins ronds, bouche souple, fraîcheur apportée par l'océan.","temp":"14 à 16 °C","garde":"2 à 5 ans","prix":1,"accords":["charcuterie","volaille","porc","grille","mijote","tomate"],"eviter":["huitre","poisson_cru"],"classique":"Lisboa rouge et bifana (sandwich au porc mariné)","note":"Ancienne Estremadura, bande de collines entre Lisbonne et Leiria, balayée par l'Atlantique. Longtemps terre de vins de volume, elle produit des rouges souples et bon marché, de plus en plus soignés, et des blancs frais. Inclut les DOC Alenquer, Óbidos, Torres Vedras, Bucelas, Colares et Carcavelos.","lat":39.09,"lon":-9.26,"importance":2,"niveau":"classique"},{"id":"pt-madere-bual-malmsey","nom":"Madère Bual et Malmsey","pays":"Portugal","region":"Madère","sousRegion":"","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Boal","Malvasia","Tinta Negra"],"style":"Ambré foncé : caramel, raisin sec, figue, café, orange amère ; doux (Bual) à très doux (Malmsey), acidité qui garde la bouche fraîche.","temp":"12 à 14 °C","garde":"20 à 100 ans","prix":3,"accords":["caramel","patisserie","chocolat","noix","fromage_bleu","glace"],"eviter":["poisson_maigre","huitre","acide"],"classique":"Malmsey et gâteau au miel de Madère (bolo de mel)","note":"Les deux styles doux du madère : Bual (ou Boal), demi-doux, et Malmsey (Malvasia), le plus riche. Les mentions 5, 10, 15 ans indiquent l'âge minimal, et les « frasqueira » portent un millésime après 20 ans de fût. Le vin se sert frais, après le repas, et vit des décennies même ouvert.","lat":32.65,"lon":-16.98,"importance":4,"niveau":"classique"},{"id":"pt-madere-sercial-verdelho","nom":"Madère Sercial et Verdelho","pays":"Portugal","region":"Madère","sousRegion":"","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Sercial","Verdelho"],"style":"Ambré clair : amande grillée, citron confit, noix, fumée ; acidité tranchante, sec (Sercial) ou demi-sec (Verdelho), 18 à 20 % d'alcool.","temp":"10 à 12 °C","garde":"20 à 100 ans","prix":3,"accords":["noix","fromage_dure","fume","foie_gras","crustace","oeuf"],"eviter":["chocolat","fruits_rouges","cremeux"],"classique":"Sercial et consommé ou amandes grillées à l'apéritif","note":"Île volcanique à 900 km de Lisbonne, vignes en terrasses. Le madère est muté puis vieilli à la chaleur : cuves chauffées environ trois mois (estufagem) ou fûts sous les combles pendant des années (canteiro). Cette oxydation voulue le rend quasi indestructible : une bouteille ouverte tient des mois.","lat":32.65,"lon":-16.91,"importance":4,"niveau":"classique"},{"id":"pt-vinho-verde","nom":"Vinho Verde","pays":"Portugal","region":"Minho","sousRegion":"","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Vinhão : rouge sombre, acide et tannique, servi frais sur les sardines grillées dans le Minho."},{"couleur":"rose","famille":"rose","note":"Rosé léger et perlant d'Espadeiro ou de Vinhão, à boire dans l'année."},{"couleur":"bulles","famille":"bulles","note":"Espumante de Loureiro ou d'Alvarinho, méthode traditionnelle, encore rare."}],"cepages":["Loureiro","Arinto","Trajadura","Alvarinho"],"style":"Blanc léger, vif, parfois perlant : citron vert, pomme verte, fleur d'oranger ; 9 à 12 % d'alcool, finale nette.","temp":"7 à 9 °C","garde":"1 à 2 ans","prix":1,"accords":["coquillage","poisson_maigre","crustace","frit","vapeur","fromage_frais"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Vinho Verde et sardines grillées","note":"« Vert » comme la région du Minho, au nord-ouest, où la vigne poussait en treille au-dessus des potagers. Le vin est jeune, peu alcoolisé, souvent légèrement perlant par un reste de gaz. On le sert très frais, à l'apéritif ou sur les fruits de mer et les beignets de morue.","lat":41.73,"lon":-8.5,"importance":4,"niveau":"incontournable"},{"id":"pt-alvarinho-moncao-melgaco","nom":"Alvarinho de Monção e Melgaço","pays":"Portugal","region":"Minho","sousRegion":"Monção e Melgaço","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Alvarinho"],"style":"Blanc sec et dense : pêche, pamplemousse, fleur d'acacia, pointe saline ; plus d'alcool et de corps que le Vinho Verde courant.","temp":"9 à 11 °C","garde":"2 à 6 ans","prix":2,"accords":["crustace","poisson_gras","poisson_cru","volaille","asiatique","beurre_citron"],"eviter":["viande_rouge","gibier"],"classique":"Alvarinho et lamproie à la bordelaise de Monção","note":"Sous-région la plus au nord du Minho, le long du fleuve Minho face à la Galice, abritée des pluies atlantiques par les monts. L'Alvarinho, frère de l'Albariño espagnol, y mûrit mieux qu'ailleurs : 12,5 à 13,5 % d'alcool, texture ronde, acidité vive. À servir sur poissons et crustacés.","lat":42.09,"lon":-8.4,"importance":3,"niveau":"classique"},{"id":"pt-moscatel-de-setubal","nom":"Moscatel de Setúbal","pays":"Portugal","region":"Península de Setúbal","sousRegion":"Setúbal","couleur":"doux","famille":"vdn","variantes":[],"cepages":["Moscatel de Setúbal","Moscatel Roxo"],"style":"Doré à ambré : raisin muscat, orange confite, miel, fleur d'oranger, puis noix et caramel avec l'âge ; sucré, 17 à 18 % d'alcool.","temp":"10 à 12 °C","garde":"5 à 30 ans","prix":2,"accords":["patisserie","fruits_exotiques","fruits_jaunes","caramel","fromage_bleu","foie_gras"],"eviter":["viande_rouge","acide","vinaigre"],"classique":"Moscatel de Setúbal et pastel de nata","note":"Vin muté de Muscat d'Alexandrie cultivé sur les calcaires de l'Arrábida, à Setúbal et Azeitão. Après l'arrêt de la fermentation à l'eau-de-vie, le vin macère des mois sur ses peaux, puis vieillit en fût ; les 10 et 20 ans prennent un goût de noix. Il se sert frais, sur les desserts aux œufs.","lat":38.52,"lon":-8.95,"importance":3,"niveau":"classique"},{"id":"pt-palmela","nom":"Palmela","pays":"Portugal","region":"Península de Setúbal","sousRegion":"Palmela","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Fernão Pires, Arinto, Moscatel sec : blancs frais et modestes."}],"cepages":["Castelão"],"style":"Fruits rouges mûrs, cerise à l'eau-de-vie, cuir et tabac avec l'âge ; tanins souples, acidité moyenne, bouche ronde.","temp":"14 à 16 °C","garde":"3 à 8 ans","prix":1,"accords":["porc","charcuterie","volaille","grille","mijote","fromage_dure"],"eviter":["huitre","poisson_cru","piquant"],"classique":"Palmela et fromage d'Azeitão au lait de brebis","note":"DOC de rouges sur les sables de la plaine entre Palmela et le Tage, au sud de Lisbonne, sous un soleil constant. Le Castelão, appelé ici Periquita, fait au moins deux tiers de l'assemblage : rouge souple, au fruit rouge mûr, qui vieillit sur des notes de cuir. À boire entre trois et six ans.","lat":38.57,"lon":-8.9,"importance":2,"niveau":"decouverte"},{"id":"pt-peninsula-de-setubal","nom":"Península de Setúbal","pays":"Portugal","region":"Península de Setúbal","sousRegion":"","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Moscatel sec, Fernão Pires, Arinto : blancs parfumés et ronds, à boire frais."},{"couleur":"rose","famille":"rose","note":"Rosé de Castelão, fraise et pêche, souvent légèrement doux dans les marques de volume."}],"cepages":["Castelão","Syrah","Touriga Nacional","Aragonez"],"style":"Fruits noirs mûrs, prune, épices et cacao ; bouche chaleureuse, tanins ronds, alcool généreux.","temp":"15 à 17 °C","garde":"2 à 6 ans","prix":1,"accords":["grille","viande_rouge","porc","mijote","charcuterie","mediterraneen"],"eviter":["huitre","poisson_maigre","vapeur"],"classique":"Setúbal rouge et porc à l'alentejana (porc aux palourdes)","note":"Presqu'île au sud de Lisbonne, entre le Tage et le Sado : sables chauds de la plaine et calcaire de la serra da Arrábida. Indication régionale qui englobe Palmela et le Moscatel de Setúbal. Les grandes maisons de la région y produisent des rouges solaires et accessibles, à servir sur des grillades.","lat":38.57,"lon":-8.83,"importance":2,"niveau":"classique"},{"id":"pt-tejo","nom":"Tejo","pays":"Portugal","region":"Tejo","sousRegion":"","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Fernão Pires et Arinto : blancs floraux et faciles, à l'apéritif ou sur un poisson."}],"cepages":["Castelão","Trincadeira","Touriga Nacional","Cabernet Sauvignon"],"style":"Fruits rouges et noirs mûrs, épices douces ; tanins souples, bouche ronde et facile, finale courte à moyenne.","temp":"14 à 16 °C","garde":"2 à 5 ans","prix":1,"accords":["charcuterie","porc","volaille","grille","mijote","fromage_molle"],"eviter":["huitre","poisson_cru","amer"],"classique":"Tejo rouge et soupe de pierre (sopa da pedra) de Almeirim","note":"Vallée du Tage autour de Santarém, l'ancien Ribatejo : plaines alluviales fertiles au bord du fleuve, collines plus sèches au nord et au sud. Historiquement vigne de grands rendements, elle produit aujourd'hui des rouges gourmands à petit prix. À boire jeune, sur la cuisine de bistrot.","lat":39.24,"lon":-8.69,"importance":2,"niveau":"classique"},{"id":"ro-feteasca-neagra","nom":"Fetească neagră","pays":"Roumanie","region":"Moldavie roumaine","sousRegion":"Dealurile Moldovei","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rouge","famille":"rouge_puissant","note":"Cuvées élevées longuement en barrique : plus denses, prune cuite, tabac, à garder."},{"couleur":"rose","famille":"rose","note":"Rosé de Fetească neagră : fruits rouges, bouche ronde, apéritif d'été."}],"cepages":["Fetească neagră"],"style":"Rouge souple et parfumé : prune noire, mûre, violette, poivre, cacao ; tanins doux, acidité modérée.","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":1,"accords":["porc","mijote","charcuterie","volaille","epice_douce","champignon"],"eviter":["huitre","poisson_cru","acide"],"classique":"Fetească neagră et tochitură (ragoût de porc à la polenta)","note":"La « jeune fille noire » est le cépage rouge emblématique de l'espace roumain et moldave, né près de Iași. Il a survécu au phylloxéra et à l'ère communiste avant d'être replanté de la Moldavie roumaine à la République de Moldavie. Prune et violette le distinguent ; vin de ragoûts de porc.","lat":47.13,"lon":27.47,"importance":2,"niveau":"decouverte"},{"id":"ro-dealu-mare","nom":"Dealu Mare","pays":"Roumanie","region":"Munténie","sousRegion":"","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Pietroasa : Tămâioasă românească (muscat) moelleuse, parfum de rose et de miel."}],"cepages":["Fetească neagră","Merlot","Cabernet Sauvignon","Pinot noir"],"style":"Rouge mûr et rond : prune, cerise noire, épices douces, pointe de vanille ; tanins souples, chaleur contenue.","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":2,"accords":["viande_rouge","porc","mijote","grille","charcuterie","fromage_dure"],"eviter":["huitre","poisson_cru","fruits_exotiques"],"classique":"Dealu Mare et sarmale (chou farci) au porc","note":"La « grande colline » court sur 70 km au pied des Carpates, au nord de Bucarest, à la latitude du Bordelais. C'est la région des rouges roumains : Fetească neagră locale et cépages bordelais sur argiles et calcaires. Vin rond et mûr pour le porc et le chou farci, à boire entre trois et huit ans.","lat":44.99,"lon":26.23,"importance":2,"niveau":"decouverte"},{"id":"rs-prokupac","nom":"Prokupac de Župa","pays":"Serbie","region":"Serbie centrale","sousRegion":"Župa (Aleksandrovac)","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de Prokupac : fraise et grenade, le style traditionnel du cépage dans les villages."}],"cepages":["Prokupac"],"style":"Rouge souple et rustique : cerise griotte, prune, poivre, herbes sèches ; tanins moyens, acidité fraîche.","temp":"15 à 17 °C","garde":"3 à 8 ans","prix":2,"accords":["grille","porc","charcuterie","mijote","fromage_dure","epice_douce"],"eviter":["huitre","poisson_cru","patisserie"],"classique":"Prokupac et ćevapi grillés aux oignons","note":"Le Prokupac est le cépage rouge historique de Serbie, cultivé depuis le Moyen Âge dans la Župa d'Aleksandrovac, au centre du pays. Longtemps relégué au vin de table, il est repris par de petits domaines qui le vinifient avec soin : cerise, poivre, tanins moyens. Vin de grillades balkaniques.","lat":43.46,"lon":21.05,"importance":1,"niveau":"decouverte"},{"id":"sk-tokaj-slovaque","nom":"Tokaj slovaque","pays":"Slovaquie","region":"Tokaj","sousRegion":"Malá Tŕňa, Viničky","couleur":"doux","famille":"blanc_doux","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Furmint et Lipovina secs : tendus, fumés, pomme et coing, moins chers que les voisins hongrois."},{"couleur":"blanc","famille":"blanc_ample","note":"Tokajský samorodný suchý : élevé sous voile, notes de noix, proche d'un xérès léger."}],"cepages":["Furmint","Lipovina","Muškát žltý"],"style":"Liquoreux ambré : abricot sec, miel, coing, noix ; sucre tenu par l'acidité, finale longue.","temp":"10 à 12 °C","garde":"10 à 30 ans","prix":2,"accords":["foie_gras","fromage_bleu","fruits_jaunes","patisserie","noix","sucre_sale"],"eviter":["viande_rouge","piquant","chocolat"],"classique":"Tokajský výber et fromage de brebis (bryndza) affiné","note":"Sept villages du sud-est de la Slovaquie appartiennent à la même région de Tokaj que la Hongrie, séparés par la frontière de 1920. Mêmes cépages, même botrytis, mêmes caves en tuf ; le « výber » à 3, 4, 5 ou 6 puttonyos est l'équivalent de l'Aszú, souvent moins cher. Vin de fin de repas.","lat":48.45,"lon":21.7,"importance":1,"niveau":"decouverte"},{"id":"si-stajerska","nom":"Styrie slovène","pays":"Slovénie","region":"Podravje","sousRegion":"Štajerska Slovenija","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Vendanges tardives et vins de glace de Laški rizling ou Šipon, rares et très frais."},{"couleur":"bulles","famille":"bulles","note":"Effervescents de méthode traditionnelle à Radgona (Radgonske gorice), le plus ancien mousseux slovène."}],"cepages":["Laški rizling","Sauvignon","Šipon","Renski rizling"],"style":"Blanc sec, léger et aromatique : pomme verte, sureau, agrumes, herbe coupée ; acidité vive, faible alcool.","temp":"8 à 10 °C","garde":"1 à 5 ans","prix":1,"accords":["poisson_maigre","legumes","asperge","fromage_frais","herbes","vapeur"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Sauvignon de Štajerska et asperges à l'œuf poché","note":"La Styrie slovène, au nord-est du pays entre Maribor et Jeruzalem, prolonge les collines fraîches de la Styrie autrichienne. Les blancs y sont légers, vifs et aromatiques : Laški rizling (Welschriesling), Sauvignon, Šipon (le Furmint local). À boire jeunes, à l'apéritif ou sur légumes et poissons.","lat":46.42,"lon":15.87,"importance":2,"niveau":"decouverte"},{"id":"si-goriska-brda","nom":"Goriška Brda","pays":"Slovénie","region":"Primorska","sousRegion":"Brda","couleur":"blanc","famille":"blanc_ample","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Rebula macérée (vin « orange ») : ambrée, tannique, notes de thé, d'abricot sec et de noix."},{"couleur":"rouge","famille":"rouge_souple","note":"Merlot et Cabernet Sauvignon : rouges souples et mûrs, proches des voisins du Frioul."}],"cepages":["Rebula","Sauvignonasse","Malvazija","Chardonnay"],"style":"Blanc sec, texturé et salin : pomme, poire, amande, pointe de miel ; corps ample, acidité moyenne à vive.","temp":"10 à 12 °C","garde":"3 à 10 ans","prix":2,"accords":["poisson_gras","crustace","volaille","charcuterie","fromage_dure","legumes"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Rebula de Brda et prosciutto de Kras","note":"Les collines de Brda, à cheval sur la frontière italienne, prolongent le Collio frioulan : même marne et grès, même Rebula (Ribolla gialla). La Slovénie y a popularisé les blancs macérés, ambrés et tanniques. En version classique, blanc ample et salin pour poissons et charcuteries de l'Adriatique.","lat":45.99,"lon":13.52,"importance":2,"niveau":"decouverte"},{"id":"ch-geneve","nom":"Genève","pays":"Suisse","region":"Genève","sousRegion":"Satigny","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Chasselas, Chardonnay et Aligoté, blancs secs et simples"}],"cepages":["Gamay","Gamaret","Pinot noir"],"style":"Fruits rouges, poivre, violette ; léger à moyen, souple, tanins doux, le Gamaret plus coloré et épicé.","temp":"13 à 15 °C","garde":"1 à 5 ans","prix":2,"accords":["charcuterie","volaille","porc","legumes","fromage_molle","grille"],"eviter":["gibier","piquant","chocolat"],"classique":"Gamay de Genève et longeole, la saucisse genevoise au fenouil","note":"Troisième canton viticole suisse, en plaine autour de Satigny et du Mandement, sur des moraines glaciaires. Le Gamay domine, souvent en rouge léger, et le Gamaret, croisement suisse de 1970 résistant à la pourriture, y est né. Vins simples et francs, à servir un peu frais sur une cuisine de bistrot.","lat":46.22,"lon":6.03,"importance":1,"niveau":"decouverte"},{"id":"ch-graubunden-pinot-noir","nom":"Grisons Pinot noir","pays":"Suisse","region":"Grisons","sousRegion":"Bündner Herrschaft","couleur":"rouge","famille":"rouge_leger","variantes":[],"cepages":["Pinot noir"],"style":"Cerise, framboise, sous-bois, épices fines ; soyeux, tanins fins, acidité fraîche, boisé mesuré, bourguignon.","temp":"14 à 16 °C","garde":"5 à 15 ans","prix":3,"accords":["volaille","canard","gibier","champignon","fromage_molle","roti"],"eviter":["huitre","piquant","chocolat"],"classique":"Pinot noir de la Herrschaft et Capuns, les feuilles de bette farcies","note":"La Bündner Herrschaft (Fläsch, Maienfeld, Jenins, Malans) est une poche chaude de la vallée du Rhin alpin, réchauffée par le foehn, sur des sols calcaires. Le Pinot noir y donne les rouges les plus réputés de Suisse, fins et de garde, chers. À servir à peine frais sur une volaille ou un gibier.","lat":47.0,"lon":9.53,"importance":2,"niveau":"decouverte"},{"id":"ch-neuchatel-oeil-de-perdrix","nom":"Neuchâtel Œil-de-Perdrix","pays":"Suisse","region":"Neuchâtel","sousRegion":"Auvernier","couleur":"rose","famille":"rose","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Chasselas non filtré, perlant, mis en bouteille le troisième mercredi de janvier"}],"cepages":["Pinot noir"],"style":"Fraise, groseille, pétale de rose ; rosé pâle saumoné, sec, délicat, acidité fine, finale douce.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":2,"accords":["charcuterie","poisson_maigre","legumes","fromage_frais","crustace","mediterraneen"],"eviter":["viande_rouge","gibier","chocolat"],"classique":"Œil-de-Perdrix et filets de perche du lac","note":"Rosé de Pinot noir né sur la rive nord du lac de Neuchâtel, entre Vaumarcus et Le Landeron, sur des coteaux calcaires du Jura. Son nom vient de sa couleur, le rose doré de l'œil d'une perdrix ; il est obtenu par pressurage direct et courte macération. À servir frais sur un poisson de lac.","lat":46.98,"lon":6.88,"importance":2,"niveau":"decouverte"},{"id":"ch-tessin-merlot","nom":"Tessin Merlot","pays":"Suisse","region":"Tessin","sousRegion":"Mendrisiotto","couleur":"rouge","famille":"rouge_souple","variantes":[{"couleur":"blanc","famille":"blanc_ample","note":"Merlot bianco : Merlot vinifié en blanc, rond et fruité, spécialité tessinoise"}],"cepages":["Merlot"],"style":"Cerise noire, prune, cacao, herbes sèches ; souple, charnu, tanins ronds, élevage en barrique fréquent.","temp":"15 à 17 °C","garde":"3 à 12 ans","prix":3,"accords":["viande_rouge","roti","mijote","porc","champignon","fromage_dure"],"eviter":["huitre","poisson_maigre","piquant"],"classique":"Merlot du Tessin et polenta au brasato","note":"Le Merlot a été introduit au Tessin en 1906 après le phylloxéra et fait aujourd'hui plus de 80 % du vignoble, sur les collines granitiques du Sopraceneri et les marnes du Mendrisiotto, au sud. Climat italien, cuisine lombarde : rouge souple et mûr, à servir sur un brasato, une polenta ou un risotto.","lat":45.87,"lon":8.98,"importance":3,"niveau":"classique"},{"id":"ch-valais-fendant","nom":"Valais Fendant","pays":"Suisse","region":"Valais","sousRegion":"Sion","couleur":"blanc","famille":"blanc_vif","variantes":[],"cepages":["Chasselas"],"style":"Fleur de tilleul, pomme, pierre, parfois un perlant ; sec, léger, peu acide, texture douce, finale amère fine.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":2,"accords":["fromage_dure","fromage_lave","creme","poisson_maigre","charcuterie","beurre_citron"],"eviter":["viande_rouge","piquant","chocolat"],"classique":"Fendant et raclette","note":"Fendant est le nom valaisan du Chasselas, cépage dont la baie se fend sous le doigt. Sur les coteaux secs et ensoleillés de Sion et Sierre, il donne un blanc discret, un peu perlant, peu acide, qui ne lutte pas avec le fromage fondu. C'est le vin de la raclette et de la fondue, à servir bien frais.","lat":46.23,"lon":7.36,"importance":3,"niveau":"classique"},{"id":"ch-cornalin","nom":"Cornalin","pays":"Suisse","region":"Valais","sousRegion":"Sierre","couleur":"rouge","famille":"rouge_souple","variantes":[],"cepages":["Cornalin"],"style":"Cerise noire, violette, cannelle, cacao ; coloré, charnu, tanins francs mais fins, acidité fraîche.","temp":"15 à 17 °C","garde":"4 à 12 ans","prix":3,"accords":["gibier","viande_rouge","mijote","agneau","fromage_dure","roti"],"eviter":["huitre","poisson_maigre","piquant"],"classique":"Cornalin et viande séchée du Valais","note":"Appelé Rouge du Pays jusqu'en 1972, ce cépage valaisan était presque disparu avant sa renaissance dans les années 1990. Capricieux à la vigne, il donne sur les coteaux de Sierre et Salquenen un rouge sombre et épicé, le plus noble du Valais. À servir sur une viande séchée, un gibier ou un ragoût.","lat":46.29,"lon":7.53,"importance":2,"niveau":"decouverte"},{"id":"ch-dole","nom":"Dôle","pays":"Suisse","region":"Valais","sousRegion":"","couleur":"rouge","famille":"rouge_leger","variantes":[{"couleur":"rose","famille":"rose","note":"Dôle blanche : les mêmes raisins pressés directement, rosé pâle"}],"cepages":["Pinot noir","Gamay"],"style":"Cerise, framboise, fraise, pointe de poivre ; léger, souple, tanins fins, fruité, à boire jeune.","temp":"13 à 15 °C","garde":"1 à 4 ans","prix":2,"accords":["charcuterie","volaille","porc","fromage_dure","fromage_lave","mijote"],"eviter":["huitre","piquant","chocolat"],"classique":"Dôle et assiette valaisanne (viande séchée, lard, fromage)","note":"Assemblage valaisan traditionnel de Pinot noir (au moins 51 %) et de Gamay, cultivés sur les coteaux de la vallée du Rhône entre Martigny et Sierre. Rouge de soif, léger et fruité, il accompagne tout le repas montagnard. À servir un peu frais sur une assiette valaisanne ou une raclette.","lat":46.22,"lon":7.3,"importance":2,"niveau":"decouverte"},{"id":"ch-petite-arvine","nom":"Petite Arvine","pays":"Suisse","region":"Valais","sousRegion":"Fully","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"doux","famille":"blanc_doux","note":"Petite Arvine flétrie : raisins passerillés, liquoreux salin de grande garde"}],"cepages":["Petite Arvine"],"style":"Pamplemousse, rhubarbe, glycine, touche saline en finale ; sec, vif, dense, nerveux, reconnaissable au sel.","temp":"9 à 11 °C","garde":"3 à 10 ans","prix":3,"accords":["crustace","poisson_maigre","asperge","fromage_chevre","beurre_citron","huitre"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Petite Arvine et filets de perche du Léman","note":"Cépage autochtone du Valais, planté sur les terrasses de granit de Fully et Martigny, exigeant et peu productif. Sa signature est une pointe de sel en finale, unique parmi les blancs d'Europe, avec le pamplemousse et la rhubarbe. À servir frais sur des crustacés ou une perche du Léman.","lat":46.14,"lon":7.11,"importance":2,"niveau":"decouverte"},{"id":"ch-lavaux-dezaley","nom":"Lavaux Dézaley","pays":"Suisse","region":"Vaud","sousRegion":"Lavaux","couleur":"blanc","famille":"blanc_ample","variantes":[],"cepages":["Chasselas"],"style":"Miel, amande, pierre à fusil, tilleul, fumée ; sec, ample, rond, peu acide, finale longue et minérale.","temp":"10 à 12 °C","garde":"3 à 15 ans","prix":3,"accords":["poisson_maigre","fromage_dure","creme","crustace","volaille","beurre_citron"],"eviter":["viande_rouge","piquant","chocolat"],"classique":"Dézaley et filets de perche meunière","note":"Terrasses de Lavaux, classées à l'Unesco, bâties par les moines cisterciens au XIIe siècle au-dessus du Léman entre Lausanne et Vevey. Dézaley, grand cru, a trois soleils : le ciel, le lac qui le reflète et les murs qui le gardent. Chasselas le plus dense de Suisse, qui vieillit dix ans et plus.","lat":46.49,"lon":6.76,"importance":3,"niveau":"classique"},{"id":"cz-moravie","nom":"Moravie","pays":"Tchéquie","region":"Moravie","sousRegion":"Mikulov, Znojmo, Velké Pavlovice","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"blanc","famille":"blanc_aromatique","note":"Pálava : croisement local Müller-Thurgau × Traminer, parfumé, rose et litchi, parfois demi-sec."},{"couleur":"rouge","famille":"rouge_leger","note":"Frankovka (Blaufränkisch) et Svatovavřinecké (Saint-Laurent) : rouges légers et poivrés de Velké Pavlovice."}],"cepages":["Ryzlink vlašský","Veltlínské zelené","Ryzlink rýnský","Sauvignon"],"style":"Blanc sec, léger et frais : pomme, agrumes, poivre blanc, fleurs ; acidité vive, alcool modéré.","temp":"8 à 10 °C","garde":"1 à 5 ans","prix":1,"accords":["poisson_maigre","volaille","legumes","asperge","fromage_frais","frit"],"eviter":["viande_rouge","sauce_vin_rouge","chocolat"],"classique":"Veltlínské zelené de Moravie et escalope panée (řízek)","note":"La Moravie du Sud, autour de Mikulov et Znojmo le long de la frontière autrichienne, porte 96 % des vignes tchèques. Même climat et mêmes cépages que le Weinviertel voisin : Welschriesling, Grüner Veltliner, Riesling, plus le Pálava local. Blancs légers et frais, à boire jeunes sur la cuisine panée.","lat":48.81,"lon":16.64,"importance":2,"niveau":"decouverte"},{"id":"tn-mornag","nom":"Mornag","pays":"Tunisie","region":"Cap Bon et région de Tunis","sousRegion":"Mornag","couleur":"rouge","famille":"rouge_solaire","variantes":[{"couleur":"rose","famille":"rose","note":"Rosés de Carignan et Grenache, les vins tunisiens les plus exportés."}],"cepages":["Carignan","Grenache","Syrah","Mourvèdre"],"style":"Garrigue, griotte, poivre et terre sèche ; rouge méditerranéen simple et chaleureux, tanins ronds.","temp":"15 à 17 °C","garde":"2 à 5 ans","prix":1,"accords":["agneau","grille","mijote","epice_douce","mediterraneen","charcuterie"],"eviter":["huitre","poisson_cru","creme"],"classique":"Rouge de Mornag et brochettes d'agneau à la harissa","note":"Au sud-est de Tunis, la plaine de Mornag, adossée au djebel Ressas, est la principale appellation tunisienne, plantée surtout en Carignan et Grenache hérités de l'époque française. Les rouges sont simples et solaires, les rosés très courants. Servir frais, sur des grillades et la cuisine épicée.","lat":36.68,"lon":10.29,"importance":1,"niveau":"decouverte"},{"id":"tr-cappadoce","nom":"Cappadoce","pays":"Turquie","region":"Anatolie centrale","sousRegion":"Cappadoce","couleur":"blanc","famille":"blanc_vif","variantes":[{"couleur":"rouge","famille":"rouge_leger","note":"Kalecik Karası et Öküzgözü, rouges fruités et peu tanniques."}],"cepages":["Emir","Kalecik Karası","Öküzgözü"],"style":"Emir : citron, poire verte, pierre à fusil, amande ; blanc sec, léger et tendu, à boire jeune.","temp":"8 à 10 °C","garde":"1 à 3 ans","prix":2,"accords":["poisson_maigre","coquillage","legumes","fromage_frais","herbes","vapeur"],"eviter":["viande_rouge","chocolat","sauce_vin_rouge"],"classique":"Emir de Cappadoce et mezze de yaourt aux herbes","note":"Sur les tufs volcaniques d'Ürgüp et de Göreme, à 1 000 m d'altitude, la vigne est cultivée depuis les Hittites et le vin se conservait dans des caves creusées dans la roche. L'Emir, cépage blanc local, donne des vins secs et tendus ; Turasan et Kavaklıdere en sont les noms connus.","lat":38.63,"lon":34.91,"importance":2,"niveau":"decouverte"},{"id":"uy-canelones-tannat","nom":"Canelones Tannat","pays":"Uruguay","region":"Canelones","sousRegion":"","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"rose","famille":"rose","note":"Rosé de tannat, vif et fruité"}],"cepages":["Tannat","Merlot","Cabernet Franc"],"style":"Mûre, cassis, cacao et cuir, tanins abondants mais plus ronds qu'à Madiran, acidité fraîche.","temp":"16 à 18 °C","garde":"4 à 12 ans","prix":2,"accords":["viande_rouge","grille","mijote","fromage_dure","chocolat"],"eviter":["poisson_maigre","coquillage"],"classique":"Tannat de Canelones et asado uruguayen au feu de bois","note":"Introduit en 1870 par le Basque Pascual Harriague, le tannat est devenu le cépage national de l'Uruguay. Canelones, autour de Montevideo, concentre la majorité des vignes sous un climat atlantique humide : des tannats plus souples qu'à Madiran, faits pour la viande grillée.","lat":-34.52,"lon":-56.28,"importance":3,"niveau":"classique"},{"id":"uy-maldonado","nom":"Maldonado","pays":"Uruguay","region":"Maldonado","sousRegion":"Garzón et José Ignacio","couleur":"rouge","famille":"rouge_puissant","variantes":[{"couleur":"blanc","famille":"blanc_vif","note":"Albariño atlantique, salin et citronné"}],"cepages":["Tannat","Albariño","Cabernet Franc","Marselan"],"style":"Tannat frais et élégant, fruits noirs, herbes, tanins fins et salins, acidité atlantique.","temp":"16 à 18 °C","garde":"4 à 10 ans","prix":3,"accords":["viande_rouge","agneau","grille","fromage_dure","mediterraneen"],"eviter":["poisson_cru","huitre"],"classique":"Tannat de Maldonado et côte de bœuf grillée au feu de bois","note":"À l'est de l'Uruguay, près de Punta del Este, Maldonado est le vignoble le plus récent du pays, planté depuis les années 2000 sur granit et sous l'influence directe de l'Atlantique. Ses tannats fins et ses albariños salins, menés par Bodega Garzón, ont fait connaître l'Uruguay à l'export.","lat":-34.6,"lon":-54.56,"importance":2,"niveau":"decouverte"}];
